export interface CmdFTakeoverBarUiState {
  position: { top: number | null; left: number | null };
  snippetsPanel?: {
    position: { top: number | null; left: number | null };
    isCollapsed: boolean;
  };
}

export const isCmdFTakeoverBarUiState = (v: unknown): v is CmdFTakeoverBarUiState => {
  if (!v || typeof v !== "object") return false;
  const o = v as Record<string, unknown>;
  if (!o.position || typeof o.position !== "object") return false;
  const p = o.position as Record<string, unknown>;
  const okNum = (x: unknown) => x === null || typeof x === "number";
  if (!okNum(p.top) || !okNum(p.left)) return false;
  // snippetsPanel: optional for backward compatibility with pre-migration
  // storage values. If present, validate strictly so corrupt data is
  // rejected and consumers fall back to defaults.
  // Extra keys (e.g. legacy isMinimized) are tolerated — the guard ignores them.
  if (o.snippetsPanel !== undefined) {
    if (!o.snippetsPanel || typeof o.snippetsPanel !== "object") return false;
    const sp = o.snippetsPanel as Record<string, unknown>;
    if (typeof sp.isCollapsed !== "boolean") return false;
    if (!sp.position || typeof sp.position !== "object") return false;
    const spp = sp.position as Record<string, unknown>;
    if (!okNum(spp.top) || !okNum(spp.left)) return false;
  }
  return true;
};

