// MSG-08: validate the SENDER/ORIGIN of a broadcast independently of whether
// its payload changed. Previously this ANDed in `hasGlobalSettingsChanged`, so
// a perfectly valid message whose payload was JSON-equal to our cached settings
// was REJECTED — even when our live DOM state had drifted (a dropped earlier
// update, an incomplete cleanup) and the repair broadcast was exactly what we
// needed to re-sync. Sender validity and "is this new work" are now separate
// concerns: this gate only proves the message is genuinely ours.
export const validateSender = (
  message: ChromeMessage,
  sender: chrome.runtime.MessageSender
) => {
  return (
    !!message?.message?.globalSettings &&
    sender.id === BROWSER_CALLER.runtime.id &&
    message.from === Sender.React
  );
};

export const receiveMessageFromPopup = async (
  message: ChromeMessage,
  sender: chrome.runtime.MessageSender,
  response: MessageResponse
) => {
  const isValidated = validateSender(message, sender);

  if (!isValidated) return;

  const isMessagingTrigger = true;

  // SUB-20: the popup-save broadcast (globalSettingsPopupInterceptor →
  // sendToAllTabs) and the background kill-switch broadcast carry the PERSISTED
  // settings projection (mapFreeGlobalSettings capAllLists:false — selectedList
  // capped, but per-item `isRegexp` and queryList[] left INTACT for SUB-21
  // data-safety). Applied raw, that would run the PRO regex matcher for a free
  // user on every popup save. Re-run the TRANSIENT freemium converter here — the
  // same one `onStart` uses — so the in-tab highlight copy is fully clamped
  // (isRegexp off, all lists capped) regardless of the broadcast source. The
  // converter is a no-op for entitled users and never touches persisted storage.
  const globalSettings = await globalSettingsFreemiumConverter(
    message.message.globalSettings
  );

  // MSG-08: change-detection now gates the WORK, not the message. A valid
  // broadcast whose payload is JSON-equal to our cached settings is no longer
  // rejected up front (that dropped legitimate repair re-syncs); instead we
  // accept it, skip the (re-)apply when nothing changed, and still ACK so the
  // sender's response channel closes cleanly. `hasGlobalSettingsChanged` also
  // updates the cached snapshot as a side effect when the payload differs.
  if (hasGlobalSettingsChanged(globalSettings)) {
    // Toggle scrollbar highlighter based on settings
    if (globalSettings && globalSettings.scrollbarHighlighter !== undefined) {
      toggleScrollbarHighlighter(globalSettings.scrollbarHighlighter.isOn);
    }

    invokeBehaviour(globalSettings, isMessagingTrigger);
  }

  try {
    response({ success: true });
    // console.log("✅ Response sent!");
  } catch (error) {
    console.error("❌ Error in content.js + popup messaging:", error);
    response({ success: false, error: (error as any).message });
  }
};

// Exported async function with debounce logic
export const contentFileLogic = async (
  currentGlobalSettings: GlobalSettings,
  isObserver?: boolean,
  isMessagingTrigger?: boolean
) => {
  initSearchOnHotkey(currentGlobalSettings, isObserver);

  await collectAnalyticsData(
    currentGlobalSettings,
    isObserver,
    isMessagingTrigger
  );

  disableColorsOnKeyStroke(currentGlobalSettings, isObserver);

  navigation(currentGlobalSettings, isObserver, isMessagingTrigger);

  initSearchBySelect(currentGlobalSettings);

  // Cmd+F takeover lives next to the other content-script features and
  // honours its own isOn flag — boot is idempotent on settings changes.
  bootCmdFTakeover(currentGlobalSettings);

  // Form-field highlighting (beta, gated by formFieldHighlighting.isOn).
  // boot is a no-op when the setting is off; when on, it (re-)attaches
  // mirrors and arms the mutation observer for SPA-added textareas.
  bootFormFieldHighlights(currentGlobalSettings);
  // Any time the saved-query list changes, fields need a repaint pass —
  // the form-field module reads the live list on each repaint, but it
  // doesn't know on its own that the list mutated.
  repaintFormFieldHighlights();

  // Rich-editor highlighting (Lexical, ProseMirror, Tiptap, Monaco,
  // CodeMirror, Notion, plain contenteditable — anything that matches
  // EDITOR_FRAMEWORK_SELECTORS). Uses the CSS Custom Highlight API so
  // it paints without modifying the editor's DOM (which would otherwise
  // trip the editor's reconciler and revert the user's typed text). The
  // module self-feature-detects and no-ops on browsers without
  // CSS.highlights support.
  bootRichEditorHighlights(currentGlobalSettings);
  repaintRichEditorHighlights();
};

export const invokeBehaviour = async (
  currentGlobalSettings: GlobalSettings,
  isMessagingTrigger?: boolean
) => {
  const isNotEligible =
    !currentGlobalSettings ||
    isBlackListedSite(currentGlobalSettings) ||
    !isWhiteListedSite(currentGlobalSettings);

  if (isNotEligible) {
    // TGL-04: an origin can flip eligible→ineligible WHILE features are already
    // booted (the user blacklists the current site, or enables whitelist mode
    // without it — pushed here via the popup broadcast). Tearing down only the
    // observer would leave every <hility> mark, injected stylesheet, host,
    // badge, and keystroke listener live on a page the user just disabled. Run
    // the full teardown (switchOffCleanup calls destroyObserverLogic first, so
    // it's a strict superset; idempotent on a fresh ineligible load).
    switchOffCleanup();
    return;
  }

  // has to work even when the extension is turned off
  switchOffHotkey();

  if (!currentGlobalSettings.isExtensionOn) {
    // cleanup after turning off

    switchOffCleanup();
    return;
  }

  await contentFileLogic(currentGlobalSettings, false, isMessagingTrigger);
  observerLogic();
};

export const switchOffCleanup = () => {
  destroyObserverLogic();
  doUnmark();
  showFoundCountOnIconCleanup(); // removes the badge from the extension icon
  toggleScrollbarHighlighter(false); // disable scrollbar highlighter
  clearMinimap(); // Removes from DOM
  // Drop the per-feature listeners and any stylesheets/toasts the
  // user-toggleable features inject. The switchOffHotkey listener is
  // *not* aborted here — it has to keep running so Shift+T can flip the
  // extension back on.
  cleanupSearchBySelect();
  cleanupSearchOnHotkey();
  cleanupNavigation();
  cleanupDisableColors();
  clearToastDom();
  cleanupCmdFTakeover();
  cleanupFormFieldHighlights();
  cleanupRichEditorHighlights();
  removeAllHilityStylesheets();
};
