// Public entrypoint for the form-field-highlighting feature.
//
// boot(settings) — installs mirrors for currently-eligible textareas and
//                  arms discovery on future DOM mutations. Idempotent.
// cleanup()     — removes every mirror, every listener, and the global
//                  stylesheet. Safe to call when nothing is attached.
// repaintAll()  — forces a repaint pass; called from message handlers
//                  when the saved-query list changes in the popup so
//                  edits don't wait for the next field input.
//
// Discovery scope:
//   - Light DOM + every open shadow root reachable from the document.
//     This includes custom-element shadow roots (Reddit's
//     `<faceplate-textarea-input>`, `<faceplate-search-input>`, Material
//     Web `<md-filled-text-field>`, Shoelace, Spectrum, etc.) — the
//     non-mutating mirror leaves the source DOM pristine, so controlled
//     components no longer trip on our presence.
//   - Closed shadow roots are unreachable by the platform.
//
// Disable paths the host page can't override:
//   - extension off (isExtensionOn) → cleanup runs via switchOffCleanup
//   - blacklisted site → invokeBehaviour short-circuits and we are never
//     called; existing mirrors fall through to cleanup elsewhere
//   - formFieldHighlighting.isOn=false → boot is a no-op; if previously
//     true, the caller should run cleanup first

import { GlobalSettings, QueryItem } from "../../../definitions/global.definition";
import { QuerySearchOptions } from "../../../search/types";
import { getSearchOptions } from "../../../search/queryMatching";
import {
  createFieldMirror,
  FieldMirror,
  FormFieldElement,
  isEligibleField,
} from "./mirror";
import {
  injectStyles,
  removeOverlayRoot,
  removeStyles,
  OVERLAY_ROOT_ID,
} from "./styles";

interface FormFieldState {
  doc: Document;
  win: Window;
  mirrors: Map<FormFieldElement, FieldMirror>;
  // Top-level observer (light DOM under doc.body). Each open shadow root
  // we discover also gets its own observer — keyed below.
  observer: MutationObserver | null;
  // Per-shadow-root observers. We re-create one for each newly-encountered
  // open shadow root so SPAs adding textareas inside a web component still
  // get picked up. Closed shadow roots are unreachable by design and
  // documented as a phase-1 limitation.
  shadowObservers: Map<ShadowRoot, MutationObserver>;
  // Snapshot of current settings — the active queries and search options
  // are read on every repaint via getQueries()/getSearchOptions() closures,
  // so the snapshot only needs to be replaced when boot() runs.
  settings: GlobalSettings | null;
  pendingDiscovery: number;
}

let state: FormFieldState | null = null;

// Cumulative count of full discoverFields passes. Exposed via __testing so a
// test can prove our own overlay mutations do NOT schedule a discovery pass
// (FFH-01) while genuine page mutations still do. Not reset on cleanup —
// tests read a baseline before/after rather than assuming zero.
let discoveryRunCount = 0;

const isFormFieldHighlightingEnabled = (settings: GlobalSettings): boolean => {
  const cfg = settings.formFieldHighlighting;
  if (!cfg) return false;
  return Boolean(cfg.isOn);
};

// `position: fixed` is resolved against the layout viewport — UNLESS an
// ancestor has a transform/filter/perspective/will-change/backdrop-filter
// that establishes a new containing block. When that happens, our
// overlay (which uses position: fixed) becomes positioned relative to
// that ancestor instead, and its coordinates from getBoundingClientRect
// no longer map to the same coordinate system as the host's rect.
//
// The cure is intrusive — re-architect positioning around an absolute
// coordinate system that compensates for ancestor transforms. Instead,
// detect at boot time and skip the feature on those pages. The user sees
// no highlights inside fields on the affected site (vs. broken
// highlights they can't dismiss) and we log a one-time warning.
//
// Body and documentElement are the only ancestors of the overlay root
// (we append to body). If either of them has a transform context, the
// overlay is affected. Checking just those two is cheap.
const TRANSFORM_TRIGGERS: ReadonlyArray<keyof CSSStyleDeclaration> = [
  "transform",
  "perspective",
  "filter",
  "backdropFilter",
  "willChange",
];

const hasTransformContext = (
  el: Element | null,
  win: Window
): boolean => {
  if (!el || typeof win.getComputedStyle !== "function") return false;
  let cs: CSSStyleDeclaration;
  try {
    cs = win.getComputedStyle(el);
  } catch {
    return false;
  }
  for (const prop of TRANSFORM_TRIGGERS) {
    const value = (cs as any)[prop];
    if (typeof value !== "string") continue;
    if (prop === "willChange") {
      // will-change creates a containing block only when listing one of
      // the trigger properties.
      if (/transform|perspective|filter/.test(value)) return true;
      continue;
    }
    if (value && value !== "none" && value !== "normal") return true;
  }
  return false;
};

const overlayTopAncestorIsTransformed = (doc: Document, win: Window): boolean => {
  return (
    hasTransformContext(doc.body, win) ||
    hasTransformContext(doc.documentElement, win)
  );
};

let warnedAboutTransform = false;

const warnTransformSkipOnce = (): void => {
  if (warnedAboutTransform) return;
  warnedAboutTransform = true;
  // eslint-disable-next-line no-console
  console.warn(
    "[highlighty] form-field highlighting skipped: <body> or <html> has a transform / filter / perspective / will-change that breaks position:fixed positioning."
  );
};

const activeQueriesFrom = (settings: GlobalSettings): QueryItem[] => {
  return settings.queryListState?.selectedList?.itemList ?? [];
};

const searchOptionsFrom = (settings: GlobalSettings): QuerySearchOptions => {
  return getSearchOptions(settings);
};

const eligibilityOptsFrom = (_settings: GlobalSettings | null) => {
  // The popup currently exposes a single isOn toggle. The textareas /
  // textInputs sub-flags live in the type and storage so a future popup
  // version can opt into per-class granularity (e.g. "highlight in
  // textareas but not single-line inputs"). Until that UI exists we
  // ignore the stored sub-flags entirely — otherwise users with stale
  // storage from a pre-phase-2 build (whose seeded textInputs:false
  // never got migrated) would see inputs silently un-highlighted with no
  // popup control to fix it.
  //
  // Tests that want to verify the granular gate call isEligibleField
  // directly with explicit opts — that's the future extension point.
  return {
    includeTextareas: true,
    includeTextInputs: true,
  };
};

const FIELD_SELECTOR =
  "textarea, input[type=text], input[type=search], input[type=email], input[type=url], input[type=tel], input:not([type])";

/**
 * Collect every open shadow root reachable from `root`, recursively.
 * Closed shadow roots return null for `element.shadowRoot` and are
 * unreachable; that's a platform limitation.
 *
 * Note on Web Components: an earlier revision of this function skipped
 * shadow roots whose host was a custom element (tag name with a hyphen),
 * because the mirror was MUTATING the source — adding a transparent-text
 * class and a `data-highlighty-form-field` attribute that caused
 * controlled components (Reddit's `<faceplate-textarea-input>`, Material
 * Web text fields) to reset their synced state. The non-mutating mirror
 * doesn't touch the source DOM at all, so re-entering custom-element
 * shadow roots is now safe and we get coverage of every Web Component
 * input/textarea on the page (Reddit's navbar search, Material Web
 * components, Shoelace, Spectrum, et al.). Highlighty's own UI subtrees
 * are still skipped so we don't observe ourselves.
 */
export const collectOpenShadowRoots = (root: Document | Element): ShadowRoot[] => {
  const out: ShadowRoot[] = [];
  const startTarget: Element | null =
    root instanceof Document ? root.documentElement : root;
  if (!startTarget) return out;

  const visit = (node: Element) => {
    if (node.id === "highlighty-cmdf-host") return;
    if (
      node.hasAttribute("data-highlighty-overlay") ||
      node.hasAttribute("data-highlighty-cmdf") ||
      node.hasAttribute("data-highlighty-adhoc")
    ) {
      return;
    }
    const sr = (node as HTMLElement).shadowRoot;
    if (sr) {
      out.push(sr);
      Array.from(sr.children).forEach((c) => {
        if (c.nodeType === Node.ELEMENT_NODE) visit(c as Element);
      });
    }
    Array.from(node.children).forEach((c) => {
      if (c.nodeType === Node.ELEMENT_NODE) visit(c as Element);
    });
  };

  visit(startTarget);
  return out;
};

// True when a mutation originates from our OWN overlay layer (the overlay
// root + every mirror element inside it). The top-level observer watches the
// whole documentElement subtree, and the overlay lives under <body> inside
// that subtree, so without this guard the mirror's own work re-triggers the
// observer:
//   - syncLayout writes inline styles on every mirror (a `style` attribute
//     mutation, which passes the observer's attributeFilter), and
//   - repaints call replaceChildren on the mirror (a childList mutation).
// Each of those set `needsDiscovery` → a full-document discoverFields pass
// (querySelectorAll over the page + collectOpenShadowRoots walking every
// element). On scroll/keystroke that fires up to once per animation frame
// producing zero new mirrors — a self-inflicted discovery storm (FFH-01).
// repaintAll's syncLayout writes reach the same path (FFH-02). The overlay
// never lives inside a shadow root, so this is a no-op for shadow observers,
// but it's applied symmetrically for safety.
const isOwnOverlayMutation = (m: MutationRecord): boolean => {
  const t = m.target;
  if (!(t instanceof Element)) return false;
  // closest() includes the element itself, so a childList mutation whose
  // target IS the overlay root (a mirror being added/removed) also matches.
  return Boolean(t.closest(`#${OVERLAY_ROOT_ID}`));
};

const installShadowObserver = (s: FormFieldState, sr: ShadowRoot): void => {
  if (s.shadowObservers.has(sr)) return;
  const Ctor = (s.win as unknown as { MutationObserver?: typeof MutationObserver })
    .MutationObserver;
  if (typeof Ctor !== "function") return;
  const observer = new Ctor((mutations: MutationRecord[]) => {
    // Drop our own overlay-layer mutations so the mirror's style/childList
    // writes can't re-trigger discovery (see isOwnOverlayMutation / FFH-01).
    const relevant = mutations.filter((m) => !isOwnOverlayMutation(m));
    if (!relevant.length) return;
    let needsDiscovery = false;
    for (const m of relevant) {
      if (m.type === "childList" && (m.addedNodes.length || m.removedNodes.length)) {
        needsDiscovery = true;
        break;
      }
      if (m.type === "attributes") {
        needsDiscovery = true;
        break;
      }
    }
    if (needsDiscovery) scheduleDiscovery(s);
    repaintMutatedHosts(s, relevant);
  });
  s.shadowObservers.set(sr, observer);
  observer.observe(sr, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["disabled", "readonly", "hidden", "style", "class", "type"],
  });
};

const discoverFields = (s: FormFieldState): void => {
  discoveryRunCount++;
  const eligibilityOpts = eligibilityOptsFrom(s.settings);

  // Light DOM pass.
  const candidates: Element[] = Array.from(s.doc.querySelectorAll(FIELD_SELECTOR));

  // Shadow DOM pass. For each open shadow root, also query for fields AND
  // install an observer if we haven't already.
  const shadowRoots = collectOpenShadowRoots(s.doc);
  for (const sr of shadowRoots) {
    installShadowObserver(s, sr);
    Array.from(sr.querySelectorAll(FIELD_SELECTOR)).forEach((el) => candidates.push(el));
  }
  // Reap observers for shadow roots that have detached. (A web component
  // can be removed wholesale; the shadow root's `host` would no longer be
  // connected.)
  for (const [sr, obs] of s.shadowObservers) {
    if (!sr.host?.isConnected) {
      obs.disconnect();
      s.shadowObservers.delete(sr);
    }
  }

  candidates.forEach((el) => {
    if (s.mirrors.has(el as FormFieldElement)) return;
    if (!isEligibleField(el, eligibilityOpts)) return;
    const mirror = createFieldMirror(el as FormFieldElement, {
      doc: s.doc,
      getQueries: () => (s.settings ? activeQueriesFrom(s.settings) : []),
      getSearchOptions: () =>
        s.settings ? searchOptionsFrom(s.settings) : {
          caseSensitive: false,
          diacriticSensitive: false,
          splitSearch: false,
          completePhrase: false,
        },
    });
    s.mirrors.set(el as FormFieldElement, mirror);
  });

  // Reap mirrors whose host is no longer attachable. Two reasons:
  //   1) Host detached from the DOM. The mutation observer normally fires
  //      for these, but a parent's wholesale replace can sneak past the
  //      childList callback in some browser versions.
  //   2) Host is now ineligible per the active sub-flags (e.g. the user
  //      flipped textInputs off in the popup). Without this pass, the
  //      mirror would linger and the host would keep its transparent-text
  //      class until a page reload.
  for (const [host, mirror] of s.mirrors) {
    // Two reasons a tracked mirror's host might no longer deserve one:
    //   1) Host detached from the DOM. The mutation observer normally fires
    //      for these, but a parent's wholesale replace can sneak past the
    //      childList callback in some browser versions.
    //   2) Host is now ineligible per the active sub-flags (e.g. the user
    //      flipped textInputs off in the popup).
    // Under the non-mutating mirror the eligibility check is pure (no
    // DATA_MANAGED attribute is set on the source, so isEligibleField
    // returns a true reflection of the host's standalone state).
    if (!host.isConnected || !isEligibleField(host, eligibilityOpts)) {
      mirror.destroy();
      s.mirrors.delete(host);
    }
  }
};

const scheduleDiscovery = (s: FormFieldState): void => {
  if (s.pendingDiscovery) return;
  const raf =
    typeof s.win.requestAnimationFrame === "function"
      ? s.win.requestAnimationFrame.bind(s.win)
      : (cb: FrameRequestCallback) => s.win.setTimeout(() => cb(0), 16);
  s.pendingDiscovery = raf(() => {
    s.pendingDiscovery = 0;
    discoverFields(s);
  });
};

// React to attribute mutations on a single managed host. JS-driven style
// changes (drag-drop reordering, CSS transition end, dark-mode class flip,
// inline transform) need to re-sync layout AND re-capture the source's
// color in case the theme changed. scheduleRepaint is rAF-coalesced so
// bursts of mutations from the same tick fold to one repaint.
//
// Repaint any mirror whose host's attributes change. The non-mutating
// mirror itself never writes to the source, so we no longer have to
// worry about feedback loops from self-mutations — every attribute
// change here is genuinely page-driven and worth a repaint.
//
// Pre-non-mutating this function ALSO called mirror.recaptureColor() to
// follow source's text-color through theme flips. The non-mutating
// mirror's color is uniformly transparent (the source's own glyphs
// supply the visible text) so there is nothing to recapture; the
// theme-switch handling is therefore just a plain repaint.
const repaintMutatedHosts = (
  s: FormFieldState,
  mutations: MutationRecord[]
): void => {
  const themeMutation = mutations.some(
    (m) =>
      m.type === "attributes" &&
      (m.attributeName === "class" || m.attributeName === "style") &&
      (m.target === s.doc.body || m.target === s.doc.documentElement)
  );
  if (themeMutation) {
    // FFH-03: a transform / filter / perspective / will-change applied to
    // <body> or <html> AFTER boot turns the mirror's position:fixed into
    // positioning relative to that ancestor, so every overlay drifts off its
    // field with no recovery — the boot-time guard runs only once and can't
    // catch this. A transform is applied via exactly these style/class
    // mutations, so re-check here and tear down (matching boot's "skip on a
    // transformed ancestor" behavior): the user sees no highlights rather than
    // broken ones they can't dismiss. Re-enables on the next boot (settings
    // change / navigation) once the transform is gone.
    if (overlayTopAncestorIsTransformed(s.doc, s.win)) {
      warnTransformSkipOnce();
      cleanup(s.doc);
      return;
    }
    for (const mirror of s.mirrors.values()) mirror.repaint();
    return;
  }
  for (const m of mutations) {
    if (m.type !== "attributes") continue;
    const t = m.target;
    if (!(t instanceof Element)) continue;
    const mirror = s.mirrors.get(t as FormFieldElement);
    if (!mirror) continue;
    mirror.repaint();
  }
};

const installObserver = (s: FormFieldState): void => {
  if (s.observer) return;
  const Ctor = (s.win as unknown as { MutationObserver?: typeof MutationObserver })
    .MutationObserver;
  if (typeof Ctor !== "function") return;
  const observer = new Ctor((mutations: MutationRecord[]) => {
    // Drop our own overlay-layer mutations FIRST. The overlay lives under
    // <body>, inside this observer's subtree, so the mirror's syncLayout
    // style writes and replaceChildren repaints would otherwise re-trigger
    // a full-document discovery on every scroll frame / keystroke (FFH-01)
    // and on every repaintAll (FFH-02). See isOwnOverlayMutation.
    const relevant = mutations.filter((m) => !isOwnOverlayMutation(m));
    if (!relevant.length) return;
    // Most pages with form fields use SPA frameworks that add/remove
    // textareas in bursts. rAF-coalesce discovery to keep the cost down.
    let needsDiscovery = false;
    for (const m of relevant) {
      if (m.type === "childList" && (m.addedNodes.length || m.removedNodes.length)) {
        needsDiscovery = true;
        break;
      }
      if (m.type === "attributes") {
        // disabled/readonly toggles need a re-eligibility check.
        needsDiscovery = true;
        break;
      }
    }
    if (needsDiscovery) scheduleDiscovery(s);
    // Even if discovery is scheduled, also repaint any managed hosts that
    // mutated. Their position/style may have changed in ways discovery
    // doesn't notice (style attr → no eligibility shift, but layout DOES
    // need to follow).
    repaintMutatedHosts(s, relevant);
  });
  s.observer = observer;
  // Observe the documentElement (not body) so a class change on <html>
  // (the standard dark-mode toggle pattern) also fires this listener.
  // Subtree:true still catches every descendant under it.
  const observeRoot = s.doc.documentElement ?? s.doc.body;
  if (!observeRoot) return;
  observer.observe(observeRoot, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["disabled", "readonly", "hidden", "style", "class", "wrap"],
  });
};

export const boot = (
  settings: GlobalSettings,
  doc: Document = document,
  win: Window = window
): void => {
  if (!isFormFieldHighlightingEnabled(settings)) {
    cleanup(doc);
    return;
  }

  // Skip on pages with a transformed body / documentElement. The mirror's
  // position: fixed would be resolved against the transformed ancestor
  // instead of the viewport and visibly misalign with the field.
  if (overlayTopAncestorIsTransformed(doc, win)) {
    warnTransformSkipOnce();
    cleanup(doc);
    return;
  }

  if (!state) {
    state = {
      doc,
      win,
      mirrors: new Map(),
      observer: null,
      shadowObservers: new Map(),
      settings,
      pendingDiscovery: 0,
    };
    injectStyles(doc);
  } else {
    state.settings = settings;
  }

  installObserver(state);
  discoverFields(state);
};

export const repaintAll = (): void => {
  if (!state) return;
  // A query-list change can affect every field's match set, so trigger
  // a repaint on each — cheap because the mirror skips DOM writes when
  // its matches-key is unchanged.
  for (const mirror of state.mirrors.values()) mirror.repaint();
};

export const cleanup = (doc: Document = document): void => {
  if (!state) {
    // Stylesheet/overlay can survive a partial init; clear them too so the
    // page is fully restored.
    removeOverlayRoot(doc);
    removeStyles(doc);
    return;
  }
  if (state.pendingDiscovery && state.win.cancelAnimationFrame) {
    state.win.cancelAnimationFrame(state.pendingDiscovery);
  }
  state.observer?.disconnect();
  state.observer = null;
  for (const obs of state.shadowObservers.values()) obs.disconnect();
  state.shadowObservers.clear();
  for (const mirror of state.mirrors.values()) mirror.destroy();
  state.mirrors.clear();
  removeOverlayRoot(state.doc);
  removeStyles(state.doc);
  state = null;
};

export const __testing = {
  getMirrorCount: () => state?.mirrors.size ?? 0,
  hasState: () => state !== null,
  isFormFieldHighlightingEnabled,
  getDiscoveryCount: () => discoveryRunCount,
  isOwnOverlayMutation,
};
