import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { QueryItem } from "../../../../definitions/global.definition";
import { rgbFormatter } from "../../../../components/shared/utils/color.utils";
import Tooltip from "./Tooltip";

export interface ChipModel {
  query: QueryItem;
  count: number;
}

export interface ChipsProps {
  chips: ChipModel[];
  activeQueryId: string | null;
  onChipClick: (queryId: string) => void;
  onChipRemove: (queryId: string) => void;
}

// Cap the inline chips so the strip stays scannable when a user has 10–25+
// saved queries. Anything past this rolls into the "+N more" overflow menu.
// 5 fits comfortably alongside the input + modifiers + Save button at the
// default 1280px viewport without forcing the bar into max-width clamp.
export const MAX_INLINE_CHIPS = 5;

const swatchFor = (q: QueryItem) =>
  q.colors?.rgb ? rgbFormatter(q.colors) : "rgba(255,255,255,0.40)";

const Chips: React.FC<ChipsProps> = ({
  chips,
  activeQueryId,
  onChipClick,
  onChipRemove,
}) => {
  // Two filters:
  //   1. Inactive saved highlights stay in the library but disappear from
  //      the bar — right-click "closes" the pill rather than greying it.
  //   2. Hide chips that don't match anything on the current page. With
  //      many saved queries this is the difference between a useful "what
  //      hit on this page" strip and a noisy "list of everything you've
  //      ever saved". Full library is still in the popup.
  const visible = chips.filter(
    ({ query, count }) => !query.isInactive && count > 0
  );
  if (!visible.length) return null;
  const inline = visible.slice(0, MAX_INLINE_CHIPS);
  const overflow = visible.slice(MAX_INLINE_CHIPS);

  return (
    <div className="chips" role="list" aria-label="Saved highlights matching this page">
      {inline.map(({ query, count }) => {
        const swatch = swatchFor(query);
        const isActive = activeQueryId === query.id;
        const tipLabel = `${query.name} — ${count} match${count === 1 ? "" : "es"}`;
        return (
          <Tooltip
            key={query.id}
            label={tipLabel}
            shortcut="Click: cycle matches · Right-click: remove"
          >
            <button
              type="button"
              role="listitem"
              className={"chip" + (isActive ? " active" : "")}
              aria-label={`${query.name}, ${count} matches. Click to cycle through matches, right-click to remove.`}
              onClick={() => onChipClick(query.id)}
              onContextMenu={(e) => {
                e.preventDefault();
                onChipRemove(query.id);
              }}
            >
              <span className="swatch" style={{ background: swatch }} aria-hidden="true" />
              <span className="cname">{query.name}</span>
              <span className="ccount">{count}</span>
            </button>
          </Tooltip>
        );
      })}
      {overflow.length > 0 && (
        <ChipOverflow
          chips={overflow}
          onChipClick={onChipClick}
          onChipRemove={onChipRemove}
        />
      )}
    </div>
  );
};

interface ChipOverflowProps {
  chips: ChipModel[];
  onChipClick: (queryId: string) => void;
  onChipRemove: (queryId: string) => void;
}

const ChipOverflow: React.FC<ChipOverflowProps> = ({
  chips,
  onChipClick,
  onChipRemove,
}) => {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLSpanElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const popRef = useRef<HTMLDivElement | null>(null);
  // Popover is positioned with fixed coordinates so it escapes the
  // chip strip's overflow:hidden clip. Computed from the button's
  // bounding rect once we know the popover is mounted.
  const [pos, setPos] = useState<{ top: number; right: number } | null>(null);

  useLayoutEffect(() => {
    if (!open || !buttonRef.current) {
      setPos(null);
      return;
    }
    const r = buttonRef.current.getBoundingClientRect();
    setPos({
      top: r.bottom + 6,
      // anchor to the button's right edge, measured from the viewport's
      // right edge — keeps the popover from drifting off-screen on
      // narrow windows.
      right: Math.max(6, window.innerWidth - r.right),
    });
  }, [open, chips.length]);

  // Close on outside click / Escape so the popover behaves like a menu.
  // composedPath() is used (instead of e.target) because the wrap lives
  // inside the bar's shadow DOM — at the document level e.target is
  // retargeted to the shadow host, which Node.contains() can't see
  // through. composedPath walks the full path including shadow content.
  useEffect(() => {
    if (!open) return;
    const onDocClick = (e: MouseEvent) => {
      const path = e.composedPath();
      if (wrapRef.current && path.includes(wrapRef.current)) return;
      if (popRef.current && path.includes(popRef.current)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDocClick, true);
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("mousedown", onDocClick, true);
      document.removeEventListener("keydown", onKey, true);
    };
  }, [open]);

  // If the overflow set drops to 0 (last remaining was removed or
  // matched-out), close so we don't leave an empty panel up.
  useLayoutEffect(() => {
    if (open && chips.length === 0) setOpen(false);
  }, [open, chips.length]);

  return (
    <>
      <span className="chip-overflow-wrap" ref={wrapRef}>
        <Tooltip
          label={`${chips.length} more matching ${chips.length === 1 ? "highlight" : "highlights"}`}
          shortcut="Click to expand"
        >
          <button
            ref={buttonRef}
            type="button"
            className={"chip chip-overflow" + (open ? " open" : "")}
            aria-haspopup="menu"
            aria-expanded={open}
            aria-label={`Show ${chips.length} more matching highlight${chips.length === 1 ? "" : "s"}`}
            onClick={() => setOpen((v) => !v)}
          >
            +{chips.length} more
          </button>
        </Tooltip>
      </span>
      {open && pos &&
        createPortal(
          // Render outside the shadow DOM so the popover stacks above
          // any same-z-index page-level overlay (e.g. the minimap host,
          // which also pins itself to z-index 2147483647 and would
          // otherwise intercept pointer events when its bounds overlap).
          // Styles are inline so the page's CSS can't reach in either.
          <div
            ref={popRef}
            role="menu"
            aria-label="More matching saved highlights"
            data-highlighty-chip-overflow-pop=""
            style={POPOVER_STYLE(pos)}
          >
            {chips.map(({ query, count }) => {
              const swatch = swatchFor(query);
              return (
                <button
                  key={query.id}
                  type="button"
                  role="menuitem"
                  data-highlighty-chip-overflow-row=""
                  aria-label={`${query.name}, ${count} matches. Click to cycle through matches, right-click to remove.`}
                  style={POPOVER_ROW_STYLE}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLElement).style.background =
                      "rgba(118, 244, 233, 0.10)";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLElement).style.background =
                      "transparent";
                  }}
                  onClick={() => {
                    onChipClick(query.id);
                    setOpen(false);
                  }}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    onChipRemove(query.id);
                  }}
                >
                  <span
                    style={{
                      width: 8,
                      height: 8,
                      borderRadius: "50%",
                      display: "inline-block",
                      flex: "0 0 auto",
                      background: swatch,
                      boxShadow: "inset 0 0 0 1px rgba(0,0,0,0.20)",
                    }}
                    aria-hidden="true"
                  />
                  <span style={POPOVER_NAME_STYLE}>{query.name}</span>
                  <span style={POPOVER_COUNT_STYLE}>{count}</span>
                </button>
              );
            })}
          </div>,
          // documentElement, not body — the bar and minimap inject their
          // hosts as direct children of <html> (after <body>). Portaling
          // to body would put the popover BEFORE both hosts in document
          // order, so it'd lose the same-z stacking tiebreak to the
          // minimap. Portaling to html appends after them.
          document.documentElement
        )}
    </>
  );
};

// Inline styles so the page's CSS doesn't reach the portaled popover.
// (The shadow DOM stylesheet doesn't apply once we leave the shadow tree.)
const POPOVER_STYLE = (pos: { top: number; right: number }): React.CSSProperties => ({
  position: "fixed",
  top: pos.top,
  right: pos.right,
  minWidth: 220,
  maxWidth: 360,
  maxHeight: 280,
  overflowY: "auto",
  background: "#14161b",
  border: "1px solid rgba(172, 137, 245, 0.30)",
  borderRadius: 6,
  boxShadow: "0 8px 24px rgba(0, 0, 0, 0.40)",
  padding: 4,
  display: "flex",
  flexDirection: "column",
  gap: 2,
  zIndex: 2147483647,
  pointerEvents: "auto",
  font: "12px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  color: "rgba(245, 246, 248, 0.92)",
});
const POPOVER_ROW_STYLE: React.CSSProperties = {
  all: "unset",
  display: "inline-flex",
  alignItems: "center",
  gap: 8,
  padding: "6px 10px",
  borderRadius: 4,
  cursor: "pointer",
  fontSize: 12,
  color: "rgba(245, 246, 248, 0.92)",
  background: "transparent",
  transition: "background 80ms ease, color 80ms ease",
};
const POPOVER_NAME_STYLE: React.CSSProperties = {
  flex: "1 1 auto",
  minWidth: 0,
  overflow: "hidden",
  textOverflow: "ellipsis",
  whiteSpace: "nowrap",
};
const POPOVER_COUNT_STYLE: React.CSSProperties = {
  fontVariantNumeric: "tabular-nums",
  opacity: 0.65,
  fontWeight: 600,
  flex: "0 0 auto",
};

export default Chips;
