import { QueryItem } from "../../../definitions/global.definition";
import { adaptiveFontColor, hslFormatter } from "../../../components/shared/utils/color.utils";
import {
  dataHility,
  dataHilityMatch,
  dataHilityName,
  hilityTag,
} from "../../content.consts";

/**
 * Convert decoration thickness setting to CSS value
 */
export const getThicknessValue = (thickness?: string): string => {
  return thickness === "thin"
    ? "3px"
    : thickness === "medium"
    ? "4px"
    : thickness === "thick"
    ? "5px"
    : thickness === "very-thick"
    ? "6px"
    : thickness === "extra-thick"
    ? "7px"
    : "auto";
};

/**
 * Helper function to generate CSS for different decoration types
 */
export const getDecorationCSS = (queryItem: QueryItem): string => {
  // Defensive: corrupted/upgraded storage occasionally lands a QueryItem
  // without a `colors` object. Fall back to a neutral grey so the rest of
  // the highlight pass still runs.
  const safeHsl = queryItem.colors?.hsl ?? { h: 0, s: 0, l: 70, a: 1 };
  const color = hslFormatter(safeHsl);
  // Ensure we're using the decoration type from the queryItem, defaulting to 'background'
  const type = queryItem.decorationType || "background";
  const thickness = queryItem.decorationThickness || "medium";

  // Get thickness value using the shared function
  const thicknessValue = getThicknessValue(thickness);

  // Log the decoration type and thickness for debugging
  // console.log(`Applying decoration: ${type}, thickness: ${thickness}, color: ${color}`);

  switch (type) {
    case "background":
      // !important on background + color so hostile page rules
      // (e.g. `hility { background: transparent !important }` published by
      // sites trying to defeat highlight extensions) lose the duel even at
      // equal specificity.
      return `
        background: ${color} !important;
        color: ${adaptiveFontColor(safeHsl, true)} !important;
        height: 100%;
        border-radius: 4px;
        box-shadow: 0px 0px 3px 0px rgba(0, 0, 0, 0.65);
      `;
    case "underline":
      return `
        text-decoration-line: underline;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    case "overline":
      return `
        text-decoration-line: overline;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    case "line-through":
      return `
        text-decoration-line: line-through;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    case "dotted-underline":
      return `
        text-decoration-line: underline;
        text-decoration-style: dotted;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    case "wavy-underline":
      return `
        text-decoration-line: underline;
        text-decoration-style: wavy;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    case "double-underline":
      return `
        text-decoration-line: underline;
        text-decoration-style: double;
        text-decoration-color: ${color};
        text-decoration-thickness: ${thicknessValue};
        background: transparent;
        color: inherit;
      `;
    default:
      return `
        background: ${color};
        color: ${adaptiveFontColor(safeHsl, true)};
        height: 100%;
        border-radius: 4px;
        box-shadow: 0px 0px 3px 0px rgba(0, 0, 0, 0.65);
      `;
  }
};

export const buildHighlightMatchId = (
  matchIndex: number,
  highlightPassId?: string
) => (highlightPassId ? `${highlightPassId}:${matchIndex}` : String(matchIndex));

/**
 * Apply ONLY the visual decoration styles to an element. Separated from
 * applyDecorationToMark so consumers that don't want the mark.js metadata
 * (data-hility, role="mark", data-hility-match) — like the form-field
 * mirror's per-match spans — can render identical visuals without
 * inheriting attributes that other subsystems use to find saved-highlight
 * marks. Pass the same QueryItem and the result will look the same as a
 * mark.js-rendered `<hility>` for that query.
 */
export const applyVisualDecorationToElement = (
  el: HTMLElement,
  item: QueryItem
): void => {
  const decorationType = item.decorationType || "background";
  const thicknessValue = getThicknessValue(item.decorationThickness);

  // Set CSS variable for thickness so the addTextDecorationFallbacks
  // stylesheet can match its `[style*="--decoration-thickness: Npx"]`
  // selectors if a consumer chooses to opt into the fallback styles.
  el.style.setProperty("--decoration-thickness", thicknessValue);
  el.setAttribute("data-decoration-type", decorationType);

  if (decorationType === "background") {
    // Background is the implicit default for the mirror — no inline
    // styling needed beyond what the caller set (e.g. backgroundColor).
    return;
  }

  const safeHsl = item.colors?.hsl ?? { h: 0, s: 0, l: 70, a: 1 };
  const color = hslFormatter(safeHsl);

  // Always reset background so a previous decorationType (e.g. background)
  // doesn't leak through when the user changes the type on an existing
  // query — relevant for the form-field mirror since spans get reused
  // across repaints when no values changed.
  el.style.background = "transparent";

  switch (decorationType) {
    case "underline":
      el.style.textDecorationLine = "underline";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
    case "overline":
      el.style.textDecorationLine = "overline";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
    case "line-through":
      el.style.textDecorationLine = "line-through";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
    case "dotted-underline":
      el.style.textDecorationLine = "underline";
      el.style.textDecorationStyle = "dotted";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
    case "wavy-underline":
      el.style.textDecorationLine = "underline";
      el.style.textDecorationStyle = "wavy";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
    case "double-underline":
      el.style.textDecorationLine = "underline";
      el.style.textDecorationStyle = "double";
      el.style.textDecorationColor = color;
      el.style.textDecorationThickness = thicknessValue;
      break;
  }
};

/**
 * Apply decoration styles to a mark element based on the query item's decoration settings
 */
export const applyDecorationToMark = (
  mark: HTMLElement,
  item: QueryItem,
  matchIndex?: number,
  highlightPassId?: string
) => {
  // ARIA: a11y tools (screen readers, search-tools) recognise `role="mark"`
  // as a highlighted phrase. Our custom `<hility>` element doesn't carry
  // implicit semantics, so we set it explicitly.
  mark.setAttribute("role", "mark");

  // Set the data attribute for the highlight ID
  mark.setAttribute(dataHility, item.id);

  // Friendly query name — consumed by the scrollbar strip tooltip so it can
  // surface the user-visible query label rather than the synthetic queryId.
  if (item.name) {
    mark.setAttribute(dataHilityName, item.name);
  }

  if (typeof matchIndex === "number" && Number.isFinite(matchIndex)) {
    mark.setAttribute(
      dataHilityMatch,
      buildHighlightMatchId(matchIndex, highlightPassId)
    );
  }

  // Delegate the visual part so mark.js spans and form-field mirror spans
  // can never visually diverge — they share a single source of truth.
  applyVisualDecorationToElement(mark, item);
};

/**
 * Add browser compatibility fallbacks for text decoration styles
 */
export const addTextDecorationFallbacks = () => {
  // Check if we've already added the fallbacks. Scope to <head> and
  // tag-name so a page-owned element with the same id can't trick us
  // into bailing early (which would mean fallback styles never apply).
  if (
    document.head.querySelector(
      "style#highlighty-text-decoration-fallbacks"
    )
  ) {
    return;
  }

  // console.log("Adding text decoration fallbacks");

  // HLE-07: the old per-query `colorRules` block was captured here, once, from
  // `[data-hility]` elements that don't exist yet on first run (this is called
  // BEFORE any <hility> is wrapped), and the self-lock above then prevented it
  // from ever being rebuilt — so the block was dead on first run and stale on
  // later color edits. It was also redundant: `generateHilityStylesheet`
  // already emits an equivalent, ALWAYS-refreshed per-query color rule
  // (`hility[data-hility="<id>"] { text-decoration-color … !important }`) into
  // each query's own [css-hility] sheet (which is likewise cloned into iframe
  // heads). Folding the per-query color into that always-current sheet — and
  // dropping the frozen copy here — is the minimal correct fix. This fallback
  // sheet now carries only the static, query-independent decoration fallbacks,
  // so building it once is correct.

  const fallbackStyles = document.createElement("style");
  fallbackStyles.id = "highlighty-text-decoration-fallbacks";
  fallbackStyles.textContent = `
    /* Basic fallbacks for all decoration types - using individual properties instead of shorthand */
    ${hilityTag}[data-decoration-type="underline"] {
      text-decoration-line: underline !important;
      text-decoration-thickness: var(--decoration-thickness, 2px) !important;
      background: transparent !important;
    }

    ${hilityTag}[data-decoration-type="overline"] {
      text-decoration-line: overline !important;
      text-decoration-thickness: var(--decoration-thickness, 2px) !important;
      background: transparent !important;
    }

    ${hilityTag}[data-decoration-type="line-through"] {
      text-decoration-line: line-through !important;
      text-decoration-thickness: var(--decoration-thickness, 2px) !important;
      background: transparent !important;
    }

    /* Thickness-specific styles */
    ${hilityTag}[data-decoration-type][style*="--decoration-thickness: 1px"] {
      text-decoration-thickness: 1px !important;
    }

    ${hilityTag}[data-decoration-type][style*="--decoration-thickness: 2px"] {
      text-decoration-thickness: 2px !important;
    }

    ${hilityTag}[data-decoration-type][style*="--decoration-thickness: 3px"] {
      text-decoration-thickness: 3px !important;
    }

    ${hilityTag}[data-decoration-type][style*="--decoration-thickness: 4px"] {
      text-decoration-thickness: 4px !important;
    }

    ${hilityTag}[data-decoration-type][style*="--decoration-thickness: 5px"] {
      text-decoration-thickness: 5px !important;
    }

    /* Fallbacks for browsers that don't support text-decoration-style */
    @supports not (text-decoration-style: dotted) {
      ${hilityTag}[data-decoration-type="dotted-underline"] {
        border-bottom-style: dotted !important;
        border-bottom-width: var(--decoration-thickness, 2px) !important;
        text-decoration: none !important;
      }

      ${hilityTag}[data-decoration-type="wavy-underline"] {
        border-bottom-style: solid !important;
        border-bottom-width: var(--decoration-thickness, 2px) !important;
        text-decoration: none !important;
      }

      ${hilityTag}[data-decoration-type="double-underline"] {
        border-bottom-style: double !important;
        border-bottom-width: var(--decoration-thickness, 3px) !important;
        text-decoration: none !important;
      }
    }

    /* Styles for browsers that do support text-decoration-style */
    @supports (text-decoration-style: dotted) {
      ${hilityTag}[data-decoration-type="dotted-underline"] {
        text-decoration-line: underline !important;
        text-decoration-style: dotted !important;
        text-decoration-thickness: var(--decoration-thickness, 2px) !important;
        background: transparent !important;
      }

      ${hilityTag}[data-decoration-type="wavy-underline"] {
        text-decoration-line: underline !important;
        text-decoration-style: wavy !important;
        text-decoration-thickness: var(--decoration-thickness, 2px) !important;
        background: transparent !important;
      }

      ${hilityTag}[data-decoration-type="double-underline"] {
        text-decoration-line: underline !important;
        text-decoration-style: double !important;
        text-decoration-thickness: var(--decoration-thickness, 3px) !important;
        background: transparent !important;
      }
    }
  `;

  document.head.appendChild(fallbackStyles);
};
