// Detects a Cmd/Ctrl+F press within DOUBLE_PRESS_WINDOW_MS of the previous
// one. Used to drive native handoff: first press opens our bar, second
// press within the window closes it and arms a suppression window so the
// user's *next* Cmd+F passes through to native.

export const DOUBLE_PRESS_WINDOW_MS = 400;

let lastPressAt = 0;

export const isDoublePress = (now: number = Date.now()): boolean => {
  const isDouble = lastPressAt > 0 && now - lastPressAt <= DOUBLE_PRESS_WINDOW_MS;
  lastPressAt = now;
  if (isDouble) lastPressAt = 0;
  return isDouble;
};

export const reset = () => {
  lastPressAt = 0;
};

export const __getLastPressAt = () => lastPressAt;
