// Synchronous mirror of the two booleans needed to decide whether to
// install the Cmd+F intercept at content-script entry, before async
// chrome.storage.local hydration completes. Read at document_start;
// written every time canonical settings persist.
//
// Writing the cache in the same call as setStorageDataLocal keeps these
// two stores in sync in steady state. The only divergence window is "user
// toggled in another tab → opens a fresh tab whose cache is stale for one
// keypress" — acceptable, self-corrects on next press.

const KEY_ON = "highlighty.cmdf.on";
const KEY_BL = "highlighty.cmdf.bl";

export interface FastBoot {
  on: boolean;
  blacklist: string[];
}

const safeStorage = (): Storage | null => {
  try {
    if (typeof localStorage === "undefined") return null;
    return localStorage;
  } catch {
    return null;
  }
};

export const readFastBoot = (): FastBoot => {
  const ls = safeStorage();
  if (!ls) return { on: false, blacklist: [] };
  let on = false;
  let blacklist: string[] = [];
  try {
    on = ls.getItem(KEY_ON) === "1";
  } catch {}
  try {
    const raw = ls.getItem(KEY_BL);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed))
        blacklist = parsed.filter((x) => typeof x === "string");
    }
  } catch {}
  return { on, blacklist };
};

export const writeFastBoot = (val: FastBoot): void => {
  const ls = safeStorage();
  if (!ls) return;
  try {
    ls.setItem(KEY_ON, val.on ? "1" : "0");
    ls.setItem(KEY_BL, JSON.stringify(val.blacklist));
  } catch {}
};

export const clearFastBoot = (): void => {
  const ls = safeStorage();
  if (!ls) return;
  try {
    ls.removeItem(KEY_ON);
    ls.removeItem(KEY_BL);
  } catch {}
};
