import { useEffect, useState } from "react";
import {
  PremiumFeatureAccessState,
  getPremiumFeatureAccessState,
} from "../../../../components/shared/utils/premiumFeature.utils";
import { UserSubscription } from "../../../../definitions/global.definition";
import { getStorageDataLocal } from "../../../chrome.utils";

// Reads the user's subscription out of chrome.storage.local and resolves
// to "free" / "trial" / "paid". Used by the bar to distinguish trial
// users from paid users so trial-state PRO modifiers get a "✨TRIAL"
// hint instead of "🔐PRO" — same access, but a reminder that the
// window for upgrade is finite.
//
// Defaults to "free" before resolution, and stays "free" if the storage read
// fails. This is a FAIL-CLOSED default: the bar shows PRO chips to free users in
// a locked state, so defaulting to "paid"/"trial" (the old behavior) flashed an
// UNLOCKED treatment to free users on first paint and — on a failed read — left
// it unlocked for the bar's lifetime (SUB-03). Paid/trial users briefly see the
// locked state for the ~5 ms storage round-trip, then it elevates on resolve.
export const useCmdFAccessState = (): PremiumFeatureAccessState => {
  const [state, setState] = useState<PremiumFeatureAccessState>("free");
  useEffect(() => {
    let cancelled = false;
    const promise = getStorageDataLocal<{ subscription?: UserSubscription }>(
      "subscription"
    );
    if (!promise) return;
    promise
      .then((result) => {
        if (cancelled) return;
        setState(getPremiumFeatureAccessState(result?.subscription ?? null));
      })
      .catch(() => {
        /* storage unavailable — stay on the fail-closed "free" default */
      });
    return () => {
      cancelled = true;
    };
  }, []);
  return state;
};
