import { getStorageDataLocal, setStorageDataLocal } from "../chrome.utils";
import { GlobalSettings } from "../../definitions/global.definition";

// SUB-27: persist an owned-key delta WITHOUT clobbering the RAW stored settings
// with the freemium-clamped runtime projection. Reads the current *raw*
// globalSettings fresh from storage, applies `patch`, writes it back. Every
// content-side writer must persist through this — never `setStorageDataLocal({
// globalSettings: {...currentGlobalSettings, ...}})`, which for a free/lapsed
// user is the clamped copy (persisting it permanently truncates lists / strips
// flags). A fresh read (not a cached snapshot) also avoids reviving stale state
// after a missed broadcast.
export const persistGlobalSettingsDelta = async (
  patch: (raw: GlobalSettings) => GlobalSettings
): Promise<void> => {
  const stored = (await getStorageDataLocal("globalSettings")) as
    | { globalSettings?: GlobalSettings }
    | undefined;
  const raw = stored?.globalSettings;
  if (!raw) return; // nothing persisted yet — never create storage from a clamped copy
  await setStorageDataLocal({ globalSettings: patch(raw) });
};
