// Notification bus fired once at the end of every settled highlight pass
// in content.highlight.ts (i.e. after waitForPostHighlightSync's debounce
// and scrollbar/minimap sync). Subscribers piggyback on this signal to
// recompute DOM-derived state that depends on the painted <hility> set —
// notably the Cmd+F bar's saved-query chip counts, which must reflect
// the current visible set after content shows/hides (nav drawers,
// accordions, SPA route changes).
//
// Kept as its own module rather than a callback property on
// content.highlight.ts because (a) cmdFTakeover imports from many
// shared modules already and a circular dependency through
// content.highlight is easy to introduce, and (b) it isolates the
// listener-storage semantics so we can unit-test add/dispose/fire
// without spinning up the whole highlight pipeline.

type Listener = () => void;

const listeners = new Set<Listener>();

export const addPostHighlightListener = (cb: Listener): (() => void) => {
  listeners.add(cb);
  // Returned dispose closes over the original reference so listeners.delete
  // works even if the caller has wrapped/forgotten its own copy.
  return () => {
    listeners.delete(cb);
  };
};

export const firePostHighlightListeners = (): void => {
  // Snapshot before iterating: a listener that disposes itself (or another
  // listener) during the flush would otherwise mutate the live Set mid-loop.
  const snapshot = Array.from(listeners);
  for (const cb of snapshot) {
    try {
      cb();
    } catch {
      // Swallow per-listener errors so one bad subscriber can't block the
      // rest of the post-highlight hooks (or the highlight pass itself,
      // which awaits this fire).
    }
  }
};

export const __testing = {
  reset: () => listeners.clear(),
};
