// Lightweight tooltip kept inside the Cmd+F bar's shadow root. Wraps a
// single child element, injects aria-describedby, and shows the bubble on
// hover (after a short delay) or focus (immediate). Pure inline styles so
// it doesn't depend on the bar's stylesheet.

import React, { useEffect, useId, useLayoutEffect, useRef, useState } from "react";

const HOVER_DELAY_MS = 400;
const FADE_MS = 60;

export interface TooltipProps {
  label: string;
  shortcut?: string;
  hint?: string;
  children: React.ReactElement;
  placement?: "top" | "bottom";
}

const Tooltip: React.FC<TooltipProps> = ({
  label,
  shortcut,
  hint,
  children,
  placement = "top",
}) => {
  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState<{ top: number; left: number }>({
    top: -9999,
    left: -9999,
  });
  const [measured, setMeasured] = useState(false);
  const triggerRef = useRef<HTMLElement | null>(null);
  const bubbleRef = useRef<HTMLDivElement | null>(null);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const id = useId();

  const show = (immediate: boolean) => {
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
    if (immediate) {
      setOpen(true);
    } else {
      hoverTimer.current = setTimeout(() => setOpen(true), HOVER_DELAY_MS);
    }
  };
  const hide = () => {
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
    setOpen(false);
  };

  useEffect(() => () => {
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
  }, []);

  useLayoutEffect(() => {
    if (!open) {
      setMeasured(false);
      return;
    }
    if (!triggerRef.current || !bubbleRef.current) return;
    const tr = triggerRef.current.getBoundingClientRect();
    const bubble = bubbleRef.current;
    const bubbleH = bubble.offsetHeight;
    const bubbleW = bubble.offsetWidth;
    const wantedTop =
      placement === "top" ? tr.top - bubbleH - 6 : tr.bottom + 6;
    const flipsToBottom = placement === "top" && wantedTop < 4;
    const flipsToTop =
      placement === "bottom" && wantedTop + bubbleH > window.innerHeight - 4;
    const finalTop = flipsToBottom
      ? tr.bottom + 6
      : flipsToTop
      ? tr.top - bubbleH - 6
      : wantedTop;
    // Clamp horizontally so the bubble can't bleed past the viewport.
    // Critical for triggers near the right/left edge (e.g., the takeover
    // toggle and close button that sit at the corner of the bar).
    const margin = 6;
    const idealLeft = tr.left + tr.width / 2 - bubbleW / 2;
    const clampedLeft = Math.max(
      margin,
      Math.min(idealLeft, window.innerWidth - bubbleW - margin)
    );
    setCoords({ top: finalTop, left: clampedLeft });
    setMeasured(true);
  }, [open, placement]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") hide();
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [open]);

  const childRef = (children as any).ref;
  const child = React.cloneElement(children, {
    ref: (node: HTMLElement | null) => {
      triggerRef.current = node;
      if (typeof childRef === "function") childRef(node);
      else if (childRef && typeof childRef === "object") childRef.current = node;
    },
    onMouseEnter: (e: React.MouseEvent) => {
      children.props.onMouseEnter?.(e);
      show(false);
    },
    onMouseLeave: (e: React.MouseEvent) => {
      children.props.onMouseLeave?.(e);
      hide();
    },
    onFocus: (e: React.FocusEvent) => {
      children.props.onFocus?.(e);
      show(true);
    },
    onBlur: (e: React.FocusEvent) => {
      children.props.onBlur?.(e);
      hide();
    },
    onClick: (e: React.MouseEvent) => {
      children.props.onClick?.(e);
      hide();
    },
    "aria-describedby": open ? id : children.props["aria-describedby"],
  });

  return (
    <>
      {child}
      {open && (
        <div
          ref={bubbleRef}
          id={id}
          role="tooltip"
          className="hl-tooltip"
          style={{
            position: "fixed",
            top: coords.top,
            left: coords.left,
            background: "rgba(20,22,27,0.96)",
            color: "#fff",
            padding: "5px 9px",
            borderRadius: 6,
            font: "12px -apple-system,system-ui,sans-serif",
            boxShadow: "0 4px 12px rgba(0,0,0,0.35)",
            border: "1px solid rgba(172,137,245,0.30)",
            pointerEvents: "none",
            zIndex: 2147483647,
            maxWidth: hint ? 260 : undefined,
            whiteSpace: hint ? "normal" : "nowrap",
            opacity: measured ? 1 : 0,
            transition: `opacity ${FADE_MS}ms`,
          }}
        >
          <div style={{ whiteSpace: "nowrap" }}>
            {label}
            {shortcut && (
              <span style={{ opacity: 0.6, marginLeft: 8 }}>{shortcut}</span>
            )}
          </div>
          {hint && (
            <div style={{ opacity: 0.65, fontSize: 11, marginTop: 3, lineHeight: 1.35 }}>
              {hint}
            </div>
          )}
        </div>
      )}
    </>
  );
};

export default Tooltip;
