// 50ms render watchdog. Started by intercept.ts when a Cmd+F is captured;
// must be cancel()'d by BarRoot when it has rendered. If the timer fires
// the bar is presumed broken — the watchdog calls back so the caller can
// record a failure, unmount, and arm a suppression window so the next
// keystroke falls through to native.
//
// 50ms is empirically generous for a Shadow DOM React mount on a modern
// machine; we'd rather declare failure quickly than leave the user with a
// half-mounted bar staring at them.

export const WATCHDOG_TIMEOUT_MS = 50;

let timer: ReturnType<typeof setTimeout> | null = null;

export const start = (onTimeout: () => void) => {
  cancel();
  timer = setTimeout(() => {
    timer = null;
    onTimeout();
  }, WATCHDOG_TIMEOUT_MS);
};

export const cancel = () => {
  if (timer !== null) {
    clearTimeout(timer);
    timer = null;
  }
};

export const __isPending = () => timer !== null;
