import { GlobalSettings } from '../../definitions/global.definition';

// "".split(",") returns [""] — a length-1 array with an empty entry — so a
// naive .reduce over the result would call currentUrl.includes("") which
// always matches. That accidentally turns "list ON, no entries yet" into
// "match every URL", which blocks everything for blacklist users.
// Treat all-whitespace/empty entries as no entries at all.
const parseEntries = (raw: string | undefined): string[] =>
  (raw ?? '')
    .split(',')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

// Reduce a user-typed list entry to a bare hostname: lowercase, drop any
// scheme, userinfo, path/query/fragment, port, and a trailing root dot the user
// may have pasted. So "HTTPS://user:pass@Example.com.:8080/path?x=1" ->
// "example.com". (SCO-01, SCO-02; userinfo + trailing-dot added in SCO-04.)
export const entryToHost = (entry: string): string =>
  entry
    .trim()
    .toLowerCase()
    .replace(/^[a-z][a-z0-9+.-]*:\/\//, '') // strip scheme://
    .replace(/^[^/@]*@/, '') // strip user:pass@ userinfo (only before any path)
    .replace(/[/?#].*$/, '') // strip path / query / fragment
    .replace(/:\d+$/, '') // strip :port
    .replace(/\.$/, '') // strip a trailing root dot (FQDN form "example.com.")
    .replace(/^\.+/, ''); // SCO-05: strip a leading dot (cookie-domain form ".example.com")

// A page matches a list entry when its HOST equals the entry or is a subdomain
// of it. This replaces the old `href.includes(entry)` substring test, which
// (a) was case-sensitive (SCO-01) and (b) matched anywhere in the full URL —
// path, query, or an unrelated host — so "example.com" wrongly matched
// "notexample.com" and "safe.com/?ref=example.com", and a short entry like
// "com" matched nearly everything (SCO-02). Comparison is case-insensitive on
// both sides; entries are normalized to a bare host first.
export const hostMatchesAnyEntry = (
  hostname: string,
  entries: string[]
): boolean => {
  // SCO-05: mirror entryToHost's trailing-dot strip on the live-host side.
  // Chrome preserves the FQDN root dot in `location.hostname` for
  // `https://example.com./`, so without this strip "example.com." would
  // never equal/subdomain-match a normalized entry "example.com".
  const host = hostname.trim().toLowerCase().replace(/\.$/, '');
  if (!host) return false;

  return entries.some((rawEntry) => {
    const entry = entryToHost(rawEntry);
    if (!entry) return false;
    if (host === entry) return true;
    // Subdomain match — but only for multi-label entries, so a single-label
    // entry like "com" does NOT match every "anything.com" (SCO-02). A bare
    // host such as "localhost" still matches itself via the exact check above.
    return entry.includes('.') && host.endsWith('.' + entry);
  });
};

export function isWhiteListedSite(settings: GlobalSettings) {
  const sites = parseEntries(settings?.whitelistSites.websiteList);

  if (!settings?.whitelistSites.isOn) return true;
  if (sites.length === 0) return true;

  const currentHost = window?.location?.hostname ?? '';

  return hostMatchesAnyEntry(currentHost, sites);
}
export function isBlackListedSite(settings: GlobalSettings) {
  const sites = parseEntries(settings?.blacklistSites.websiteList);

  if (!settings?.blacklistSites.isOn) return false;
  if (sites.length === 0) return false;

  const currentHost = window?.location?.hostname ?? '';

  return hostMatchesAnyEntry(currentHost, sites);
}
