import { GlobalSettings } from '../../definitions/global.definition';
import { cssHility, disableColorsState } from '../content.consts';
import { disableNavigationCss } from './content.navigation';
import { isEditableEventTarget } from './utils/editable.utils';

// One persistent listener, mirroring the AbortController idiom used by the
// other key-stroke features (see content.searchBySelect.ts). The previous
// implementation built a fresh `keydown` closure and addEventListener'd it on
// *every* popup settings message (contentFileLogic runs per message), while
// its removeEventListener sat in the dead `else` branch and referenced a brand
// new closure — so listeners leaked unbounded and Shift+D flipped the shared
// boolean N+1 times (net no-op after an even number of popup changes). (TGL-01)
let deselectListener = null as unknown as AbortController;

// Re-queried live at press time so the toggle always targets the highlights
// currently on the page, not a snapshot taken when the listener was armed.
const applyStyleDisabled = (isStyleDisabled: boolean) => {
  document
    .querySelectorAll(`[${cssHility}]`)
    .forEach((styleSheet) => ((styleSheet as any).disabled = isStyleDisabled));
};

export const disableColorsOnKeyStroke = (
  globalSettings: GlobalSettings,
  isObserver?: boolean
) => {
  if (isObserver) return;

  const isTemporaryDeselect = globalSettings.temporaryDeselect.isOn;

  if (isTemporaryDeselect && !deselectListener) {
    deselectListener = new AbortController();

    const keyDown = (e: KeyboardEvent) => {
      if (e.key === 'D' && e.shiftKey) {
        // See editable.utils.ts: don't fire while the user is typing.
        if (isEditableEventTarget(e)) return;
        disableColorsState.isStyleDisabled = !disableColorsState.isStyleDisabled;
        applyStyleDisabled(disableColorsState.isStyleDisabled);
        disableNavigationCss(disableColorsState.isStyleDisabled);
      }
    };

    document.addEventListener('keydown', keyDown, deselectListener);
  } else if (!isTemporaryDeselect && deselectListener?.abort) {
    deselectListener.abort();
    deselectListener = null as unknown as AbortController;

    // Feature turned off: re-enable anything we had deselected so the page
    // isn't left stuck with hidden highlights.
    if (disableColorsState.isStyleDisabled) {
      disableColorsState.isStyleDisabled = false;
      applyStyleDisabled(false);
      disableNavigationCss(false);
    }
  }
};

// switchOffCleanup calls this when the user toggles the extension off in the
// popup. The init function only aborts when the *feature* is toggled off;
// without an explicit cleanup the listener would survive an extension-wide off
// and keep handling Shift+D.
export const cleanupDisableColors = () => {
  if (deselectListener?.abort) {
    deselectListener.abort();
    deselectListener = null as unknown as AbortController;
  }
  // TGL-05: reset the shared deselect flag on extension-off cleanup (mirror
  // the feature-off branch). Without this, an extension-off taken while
  // highlights were deselected (isStyleDisabled === true) leaves the flag
  // stuck true; re-enabling repaints visible highlights but the flag is
  // desynced, so the first Shift+D after the off→on cycle flips true→false
  // with no visual change — a dead keystroke.
  disableColorsState.isStyleDisabled = false;
};
