import { GlobalSettings, QueryItem } from "../definitions/global.definition";
import { RegexHit, advanceRegexIndex, execAllRegexMatches } from "./regexExec";
import {
  normalizeSearchText,
  normalizeSearchTextWithMap,
  isWordBoundary,
  compileWholeWordRegex,
} from "./normalization";
import {
  PreparedPlainQuery,
  PreparedQuery,
  QueryMatch,
  QueryMatchSummary,
  QuerySearchOptions,
  QuerySnippet,
} from "./types";

export interface IndexedTextRun {
  index: number;
  text: string;
}

export interface IndexedTextRunInput {
  text: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  endsLine?: boolean;
}

export interface IndexedTextDocument {
  pageNumber: number;
  text: string;
  runs: IndexedTextRun[];
  normalizedText: string;
  normalizedToTextMap: number[];
  runOffsets: Array<{ start: number; end: number }>;
  normalizedSearchKey?: string;
  normalizationCache?: Map<
    string,
    {
      value: string;
      sourceMap: number[];
    }
  >;
}

const DEFAULT_SNIPPET_RADIUS = 45;

// Unicode combining marks (non-global so .test() is stateless in a loop). Used
// to extend a diacritic-insensitive match past trailing accents (QRX-02).
const COMBINING_MARK_REGEX = /[\u0300-\u036f]/;

export function getSearchOptions(globalSettings: GlobalSettings): QuerySearchOptions {
  return {
    caseSensitive: globalSettings.caseSens.isOn,
    diacriticSensitive: globalSettings.diacriticSens.isOn,
    splitSearch: globalSettings.splitSearch.isOn,
    completePhrase: globalSettings.completeWordSearch.isOn,
  };
}

function getPreparedVariants(
  item: QueryItem,
  options: QuerySearchOptions
): PreparedPlainQuery[] {
  if (item.isRegexp) return [];

  const rawValues = new Set<string>();
  const trimmedName = item.name.trim();

  if (!trimmedName.length) return [];

  rawValues.add(trimmedName);

  if (options.splitSearch && /\s/.test(trimmedName)) {
    trimmedName
      .split(/\s+/)
      .map((part) => part.trim())
      .filter(Boolean)
      .forEach((part) => rawValues.add(part));
  }

  return Array.from(rawValues).map((rawValue) => ({
    rawValue,
    normalizedValue: normalizeSearchText(rawValue, options).replace(/\s+/g, " "),
  }));
}

export function prepareQueries(
  items: QueryItem[],
  options: QuerySearchOptions
): PreparedQuery[] {
  return items
    .filter((item) => !item.isInactive)
    .map((item) => ({
      item,
      variants: getPreparedVariants(item, options),
      regex: buildRegex(item, options),
    }));
}

function buildRegex(
  item: QueryItem,
  options: QuerySearchOptions
): RegExp | null {
  if (!item.isRegexp || !item.name.trim()) return null;

  const flags = `gm${options.caseSensitive ? "" : "i"}u`;

  // QRX-16: honor whole-word for regex by WRAPPING the user pattern in zero-width
  // word-boundary lookarounds (shared `wrapRegexWholeWord`) instead of a
  // post-match boundary filter. Baking the boundary INTO the pattern lets the
  // engine backtrack across alternation to a longer whole-word alternative when
  // the short one fails the boundary (`cat|category` on "category" → "category",
  // not 0 matches), so this surface agrees with the on-page mark.js highlighter
  // (QRX-06). BOTH consumers of this regex derive their source from here — the
  // synchronous `findRegexMatches` AND the PDF Web-Worker path
  // (pdfDocumentSession runs `regex.source` off the main thread) — so both honor
  // whole-word identically with no separate post-filter. Safety: the wrap is
  // zero-width and non-capturing (no new backtracking, capture numbering and
  // `acrossElements`-style offsets preserved); the PDF worker stays
  // timeout-protected (QRX-01), so a pathological inner pattern is still aborted.
  try {
    // QRX-20: validate the raw pattern before whole-word-wrapping (see
    // compileWholeWordRegex) so a malformed class can't become a valid-but-wrong
    // regex when completePhrase is on.
    return compileWholeWordRegex(item.name, flags, options.completePhrase);
  } catch {
    return null;
  }
}

function dedupeMatches(matches: QueryMatch[]) {
  const seen = new Set<string>();

  return matches.filter((match) => {
    const key = `${match.queryId}:${match.pageNumber}:${match.start}:${match.end}`;

    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function buildFragments(
  start: number,
  end: number,
  runOffsets: Array<{ start: number; end: number }>
) {
  const fragments: QueryMatch["fragments"] = [];

  for (const [runIndex, offset] of runOffsets.entries()) {
    const fragmentStart = Math.max(start, offset.start);
    const fragmentEnd = Math.min(end, offset.end);

    if (fragmentStart >= fragmentEnd) continue;

    fragments.push({
      runIndex,
      startChar: fragmentStart - offset.start,
      endChar: fragmentEnd - offset.start,
    });
  }

  return fragments;
}

function findPlainMatches(
  document: IndexedTextDocument,
  item: QueryItem,
  prepared: PreparedPlainQuery,
  options: QuerySearchOptions
) {
  const matches: QueryMatch[] = [];

  if (!prepared.normalizedValue.length) return matches;

  let searchIndex = 0;
  while (searchIndex < document.normalizedText.length) {
    const nextIndex = document.normalizedText.indexOf(
      prepared.normalizedValue,
      searchIndex
    );

    if (nextIndex === -1) break;

    const nextEnd = nextIndex + prepared.normalizedValue.length;
    const hasBoundary =
      !options.completePhrase ||
      (isWordBoundary(document.normalizedText, nextIndex - 1) &&
        isWordBoundary(document.normalizedText, nextEnd));

    if (hasBoundary) {
      const originalStart = document.normalizedToTextMap[nextIndex] ?? nextIndex;
      // End at the source position of the NEXT normalized char, which sits past
      // any trailing combining marks of the final matched grapheme — those marks
      // are stripped from normalizedText for diacritic-insensitive search, so
      // they never appear in normalizedToTextMap. (QRX-02 — the old
      // `lastSourceIndex + 1` dropped a trailing combining mark, truncating
      // accented final letters.)
      const nextSourceIndex = document.normalizedToTextMap[nextEnd];
      let originalEnd: number;
      if (nextSourceIndex !== undefined) {
        originalEnd = nextSourceIndex;
      } else {
        // Match runs to the end of normalizedText. Extend past the last matched
        // grapheme's trailing combining marks only — NOT over trailing
        // whitespace (which is trimmed out of normalizedText), so the highlight
        // doesn't paint blank space at the end of the text.
        // QRX-18: step past the WHOLE final source code point, not a hardcoded
        // `+1`. When the last matched grapheme is ASTRAL its two source code
        // units share one map entry, so `map[nextEnd-1]` points at the high
        // surrogate and `+1` landed on the LOW surrogate → the span ended one
        // unit short and `matchedText` was a lone high surrogate (renders as �).
        // advanceRegexIndex adds 2 for an astral code point, else 1 (the same
        // code-point step the regex loops use).
        const lastSourceIndex =
          document.normalizedToTextMap[nextEnd - 1] ?? originalStart;
        originalEnd = advanceRegexIndex(document.text, lastSourceIndex);
        while (
          originalEnd < document.text.length &&
          COMBINING_MARK_REGEX.test(document.text[originalEnd])
        ) {
          originalEnd += 1;
        }
      }
      // QRX-13: do NOT trim here. `start`/`end` and `fragments` describe the
      // untrimmed [originalStart, originalEnd) span; trimming only `matchedText`
      // made the label/snippet text disagree with the painted span (and broke
      // the `matchedText.length === end - start` invariant) whenever the span
      // legitimately included a boundary/synthetic-gap space.
      const matchedText = document.text.slice(originalStart, originalEnd);

      matches.push({
        id: `${item.id}:${document.pageNumber}:${originalStart}:${originalEnd}`,
        queryId: item.id,
        pageNumber: document.pageNumber,
        start: originalStart,
        end: originalEnd,
        matchedText,
        fragments: buildFragments(originalStart, originalEnd, document.runOffsets),
      });
    }

    searchIndex = nextIndex + Math.max(prepared.normalizedValue.length, 1);
  }

  return matches;
}

// Map raw regex hits ({start,end,text}) to QueryMatch objects. Shared by the
// synchronous path (findRegexMatches) and the worker-backed async path (the PDF
// session computes hits off the main thread and passes them in via
// regexHitsByQuery — QRX-01).
function buildRegexMatchesFromHits(
  document: IndexedTextDocument,
  item: QueryItem,
  hits: RegexHit[]
): QueryMatch[] {
  return hits.map((hit) => ({
    id: `${item.id}:${document.pageNumber}:${hit.start}:${hit.end}`,
    queryId: item.id,
    pageNumber: document.pageNumber,
    start: hit.start,
    end: hit.end,
    matchedText: hit.text,
    fragments: buildFragments(hit.start, hit.end, document.runOffsets),
  }));
}

// Synchronous regex matching (runs exec on the calling thread). Used only by
// callers that DON'T supply precomputed hits — note this can backtrack
// catastrophically (QRX-01); the PDF engine avoids it by passing worker hits.
function findRegexMatches(
  document: IndexedTextDocument,
  preparedQuery: PreparedQuery
) {
  const regex = preparedQuery.regex;
  if (!regex) return [];

  let hits: RegexHit[];
  try {
    hits = execAllRegexMatches(regex.source, regex.flags, document.text);
  } catch {
    return [];
  }

  return buildRegexMatchesFromHits(document, preparedQuery.item, hits);
}

export function findPreparedDocumentMatches(
  document: IndexedTextDocument,
  preparedQueries: PreparedQuery[],
  options: QuerySearchOptions,
  // When provided, regex matches come from these precomputed hits (run off the
  // main thread by a Web Worker — QRX-01) instead of synchronous exec. The map
  // is authoritative: a missing/empty entry means "no matches" (e.g. the worker
  // timed out on a pathological pattern), NOT "fall back to sync exec".
  regexHitsByQuery?: Map<string, RegexHit[]>
) {
  const matches: QueryMatch[] = [];

  for (const preparedQuery of preparedQueries) {
    if (preparedQuery.item.isRegexp) {
      // QRX-03/QRX-16: whole-word ("complete phrase") for regex is enforced
      // INSIDE the compiled pattern by `buildRegex` (zero-width word-boundary
      // lookarounds), so no post-match boundary filter is needed here. The
      // pattern-level constraint is strictly more correct than the old
      // post-filter: it lets alternation fall through to a longer whole-word
      // alternative the post-filter silently dropped, and it applies to the
      // PDF Web-Worker hits too (the worker runs the same wrapped source).
      const regexMatches = regexHitsByQuery
        ? buildRegexMatchesFromHits(
            document,
            preparedQuery.item,
            regexHitsByQuery.get(preparedQuery.item.id) ?? []
          )
        : findRegexMatches(document, preparedQuery);
      matches.push(...regexMatches);
      continue;
    }

    for (const variant of preparedQuery.variants) {
      matches.push(
        ...findPlainMatches(document, preparedQuery.item, variant, options)
      );
    }
  }

  return dedupeMatches(matches).sort((left, right) => left.start - right.start);
}

export function findDocumentMatches(
  document: IndexedTextDocument,
  items: QueryItem[],
  options: QuerySearchOptions
) {
  return findPreparedDocumentMatches(
    document,
    prepareQueries(items, options),
    options
  );
}

function getNormalizationCacheKey(
  options: Pick<QuerySearchOptions, "caseSensitive" | "diacriticSensitive">
) {
  return `${options.caseSensitive ? "1" : "0"}:${options.diacriticSensitive ? "1" : "0"}`;
}

function hasExplicitWhitespaceBoundary(previousText: string, nextText: string) {
  return /\s$/.test(previousText) || /^\s/.test(nextText);
}

function hasLineBreakBoundary(
  previousRun: IndexedTextRunInput,
  nextRun: IndexedTextRunInput
) {
  if (previousRun.endsLine) return true;

  if (
    typeof previousRun.y !== "number" ||
    typeof nextRun.y !== "number" ||
    typeof previousRun.height !== "number" ||
    typeof nextRun.height !== "number"
  ) {
    return false;
  }

  const lineThreshold =
    Math.max(previousRun.height, nextRun.height, 1) * 0.6;

  return Math.abs(nextRun.y - previousRun.y) > lineThreshold;
}

function hasHorizontalWordGap(
  previousRun: IndexedTextRunInput,
  nextRun: IndexedTextRunInput
) {
  if (
    typeof previousRun.x !== "number" ||
    typeof previousRun.width !== "number" ||
    typeof nextRun.x !== "number"
  ) {
    return false;
  }

  const gap = nextRun.x - (previousRun.x + previousRun.width);
  const referenceHeight =
    typeof previousRun.height === "number" && typeof nextRun.height === "number"
      ? Math.max(Math.min(previousRun.height, nextRun.height), 1)
      : 1;

  return gap > Math.max(referenceHeight * 0.18, 1.25);
}

function shouldInsertSyntheticGap(
  previousRun: IndexedTextRunInput | null,
  nextRun: IndexedTextRunInput
) {
  if (!previousRun) return false;

  const previousText = previousRun.text || "";
  const nextText = nextRun.text || "";

  if (!previousText.length || !nextText.length) return false;
  if (hasExplicitWhitespaceBoundary(previousText, nextText)) return false;
  if (previousText.endsWith("-")) return false;

  return (
    hasLineBreakBoundary(previousRun, nextRun) ||
    hasHorizontalWordGap(previousRun, nextRun)
  );
}

export function buildIndexedTextDocument(
  pageNumber: number,
  runs: IndexedTextRunInput[]
): IndexedTextDocument {
  let text = "";
  const runOffsets: IndexedTextDocument["runOffsets"] = [];
  let previousRun: IndexedTextRunInput | null = null;

  runs.forEach((run) => {
    const rawText = run.text || "";

    if (shouldInsertSyntheticGap(previousRun, run)) {
      text += " ";
    }

    const start = text.length;
    text += rawText;
    runOffsets.push({
      start,
      end: text.length,
    });
    // QRX-12: track the last NON-EMPTY run for the synthetic-gap decision. An
    // empty run carries no text and no reliable geometry; advancing through it
    // would make the next real run compare against the empty run, whose
    // `!previousText.length` short-circuits shouldInsertSyntheticGap to false
    // and drops the space that should separate the two real neighbors
    // (["foo", "", "bar"] → "foobar" instead of "foo bar").
    if (rawText.length > 0) {
      previousRun = run;
    }
  });

  const normalized = normalizeSearchTextWithMap(text, {
    caseSensitive: true,
    diacriticSensitive: true,
  });
  const normalizedSearchKey = getNormalizationCacheKey({
    caseSensitive: true,
    diacriticSensitive: true,
  });

  return {
    pageNumber,
    text,
    runs: runs.map((run, index) => ({
      index,
      text: run.text,
    })),
    normalizedText: normalized.value,
    normalizedToTextMap: normalized.sourceMap,
    runOffsets,
    normalizedSearchKey,
    normalizationCache: new Map([[normalizedSearchKey, normalized]]),
  };
}

export function applySearchOptionsToIndexedDocument(
  document: IndexedTextDocument,
  options: QuerySearchOptions
) {
  const cacheKey = getNormalizationCacheKey(options);
  if (document.normalizedSearchKey === cacheKey) {
    return document;
  }

  const normalizationCache =
    document.normalizationCache || new Map<string, { value: string; sourceMap: number[] }>();
  const cachedNormalized = normalizationCache.get(cacheKey);
  const normalized =
    cachedNormalized || normalizeSearchTextWithMap(document.text, options);

  if (!cachedNormalized) {
    normalizationCache.set(cacheKey, normalized);
  }

  return {
    ...document,
    normalizedText: normalized.value,
    normalizedToTextMap: normalized.sourceMap,
    normalizedSearchKey: cacheKey,
    normalizationCache,
  };
}

// QRX-10: nudge a radius-extended snippet endpoint off the inside of a
// surrogate pair so a slice never begins on a low surrogate or ends on a high
// surrogate (which would render as a lone-surrogate `�`). The `before` start is
// pulled FORWARD (off a trailing low surrogate of the char just before it) and
// the `after` end is pulled BACK (off a leading high surrogate). match.start /
// match.end are real grapheme boundaries and are left untouched.
function isLowSurrogate(code: number) {
  return code >= 0xdc00 && code <= 0xdfff;
}

function isHighSurrogate(code: number) {
  return code >= 0xd800 && code <= 0xdbff;
}

function snippetStart(text: string, index: number): number {
  // `index` is the first char of `before`. If it's a low surrogate, its high
  // surrogate sits at index-1 and belongs to the previous char — start one
  // later so we don't lead with half a pair.
  if (index > 0 && index < text.length && isLowSurrogate(text.charCodeAt(index))) {
    return index + 1;
  }
  return index;
}

function snippetEnd(text: string, index: number): number {
  // `index` is one past the last char of `after`. If the last included char
  // (index-1) is a high surrogate, it's the start of a pair whose low half is
  // at `index` — drop it so we don't trail with half a pair.
  if (index > 0 && index <= text.length && isHighSurrogate(text.charCodeAt(index - 1))) {
    return index - 1;
  }
  return index;
}

export function buildSnippet(
  document: IndexedTextDocument,
  match: QueryMatch,
  radius = DEFAULT_SNIPPET_RADIUS
): QuerySnippet {
  const text = document.text;
  const beforeStart = snippetStart(text, Math.max(0, match.start - radius));
  const afterEnd = snippetEnd(text, Math.min(text.length, match.end + radius));

  return {
    id: match.id,
    queryId: match.queryId,
    pageNumber: match.pageNumber,
    before: text.slice(beforeStart, match.start),
    matchText: text.slice(match.start, match.end),
    after: text.slice(match.end, afterEnd),
  };
}

export function summarizeMatches(matches: QueryMatch[]): QueryMatchSummary[] {
  const summaryMap = new Map<string, QueryMatchSummary>();

  matches.forEach((match) => {
    const currentSummary = summaryMap.get(match.queryId) || {
      queryId: match.queryId,
      count: 0,
      firstPage: null,
    };

    currentSummary.count += 1;
    currentSummary.firstPage =
      currentSummary.firstPage === null
        ? match.pageNumber
        : Math.min(currentSummary.firstPage, match.pageNumber);

    summaryMap.set(match.queryId, currentSummary);
  });

  return Array.from(summaryMap.values());
}
