type MinimapVisibilityState =
  | "visible"
  | "collapsed"
  | "hidden"
  | "covered"
  | "stale";

export interface MinimapSnippet {
  matchKey: string;
  id: string;
  term: string;
  queryLabel: string;
  contextBefore: string;
  contextAfter: string;
  color: string;
  element: HTMLElement;
  elements: HTMLElement[];
  visibilityState: MinimapVisibilityState;
  visibilityLabel: string;
  visibilityNote: string;
  isRevealable: boolean;
}

interface GroupedSnippets {
  id: string;
  term: string;
  color: string;
  snippets: MinimapSnippet[];
}

