const MINIMAP_HOST_ID = "highlighty-minimap-host";
const MINIMAP_FONT_STYLE_ID = "highlighty-minimap-font-style";
// XRY-04: the extension's own overlays (the X-Ray/minimap host, the Cmd+F bar,
// the field/form overlay roots, the scrollbar strip) sit above the page. When a
// match happens to lie under one of them, the covered-check must NOT report it
// as "covered by another layer" — it's under Highlighty's own UI (reachable by
// scrolling), not a page layer. Same class as FFH-10's overlay-root exclude.
const EXTENSION_OVERLAY_SELECTOR =
  "#highlighty-minimap-host,#highlighty-cmdf-host," +
  "#highlighty-cmdf-field-overlay-root,#highlighty-form-field-overlay-root," +
  ".highlighty-scrollbar-highlighter," +
  // Transient extension chrome that can sit over a match exactly at highlight-
  // sync time (the toast fires on highlight completion; the hint pill lives ~2s):
  // include them so a match under them isn't briefly mislabelled "covered".
  // NOT data-highlighty-adhoc (those are in-page text wrappers — covered by the
  // contains() checks; skipping them could over-promote under sticky headers).
  "hility-success,hility-error,[data-highlighty-cmdf]";
const isExtensionOwnedNode = (node: Element | null): boolean =>
  !!node && !!node.closest(EXTENSION_OVERLAY_SELECTOR);
