const ensureMinimapFontFace = () => {
  if (document.getElementById(MINIMAP_FONT_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = MINIMAP_FONT_STYLE_ID;
  style.textContent = `
    @font-face {
      font-family: "Phenoregu";
      src: url("${MINIMAP_FONT_URL}") format("opentype");
      font-style: normal;
      font-weight: 400;
      font-display: swap;
    }
    /* The minimap host is a screen affordance — hide it for print so a
       page printout doesn't carry our right-side panel into the
       printed output. The host is in document.body, but its content
       lives in shadow root; rules on the host element are enough. */
    @media print {
      #${MINIMAP_HOST_ID} {
        display: none !important;
      }
    }
  `;

  document.head.appendChild(style);
};

const ensurePulseStyles = () => {
  if (document.getElementById(MINIMAP_PULSE_STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = MINIMAP_PULSE_STYLE_ID;
  style.textContent = `
    .${MINIMAP_PULSE_CLASS} {
      position: relative !important;
      z-index: 1 !important;
      border-radius: 6px !important;
      outline: 2px solid rgba(244, 63, 94, 0.92) !important;
      outline-offset: 2px !important;
      box-shadow:
        0 0 0 1px rgba(244, 63, 94, 0.22),
        0 0 0 0 rgba(244, 63, 94, 0) !important;
      animation: highlighty-minimap-pulse 1.4s ease-out 1 !important;
    }

    @keyframes highlighty-minimap-pulse {
      0% {
        box-shadow:
          0 0 0 1px rgba(244, 63, 94, 0.22),
          0 0 0 0 rgba(244, 63, 94, 0);
      }
      32% {
        box-shadow:
          0 0 0 2px rgba(244, 63, 94, 0.32),
          0 0 0 6px rgba(244, 63, 94, 0.16),
          0 0 16px rgba(244, 63, 94, 0.24);
      }
      100% {
        box-shadow:
          0 0 0 2px rgba(244, 63, 94, 0),
          0 0 0 10px rgba(244, 63, 94, 0),
          0 0 18px rgba(244, 63, 94, 0);
      }
    }
  `;

  document.head.appendChild(style);
};

const clearActivePulse = () => {
  if (!activePulse) return;

  window.clearTimeout(activePulse.timeoutId);
  activePulse.elements.forEach((element) => {
    element.classList.remove(MINIMAP_PULSE_CLASS);
  });
  activePulse = null;
};

const pulseHighlight = (elements: HTMLElement[]) => {
  ensurePulseStyles();
  clearActivePulse();

  const pulseTargets = elements.filter(
    (element) => element?.isConnected && element.getClientRects().length > 0
  );
  if (!pulseTargets.length) return;

  pulseTargets.forEach((element) => {
    element.classList.remove(MINIMAP_PULSE_CLASS);
  });
  void pulseTargets[0].offsetWidth;
  pulseTargets.forEach((element) => {
    element.classList.add(MINIMAP_PULSE_CLASS);
  });

  activePulse = {
    elements: pulseTargets,
    timeoutId: window.setTimeout(() => {
      if (activePulse?.elements !== pulseTargets) return;

      pulseTargets.forEach((element) => {
        element.classList.remove(MINIMAP_PULSE_CLASS);
      });
      activePulse = null;
    }, 3000),
  };
};

