import { GlobalSettings } from "../../definitions/global.definition";
import { persistGlobalSettingsDelta } from "./content.persistGlobalSettings";
import { invokeBehaviour } from "../content.utils";
import { BROADCAST_SETTINGS } from "./background.broadcastSettings";
import {
  currentGlobalSettings,
  setGlobalSettings,
} from "./content.globalSettingsState";
import { isEditableEventTarget } from "./utils/editable.utils";
let selectListener = null as unknown as AbortController;

export const switchOffHotkey = () => {
  const isSwitchHotkeyOn = currentGlobalSettings?.switchOffHotkey?.isOn;

  const selectPress = async (e: KeyboardEvent) => {
    if (e.key === "T" && e.shiftKey && isSwitchHotkeyOn) {
      // Suppress while the user is typing in an editable surface.
      // Without this, every capital "T" in a search box / compose
      // field / contenteditable on a Highlighty-using site silently
      // toggles the extension off — a recurring "did my highlights
      // just disappear?" papercut.
      if (isEditableEventTarget(e)) return;

      const isExtensionOn = !currentGlobalSettings.isExtensionOn;

      const newGlobalSettings = {
        ...currentGlobalSettings,
        isExtensionOn,
      };

      invokeBehaviour(newGlobalSettings, true);

      saveToDatabase(newGlobalSettings);
      setGlobalSettings(newGlobalSettings);
      // MSG-05: propagate the toggle to OTHER open tabs. This tab already
      // applied it; other tabs have no storage.onChanged listener, so without
      // this broadcast they keep their stale isExtensionOn until they reload.
      broadcastSettingsToOtherTabs(newGlobalSettings);
    }
  };

  if (isSwitchHotkeyOn && !selectListener) {
    selectListener = new AbortController();

    document.addEventListener("keydown", selectPress, selectListener);
  } else if (!isSwitchHotkeyOn && selectListener?.abort) {
    selectListener.abort();
    selectListener = null as unknown as AbortController;

    // console.log('abort nav listener');
  }
};

const saveToDatabase = async (newGlobalSettings: GlobalSettings) => {
  // SUB-27: persist ONLY the isExtensionOn flag onto the RAW stored settings.
  // `newGlobalSettings` is built from the clamped in-memory copy, so writing it
  // whole would truncate a free user's lists / strip regex flags.
  await persistGlobalSettingsDelta((raw) => ({
    ...raw,
    isExtensionOn: newGlobalSettings.isExtensionOn,
  }));
};

// Ask the background to re-broadcast the new settings to every other tab. A
// content script can't message other tabs directly. Best-effort.
const broadcastSettingsToOtherTabs = (globalSettings: GlobalSettings) => {
  try {
    const runtimeApi: any =
      typeof chrome !== "undefined" && chrome.runtime
        ? chrome.runtime
        : typeof browser !== "undefined" && (browser as any).runtime
        ? (browser as any).runtime
        : null;
    runtimeApi?.sendMessage?.(
      { type: BROADCAST_SETTINGS, globalSettings },
      () => void runtimeApi?.lastError
    );
  } catch {
    /* best-effort — toggle still applied + persisted locally */
  }
};
