let minimalInstalled = false;

// Caller-supplied scope for the bar's matcher. Defaults to undefined (the
// bar walks document.body). The PDF viewer passes a getter pointing at
// the page-text container so its surrounding React UI doesn't match.
let currentSearchRoot: (() => Node) | undefined;

export interface BootOptions {
  /**
   * Where the bar's ad-hoc matcher walks. Forwarded as BarRoot's
   * `searchRoot` prop. Resolved at search time (per keystroke debounce),
   * so the getter can return a late-mounted element.
   */
  searchRoot?: () => Node;
}

const mirrorFastBoot = (settings: GlobalSettings) => {
  const cmdf = settings.cmdFTakeover;
  if (!cmdf) {
    writeFastBoot({ on: false, blacklist: [] });
    return;
  }
  // We only know the current origin's blacklist status from
  // isBlackListedSite, so mirror just that origin when blocked. The
  // fast-boot reader checks `blacklist.includes(origin)`.
  const blacklist: string[] = [];
  try {
    if (isBlackListedSite(settings)) blacklist.push(window.location.origin);
  } catch {}
  writeFastBoot({ on: cmdf.isOn, blacklist });
};

let probeHandlerInstalled = false;
let probeHandlerDispose: (() => void) | null = null;
let openWithTermInstalled = false;
let openWithTermDispose: (() => void) | null = null;
let postHighlightDispose: (() => void) | null = null;

let pendingHint: string | null = null;
// Cross-tab "jump" entry path: a one-shot seed consumed by the very next
// openBar() so the destination bar mounts pre-filled + seeded-externally (scroll
// to first match, no persist). Null for every ordinary open. The "seeded"
// boolean is derived from this being non-null — no separate flag to desync.
let pendingSeedTerm: string | null = null;
let savedQueryNavIndex: { [queryId: string]: number } = {};

const HINT_MAX_PER_ORIGIN = 3;
const HINT_DOUBLE_PRESS = `Press ${cmdOrCtrlLabel("F")} again for native search`;
const URL_HASH_KEY = "highlighty-search";

// History updates and last-query persistence are debounced together: the
// user typing rapidly shouldn't burn through chrome.storage writes.
let persistTimer: ReturnType<typeof setTimeout> | null = null;
const PERSIST_DEBOUNCE_MS = 600;

const getInitialTerm = (): string => {
  const settings = currentGlobalSettings?.cmdFTakeover;
  if (!settings) return "";
  // 1) Bookmarkable URL hash takes precedence — explicit user intent
  if (settings.bookmarkableUrls) {
    const hashTerm = readUrlHash();
    if (hashTerm) return hashTerm;
  }
  // 2) Persisted per-site last query
  if (settings.persistLastQueryPerSite) {
    const origin = getOrigin();
    return settings.lastQueryPerSite?.[origin] ?? "";
  }
  return "";
};

const readUrlHash = (): string | null => {
  try {
    const hash = window.location.hash || "";
    const params = new URLSearchParams(hash.replace(/^#/, ""));
    return params.get(URL_HASH_KEY);
  } catch {
    return null;
  }
};

const writeUrlHash = (term: string) => {
  try {
    const url = new URL(window.location.href);
    const params = new URLSearchParams(url.hash.replace(/^#/, ""));
    if (term) params.set(URL_HASH_KEY, term);
    else params.delete(URL_HASH_KEY);
    const next = params.toString();
    const newHash = next ? `#${next}` : "";
    if (window.location.hash !== newHash) {
      window.history.replaceState(null, "", `${url.pathname}${url.search}${newHash}`);
    }
  } catch {}
};

// Latest pending term is held here so flushPersist() can write the
// last-known value on bar close even before the debounce fires.
let pendingTerm: string | null = null;

// SUB-27: the pure lastQueryPerSite + history delta, applied to whatever
// cmdFTakeover base is passed in. Used for BOTH the in-memory display
// projection (base = clamped runtime cmdFTakeover) and the raw persist
// (base = the RAW stored cmdFTakeover) so the two stay in lock-step without
// the persist inheriting the clamp. Returns the same reference when nothing
// changed so callers can no-op.
export const applyTermChange = (
  cmdF: CmdFTakeoverSettings,
  term: string,
  origin: string
): CmdFTakeoverSettings => {
  let next: CmdFTakeoverSettings = cmdF;

  // Never persist an empty/whitespace term as the remembered last-query (mirrors
  // the history guard below). An empty remembered query is meaningless for
  // pre-fill, and persisting "" would WIPE a real remembered query when the term
  // is mechanically cleared — e.g. Save clears the input, or a cross-tab-jump
  // bar is cleared — clobbering a value the user may never have seen.
  if (cmdF.persistLastQueryPerSite && term.trim()) {
    next = {
      ...next,
      lastQueryPerSite: { ...next.lastQueryPerSite, [origin]: term },
    };
  }

  if (cmdF.searchHistory.isOn && term.trim()) {
    const trimmed = term.trim();
    const filtered = (next.history ?? []).filter((h) => h !== trimmed);
    const max = Math.max(1, cmdF.searchHistory.max);
    next = { ...next, history: [trimmed, ...filtered].slice(0, max) };
  }

  return next;
};

const writePersistNow = async (term: string) => {
  const settings = currentGlobalSettings;
  if (!settings?.cmdFTakeover) return;
  const cmdF = settings.cmdFTakeover;
  const origin = getOrigin();
  const next = applyTermChange(cmdF, term, origin);

  // Only write the bookmarkable hash for a real (non-empty) term. A mechanical
  // clear must not DELETE a pre-existing #highlighty-search hash the user arrived
  // with — the same clobber-on-empty class as lastQueryPerSite above.
  if (cmdF.bookmarkableUrls && term.trim()) writeUrlHash(term);

  if (next === cmdF) return;
  const merged = { ...settings, cmdFTakeover: next };
  setGlobalSettings(merged);
  // SUB-27: persist the SAME term delta onto the RAW stored cmdFTakeover so a
  // free/lapsed user's full lists / regex flags / PRO prefs aren't clobbered
  // by the clamped `merged`. Recompute against `raw.cmdFTakeover` (not the
  // in-memory clamp) so history/lastQueryPerSite land on the real data.
  await persistGlobalSettingsDelta((raw) =>
    raw.cmdFTakeover
      ? { ...raw, cmdFTakeover: applyTermChange(raw.cmdFTakeover, term, origin) }
      : raw
  );
  mirrorFastBoot(merged);
};

const persistTermChange = (term: string) => {
  pendingTerm = term;
  if (persistTimer) clearTimeout(persistTimer);
  persistTimer = setTimeout(async () => {
    persistTimer = null;
    const t = pendingTerm;
    pendingTerm = null;
    if (t === null) return;
    await writePersistNow(t);
  }, PERSIST_DEBOUNCE_MS);
};

const flushPersist = async () => {
  if (persistTimer) {
    clearTimeout(persistTimer);
    persistTimer = null;
  }
  if (pendingTerm !== null) {
    const t = pendingTerm;
    pendingTerm = null;
    await writePersistNow(t);
  }
};

const incrementHintShown = async (origin: string) => {
  const settings = currentGlobalSettings;
  if (!settings?.cmdFTakeover) return;
  const next: CmdFTakeoverSettings = {
    ...settings.cmdFTakeover,
    hintShown: {
      ...settings.cmdFTakeover.hintShown,
      [origin]: (settings.cmdFTakeover.hintShown[origin] ?? 0) + 1,
    },
  };
  const merged = { ...settings, cmdFTakeover: next };
  setGlobalSettings(merged);
  // SUB-27: bump hintShown on the RAW stored cmdFTakeover, not the clamp.
  await persistGlobalSettingsDelta((raw) =>
    raw.cmdFTakeover
      ? {
          ...raw,
          cmdFTakeover: {
            ...raw.cmdFTakeover,
            hintShown: {
              ...raw.cmdFTakeover.hintShown,
              [origin]: (raw.cmdFTakeover.hintShown?.[origin] ?? 0) + 1,
            },
          },
        }
      : raw
  );
};

const hintCount = (origin: string): number => {
  return currentGlobalSettings?.cmdFTakeover?.hintShown?.[origin] ?? 0;
};

const getOrigin = (): string => {
  try {
    return window.location.origin;
  } catch {
    return "";
  }
};

const HILITY_PULSE_STYLE_ID = "highlighty-cmdf-cycle-pulse-style";
const HILITY_PULSE_CLASS = "highlighty-cmdf-cycle-pulse";
let hilityPulseTimeout: ReturnType<typeof setTimeout> | null = null;
let hilityPulseEl: HTMLElement | null = null;

const ensureHilityPulseStyles = () => {
  if (document.getElementById(HILITY_PULSE_STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = HILITY_PULSE_STYLE_ID;
  style.textContent = `
    .${HILITY_PULSE_CLASS} {
      outline: 2px solid rgba(244, 63, 94, 0.92) !important;
      outline-offset: 2px !important;
      border-radius: 3px !important;
      animation: highlighty-cmdf-cycle-pulse 1.4s ease-out 1 !important;
    }
    @keyframes highlighty-cmdf-cycle-pulse {
      0%   { box-shadow: 0 0 0 0  rgba(244, 63, 94, 0.55); }
      40%  { box-shadow: 0 0 0 8px rgba(244, 63, 94, 0.20); }
      100% { box-shadow: 0 0 0 12px rgba(244, 63, 94, 0); }
    }
  `;
  document.head.appendChild(style);
};

// Briefly outline + pulse the active <hility> so the user sees which
// match is current when cycling via chip click. ad-hoc Cmd+F navigation
// gets its own active-paint via paintAdHoc; saved-query matches had no
// signal until now.
const pulseHilityElement = (el: HTMLElement) => {
  ensureHilityPulseStyles();
  if (hilityPulseEl && hilityPulseEl !== el) {
    hilityPulseEl.classList.remove(HILITY_PULSE_CLASS);
  }
  if (hilityPulseTimeout) clearTimeout(hilityPulseTimeout);
  // Re-trigger animation if user clicks the chip repeatedly on the same el.
  el.classList.remove(HILITY_PULSE_CLASS);
  void el.offsetWidth;
  el.classList.add(HILITY_PULSE_CLASS);
  hilityPulseEl = el;
  hilityPulseTimeout = setTimeout(() => {
    el.classList.remove(HILITY_PULSE_CLASS);
    if (hilityPulseEl === el) hilityPulseEl = null;
    hilityPulseTimeout = null;
  }, 1600);
};

const buildSavedQueryRefs = (): SavedQueryRef[] => {
  const items =
    currentGlobalSettings?.queryListState?.selectedList?.itemList ?? [];
  // Filter so the chip count mirrors the bar's logical-match count —
  // drops display:none / visibility:hidden marks that mark.js still
  // paints (e.g. Wikipedia's collapsed language blocks).
  return items.map((q) => {
    const all = Array.from(
      document.querySelectorAll<Element>(`[${dataHility}='${q.id}']`)
    );
    const counted = all.filter((el) => isHilityCounted(el));
    return { query: q, count: counted.length };
  });
};

const scrollToMatch = (match: AdHocMatch) => {
  // Field match: the only visible signal we can give is to select the
  // matched substring inside the input/textarea (the CSS Custom Highlight
  // API can't paint into form fields) and scroll the field into view.
  // setSelectionRange works without focus on Chrome/Firefox; calling
  // focus() too would steal it from the cmd+F bar and break the user's
  // ability to press Enter for the next match.
  if (match.field) {
    const el = match.field.element;
    try {
      el.setSelectionRange?.(match.field.fieldStart, match.field.fieldEnd);
    } catch {
      /* unsupported field type (input type=number on Safari, etc.) — ignore */
    }
    el.scrollIntoView?.({ behavior: "smooth", block: "center", inline: "nearest" });
    return;
  }
  // Range API doesn't have scrollIntoView; use the start container's
  // parent element when it's a Text node. Smooth + center.
  const node = match.range.startContainer;
  const target = (node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element));
  target?.scrollIntoView?.({ behavior: "smooth", block: "center", inline: "nearest" });
};

let currentBarUiState: CmdFTakeoverBarUiState = { ...DEFAULT_CMDF_BAR_UI_STATE };
let hasLoadedBarUiState = false;
let barUiPersistTimer: ReturnType<typeof setTimeout> | null = null;
let pendingBarUiState: CmdFTakeoverBarUiState | null = null;

const ensureBarUiStateLoaded = async () => {
  if (hasLoadedBarUiState) return;
  const raw = (await getStorageDataLocal(CMDF_BAR_UI_STATE_STORAGE_KEY)) as
    | Record<string, unknown>
    | undefined;
  const loaded = raw?.[CMDF_BAR_UI_STATE_STORAGE_KEY];
  const validated = isCmdFTakeoverBarUiState(loaded) ? loaded : DEFAULT_CMDF_BAR_UI_STATE;
  currentBarUiState = {
    ...validated,
    snippetsPanel: validated.snippetsPanel ?? DEFAULT_CMDF_BAR_UI_STATE.snippetsPanel,
  };
  hasLoadedBarUiState = true;
};

const flushBarUiPersist = async () => {
  if (!pendingBarUiState) return;
  const toWrite = pendingBarUiState;
  pendingBarUiState = null;
  barUiPersistTimer = null;
  currentBarUiState = toWrite;
  await setStorageDataLocal({ [CMDF_BAR_UI_STATE_STORAGE_KEY]: toWrite });
};

const schedulePersistBarUiState = (state: CmdFTakeoverBarUiState) => {
  pendingBarUiState = state;
  // SNP-10: write-through. Refresh the in-memory cache eagerly so a
  // close→reopen inside the 200ms debounce window (Esc then immediately
  // re-open) seeds the bar from the just-applied state instead of the
  // pre-interaction value. Only the chrome.storage WRITE stays debounced.
  currentBarUiState = state;
  if (barUiPersistTimer) clearTimeout(barUiPersistTimer);
  barUiPersistTimer = setTimeout(() => { void flushBarUiPersist(); }, 200);
};

// SNP-07: reconcile the bar UI state across tabs. Each tab loads
// CMDF_BAR_UI_STATE_STORAGE_KEY once (`hasLoadedBarUiState`) and then only
// refreshes its in-memory cache from its OWN writes, so without this a tab that
// had the bar open kept serving — and re-persisting — a stale snippets-panel
// position, silently reverting a drag made in another tab. Adopt any EXTERNAL
// write into `currentBarUiState` so the next openBar() seeds fresh; ignore the
// echo of our own write.
let hasRegisteredBarUiReconcile = false;

const resolveStorageApi = (): typeof chrome.storage | null => {
  if (typeof chrome !== "undefined" && chrome.storage) return chrome.storage;
  const b = (globalThis as any).browser;
  return b?.storage ? (b.storage as typeof chrome.storage) : null;
};

const ensureBarUiReconcileListener = () => {
  if (hasRegisteredBarUiReconcile) return;
  const storageApi = resolveStorageApi();
  if (!storageApi?.onChanged?.addListener) return;
  hasRegisteredBarUiReconcile = true;
  storageApi.onChanged.addListener(
    (
      changes: { [key: string]: chrome.storage.StorageChange },
      areaName: string
    ) => {
      if (areaName !== "local") return;
      const change = changes?.[CMDF_BAR_UI_STATE_STORAGE_KEY];
      if (!change || !("newValue" in change)) return;
      const next = change.newValue;
      if (!isCmdFTakeoverBarUiState(next)) return;
      // If THIS tab has a local write still pending (debounced flush not yet
      // run), that intent is authoritative — it will overwrite storage on flush.
      // Ignore incoming changes during that window so a late echo of a prior
      // write can't transiently revert the newer local value.
      if (pendingBarUiState) return;
      // Skip our own write's echo (already reflected in currentBarUiState), so a
      // self-write never re-applies; adopt only a genuinely different value from
      // another tab.
      if (JSON.stringify(next) === JSON.stringify(currentBarUiState)) return;
      currentBarUiState = {
        ...next,
        snippetsPanel:
          next.snippetsPanel ?? DEFAULT_CMDF_BAR_UI_STATE.snippetsPanel,
      };
      hasLoadedBarUiState = true;
    }
  );
};

const isPlainObject = (v: any): v is Record<string, any> =>
  v !== null && typeof v === "object" && !Array.isArray(v);

// SUB-28: a value-based (not reference-based) diff. Applies onto `rawVal` only
// the leaves whose `nextVal` differs BY VALUE from `baseVal`, recursing into
// plain objects. This is the fix for the reference-diff clobber: when a hook
// rebuilds a sub-object wholesale (e.g. onModifiersChange builds a fresh
// `modifiers`), a reference diff would flag the whole object as changed and
// overwrite raw's untouched PRO leaves (regex/fuzzy.isOn) with the clamped
// operativeBase falses. Diffing by value keeps `next===base` leaves off raw, so
// only the one leaf the user actually toggled lands. Pure; never throws.
const mergeChangedLeaves = (rawVal: any, nextVal: any, baseVal: any): any => {
  // When both `next` and `base` are plain objects, recurse leaf-by-leaf so a
  // rebuilt-but-value-identical sub-object doesn't clobber raw. Any other shape
  // (primitive, array, or one side null/undefined) is compared as a whole leaf.
  if (isPlainObject(nextVal) && isPlainObject(baseVal)) {
    // Start from raw's value (preserving any raw-only sub-keys). If raw's value
    // isn't an object here, fall back to an empty base so we still overlay the
    // genuinely-changed leaves from `next`.
    const merged: Record<string, any> = isPlainObject(rawVal) ? { ...rawVal } : {};
    for (const k of Object.keys(nextVal)) {
      // A key present in `next` but absent from `base` is treated as changed
      // (baseVal[k] is undefined), so `next`'s value lands.
      merged[k] = mergeChangedLeaves(
        merged[k],
        nextVal[k],
        (baseVal as any)[k]
      );
    }
    return merged;
  }
  // Leaf comparison. Arrays and mismatched shapes fall here: a reference/JSON
  // compare is fine (the arrays in this settings shape are small). If the value
  // is unchanged from the base, keep raw's value; otherwise take next's.
  const changed = Array.isArray(nextVal) || Array.isArray(baseVal)
    ? JSON.stringify(nextVal) !== JSON.stringify(baseVal)
    : nextVal !== baseVal;
  return changed ? nextVal : rawVal;
};

// SUB-27/SUB-28: `next` is a full cmdFTakeover built from the CLAMPED
// operativeBase, so spreading it whole onto raw would overwrite raw's PRO
// cmdFTakeover fields (searchHistory.isOn, regex/fuzzy modifiers, layout) with
// their clamped-off values. Apply ONLY the leaves the user actually changed
// relative to operativeBaseCmdF (a deep, value-based diff — see
// mergeChangedLeaves), leaving every untouched raw field intact even when a
// hook hands us a freshly-rebuilt sub-object.
export const mergeChangedCmdFKeys = (
  rawCmdF: CmdFTakeoverSettings,
  next: CmdFTakeoverSettings,
  operativeBaseCmdF: CmdFTakeoverSettings | undefined
): CmdFTakeoverSettings => {
  // No base to diff against → apply every next key (original behavior).
  if (!operativeBaseCmdF) {
    return { ...rawCmdF, ...next };
  }
  const patched: Record<string, any> = { ...rawCmdF };
  for (const k of Object.keys(next) as (keyof CmdFTakeoverSettings)[]) {
    patched[k as string] = mergeChangedLeaves(
      (rawCmdF as any)[k],
      (next as any)[k],
      (operativeBaseCmdF as any)[k]
    );
  }
  return patched as CmdFTakeoverSettings;
};

const persistSettings = async (
  next: CmdFTakeoverSettings,
  base?: GlobalSettings
) => {
  const operativeBase = base ?? currentGlobalSettings;
  if (!operativeBase) return;
  const merged = { ...operativeBase, cmdFTakeover: next };
  setGlobalSettings(merged);
  await persistGlobalSettingsDelta((raw) =>
    raw.cmdFTakeover
      ? {
          ...raw,
          cmdFTakeover: mergeChangedCmdFKeys(
            raw.cmdFTakeover,
            next,
            operativeBase.cmdFTakeover
          ),
        }
      : raw
  );
  mirrorFastBoot(merged);
};

const buildHooks = (settings: CmdFTakeoverSettings): BarHooks => ({
  onClose: () => {
    void flushPersist();
    unmount();
  },
  onPromote: async (submission) => {
    const c = getDefaultColors();
    const newQuery: QueryItem = {
      id: uuid(),
      name: submission.name,
      isInactive: false,
      isRegexp: settings.modifiers.regex.isOn,
      colors: {
        hex: c.hex.replace("#", ""),
        rgb: { ...c.rgb, a: c.rgb?.a ?? 1 },
        hsl: { ...c.hsl, a: c.hsl?.a ?? 1 },
      },
    };
    try {
      await addQueryAndHighlight(newQuery);
      // Re-render the bar so the new saved highlight appears as a pill.
      // Without this the chips list is whatever was passed at mount.
      const cur = currentGlobalSettings?.cmdFTakeover;
      if (cur && isMounted()) {
        update({
          settings: cur,
          savedQueries: buildSavedQueryRefs(),
          hooks: buildHooks(cur),
        });
      }
    } catch {
      // Storage write or highlight pass failed — keep the bar open so
      // the user can retry. addQueryAndHighlight is responsible for
      // reverting any partial state on failure.
    }
  },
  onRemoveSavedQuery: (queryId) => {
    const settings = currentGlobalSettings;
    if (!settings) return;
    const items = settings.queryListState.selectedList.itemList.filter(
      (it) => it.id !== queryId
    );
    const merged: GlobalSettings = {
      ...settings,
      queryListState: {
        ...settings.queryListState,
        selectedList: {
          ...settings.queryListState.selectedList,
          itemList: items,
        },
      },
    };
    setGlobalSettings(merged);
    // SUB-27: remove the query from the RAW stored itemList (not the clamped
    // 5-item projection `items`), so a free user's queries 6+ survive.
    void persistGlobalSettingsDelta((raw) => ({
      ...raw,
      queryListState: {
        ...raw.queryListState,
        selectedList: {
          ...raw.queryListState.selectedList,
          itemList: raw.queryListState.selectedList.itemList.filter(
            (it) => it.id !== queryId
          ),
        },
      },
    }));
    // Strip the painted highlights for the removed query so the page
    // updates instantly. Each match is a <hility data-hility='<id>'>
    // wrapping a text node — unwrap and merge adjacent text nodes.
    document
      .querySelectorAll<HTMLElement>(`[${dataHility}='${queryId}']`)
      .forEach((el) => {
        const parent = el.parentNode;
        if (!parent) return;
        while (el.firstChild) parent.insertBefore(el.firstChild, el);
        parent.removeChild(el);
        if (parent instanceof Element || parent instanceof Document) {
          (parent as any).normalize?.();
        }
      });
    delete savedQueryNavIndex[queryId];
    if (isMounted() && settings.cmdFTakeover) {
      update({
        settings: settings.cmdFTakeover,
        savedQueries: buildSavedQueryRefs(),
        hooks: buildHooks(settings.cmdFTakeover),
      });
    }
  },
  onJumpToSavedMatch: (queryId, direction) => {
    const all = Array.from(
      document.querySelectorAll<HTMLElement>(`[${dataHility}='${queryId}']`)
    );
    // Navigate over the same set the chip count advertises — see
    // buildSavedQueryRefs.
    const els = all.filter((el) => isHilityCounted(el));
    if (!els.length) return;
    const prev = savedQueryNavIndex[queryId] ?? -1;
    const next = (prev + direction + els.length) % els.length;
    savedQueryNavIndex[queryId] = next;
    els[next].scrollIntoView({ behavior: "smooth", block: "center" });
    pulseHilityElement(els[next]);
  },
  onScrollToMatch: scrollToMatch,
  onJumpToTab: (tabId, term) => {
    // Focus the matched tab. We send a runtime message rather than
    // calling chrome.tabs.update directly because content scripts don't
    // have the tabs API — the background script will do it on our behalf.
    // `openTerm` rides along so the background can tell that clicked tab to
    // open its finder pre-filled and continue this search there.
    try {
      const runtime: any =
        typeof chrome !== "undefined" && chrome.runtime
          ? chrome.runtime
          : typeof browser !== "undefined" && browser.runtime
          ? browser.runtime
          : null;
      runtime?.sendMessage?.({ type: "highlighty-cmdf-focus-tab", tabId, openTerm: term });
    } catch {}
  },
  onTermChange: persistTermChange,
  onClearHistory: () => {
    // Wipe the persisted history and update the live bar so the
    // dropdown collapses without waiting for a re-render round-trip
    // through storage.
    const cur = currentGlobalSettings;
    if (!cur?.cmdFTakeover) return;
    const nextCmdF: CmdFTakeoverSettings = { ...cur.cmdFTakeover, history: [] };
    const merged: GlobalSettings = { ...cur, cmdFTakeover: nextCmdF };
    setGlobalSettings(merged);
    // SUB-27: clear history on the RAW stored cmdFTakeover, not the clamp.
    void persistGlobalSettingsDelta((raw) =>
      raw.cmdFTakeover
        ? { ...raw, cmdFTakeover: { ...raw.cmdFTakeover, history: [] } }
        : raw
    );
    mirrorFastBoot(merged);
    if (isMounted()) {
      update({
        settings: nextCmdF,
        savedQueries: buildSavedQueryRefs(),
        history: [],
        hooks: buildHooks(nextCmdF),
      });
    }
  },
  onAdHocResultsUpdate: (matches: AdHocMatch[]) => {
    if (!settings.showInScrollbar) {
      // User disabled the feature mid-bar — make sure any stale ad-hoc
      // markers from a previous on-state don't linger.
      clearAdHocMarkers();
      return;
    }
    if (!matches.length) {
      clearAdHocMarkers();
      return;
    }
    // Cyan accent matches the ad-hoc paint color from paintAdHoc.ts but
    // with extra alpha so single markers stay visible against light page
    // chrome.
    setAdHocMarkers(
      matches.map((m) => m.range),
      "rgba(118, 244, 233, 0.95)"
    );
  },
  onModifiersChange: async (modifiers) => {
    const cur = currentGlobalSettings?.cmdFTakeover;
    if (!cur) return;
    const nextSettings: CmdFTakeoverSettings = { ...cur, modifiers };
    await persistSettings(nextSettings);
  },
  onDisableTakeover: () => {
    const cur = currentGlobalSettings?.cmdFTakeover;
    if (!cur) return;
    void persistSettings({ ...cur, isOn: false });
    void flushPersist();
    unmount();
  },
  onCloseSnippets: () => {
    // Flip the layout back to "stripe" and immediately re-render the bar
    // so the snippet panel disappears without waiting for a storage round-
    // trip. The popup dropdown will read "Top stripe" on its next open.
    const cur = currentGlobalSettings?.cmdFTakeover;
    if (!cur) return;
    const nextSettings: CmdFTakeoverSettings = { ...cur, layout: "stripe" };
    void persistSettings(nextSettings);
    void flushPersist();
    // Re-render the bar synchronously so the snippet panel is removed
    // immediately (persistSettings writes to storage async; the storage
    // change listener that normally drives update() fires too late).
    if (isMounted()) {
      update({
        settings: nextSettings,
        savedQueries: buildSavedQueryRefs(),
        hooks: buildHooks(nextSettings),
      });
    }
  },
  onReady: () => intercept.notifyBarReady(),
  onPersistBarUiState: (state) => {
    schedulePersistBarUiState(state);
  },
  onToggleSearchOnlySaved: () => {
    const cur = currentGlobalSettings?.cmdFTakeover;
    if (!cur) return;
    const nextSettings: CmdFTakeoverSettings = {
      ...cur,
      searchOnlyInSavedHighlights: !cur.searchOnlyInSavedHighlights,
    };
    void persistSettings(nextSettings);
    if (isMounted()) {
      update({
        settings: nextSettings,
        savedQueries: buildSavedQueryRefs(),
        hooks: buildHooks(nextSettings),
      });
    }
  },
  onToggleRememberLastQuery: () => {
    const cur = currentGlobalSettings?.cmdFTakeover;
    if (!cur) return;
    const nextSettings: CmdFTakeoverSettings = {
      ...cur,
      persistLastQueryPerSite: !cur.persistLastQueryPerSite,
    };
    void persistSettings(nextSettings);
    if (isMounted()) {
      update({
        settings: nextSettings,
        savedQueries: buildSavedQueryRefs(),
        hooks: buildHooks(nextSettings),
      });
    }
  },
});

const openBar = () => {
  const settings = currentGlobalSettings?.cmdFTakeover;
  if (!settings) return;
  // SNP-07: make sure this tab is listening for cross-tab bar-UI-state writes
  // before it seeds/persists from the cache (idempotent).
  ensureBarUiReconcileListener();
  // Consume the one-shot cross-tab-jump seed (if any): a pending term overrides
  // the usual initial term and marks the open as seeded-externally. Cleared
  // immediately so the next ordinary open is unaffected.
  const seededTerm = pendingSeedTerm;
  pendingSeedTerm = null;
  mount({
    settings,
    savedQueries: buildSavedQueryRefs(),
    initialTerm: seededTerm ?? getInitialTerm(),
    history: settings.history,
    hint: pendingHint ?? undefined,
    onHintDone: pendingHint
      ? () => {
          pendingHint = null;
          if (isMounted()) update({ hint: undefined, hooks: buildHooks(settings), savedQueries: buildSavedQueryRefs() });
        }
      : undefined,
    hooks: buildHooks(settings),
    searchRoot: currentSearchRoot,
    initialBarUiState: currentBarUiState,
    seededExternally: seededTerm !== null,
  });
  // First open: kick the async load and update once it lands. Subsequent
  // opens use the cached value synchronously.
  if (!hasLoadedBarUiState) {
    void ensureBarUiStateLoaded().then(() => {
      if (isMounted()) {
        update({ initialBarUiState: currentBarUiState, hooks: buildHooks(settings), savedQueries: buildSavedQueryRefs() });
      }
    });
  }
};

const closeBar = () => {
  if (isMounted()) unmount();
};

// Destination-side of the cross-tab "jump" flow: the background forwarded the
// searcher's term to THIS clicked tab. Open the finder pre-filled and scrolled
// to the first match so the user can keep searching here.
//
// Respect this tab's own gating: if the takeover is off or the origin is
// blacklisted, don't force a bar open (the tab is already focused by the
// background — we just decline the extra UI, honoring the user's per-site
// opt-out). The bar's term is local state seeded only at mount, so if a bar is
// already open (with an unrelated term) we remount to force the new term in.
const openBarWithTerm = (term: string) => {
  const settings = currentGlobalSettings;
  // Mirror the FULL normal open gate (intercept.shouldIntercept) so a forced
  // open can't bypass a gate the keyboard path enforces: isOn + blacklist +
  // per-origin auto-disable (failure tracker backed off after repeated failures
  // here) + the transient gates (native-handoff suppression window, fullscreen).
  if (!settings?.cmdFTakeover?.isOn) return;
  try {
    if (isBlackListedSite(settings)) return;
  } catch {}
  try {
    if (failureTracker.isAutoDisabled(getOrigin())) return;
  } catch {}
  try {
    if (intercept.isTransientlyBlocked()) return;
  } catch {}
  pendingSeedTerm = term;
  if (isMounted()) unmount();
  // Wrap the open in the same failure-recording envelope the keyboard path has.
  // mount() rethrows on failure (CMF-18); without this the throw would vanish in
  // installOpenWithTermHandler's catch — no failure recorded (so a repeatedly-
  // broken origin could never auto-disable via jumps) and no signal. Clear the
  // seed on failure so a later ordinary open isn't polluted by a stale term.
  try {
    openBar();
  } catch (err) {
    pendingSeedTerm = null;
    void failureTracker.recordFailure(getOrigin(), err);
  }
};

// Minimal-bar fallback used when bootMinimal mounted before real settings
// arrived. No saved queries, no history, default modifiers. The real
// boot() will swap deps once settings hydrate; if the user closes/reopens
// the bar after that, openBar() takes over.
const openMinimalBar = () => {
  const settings: CmdFTakeoverSettings = {
    ...cmdFTakeoverDefaults,
    isOn: true,
  };
  mount({
    settings,
    savedQueries: [],
    initialTerm: "",
    history: [],
    hooks: {
      onClose: () => unmount(),
      onPromote: async () => {},
      onRemoveSavedQuery: () => {},
      onJumpToSavedMatch: () => {},
      onScrollToMatch: () => {},
      onModifiersChange: () => {},
      onTermChange: () => {},
      onReady: () => intercept.notifyBarReady(),
    },
  });
};

export const bootMinimal = () => {
  if (minimalInstalled) return;
  const fast = readFastBoot();
  if (!fast.on) return;
  const origin = getOrigin();
  if (fast.blacklist.includes(origin)) return;
  minimalInstalled = true;
  intercept.install({
    getSettings: () =>
      currentGlobalSettings ??
      ({ cmdFTakeover: { ...cmdFTakeoverDefaults, isOn: true } } as GlobalSettings),
    isOriginBlacklisted: () => false,
    openBar: () => {
      // If real settings have arrived, use the full openBar.
      if (currentGlobalSettings?.cmdFTakeover) openBar();
      else openMinimalBar();
    },
    closeBar,
    isBarOpen: () => isMounted(),
    showHint: () => {},
    onFailure: (origin, err) => {
      void failureTracker.recordFailure(origin, err);
    },
    getOrigin,
  });
};

export const boot = (settings: GlobalSettings, opts?: BootOptions) => {
  // The PDF viewer re-calls boot() on every settings refresh; preserving
  // the most recently supplied searchRoot keeps Cmd+F scoped across those
  // refreshes (otherwise a popup change would silently revert to body).
  if (opts?.searchRoot !== undefined) {
    currentSearchRoot = opts.searchRoot;
  }
  // Always mirror — including when off, so a stale cache from a prior
  // session can't keep installing the intercept after the user disables.
  mirrorFastBoot(settings);
  if (!settings.cmdFTakeover?.isOn) {
    cleanup();
    return;
  }
  // The cross-tab probe handler is installed once per content script
  // (regardless of whether this tab is the searcher or the searched).
  // It only acts when a CROSS_TAB_PROBE message arrives, so it's cheap
  // to leave armed.
  if (!probeHandlerInstalled) {
    // CMF-30: hand the probe THIS tab's live search root (read lazily so a
    // later boot() that supplies a scoped root — e.g. the PDF viewer's text
    // layer — is honored) so cross-tab counts match this tab's own bar count.
    probeHandlerDispose = installCrossTabProbeHandler(
      () => currentSearchRoot?.() ?? document.body
    );
    probeHandlerInstalled = true;
  }
  // Destination-side of the cross-tab "jump" flow — armed once per content
  // script, like the probe handler. Only acts when the background forwards an
  // OPEN_WITH_TERM message to THIS clicked tab, so it's cheap to leave armed.
  if (!openWithTermInstalled) {
    openWithTermDispose = installOpenWithTermHandler((term) => openBarWithTerm(term));
    openWithTermInstalled = true;
  }
  // Refresh chip counts after every settled highlight pass — this is the
  // signal that fires when content.observer.ts caught a relevant DOM
  // mutation (nav drawer opened, accordion expanded, SPA route change).
  // Without this, the chip's count stayed frozen at whatever the last
  // explicit refresh (bar open / save / settings change) computed, so
  // newly-visible hility nodes never made it into the displayed total.
  //
  // We pass settings + hooks alongside savedQueries because update()
  // doesn't preserve them across calls — see ui/mount.ts (hooks is
  // non-null-asserted, settings falls back to lastSettings only if
  // omitted from the partial). Passing them keeps the bar's wiring
  // intact through the re-render.
  if (!postHighlightDispose) {
    postHighlightDispose = addPostHighlightListener(() => {
      if (!isMounted()) return;
      const cmdF = currentGlobalSettings?.cmdFTakeover;
      if (!cmdF) return;
      update({
        settings: cmdF,
        savedQueries: buildSavedQueryRefs(),
        hooks: buildHooks(cmdF),
      });
    });
  }
  intercept.install({
    getSettings: () => currentGlobalSettings,
    isOriginBlacklisted: (s) => isBlackListedSite(s),
    openBar,
    closeBar,
    isBarOpen: () => isMounted(),
    showHint: (msg) => {
      // Suppress the double-press handoff hint after the user has seen
      // it a few times on this origin — by then they know the gesture
      // and the toast becomes noise. Other hint messages (e.g., error
      // recovery) are always shown.
      const origin = getOrigin();
      const isDoublePressHint = msg === HINT_DOUBLE_PRESS;
      if (isDoublePressHint && hintCount(origin) >= HINT_MAX_PER_ORIGIN) return;
      if (isDoublePressHint) void incrementHintShown(origin);

      if (isMounted()) {
        const cmdFSettings = currentGlobalSettings?.cmdFTakeover;
        if (!cmdFSettings) return;
        pendingHint = msg;
        update({
          settings: cmdFSettings,
          savedQueries: buildSavedQueryRefs(),
          hint: msg,
          onHintDone: () => {
            pendingHint = null;
            update({ hint: undefined, hooks: buildHooks(cmdFSettings), savedQueries: buildSavedQueryRefs() });
          },
          hooks: buildHooks(cmdFSettings),
        });
      } else {
        pendingHint = msg;
        // No bar to attach the hint to; show a transient one in the page.
        const node = document.createElement("div");
        node.textContent = msg;
        node.style.cssText =
          "position:fixed;top:14px;left:50%;transform:translateX(-50%);background:rgba(20,22,27,0.96);color:#fff;padding:6px 14px;border-radius:999px;font:12px -apple-system,system-ui,sans-serif;box-shadow:0 6px 18px rgba(0,0,0,0.35);z-index:2147483647;border:1px solid rgba(172,137,245,0.30);";
        node.setAttribute("data-highlighty-cmdf", "");
        document.body.appendChild(node);
        setTimeout(() => node.remove(), 2000);
      }
    },
    onFailure: (origin, err) => {
      void failureTracker.recordFailure(origin, err);
    },
    getOrigin,
  });
  installBfcacheReinstall(() => {
    if (currentGlobalSettings) boot(currentGlobalSettings);
    else bootMinimal();
  });
  // Popup edits propagate via boot(); if the bar happens to be open,
  // refresh its props so chip add/remove and modifier toggles from the
  // popup show up live instead of waiting for a reopen.
  if (isMounted() && settings.cmdFTakeover) {
    update({
      settings: settings.cmdFTakeover,
      savedQueries: buildSavedQueryRefs(),
      hooks: buildHooks(settings.cmdFTakeover),
    });
  }
};

export const cleanup = () => {
  intercept.uninstall();
  uninstallBfcacheReinstall();
  unmount();
  // Tear down the cross-tab probe listener — without this, a tab that
  // disabled the takeover still answers probe messages from other tabs
  // (audit bug #7 — privacy regression).
  if (probeHandlerDispose) {
    try {
      probeHandlerDispose();
    } catch {}
    probeHandlerDispose = null;
  }
  probeHandlerInstalled = false;
  // Tear down the open-with-term handler too — a tab that disabled the takeover
  // shouldn't get a finder force-opened by a stale listener.
  if (openWithTermDispose) {
    try {
      openWithTermDispose();
    } catch {}
    openWithTermDispose = null;
  }
  openWithTermInstalled = false;
  pendingSeedTerm = null;
  if (postHighlightDispose) {
    try {
      postHighlightDispose();
    } catch {}
    postHighlightDispose = null;
  }
  pendingHint = null;
  savedQueryNavIndex = {};
  minimalInstalled = false;
  currentSearchRoot = undefined;
};
