import { v4 as uuidv4 } from 'uuid';
import { getDefaultColors } from '../../components/shared/utils/color.utils';
import { GlobalSettings, QueryItem } from '../../definitions/global.definition';
import { persistGlobalSettingsDelta } from './content.persistGlobalSettings';
import {
  currentGlobalSettings,
  setGlobalSettings
} from './content.globalSettingsState';
import { doMarkSearch } from './content.highlight';
import { isEditableEventTarget } from './utils/editable.utils';
let selectListener = null as unknown as AbortController;

export const initSearchBySelect = (settings: GlobalSettings) => {
  const isSearchBySelect = settings.searchBySelect.isOn;

  const selectPress = async (e: KeyboardEvent) => {
    if (e.key === 'L' && e.shiftKey && isSearchBySelect) {
      // TGL-03: read the brightness setting LIVE at fire time, not from a
      // value captured when the listener was armed. The listener is built
      // once and kept while the feature stays on, so a value captured here
      // would freeze the "bright colors" choice at first arm — flipping the
      // toggle mid-session would have no effect until a feature off/on.
      const isSearchColorBright =
        currentGlobalSettings.searchBySelect.isBright;

      // See editable.utils.ts. Inputs/textareas are already incidentally
      // safe (their selection isn't surfaced via window.getSelection),
      // but contenteditable selections ARE — so without this guard a
      // user typing capital "L" with text selected in a rich editor
      // (Google Docs, Notion, comment composers) silently turns that
      // selection into a new permanent query.
      if (isEditableEventTarget(e)) return;

      const selectedWord = window.getSelection()?.toString()?.trim();

      if (!selectedWord?.length) return;

      const newItem: QueryItem = {
        colors: getDefaultColors(isSearchColorBright),
        id: uuidv4(),
        isInactive: false,
        isRegexp: false,
        name: selectedWord,
        decorationType: 'background',
        decorationThickness: 'medium',
      };

      const isAlreadyInList =
        currentGlobalSettings.queryListState.selectedList.itemList.filter(
          (listItem) => listItem.name === newItem.name
        );

      if (isAlreadyInList?.length) return;

      const newGlobalSettings = mapGlobalSettings(newItem);

      saveToDatabase(newItem);
      // await
      doMarkSearch(newGlobalSettings, undefined, newItem);
      setGlobalSettings(newGlobalSettings);
    }
  };

  if (isSearchBySelect && !selectListener) {
    selectListener = new AbortController();

    document.addEventListener('keyup', selectPress, selectListener);
  } else if (!isSearchBySelect && selectListener?.abort) {
    selectListener.abort();
    selectListener = null as unknown as AbortController;

    // console.log('abort nav listener');
  }
};

// switchOffCleanup calls this when the user toggles the extension off in
// the popup. The init function only re-aborts when the *feature* is
// toggled off; without an explicit cleanup the listener would survive an
// extension-wide off and keep adding queries on Shift+L.
export const cleanupSearchBySelect = () => {
  if (selectListener?.abort) {
    selectListener.abort();
    selectListener = null as unknown as AbortController;
  }
};

// SUB-27: prepend the new item onto the RAW stored lists — never write the
// clamped in-memory copy back to storage. Replicates the SAME two mutations
// mapGlobalSettings makes (selectedList.itemList prepend, plus the queryList[]
// entry whose id matches the selected list), but applied to the raw base so a
// free user's queries 6+ / regex flags survive.
const saveToDatabase = async (newItem: QueryItem) => {
  await persistGlobalSettingsDelta((raw) => {
    const rawSelected = raw.queryListState.selectedList;
    const newSelectedList = {
      ...rawSelected,
      itemList: [newItem, ...rawSelected.itemList],
    };
    const newQueryList = raw.queryListState.queryList.map((eachList) =>
      eachList.id === newSelectedList.id ? newSelectedList : eachList
    );
    return {
      ...raw,
      queryListState: {
        ...raw.queryListState,
        queryList: newQueryList,
        selectedList: newSelectedList,
      },
    };
  });
};

const mapGlobalSettings = (newItem: QueryItem) => {
  const newSelectedQueryList = [
    newItem,
    ...currentGlobalSettings.queryListState.selectedList.itemList,
  ];

  const newSelectedQuery = {
    ...currentGlobalSettings.queryListState.selectedList,
    itemList: newSelectedQueryList,
  };

  const newAllQueryLists = currentGlobalSettings.queryListState.queryList.map(
    (eachList) =>
      eachList.id === newSelectedQuery.id ? newSelectedQuery : eachList
  ) as any[];

  const newGlobalSettings: GlobalSettings = {
    ...currentGlobalSettings,
    queryListState: {
      ...currentGlobalSettings.queryListState,
      queryList: newAllQueryLists,
      selectedList: newSelectedQuery,
    },
  };

  return newGlobalSettings;
};
