// Per-origin failure counter. Lives in chrome.storage.local under the
// existing globalSettings.cmdFTakeover.failureCounts map. Three failures
// within the decay window add the origin to autoDisabledDomains; a
// successful intercept clears the counter for that origin.
//
// All state lives in the GlobalSettings tree so the popup, content
// scripts, and the kill-switch chord all see the same data.
import {
  CmdFTakeoverSettings,
  GlobalSettings,
} from "../../../definitions/global.definition";
import { cmdFTakeoverDefaults } from "../../../components/shared/utils/constants.consts";
import { persistGlobalSettingsDelta } from "../content.persistGlobalSettings";
import {
  currentGlobalSettings,
  setGlobalSettings,
} from "../content.globalSettingsState";

export const FAILURE_THRESHOLD = 3;
export const FAILURE_DECAY_MS = 24 * 60 * 60 * 1000;

const cloneTakeover = (
  takeover: CmdFTakeoverSettings | undefined
): CmdFTakeoverSettings => ({
  ...cmdFTakeoverDefaults,
  ...(takeover ?? {}),
  failureCounts: { ...((takeover ?? {}).failureCounts ?? {}) },
  autoDisabledDomains: [...((takeover ?? {}).autoDisabledDomains ?? [])],
  hintShown: { ...((takeover ?? {}).hintShown ?? {}) },
});

const persist = async (next: GlobalSettings) => {
  setGlobalSettings(next);
  // SUB-27: persist ONLY the two owned cmdFTakeover fields onto the RAW stored
  // settings — spreading the whole clamped `next` would truncate a free user's
  // lists / strip regex flags / drop PRO cmdFTakeover prefs.
  await persistGlobalSettingsDelta((raw) =>
    raw.cmdFTakeover
      ? {
          ...raw,
          cmdFTakeover: {
            ...raw.cmdFTakeover,
            failureCounts: next.cmdFTakeover!.failureCounts,
            autoDisabledDomains: next.cmdFTakeover!.autoDisabledDomains,
          },
        }
      : raw
  );
};

// CMF-14: recordFailure is invoked fire-and-forget (`void recordFailure(...)`)
// from the watchdog/handler/native-handoff paths. After an extension-context
// invalidation (hot update/reload), the underlying chrome.storage write
// rejects — and because the caller does not await, that rejection would surface
// as an unhandled promise rejection (console noise) even though re-arming never
// depends on the resolved value. Swallow the persist rejection on the failure
// path: the in-memory state was already updated synchronously inside persist(),
// so the only thing the rejection signals is "storage unavailable right now",
// which self-heals on the next page load.
const persistFailureBestEffort = async (next: GlobalSettings) => {
  try {
    await persist(next);
  } catch {
    /* context invalidated mid-write; in-memory state already updated */
  }
};

export const recordFailure = async (origin: string, _err?: unknown) => {
  if (!origin) return;
  const settings = currentGlobalSettings;
  if (!settings) return;
  const takeover = cloneTakeover(settings.cmdFTakeover);
  const now = Date.now();
  const previous = takeover.failureCounts[origin];
  const decayed =
    previous && now - previous.lastFailureAt > FAILURE_DECAY_MS
      ? { count: 0, lastFailureAt: now }
      : previous ?? { count: 0, lastFailureAt: now };

  takeover.failureCounts[origin] = {
    count: decayed.count + 1,
    lastFailureAt: now,
  };

  if (
    takeover.failureCounts[origin].count >= FAILURE_THRESHOLD &&
    !takeover.autoDisabledDomains.includes(origin)
  ) {
    takeover.autoDisabledDomains = [...takeover.autoDisabledDomains, origin];
  }

  await persistFailureBestEffort({ ...settings, cmdFTakeover: takeover });
};

export const recordSuccess = async (origin: string) => {
  if (!origin) return;
  const settings = currentGlobalSettings;
  if (!settings) return;
  const takeover = cloneTakeover(settings.cmdFTakeover);
  if (!takeover.failureCounts[origin]) return;
  delete takeover.failureCounts[origin];
  await persist({ ...settings, cmdFTakeover: takeover });
};

export const reEnableOrigin = async (origin: string) => {
  if (!origin) return;
  const settings = currentGlobalSettings;
  if (!settings) return;
  const takeover = cloneTakeover(settings.cmdFTakeover);
  takeover.autoDisabledDomains = takeover.autoDisabledDomains.filter(
    (d) => d !== origin
  );
  delete takeover.failureCounts[origin];
  await persist({ ...settings, cmdFTakeover: takeover });
};

export const isAutoDisabled = (origin: string): boolean => {
  const settings = currentGlobalSettings;
  if (!settings?.cmdFTakeover) return false;
  return settings.cmdFTakeover.autoDisabledDomains.includes(origin);
};
