// Pure helpers for the scrollbar strip's bucketing layer. No DOM access,
// no module-level state — all I/O happens in content.scrollbarHighlighter.ts.

export const FAN_OUT = 3;
export const MIN_BUCKET_COUNT = 60;
export const BUCKET_PX = 5;
export const BAR_HEIGHT_MIN = 5;
export const BAR_HEIGHT_MAX = 12;
export const DOC_HEIGHT_DRIFT_THRESHOLD = 0.05;

export type MarkerTarget =
  | { kind: "element"; element: HTMLElement }
  | { kind: "range"; range: Range };

export interface BarEntry {
  members: MarkerTarget[];
  markerEl: HTMLElement;
  cycleIndex: number;
  yTop: number;
  bucketTop: number;
  bucketBottom: number;
  color: string;
  source: "saved" | "adhoc";
  queryId: string;
  bucketIdx: number;
}

export interface BucketInput {
  target: MarkerTarget;
  absoluteTop: number;
  absoluteBottom: number;
}

export const bucketCountFor = (stripHeightPx: number): number =>
  Math.max(MIN_BUCKET_COUNT, Math.floor(stripHeightPx / BUCKET_PX));

/**
 * Group inputs by (absoluteTop / docHeight) × bucketCount. Returns a map
 * keyed by bucket index, value preserves input order within each bucket.
 * Out-of-range absoluteTop is clamped to the last bucket.
 */
export const bucketize = (
  inputs: ReadonlyArray<BucketInput>,
  docHeight: number,
  bucketCount: number,
): Map<number, BucketInput[]> => {
  const out = new Map<number, BucketInput[]>();
  if (inputs.length === 0 || docHeight <= 0 || bucketCount <= 0) return out;
  for (const input of inputs) {
    const raw = Math.floor((input.absoluteTop / docHeight) * bucketCount);
    const idx = Math.max(0, Math.min(bucketCount - 1, raw));
    let bucket = out.get(idx);
    if (!bucket) {
      bucket = [];
      out.set(idx, bucket);
    }
    bucket.push(input);
  }
  return out;
};

export const decideFanOut = (memberCount: number): "fan" | "collapse" =>
  memberCount <= FAN_OUT ? "fan" : "collapse";

/**
 * Logarithmic height for a cluster bar. h = clamp(5 + log2(n), 5, 12).
 * Single-member bars are BAR_HEIGHT_MIN.
 */
export const barHeightForCount = (memberCount: number): number => {
  if (memberCount <= 1) return BAR_HEIGHT_MIN;
  const h = BAR_HEIGHT_MIN + Math.log2(memberCount);
  if (h < BAR_HEIGHT_MIN) return BAR_HEIGHT_MIN;
  if (h > BAR_HEIGHT_MAX) return BAR_HEIGHT_MAX;
  return Math.round(h);
};

export const advanceCycleIndex = (entry: BarEntry): number => {
  const len = Math.max(1, entry.members.length);
  const acted = entry.cycleIndex % len;
  entry.cycleIndex = (acted + 1) % len;
  return acted;
};

export const resetOtherCycleIndices = (
  active: BarEntry,
  all: ReadonlyArray<BarEntry>,
): void => {
  for (const e of all) {
    if (e !== active) e.cycleIndex = 0;
  }
};
