// Capture-phase keydown listener. Owns the decision tree of "should we
// hijack this Cmd/Ctrl+F?" and the recovery path when something goes
// wrong on our side. Every external dependency (bar mount, watchdog,
// failureTracker, doublePress) is invoked through narrow function refs so
// the handler stays testable in isolation.
//
// Invariant: native Cmd+F must remain reachable. If we throw, miss the
// watchdog, or fail to render, the user's NEXT Cmd+F press falls through
// to native via suppressNext().

import { GlobalSettings } from "../../../definitions/global.definition";
import { cmdOrCtrlLabel, isMacPlatform } from "../../../components/shared/utils/platform.utils";
import { isAutoDisabled, recordFailure, recordSuccess } from "./failureTracker";
import { isDoublePress, reset as resetDoublePress } from "./doublePress";
import * as watchdog from "./watchdog";

export interface InterceptDeps {
  getSettings: () => GlobalSettings | undefined;
  isOriginBlacklisted: (settings: GlobalSettings) => boolean;
  openBar: () => void;
  closeBar: () => void;
  isBarOpen: () => boolean;
  showHint: (message: string) => void;
  onFailure: (origin: string, err: unknown) => void;
  getOrigin: () => string;
}

let deps: InterceptDeps | null = null;
let listenerAbort: AbortController | null = null;
let suppressedUntil = 0;

const isCmdF = (e: KeyboardEvent): boolean => {
  if (e.key !== "f" && e.key !== "F") return false;
  // CMF-15/16: the page-find modifier is platform-specific, so match it
  // exactly. On macOS that's ⌘ (metaKey) — ⌃F there is the Cocoa "move
  // forward one character" binding, NOT Find, and the takeover deliberately
  // fires even when focus is in an editable field, so honoring ctrlKey on a
  // Mac hijacks caret-forward in every text box. Off-Mac the modifier is
  // Ctrl, and metaKey is the Super/Win key (not Find). Requiring the other
  // modifier to be absent keeps ⌘⌃F / Ctrl+⌘+F from triggering us.
  return isMacPlatform()
    ? e.metaKey && !e.ctrlKey
    : e.ctrlKey && !e.metaKey;
};

const shouldIntercept = (e: KeyboardEvent): boolean => {
  if (!deps) return false;
  if (e.repeat) return false;
  if (e.altKey || e.shiftKey) return false; // Cmd+Shift+F is not us
  const settings = deps.getSettings();
  if (!settings?.cmdFTakeover?.isOn) return false;
  if (deps.isOriginBlacklisted(settings)) return false;
  const origin = deps.getOrigin();
  if (isAutoDisabled(origin)) return false;
  // Intentionally do NOT bail when focus is in an editable element:
  // native Cmd+F always opens browser Find regardless of focus, and many
  // sites (Wikipedia, search-first apps) auto-focus an input on load —
  // the previous bail-on-editable made the takeover useless on those
  // pages. Apps that bind Cmd+F themselves with capture-phase listeners
  // still beat us by stopping propagation.
  //
  // The transient page-state gates (native-handoff suppression window +
  // fullscreen) live in isTransientlyBlocked() so the cross-tab jump's forced
  // open honors the exact same gates — a new one applies to both by construction.
  if (isTransientlyBlocked()) return false;
  return true;
};

// CMF-10: re-focus the bar's search input on a Cmd+F-while-open press.
// openBar() re-renders the EXISTING React root (no remount), so BarRoot's
// mount-time `useEffect(…, [])` focus effect never re-runs — a second Cmd+F
// after focus moved into the page would do nothing visible. We don't fight
// React: rather than thread a new prop through the (out-of-scope) host wiring,
// we re-invoke the exact imperative action that effect performs — .focus() +
// .select() on the already-rendered shadow input. No React state is touched,
// so bar term/matches/index are preserved. Best-effort: any failure (no host,
// no shadow, no input) is swallowed so the keydown handler can't throw.
const focusBarInput = () => {
  try {
    const host =
      typeof document !== "undefined"
        ? document.getElementById("highlighty-cmdf-host")
        : null;
    const shadow = host?.shadowRoot ?? null;
    if (!shadow) return;
    const input = shadow.querySelector<HTMLInputElement>(
      'input[aria-label="Search this page"]'
    );
    if (!input) return;
    input.focus();
    input.select();
  } catch {
    // Non-fatal: the re-focus is a nicety, never a correctness requirement.
  }
};

export const suppressNext = (durationMs: number) => {
  suppressedUntil = Math.max(suppressedUntil, Date.now() + durationMs);
};

export const isSuppressed = (now: number = Date.now()): boolean =>
  now < suppressedUntil;

// Page-state gates that block OPENING the bar and change moment-to-moment,
// independent of settings: the native-handoff suppression window, and an active
// fullscreen element that doesn't contain our bar host (don't fight a
// fullscreened player, and don't mount an invisible bar behind the top layer).
// Shared by shouldIntercept (keyboard path) and the cross-tab jump's
// openBarWithTerm so both honor the same gates — and any future transient gate
// added here applies to both without a second hand-maintained list.
export const isTransientlyBlocked = (): boolean => {
  if (isSuppressed()) return true;
  if (
    typeof document !== "undefined" &&
    document.fullscreenElement &&
    !document.fullscreenElement.contains(
      document.getElementById("highlighty-cmdf-host")
    )
  ) {
    return true;
  }
  return false;
};

const handler = (e: KeyboardEvent) => {
  try {
    if (e.key === "Escape") {
      if (!deps) return;
      // CMF-04: closing an already-open bar is ALWAYS safe — gate ONLY on
      // isBarOpen(). The OPEN path (shouldIntercept) is where isOn / blacklist /
      // auto-disable belong. Those can flip to "disabled" mid-session (a
      // cross-tab settings sync, or failureTracker auto-disabling the origin)
      // WITHOUT unmounting the bar; if ESC re-consulted them the user would be
      // stuck with an open bar that ESC can no longer close.
      if (!deps.isBarOpen()) return;
      e.preventDefault();
      e.stopImmediatePropagation();
      resetDoublePress();
      deps.closeBar();
      return;
    }
    if (!isCmdF(e)) return;
    if (!deps) return;
    if (!shouldIntercept(e)) return;

    // Record the press timestamp on EVERY accepted Cmd+F so the second
    // press inside the window gets recognised as a double. Without this,
    // a first-press → (single) → second-press sequence would only see the
    // *second* press's timestamp tracked and never detect the pair.
    const wasDoublePress = isDoublePress();

    // Double-press: close our bar and step out of native's way for 2s.
    // The hint nudges the user to press Cmd+F a third time for native.
    if (
      wasDoublePress &&
      deps.isBarOpen() &&
      deps.getSettings()?.cmdFTakeover?.doublePressEscape
    ) {
      e.preventDefault();
      e.stopImmediatePropagation();
      deps.closeBar();
      deps.showHint(`Press ${cmdOrCtrlLabel("F")} again for native search`);
      suppressNext(2000);
      return;
    }

    e.preventDefault();
    e.stopImmediatePropagation();
    if (deps.isBarOpen()) {
      // Re-focus the existing bar; no watchdog needed since it's already mounted.
      // openBar() re-renders the existing root but does NOT re-run BarRoot's
      // mount-time focus effect, so explicitly pull focus back into the search
      // input here (CMF-10) — otherwise a 2nd Cmd+F after focus moved into the
      // page appears to do nothing. focusBarInput() preserves bar state (it's
      // a pure DOM .focus()/.select(), no React state change).
      deps.openBar();
      focusBarInput();
      return;
    }
    watchdog.start(() => {
      deps?.onFailure(deps.getOrigin(), new Error("watchdog: bar did not render"));
      deps?.closeBar();
      suppressNext(2000);
      deps?.showHint(`Press ${cmdOrCtrlLabel("F")} again for native search`);
    });
    deps.openBar();
  } catch (err) {
    watchdog.cancel();
    if (deps) {
      void recordFailure(deps.getOrigin(), err);
      try {
        deps.closeBar();
      } catch {}
      suppressNext(2000);
      deps.showHint(
        `Highlighty hit a snag — press ${cmdOrCtrlLabel("F")} again for native`
      );
    }
  }
};

export const install = (newDeps: InterceptDeps) => {
  uninstall();
  deps = newDeps;
  listenerAbort = new AbortController();
  document.addEventListener("keydown", handler, {
    capture: true,
    signal: listenerAbort.signal,
  });
};

export const uninstall = () => {
  if (listenerAbort) {
    listenerAbort.abort();
    listenerAbort = null;
  }
  watchdog.cancel();
  resetDoublePress();
  // CMF-17: clear the native-handoff suppression window too. suppressedUntil is
  // module-level, so a double-press/failure handoff that set it (Date.now()+2s)
  // would otherwise survive a cleanup()→uninstall() / boot()→install() toggle
  // within that window and silently swallow the first Cmd+F of the re-enabled
  // session. Reset it alongside the double-press state so re-install starts clean.
  suppressedUntil = 0;
  deps = null;
};

export const notifyBarReady = () => {
  watchdog.cancel();
  // CMF-35: a rendered bar is the definitive success signal. Clear this
  // origin's accumulated failure count so intermittent glitches spanning the
  // 24h decay window can't accrue to a PERMANENT auto-disable (the takeover
  // silently reverting to native Find on that origin until a manual
  // re-enable). recordSuccess is a no-op when the origin has no recorded
  // failures. Fire-and-forget with a swallowed rejection — re-arming never
  // depends on the persist resolving (mirrors recordFailure's CMF-14 handling).
  if (deps) void recordSuccess(deps.getOrigin()).catch(() => {});
};

export const __testing = {
  setSuppressedUntil: (ts: number) => {
    suppressedUntil = ts;
  },
};
