// FloatingSnippetsShell wraps the pure SnippetPanel content component
// into a free-floating, draggable, collapsible overlay — mirroring the
// PDF X-Ray panel's UX. Position and collapsed state are owned here and
// persisted back through onPersistSnippetsPanel so BarRoot can fold them
// into the existing cmdFTakeoverBarUiState chrome.storage entry.
//
// Drag is delegated to the shared makeDraggable util with the header as
// the drag handle. The body uses React conditional render for the
// collapsed state — no CSS-only collapse so there's nothing to clean up
// when the chevron flips.

import React, { useEffect, useRef, useState } from "react";
import { FiChevronDown, FiChevronUp } from "react-icons/fi";
import SnippetPanel from "./SnippetPanel";
import { AdHocMatch } from "../ephemeralSearch";
import { makeDraggable } from "../../sharedUi/makeDraggable";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";

export interface FloatingSnippetsState {
  position: { top: number | null; left: number | null };
  isCollapsed: boolean;
}

// Keep the panel's header — the drag handle AND the chevron/close controls, which
// sit at its TOP-RIGHT — reachable inside the viewport. Vertically, keeping this
// much of the panel below the top edge keeps the (top) header on-screen.
const PANEL_VIEWPORT_INSET_BOTTOM = 60;
// SNP-15: fallback panel width used to derive the RIGHT bound when the shell
// isn't measurable yet (jsdom / pre-layout). maxLeft = innerWidth - panelWidth
// keeps the panel's right edge — where the chevron+close controls live — on
// screen. The OLD fixed 240 right-inset was NARROWER than the ~320px panel, so a
// rightward drag pushed the right ~80px (the controls) off-screen.
const PANEL_DEFAULT_WIDTH = 320;

const maxLeftForWidth = (panelWidth: number) =>
  Math.max(0, window.innerWidth - (panelWidth || PANEL_DEFAULT_WIDTH));

// SNP-01: a position persisted on a large window must be clamped to the
// CURRENT viewport before it's applied — otherwise restoring it in a smaller
// window (laptop, resized/restored window) places the panel fully off-screen
// and unreachable (no in-page way to grab it back). The drag and resize paths
// already clamp; this makes the restore path do the same. `panelWidth` is the
// measured shell width (0/undefined → PANEL_DEFAULT_WIDTH).
const clampPanelPosition = (top: number, left: number, panelWidth = 0) => ({
  top: Math.min(
    Math.max(0, top),
    Math.max(0, window.innerHeight - PANEL_VIEWPORT_INSET_BOTTOM)
  ),
  left: Math.min(Math.max(0, left), maxLeftForWidth(panelWidth)),
});

export interface FloatingSnippetsShellProps {
  matches: AdHocMatch[];
  currentIndex: number;
  fullText: string;
  radius?: number;
  onJump: (index: number) => void;
  onClose?: () => void;
  accessState?: PremiumFeatureAccessState;
  initialState: FloatingSnippetsState;
  // SNP-23: `userInitiated` distinguishes a genuine user drag/collapse (default
  // true) from an AUTOMATIC clamp-correction (false). BarRoot only marks the
  // panel "touched this session" — which freezes later cross-tab/hydration
  // adoption — for user-initiated writes, so an off-screen clamp-correction can
  // no longer masquerade as a user action and block a legitimate later value.
  onPersistSnippetsPanel: (
    state: FloatingSnippetsState,
    userInitiated?: boolean
  ) => void;
}

const CLOSE_LABEL =
  "Hide the snippets panel. Re-enable from Highlighty popup → Cmd+F takeover → Layout.";

const FloatingSnippetsShell: React.FC<FloatingSnippetsShellProps> = ({
  matches,
  currentIndex,
  fullText,
  radius,
  onJump,
  onClose,
  accessState,
  initialState,
  onPersistSnippetsPanel,
}) => {
  const shellRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);
  const positionRef = useRef(initialState.position);
  const [isCollapsed, setIsCollapsed] = useState<boolean>(initialState.isCollapsed);
  // Ref-mirror so drag's onPersist closure reads the latest value
  // without re-running the mount-time effect.
  const isCollapsedRef = useRef<boolean>(initialState.isCollapsed);

  useEffect(() => {
    isCollapsedRef.current = isCollapsed;
  }, [isCollapsed]);

  // Re-sync positionRef when initialState.position arrives async from storage hydration.
  // positionRef is seeded at mount time; if storage data arrives after the first render
  // (which it always does, since ensureBarUiStateLoaded is async), the position prop
  // changes but the ref stales. Update it here so the mount-time makeDraggable effect
  // picks up the real position when the shell first renders (after matches land).
  // If the shell is already positioned (data-positioned), skip to avoid overwriting a
  // user drag.
  useEffect(() => {
    const shell = shellRef.current;
    if (shell?.dataset.positioned) return;
    const { top, left } = initialState.position;
    if (top !== null && left !== null) {
      // SNP-01: clamp the restored position to the current viewport.
      const clamped = clampPanelPosition(top, left, shell?.offsetWidth);
      positionRef.current = clamped;
      // If the shell is already in the DOM, apply immediately; otherwise the
      // mount-time effect ([] deps) will pick it up from the updated ref.
      if (shell) {
        shell.style.top = clamped.top + "px";
        shell.style.left = clamped.left + "px";
        shell.style.right = "auto";
        shell.dataset.positioned = "true";
      }
      // SNP-04: if the clamp moved the saved position (off-screen → on-screen),
      // persist the correction so storage settles instead of re-clamping a
      // stale off-screen value on every open. Only write when it actually
      // changed, and only from THIS site — the mount [] effect reads the now-
      // clamped positionRef and finds nothing left to correct, so storage is
      // written exactly once. Mirrors the resize handler's persist-on-clamp.
      if (clamped.top !== top || clamped.left !== left) {
        // SNP-16: use the freshly-arrived prop, NOT the lagging ref. This effect
        // is defined before the [initialState.isCollapsed] re-sync effect, so on
        // an async-hydration commit that carries BOTH a new off-screen position
        // AND isCollapsed:true, `isCollapsedRef.current` is still the stale
        // mount value (false) here — persisting it would clobber the collapse.
        // SNP-23: userInitiated:false — an automatic correction, not a user action.
        onPersistSnippetsPanel(
          {
            position: clamped,
            isCollapsed: initialState.isCollapsed,
          },
          false
        );
      }
    }
    // onPersistSnippetsPanel identity may change per render; the persist call
    // is gated on a genuine clamp correction and the dataset.positioned guard,
    // so re-running on a new callback identity cannot loop.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialState.position]);

  // Re-sync isCollapsed when initialState.isCollapsed arrives async from storage.
  // Guard against clobbering a user's in-session chevron toggle by tracking the
  // last-seen prop value — only apply the update when the prop itself changes.
  const lastSeenInitialCollapsed = useRef(initialState.isCollapsed);
  useEffect(() => {
    if (initialState.isCollapsed !== lastSeenInitialCollapsed.current) {
      setIsCollapsed(initialState.isCollapsed);
      isCollapsedRef.current = initialState.isCollapsed;
      lastSeenInitialCollapsed.current = initialState.isCollapsed;
    }
  }, [initialState.isCollapsed]);

  useEffect(() => {
    const shell = shellRef.current;
    const header = headerRef.current;
    if (!shell || !header) return;

    const { top, left } = positionRef.current;
    if (top !== null && left !== null) {
      // SNP-01: clamp the restored position to the current viewport.
      const clamped = clampPanelPosition(top, left, shell.offsetWidth);
      positionRef.current = clamped;
      shell.style.top = clamped.top + "px";
      shell.style.left = clamped.left + "px";
      shell.style.right = "auto";
      shell.dataset.positioned = "true";
      // SNP-04: persist the clamp correction here too, for the path where the
      // mount [] effect is the one that performs the restore (e.g. positionRef
      // was seeded directly and the [initialState.position] effect already ran
      // and clamped it — in which case `clamped` equals what it read and this
      // is a no-op, so storage is still written at most once across both
      // restore sites). Only write on a genuine correction.
      if (clamped.top !== top || clamped.left !== left) {
        // SNP-23: automatic correction → userInitiated:false. (isCollapsedRef is
        // correct here — it was seeded from the mount-time initialState.isCollapsed
        // and this [] effect runs once at mount before any collapse change.)
        onPersistSnippetsPanel(
          {
            position: clamped,
            isCollapsed: isCollapsedRef.current,
          },
          false
        );
      }
    }

    const { destroy } = makeDraggable(shell, header, {
      ignoreSelectors: [
        "button",
        "input",
        "textarea",
        "[role='switch']",
        ".no-drag",
      ],
      getClampBounds: () => ({
        minTop: 0,
        minLeft: 0,
        maxTop: Math.max(0, window.innerHeight - PANEL_VIEWPORT_INSET_BOTTOM),
        // SNP-15: keep the panel's right edge (chevron+close controls) on-screen
        // by deriving the bound from the measured width, not a fixed inset.
        maxLeft: maxLeftForWidth(shell.offsetWidth),
      }),
      onPersist: ({ top: t, left: l }) => {
        positionRef.current = { top: t, left: l };
        shell.dataset.positioned = "true";
        onPersistSnippetsPanel({
          position: { top: t, left: l },
          isCollapsed: isCollapsedRef.current,
        });
      },
    });

    const onResize = () => {
      const p = positionRef.current;
      if (p.top === null || p.left === null) return;
      const clamped = clampPanelPosition(p.top, p.left, shell.offsetWidth);
      if (clamped.top !== p.top || clamped.left !== p.left) {
        positionRef.current = clamped;
        shell.style.top = clamped.top + "px";
        shell.style.left = clamped.left + "px";
        // SNP-23: a window-resize re-clamp is an automatic geometry correction,
        // not a user positioning of the panel → userInitiated:false.
        onPersistSnippetsPanel(
          {
            position: clamped,
            isCollapsed: isCollapsedRef.current,
          },
          false
        );
      }
    };
    window.addEventListener("resize", onResize);

    return () => {
      destroy();
      window.removeEventListener("resize", onResize);
    };
    // Stable per mount; persist callback identity changes absorbed via closure.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!matches.length) return null;

  const isTrial = accessState === "trial";
  const className = "snippet-panel floating" + (isTrial ? " trial" : "");

  const toggleCollapsed = () => {
    const next = !isCollapsed;
    setIsCollapsed(next);
    isCollapsedRef.current = next;
    onPersistSnippetsPanel({
      position: positionRef.current,
      isCollapsed: next,
    });
  };

  return (
    <div
      ref={shellRef}
      className={className}
      role="region"
      aria-label="Match snippets"
    >
      <div ref={headerRef} className="snippet-panel-head drag-handle">
        <span className="drag-glyph" aria-hidden="true">⋮⋮</span>
        <span className="snippet-panel-title">
          {isTrial ? "✨ TRIAL · Snippets" : "Snippets"}
        </span>
        <button
          type="button"
          className="iconbtn no-drag snippet-collapse"
          aria-label={isCollapsed ? "Expand snippets" : "Collapse snippets"}
          onClick={toggleCollapsed}
        >
          {isCollapsed ? <FiChevronDown /> : <FiChevronUp />}
        </button>
        {onClose && (
          <button
            type="button"
            className="snippet-x iconbtn no-drag"
            aria-label={CLOSE_LABEL}
            title={CLOSE_LABEL}
            onClick={onClose}
          >
            <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
              <path
                d="M3 3l6 6M9 3l-6 6"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
              />
            </svg>
          </button>
        )}
      </div>
      {!isCollapsed && (
        <SnippetPanel
          matches={matches}
          currentIndex={currentIndex}
          fullText={fullText}
          radius={radius}
          onJump={onJump}
          onClose={onClose}
          accessState={accessState}
          renderHeader={false}
        />
      )}
    </div>
  );
};

export default FloatingSnippetsShell;
