// Shadow-DOM-rooted React mount for the bar. Owns the host element on
// document.documentElement and a single ReactDOM root inside it. The
// shadow root attaches a constructable stylesheet (or <style> fallback)
// containing BAR_CSS so page CSS cannot reach into the bar.
//
// Call mount({...}) to insert the host and render. Call unmount() to
// teardown — idempotent so failure paths can call it freely.

import React from "react";
import { createRoot, Root } from "react-dom/client";
import {
  CmdFTakeoverBarUiState,
  CmdFTakeoverSettings,
  QueryItem,
} from "../../../../definitions/global.definition";
import BarRoot, { BarHooks, SavedQueryRef } from "./BarRoot";
import { BAR_CSS, BAR_HOST_ID } from "./styles";
import { activate as activateFocusGuard, deactivate as deactivateFocusGuard } from "../focusGuard";

let host: HTMLElement | null = null;
let root: Root | null = null;
let lastSettings: CmdFTakeoverSettings | null = null;
let lastHistory: string[] | undefined;
let lastBarUiState: CmdFTakeoverBarUiState | undefined;
// Mount-time seed props. BarRoot reads initialTerm / seededExternally only in
// its mount initializers, but React 18's createRoot().render() commits in a
// LATER macrotask — so an update() landing in that window would otherwise
// re-render with these dropped (undefined), and the coalesced first commit would
// initialize from the wrong props (empty bar, seed lost). We re-supply the last
// mounted values on every update() so the first commit always sees the seed.
let lastInitialTerm: string | undefined;
let lastSeededExternally: boolean | undefined;
let fontLoadAttempted = false;
// CMF-09: the page element that held focus when the bar opened, so we can
// hand focus back on close (native Find restores page focus; we must too).
// Captured at mount() BEFORE the bar input grabs focus, restored in unmount().
let previousActiveElement: HTMLElement | null = null;

// Resolve the real focused element, descending through open shadow roots:
// document.activeElement reports the shadow HOST when focus is inside its
// shadow tree, so we follow the .shadowRoot.activeElement chain to the leaf.
// Used to snapshot the page's focus before our own shadow input claims it.
const deepActiveElement = (): Element | null => {
  let el: Element | null =
    typeof document !== "undefined" ? document.activeElement : null;
  while (el && (el as any).shadowRoot && (el as any).shadowRoot.activeElement) {
    el = (el as any).shadowRoot.activeElement as Element;
  }
  return el;
};

const FONT_PATH = "static/fonts/Phenomena-Regular.otf";

const loadBrandFontOnce = () => {
  // FontFace API + chrome.runtime.getURL: load the brand font once into
  // document.fonts so the Shadow-DOM-rooted bar can render the wordmark
  // in its own typeface. Idempotent: subsequent calls bail. Failures are
  // silent — the wordmark falls back to the system font stack.
  if (fontLoadAttempted) return;
  fontLoadAttempted = true;
  try {
    const runtimeApi =
      typeof chrome !== "undefined" && chrome.runtime
        ? chrome.runtime
        : typeof browser !== "undefined" && browser.runtime
        ? browser.runtime
        : null;
    if (!runtimeApi || typeof FontFace === "undefined") return;
    const url = runtimeApi.getURL(FONT_PATH);
    const face = new FontFace("Phenoregu", `url(${url})`);
    void face
      .load()
      .then((loaded) => {
        try {
          (document as any).fonts.add(loaded);
        } catch {}
      })
      .catch(() => {});
  } catch {}
};

interface MountArgs {
  settings: CmdFTakeoverSettings;
  savedQueries: SavedQueryRef[];
  initialTerm?: string;
  hint?: string;
  onHintDone?: () => void;
  history?: string[];
  hooks: BarHooks;
  // Optional override for where the bar's matcher walks. Forwarded as
  // BarRoot's searchRoot prop. The PDF viewer uses this to scope Cmd+F
  // to the page-text container so the React UI's copy isn't matched.
  searchRoot?: () => Node;
  initialBarUiState?: CmdFTakeoverBarUiState;
  // Cross-tab "jump" entry path: this open was seeded externally, not typed by
  // the user. Forwarded as BarRoot's seededExternally prop (one-shot scroll to
  // first match + no persistence of the seeded term).
  seededExternally?: boolean;
}

const ensureHost = (): { host: HTMLElement; shadow: ShadowRoot } => {
  if (host && host.shadowRoot && host.isConnected) {
    return { host, shadow: host.shadowRoot };
  }
  // The cached host is missing or DETACHED from the document — e.g. the page
  // replaced documentElement's children (document.write / a wholesale
  // innerHTML reset / a framework re-render). A detached element keeps a
  // truthy shadowRoot, so the isConnected check is what catches this (mirrors
  // paintFieldOverlay.ensureOverlayRoot). Tear down any stale React root bound
  // to the old detached shadow tree and drop the orphan host so the block
  // below rebuilds both in a fresh, connected host — otherwise mount() would
  // render into a tree that isn't in the document, leaving an invisible bar
  // while native Cmd+F stays suppressed (the watchdog never fires on the
  // intercept's "already open" path).
  if (root) {
    try {
      root.unmount();
    } catch {}
    root = null;
  }
  if (host && host.parentNode) {
    // CMF-20: a concurrent reparent can make removeChild throw (host is no
    // longer this parent's child); don't let that abort the rebuild.
    try {
      host.parentNode.removeChild(host);
    } catch {}
  }
  // CMF-19: the previous bar session is dead (its host detached/was replaced)
  // but it never ran unmount(), so the focus guard is still `active` with
  // inert tags pointing at nodes from the destroyed document. Reset it here so
  // mount()'s activateFocusGuard() (called right after this) re-scans the new
  // document and inerts any focus-trapping modal it contains.
  deactivateFocusGuard();
  host = document.createElement("div");
  host.id = BAR_HOST_ID;
  host.setAttribute("data-highlighty-cmdf", "");
  // Position the host out of normal flow so it never participates in
  // page layout. Inner .bar-root handles its own positioning.
  //
  // z-index matches the minimap host (2147483647). At equal z-index, later
  // DOM order wins — and the bar is mounted on demand (after the minimap),
  // so its popovers (chip overflow, history, snippets) stay above the
  // minimap markers instead of being intercepted by them.
  host.style.cssText = "all: initial; position: fixed; top: 0; left: 0; z-index: 2147483647;";
  const shadow = host.attachShadow({ mode: "open" });
  // Inject styles. Try constructable stylesheet first; fall back to <style>.
  let stylesAttached = false;
  try {
    if (typeof CSSStyleSheet === "function" && "replaceSync" in CSSStyleSheet.prototype) {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(BAR_CSS);
      (shadow as any).adoptedStyleSheets = [sheet];
      stylesAttached = true;
    }
  } catch {}
  if (!stylesAttached) {
    const style = document.createElement("style");
    style.textContent = BAR_CSS;
    shadow.appendChild(style);
  }
  document.documentElement.appendChild(host);
  return { host, shadow };
};

// A detached host (its document subtree was replaced out from under us) is NOT
// "mounted": isBarOpen() must report false so the intercept re-arms the bar via
// the watchdog/open path instead of dead-ending on the "already open" branch
// (which would suppress native Cmd+F with no visible bar). ensureHost() rebuilds
// the host on the next mount().
export const isMounted = (): boolean =>
  Boolean(host && root && host.isConnected);

let lastSearchRoot: (() => Node) | undefined;

export const mount = ({ settings, savedQueries, initialTerm, hint, onHintDone, history, hooks, searchRoot, initialBarUiState, seededExternally }: MountArgs) => {
  loadBrandFontOnce();
  // CMF-09: snapshot the page's focused element on the OPENING mount only —
  // before ensureHost()/activateFocusGuard()/render move focus into the bar
  // input. The `!root` gate means a re-render or "already open" refocus mount
  // doesn't clobber the original capture with the bar's own input. unmount()
  // restores this on close.
  if (!root) {
    const prior = deepActiveElement();
    // Ignore our own host/UI (defensive — focus shouldn't be there yet) and
    // non-HTMLElements (e.g. <body> / SVG) we can't meaningfully .focus().
    previousActiveElement =
      prior instanceof HTMLElement &&
      !prior.closest("[data-highlighty-cmdf]")
        ? prior
        : null;
  }
  try {
    // ensureHost() FIRST: on a detached-host rebuild it resets a stale focus
    // guard (see ensureHost) so the activateFocusGuard() below re-scans the
    // NEW document instead of short-circuiting on the stale `active` flag and
    // leaving a focus-trapping modal un-inerted (CMF-19).
    const { shadow } = ensureHost();
    // Inert any open focus-trapping modal so its document-level focusin
    // listener can't yank focus out of the bar's input. Runs before render
    // (and the bar input's focus effect), and after ensureHost appended our
    // own host (which activate() skips via data-highlighty-cmdf). See
    // focusGuard.ts for the full rationale.
    activateFocusGuard();
    lastSettings = settings;
    lastHistory = history;
    lastSearchRoot = searchRoot;
    lastBarUiState = initialBarUiState;
    lastInitialTerm = initialTerm;
    lastSeededExternally = seededExternally;
    if (!root) {
      const reactContainer = document.createElement("div");
      shadow.appendChild(reactContainer);
      root = createRoot(reactContainer);
    }
    root.render(
      React.createElement(BarRoot, {
        settings,
        savedQueries,
        initialTerm,
        hint,
        onHintDone,
        history,
        hooks,
        searchRoot,
        initialBarUiState,
        seededExternally,
      })
    );
  } catch (err) {
    // CMF-18: if the mount throws after activateFocusGuard(), the page's open
    // modals are left `inert` (dead to mouse/keyboard) with no visible bar —
    // and the watchdog's closeBar is gated on isMounted() (false here), so it
    // never reaches unmount()/deactivateFocusGuard(). Restore interactivity
    // before propagating the failure.
    deactivateFocusGuard();
    throw err;
  }
};

export const update = (
  partial: Partial<MountArgs> & { hooks?: BarHooks }
) => {
  if (!root || !lastSettings) return;
  const merged: MountArgs = {
    settings: partial.settings ?? lastSettings,
    savedQueries: partial.savedQueries ?? [],
    // Re-supply the mount-time seed props (initialTerm / seededExternally) so an
    // update() that lands before React's first commit can't reset them to
    // undefined and make the coalesced first render initialize an empty,
    // un-seeded bar. Post-commit these are inert (BarRoot reads them only in its
    // mount initializers), so re-passing the same values is harmless.
    initialTerm: partial.initialTerm ?? lastInitialTerm,
    hint: partial.hint,
    onHintDone: partial.onHintDone,
    history: partial.history ?? lastHistory,
    hooks: partial.hooks!,
    searchRoot: partial.searchRoot ?? lastSearchRoot,
    initialBarUiState: partial.initialBarUiState !== undefined ? partial.initialBarUiState : lastBarUiState,
    seededExternally: partial.seededExternally ?? lastSeededExternally,
  };
  lastSettings = merged.settings;
  if (partial.history !== undefined) lastHistory = partial.history;
  if (partial.searchRoot !== undefined) lastSearchRoot = partial.searchRoot;
  if (partial.initialBarUiState !== undefined) lastBarUiState = partial.initialBarUiState;
  root.render(
    React.createElement(BarRoot, {
      settings: merged.settings,
      savedQueries: merged.savedQueries,
      initialTerm: merged.initialTerm,
      hint: merged.hint,
      onHintDone: merged.onHintDone,
      history: merged.history,
      hooks: merged.hooks,
      searchRoot: merged.searchRoot,
      initialBarUiState: merged.initialBarUiState,
      seededExternally: merged.seededExternally,
    })
  );
};

export const unmount = () => {
  if (root) {
    try {
      root.unmount();
    } catch {}
    root = null;
  }
  if (host && host.parentNode) {
    // CMF-20: never let a removeChild throw (concurrent reparent → host is no
    // longer this parent's child) skip the deactivateFocusGuard() below and
    // leave page modals stuck `inert`.
    try {
      host.parentNode.removeChild(host);
    } catch {}
  }
  host = null;
  lastSettings = null;
  lastHistory = undefined;
  lastSearchRoot = undefined;
  lastBarUiState = undefined;
  lastInitialTerm = undefined;
  lastSeededExternally = undefined;
  // Restore interactivity to any modal we inerted on mount. Do this BEFORE
  // refocusing the page element: a still-inert ancestor would make
  // .focus() a no-op (inert subtrees can't receive focus).
  deactivateFocusGuard();
  // CMF-09: hand focus back to whatever the page had focused before the bar
  // opened, mirroring native Find. Null-safe: the element may have been
  // removed from the DOM while the bar was open (skip it then — focus stays
  // wherever the browser put it rather than landing on a detached node).
  const toRestore = previousActiveElement;
  previousActiveElement = null;
  if (toRestore && toRestore.isConnected) {
    try {
      toRestore.focus();
    } catch {
      // Some elements throw on .focus() (disabled, etc.) — non-fatal.
    }
  }
};
