// Per-field mirror lifecycle.
//
// Each instance owns:
//   - the host field (textarea OR text-like input — real, interactive, never modified)
//   - a sibling mirror <div> in the overlay root
//   - a ResizeObserver + listeners that keep the mirror aligned
//   - a selection-aware "transparent text" class on the host so highlights
//     show through; the class is dropped while text is selected so the
//     native ::selection styling stays usable
//
// Eligibility:
//   - textarea (multi-line; mirror wraps with white-space: pre-wrap)
//   - input[type=text|search|email|url|tel] (single-line; mirror sets
//     white-space: pre and syncs scrollLeft so highlights track the
//     horizontal cursor)
//   - skipped: disabled, readonly, invisible, zero-size, and any field that
//     lives inside Highlighty's own UI
//
// Rendering:
//   - mirror contents are rebuilt on input/blur/composition-end/style change
//   - spans are built with createElement + textContent, never innerHTML, so
//     the module is safe under strict CSP / Trusted Types policies
//   - per-query background color is read from QueryItem.colors.hsl; the same
//     hslFormatter the rest of the codebase uses keeps colors consistent
//
// Cleanup:
//   - removeMirror() disconnects observers, removes the DOM, restores the
//     host's color, and is safe to call multiple times. Top-level cleanup
//     iterates the per-host map and calls removeMirror on each.

import { QueryItem } from "../../../definitions/global.definition";
import { QuerySearchOptions } from "../../../search/types";
import { hslFormatter } from "../../../components/shared/utils/color.utils";
import { applyVisualDecorationToElement } from "../utils/decoration.utils";
import { computeFormFieldMatches, MAX_FIELD_CHARS } from "./computeMatches";
import {
  HIGHLIGHT_CLASS,
  MIRROR_CLASS,
  OVERLAY_ROOT_ID,
  ensureOverlayRoot,
} from "./styles";

// Style properties copied from the source field onto the mirror. The set
// is exhaustive enough that wrap, baseline, padding, and bidi direction
// match across common sites. If the source changes one of these via JS
// (e.g. font-size tweaks in a rich-text wrapper), a ResizeObserver tick
// re-syncs.
//
// Font-feature/variant/kerning are included so monospace columns and
// tabular numerals render at the same widths in the mirror as in the
// host — without them, sub-pixel font-fallback differences can drift
// highlight bands character-by-character across a long line.
// NOTE: "boxSizing" is deliberately NOT copied from the host (FFH-05).
// The mirror is sized in border-box pixels (mirror.style.width = rect.width
// from getBoundingClientRect, which is a border-box measurement). Copying the
// host's box-sizing — which defaults to content-box on <input>/<textarea> on
// pages without a `* { box-sizing: border-box }` reset — would reinterpret
// that border-box width as a CONTENT width and stack the copied padding+border
// on top, making the mirror's content box wider than the host's. Text then
// wraps at a different column after line 1 and highlight bands drift. The
// mirror keeps box-sizing:border-box from MIRROR_CLASS (styles.ts) and
// syncLayout re-asserts it inline so a host inline box-sizing can't leak in.
const COPIED_STYLE_PROPS: ReadonlyArray<keyof CSSStyleDeclaration> = [
  "direction",
  "fontFamily",
  "fontSize",
  "fontStyle",
  "fontVariant",
  "fontVariantNumeric",
  "fontFeatureSettings",
  "fontKerning",
  "fontWeight",
  "fontStretch",
  "letterSpacing",
  "lineHeight",
  "textAlign",
  "textIndent",
  "textTransform",
  "tabSize",
  "wordSpacing",
  "borderTopWidth",
  "borderRightWidth",
  "borderBottomWidth",
  "borderLeftWidth",
  "borderTopStyle",
  "borderRightStyle",
  "borderBottomStyle",
  "borderLeftStyle",
  "paddingTop",
  "paddingRight",
  "paddingBottom",
  "paddingLeft",
];

// DATA_MANAGED used to mark "this host already has a mirror" via an
// attribute on the source. Removed: the non-mutating mirror leaves the
// source pristine and the controller's `state.mirrors.has(host)` map
// serves the same purpose without writing to the DOM.

// The narrow set of input types we treat as "text-like" and therefore
// eligible for mirror rendering. These all expose a plain string `.value`
// and use the browser's left-to-right caret model — no native UI overlays
// (date pickers, color swatches, checkboxes) get in the mirror's way.
const TEXT_LIKE_INPUT_TYPES = new Set([
  "text",
  "search",
  "email",
  "url",
  "tel",
  // Inputs with no `type` attribute default to "text".
  "",
]);

export type FormFieldElement = HTMLTextAreaElement | HTMLInputElement;

export interface FieldMirrorOptions {
  doc?: Document;
  // Wrapping in functions lets the caller swap state without recreating
  // mirrors — every repaint reads fresh values, including newly added queries.
  getQueries: () => QueryItem[];
  getSearchOptions: () => QuerySearchOptions;
}

export interface FieldMirror {
  readonly host: FormFieldElement;
  /** Recompute matches + re-render the mirror. Cheap to call repeatedly. */
  repaint: () => void;
  /** Tear down DOM + listeners + observers. Idempotent. */
  destroy: () => void;
}

const isInputTextLike = (el: HTMLInputElement): boolean => {
  // input.type returns a normalised lowercase string for known values, and
  // "text" for unknown / unset. The empty-string entry in TEXT_LIKE_INPUT_TYPES
  // catches the edge where the attribute is present but blank.
  const t = (el.getAttribute("type") ?? "").toLowerCase();
  return TEXT_LIKE_INPUT_TYPES.has(t) || (el.type ?? "").toLowerCase() === "text";
};

export const isEligibleField = (
  el: Element,
  opts?: { includeTextareas?: boolean; includeTextInputs?: boolean }
): el is FormFieldElement => {
  const { includeTextareas = true, includeTextInputs = true } = opts ?? {};
  let host: FormFieldElement | null = null;
  if (el.tagName === "TEXTAREA") {
    if (!includeTextareas) return false;
    host = el as HTMLTextAreaElement;
  } else if (el.tagName === "INPUT") {
    if (!includeTextInputs) return false;
    const input = el as HTMLInputElement;
    if (!isInputTextLike(input)) return false;
    host = input;
  } else {
    return false;
  }
  if (host.disabled || (host as any).readOnly) return false;
  // Note: the prior implementation guarded against DATA_MANAGED here as
  // belt-and-braces against attaching twice. The controller-level
  // `state.mirrors.has(host)` check already serves that purpose, and
  // since the non-mutating mirror never sets DATA_MANAGED anyway, the
  // belt has been removed.
  // Highlighty's own UI lives behind data attributes / id prefixes that
  // start with "highlighty-". Skip any field inside such a subtree.
  if (host.closest('[data-highlighty-overlay], [data-highlighty-cmdf], [data-highlighty-adhoc], #highlighty-cmdf-host')) {
    return false;
  }
  if (host.id && host.id.startsWith("highlighty-")) return false;
  if (!isFieldVisible(host)) return false;
  return true;
};

/**
 * Backwards-compatible alias retained so test fixtures and any external
 * callers that imported the original name keep working. New code should
 * prefer isEligibleField.
 */
export const isEligibleTextarea = (el: Element): el is HTMLTextAreaElement => {
  return el.tagName === "TEXTAREA" && isEligibleField(el, { includeTextInputs: false });
};

const isFieldVisible = (el: HTMLElement): boolean => {
  // Prefer the modern API when available — much cheaper than computed-style
  // on long pages — and fall back to a basic check otherwise. We treat
  // zero-size fields as not visible: a 0x0 mirror is useless and confuses
  // ResizeObserver.
  const cv = (el as any).checkVisibility as
    | ((opts?: { contentVisibilityAuto?: boolean; visibilityProperty?: boolean }) => boolean)
    | undefined;
  if (typeof cv === "function") {
    try {
      // NOTE (CMF-37): `contentVisibilityAuto: true` here is intentional and
      // DIFFERENT from the Cmd+F match-counting surfaces (isElementInvisible /
      // isHilityCounted / navigation), which use `false` so cv:auto text is
      // searchable. This is field-OVERLAY eligibility for the saved-highlight
      // form-field painter — a form field skipped by cv:auto is off-screen and
      // not worth painting a mirror over (also gated by getBoundingClientRect
      // size below). Not a missed flip.
      if (!cv.call(el, { contentVisibilityAuto: true, visibilityProperty: true })) {
        return false;
      }
    } catch {
      // ignore and fall through
    }
  }
  const rect = el.getBoundingClientRect();
  return rect.width > 1 && rect.height > 1;
};

const getQueryColor = (item: QueryItem): string => {
  // Mirror the formatter content.highlight.ts uses so colors are visually
  // identical to saved-highlight rendering. Guard the chain to survive
  // malformed/upgraded QueryItem records.
  const hsl = item.colors?.hsl ?? { h: 0, s: 0, l: 70, a: 1 };
  return hslFormatter(hsl);
};

// Tinted variant used by the non-mutating mirror — same hue / sat / lum
// as the user picked, but alpha clamped to ~0.4 so the source field's
// own text rendering shows through legibly. We deliberately do NOT
// multiply by the user's chosen alpha (which is almost always 1): the
// 0.4 floor is a property of the rendering technique, not the user's
// stylistic preference.
const NON_MUTATING_HIGHLIGHT_ALPHA = 0.4;
const getQueryColorTinted = (item: QueryItem): string => {
  const base = item.colors?.hsl ?? { h: 0, s: 0, l: 70, a: 1 };
  return hslFormatter({ ...base, a: NON_MUTATING_HIGHLIGHT_ALPHA });
};

// Build the per-mirror DOM from a value + matches list. Pure factory —
// does not touch state; the caller appends and disposes. Spans are built
// node-by-node to avoid innerHTML and stay safe under Trusted Types.
//
// Non-mutating visibility contract:
//   - Mirror's `color` is "transparent" (set inline by the caller at
//     attach time). Plain text nodes inside the mirror are invisible —
//     they exist only to lay out positioning so highlight spans land
//     at the right pixel coordinates.
//   - Highlight spans with decorationType === "background" get an
//     alpha-reduced background-color (NON_MUTATING_HIGHLIGHT_ALPHA)
//     so the SOURCE field's own glyphs show through the tint. The
//     mirror does not render visible glyphs of its own.
//   - Highlight spans with non-background decorations (underline,
//     overline, line-through, dotted/wavy/double-underline) render
//     the text-decoration line via applyVisualDecorationToElement.
//     text-decoration paints under transparent text just fine, and
//     since the mirror is positioned identically to the source, the
//     underline appears under the source's text at the matched word.
//
// Decoration plumbing:
//   - Pass `queriesById` so each span can adopt the QueryItem's
//     decorationType + thickness via the same helper mark.js uses
//     (applyVisualDecorationToElement). Form-field highlights have
//     visual parity with the rest of Highlighty.
//   - For background decoration we set backgroundColor inline (via the
//     alpha-reduced getQueryColorTinted helper) because the mirror's
//     stylesheet doesn't carry per-query colors. Non-background types
//     ignore backgroundColor (helper clears it).
export const buildMirrorChildren = (
  doc: Document,
  value: string,
  matches: ReadonlyArray<{ queryId: string; start: number; end: number }>,
  queriesById: ReadonlyMap<string, QueryItem>
): DocumentFragment => {
  const frag = doc.createDocumentFragment();
  if (!value.length) {
    // Trailing-newline correction: a textarea whose value ends with \n
    // would render a blank final line; the mirror needs a sentinel space
    // so wrapping computes correctly. With empty value, no sentinel needed
    // and there are no matches to lay out.
    return frag;
  }

  let cursor = 0;
  for (const m of matches) {
    if (m.start > cursor) {
      frag.appendChild(doc.createTextNode(value.slice(cursor, m.start)));
    }
    const span = doc.createElement("span");
    span.className = HIGHLIGHT_CLASS;
    span.setAttribute("data-query-id", m.queryId);
    const item = queriesById.get(m.queryId);
    if (item) {
      const decorationType = item.decorationType || "background";
      if (decorationType === "background") {
        // Non-mutating model: the mirror sits ABOVE the source and the
        // source's own text rendering supplies the visible glyphs. To
        // let those glyphs show THROUGH our highlight band we drop the
        // background's alpha to ~40% — visible enough to read as a
        // highlight, transparent enough that black text on yellow tint
        // is still legible. This mirrors the "yellow highlighter on
        // paper" look users expect.
        span.style.backgroundColor = getQueryColorTinted(item);
      }
      // adaptiveFontColor is unused under non-mutating: the mirror's
      // text is uniformly transparent (positioning scaffold only) so
      // there is no foreground to contrast.
      applyVisualDecorationToElement(span, item);
    }
    span.textContent = value.slice(m.start, m.end);
    frag.appendChild(span);
    cursor = m.end;
  }
  if (cursor < value.length) {
    frag.appendChild(doc.createTextNode(value.slice(cursor)));
  }
  // Trailing-newline fix: appending a space when value ends with \n keeps
  // the mirror's wrapped height matching the textarea's wrapped height.
  if (value.endsWith("\n")) {
    frag.appendChild(doc.createTextNode(" "));
  }
  return frag;
};

const replaceMirrorContents = (
  mirror: HTMLElement,
  fragment: DocumentFragment
): void => {
  // Cheaper than removeChild loops: replaceChildren is one DOM op and
  // browsers fast-path it.
  const m = mirror as HTMLElement & {
    replaceChildren?: (...nodes: Array<Node | string>) => void;
  };
  if (typeof m.replaceChildren === "function") {
    m.replaceChildren(fragment);
    return;
  }
  while (mirror.firstChild) mirror.removeChild(mirror.firstChild);
  mirror.appendChild(fragment);
};

export const createFieldMirror = (
  host: FormFieldElement,
  options: FieldMirrorOptions
): FieldMirror => {
  const doc = options.doc ?? host.ownerDocument ?? document;
  const win = doc.defaultView ?? window;
  const overlayRoot = ensureOverlayRoot(doc);

  const isMultiline = host.tagName === "TEXTAREA";

  const mirror = doc.createElement("div");
  mirror.className = MIRROR_CLASS;
  // a11y: the source field (textarea/input) is the accessibility anchor.
  // Screen readers announce its native value. The mirror is purely a
  // visual overlay — marking it aria-hidden + role=presentation prevents
  // duplicate announcement of the same text and stops the mirror from
  // appearing in the accessibility tree at all.
  mirror.setAttribute("aria-hidden", "true");
  mirror.setAttribute("role", "presentation");
  // Diagnostic back-reference: tests assert "is there a mirror for this
  // specific source?" by querying the OVERLAY for this attribute. We
  // can't put a marker on the SOURCE (that would be a mutation), but
  // the mirror is our own DOM, so labelling it with the source's id —
  // when the source has one — is free. Sources without an id simply
  // don't appear in tests' per-source assertions; the test helper falls
  // back to overall mirror count in that case.
  if (host.id) mirror.setAttribute("data-highlighty-source-id", host.id);
  overlayRoot.appendChild(mirror);

  // Whether the mirror should wrap depends on:
  //   - input (single-line) → never wrap
  //   - textarea with wrap="off" → never wrap (host scrolls horizontally)
  //   - textarea with wrap="soft"/"hard"/default → wrap
  // Re-evaluated on every syncLayout because `wrap` can change at runtime
  // and we observe its attribute mutations in the controller.
  const applyWrapMode = (): void => {
    const isNoWrap =
      !isMultiline ||
      (host as HTMLTextAreaElement).wrap === "off" ||
      host.getAttribute("wrap") === "off";
    if (isNoWrap) {
      mirror.style.whiteSpace = "pre";
      mirror.style.overflow = "hidden";
    } else {
      // Clear inline values so the stylesheet's wrap defaults take over
      // (white-space: pre-wrap; overflow: hidden — both already set on
      // MIRROR_CLASS).
      mirror.style.whiteSpace = "";
      mirror.style.overflow = "";
    }
  };
  applyWrapMode();

  // NON-MUTATING MIRROR (v2.4.6 release path):
  //
  // The mirror sits ON TOP of the source field and paints only highlight
  // backgrounds / text-decorations. The source's own native text rendering
  // shows through because the mirror's text is transparent (positioning
  // scaffold only) and highlight backgrounds use reduced alpha.
  //
  // Crucially we DO NOT mutate the source — no class added, no
  // data-attribute set, no inline style applied. Controlled Web Components
  // (Reddit's <faceplate-textarea-input>, Material `<md-text-field>`, etc.)
  // observe their own attributes; the previous "make-source-transparent +
  // mirror-draws-text" approach kicked off the host's reset path and wiped
  // the user's typed value mid-edit. With nothing to observe, those
  // components leave the field alone.
  //
  // Cost of the change:
  //   - No text-color recapture: the source's own rendering supplies the
  //     visible glyphs, so a dark-mode toggle on the page just works —
  //     the source repaints itself with the new color, the mirror's
  //     transparent text is unaffected, and highlight backgrounds (tinted
  //     to ~40% alpha in buildMirrorFragment) tint the source's text
  //     regardless of color scheme.
  //   - No caret pinning needed.
  //   - Alignment is now visually consequential: if the mirror's
  //     positioning drifts by 1-2 px the user sees the highlight bar
  //     slightly off the matched word. Existing sync paths
  //     (syncLayout / scheduleSyncLayout / ResizeObserver) already pin
  //     mirror geometry to source geometry, so this is the same alignment
  //     problem we've always solved, with a stricter visual contract.
  mirror.style.color = "transparent";

  let isComposing = false;
  let destroyed = false;
  let pendingRepaint = 0;
  let lastValue = "";
  let lastMatchesKey = "";

  const computeQueryMap = (queries: QueryItem[]): Map<string, QueryItem> => {
    const m = new Map<string, QueryItem>();
    for (const q of queries) m.set(q.id, q);
    return m;
  };

  const syncLayout = (): void => {
    if (destroyed) return;
    // wrap can change via attribute mutation; re-apply on every sync so
    // the mirror tracks runtime flips between wrapping and no-wrapping.
    applyWrapMode();
    const rect = host.getBoundingClientRect();
    // Hide the mirror outright if the field went invisible — don't disturb
    // the user's reflow by leaving a stale rectangle behind.
    if (rect.width <= 0 || rect.height <= 0) {
      mirror.style.display = "none";
      return;
    }
    mirror.style.display = "block";
    mirror.style.top = `${rect.top}px`;
    mirror.style.height = `${rect.height}px`;
    // (left is set below, after the CMF-47 scrollbar-side calc.)

    // Computed style of the host drives both the property copy and the
    // FFH-04 scrollbar-gutter math, so resolve it up front. If it isn't
    // available (no getComputedStyle, or it threw) fall back to the plain
    // border-box width — the legacy behavior — and skip the property copy.
    let cs: CSSStyleDeclaration | null = null;
    if (win.getComputedStyle) {
      try {
        cs = win.getComputedStyle(host);
      } catch {
        cs = null;
      }
    }

    // FFH-04: a vertically-overflowing <textarea> renders a native vertical
    // scrollbar (~15px) that subtracts from the host's content/line-box
    // width. The mirror has overflow:hidden (no scrollbar of its own), so if
    // we size it to the full border-box rect.width its text lays out across a
    // wider content box and wraps one column later than the host — the bands
    // drift after the scrollbar appears. Reserve that gutter: subtract the
    // host's scrollbar width from the mirror's border-box width so both wrap
    // at the same column.
    //
    // host.clientWidth excludes BOTH the scrollbar and the borders, so the
    // scrollbar width is `rect.width - clientWidth - (left+right border)`.
    // We clamp at 0 so sub-pixel rounding can never widen the mirror past the
    // host, and only apply it to multiline fields (single-line inputs never
    // show a vertical scrollbar).
    let mirrorWidth = rect.width;
    let mirrorLeft = rect.left;
    if (isMultiline && cs) {
      const borderL = parseFloat(cs.borderLeftWidth) || 0;
      const borderR = parseFloat(cs.borderRightWidth) || 0;
      const scrollbarW = rect.width - host.clientWidth - borderL - borderR;
      if (scrollbarW > 0) {
        mirrorWidth = rect.width - scrollbarW;
        // CMF-47: RTL fields put the vertical scrollbar on the inline-start
        // (LEFT) edge, so shrinking only the width (left pinned to rect.left)
        // leaves the mirror's content box a scrollbar-width LEFT of the host's
        // and every band drifts left. clientLeft = border-left PLUS any left
        // scrollbar, so (clientLeft - borderL) is the left-side gutter; shift
        // the mirror right by it when positive so the content boxes coincide.
        // LTR keeps the left-gutter 0 (scrollbar on the right) → left unchanged.
        const leftGutter = host.clientLeft - borderL;
        if (leftGutter > 0) mirrorLeft = rect.left + leftGutter;
      }
    }
    mirror.style.left = `${mirrorLeft}px`;
    mirror.style.width = `${mirrorWidth}px`;

    if (!cs) return;
    for (const prop of COPIED_STYLE_PROPS) {
      const v = (cs as any)[prop];
      if (typeof v === "string") (mirror.style as any)[prop] = v;
    }
    // FFH-05: force border-box. The mirror is sized in border-box pixels
    // (rect.width/height from getBoundingClientRect); MIRROR_CLASS already
    // declares border-box but we re-assert it inline so a host inline
    // box-sizing (no longer copied — see COPIED_STYLE_PROPS) or a host
    // !important rule can never flip the mirror to content-box and
    // re-introduce the drift.
    mirror.style.boxSizing = "border-box";
    // Borders are transparent on the mirror; we want the same widths so
    // padding+border math lines up with the host without painting twice.
    mirror.style.borderColor = "transparent";
    // Reflect the source's scroll position so highlights track typing past
    // the bottom of the field.
    mirror.scrollTop = host.scrollTop;
    mirror.scrollLeft = host.scrollLeft;
  };

  // Render the host's placeholder into the mirror when the field is empty.
  // Under the non-mutating mirror the source's native ::placeholder is
  // also visible (we never transparented the host), so this is mostly a
  // structural-only render — the mirror's text color is uniformly
  // transparent. We keep the span in the DOM because (a) some tests
  // assert its presence and aria-hidden, and (b) future builds might
  // restore a separate placeholder-mirror surface if the design calls
  // for one.
  const buildPlaceholderFragment = (): DocumentFragment => {
    const frag = doc.createDocumentFragment();
    const placeholder = host.placeholder;
    if (!placeholder) return frag;
    const span = doc.createElement("span");
    span.className = "highlighty-form-field-placeholder";
    span.style.opacity = "0.54";
    span.setAttribute("aria-hidden", "true");
    span.textContent = placeholder;
    frag.appendChild(span);
    return frag;
  };

  const doRepaint = (): void => {
    pendingRepaint = 0;
    if (destroyed) return;
    const value = host.value;
    // Guard against pathological size before any work: above the cap we
    // render nothing rather than freeze the page on a CMS field with
    // pasted prose.
    if (value.length > MAX_FIELD_CHARS) {
      replaceMirrorContents(mirror, doc.createDocumentFragment());
      lastValue = value;
      lastMatchesKey = "";
      syncLayout();
      return;
    }

    // Empty value path: render the placeholder if the host has one so
    // the field still feels labeled. matchesKey uses a placeholder
    // sentinel so subsequent repaints with the same empty value skip
    // the DOM write.
    if (value.length === 0) {
      const placeholderKey = `__placeholder:${host.placeholder ?? ""}`;
      if (lastValue === "" && lastMatchesKey === placeholderKey) {
        syncLayout();
        return;
      }
      replaceMirrorContents(mirror, buildPlaceholderFragment());
      lastValue = "";
      lastMatchesKey = placeholderKey;
      syncLayout();
      return;
    }

    const queries = options.getQueries();
    const searchOptions = options.getSearchOptions();
    const matches = computeFormFieldMatches(value, queries, searchOptions);

    // Skip the DOM write when nothing changed — common when scrolling
    // alone triggers a repaint.
    const matchesKey =
      value.length + ":" + matches.map((m) => `${m.queryId}|${m.start}|${m.end}`).join(",");
    if (value === lastValue && matchesKey === lastMatchesKey) {
      syncLayout();
      return;
    }

    const queryMap = computeQueryMap(queries);
    const frag = buildMirrorChildren(doc, value, matches, queryMap);
    replaceMirrorContents(mirror, frag);
    lastValue = value;
    lastMatchesKey = matchesKey;
    syncLayout();
  };

  const scheduleRepaint = (): void => {
    if (destroyed) return;
    if (isComposing) return;
    if (pendingRepaint) return;
    // requestAnimationFrame coalesces multiple events from the same tick
    // (e.g. input + scroll + resize firing together while typing).
    const raf =
      typeof win.requestAnimationFrame === "function"
        ? win.requestAnimationFrame.bind(win)
        : (cb: FrameRequestCallback) => win.setTimeout(() => cb(0), 16);
    pendingRepaint = raf(doRepaint);
  };

  // rAF-coalesce layout syncs. Scroll fires at ~60Hz; on a page with N
  // mirrors each scroll event was triggering N synchronous
  // getBoundingClientRect + getComputedStyle reads, measurably janking
  // scrolling on dense forms. With the rAF gate, redundant calls within
  // one tick fold to a single sync.
  let pendingSync = 0;
  const scheduleSyncLayout = (): void => {
    if (destroyed) return;
    if (pendingSync) return;
    const raf =
      typeof win.requestAnimationFrame === "function"
        ? win.requestAnimationFrame.bind(win)
        : (cb: FrameRequestCallback) => win.setTimeout(() => cb(0), 16);
    pendingSync = raf(() => {
      pendingSync = 0;
      syncLayout();
    });
  };

  const onInput = () => scheduleRepaint();
  const onScroll = () => {
    // Scrolling the field only needs a sync, not a re-match. Cheaper.
    // Batched under rAF so 60-Hz scroll bursts don't N-multiply with the
    // number of managed mirrors.
    scheduleSyncLayout();
  };
  const onCompositionStart = () => {
    isComposing = true;
  };
  const onCompositionEnd = () => {
    isComposing = false;
    scheduleRepaint();
  };
  const onChange = () => scheduleRepaint();

  host.addEventListener("input", onInput);
  host.addEventListener("change", onChange);
  host.addEventListener("scroll", onScroll);
  host.addEventListener("compositionstart", onCompositionStart);
  host.addEventListener("compositionend", onCompositionEnd);

  // ResizeObserver fires when the host's content box changes — covers
  // layout-driven resize (parent reflow, CSS width animation, user resize
  // handle on a textarea). For window-level scroll/resize we listen below.
  let resizeObserver: ResizeObserver | null = null;
  if (typeof win.ResizeObserver === "function") {
    resizeObserver = new win.ResizeObserver(() => scheduleSyncLayout());
    resizeObserver.observe(host);
  }

  const onWindowScroll = () => scheduleSyncLayout();
  const onWindowResize = () => scheduleSyncLayout();
  // capture-phase scroll listener catches scrolls in any ancestor — the
  // textarea can sit inside a scrollable panel that is NOT the window.
  win.addEventListener("scroll", onWindowScroll, true);
  win.addEventListener("resize", onWindowResize);

  // visualViewport tracks pinch-zoom and on-screen-keyboard layout on
  // touch devices. `position: fixed` is glued to the LAYOUT viewport, so
  // when the visual viewport scrolls/zooms independently the mirror
  // appears to detach from the field. Listening on these events resyncs.
  const vv = (win as Window & { visualViewport?: VisualViewport })
    .visualViewport;
  const onVisualViewportChange = () => scheduleSyncLayout();
  if (vv && typeof vv.addEventListener === "function") {
    vv.addEventListener("scroll", onVisualViewportChange);
    vv.addEventListener("resize", onVisualViewportChange);
  }

  // Programmatic value-change fallback. The 'input' event covers user
  // typing, paste, cut, and React's controlled-input setter. It does NOT
  // cover plain `host.value = "..."` from vanilla JS, jQuery's `.val()`,
  // or other libraries that bypass the React-monkey-patched setter.
  // Without this poll, those writes leave stale highlights until the
  // next event-driven repaint.
  //
  // Cost: one `host.value` read per interval per managed field. Cheap.
  // The poll pauses while the document is hidden (page tab in
  // background) so we don't burn battery on a non-foreground tab.
  //
  // Implementation: self-rescheduling setTimeout (not setInterval) so
  // destroy() stops the chain cleanly. setInterval keeps firing the
  // callback after clearInterval in pathological cases and would also
  // keep Jest's event loop alive after a test forgets to call destroy.
  const POLL_MS = 200;
  let pollTimer: ReturnType<typeof setTimeout> | null = null;
  let lastPolledValue = host.value;
  const pollValue = (): void => {
    pollTimer = null;
    if (destroyed) return;
    if (doc.visibilityState !== "hidden") {
      const v = host.value;
      if (v !== lastPolledValue) {
        lastPolledValue = v;
        scheduleRepaint();
      }
    }
    pollTimer = setTimeout(pollValue, POLL_MS);
  };
  pollTimer = setTimeout(pollValue, POLL_MS);

  // Initial paint.
  doRepaint();

  const destroy = (): void => {
    if (destroyed) return;
    destroyed = true;

    if (pendingRepaint) {
      if (typeof win.cancelAnimationFrame === "function") {
        win.cancelAnimationFrame(pendingRepaint);
      }
      pendingRepaint = 0;
    }
    if (pendingSync) {
      if (typeof win.cancelAnimationFrame === "function") {
        win.cancelAnimationFrame(pendingSync);
      }
      pendingSync = 0;
    }

    if (pollTimer) {
      clearTimeout(pollTimer);
      pollTimer = null;
    }

    host.removeEventListener("input", onInput);
    host.removeEventListener("change", onChange);
    host.removeEventListener("scroll", onScroll);
    host.removeEventListener("compositionstart", onCompositionStart);
    host.removeEventListener("compositionend", onCompositionEnd);
    win.removeEventListener("scroll", onWindowScroll, true);
    win.removeEventListener("resize", onWindowResize);
    if (vv && typeof vv.removeEventListener === "function") {
      vv.removeEventListener("scroll", onVisualViewportChange);
      vv.removeEventListener("resize", onVisualViewportChange);
    }

    resizeObserver?.disconnect();
    resizeObserver = null;

    // Non-mutating mirror added nothing to the source, so destroy is a
    // pure tear-down of the overlay DOM + the listener bag. No class to
    // remove, no attribute to strip, no inline style to restore.

    if (mirror.parentNode) mirror.parentNode.removeChild(mirror);

    // If we just removed the last mirror, also tear down the overlay
    // root so a stale fixed-position element doesn't sit in the DOM.
    const root = doc.getElementById(OVERLAY_ROOT_ID);
    if (root && root.childElementCount === 0) {
      root.remove();
    }
  };

  return {
    host,
    repaint: scheduleRepaint,
    destroy,
  };
};
