// CSS Custom Highlight API painter. Draws ad-hoc matches via the
// rendering layer with zero DOM mutation. Two named highlights:
//   highlighty-adhoc          — every match (subtle highlight)
//   highlighty-adhoc-current  — the focused match (accent color)
// Style rules are injected once into a constructable stylesheet attached
// to document.adoptedStyleSheets (or as a fallback <style> in <head> if
// the API isn't available).
//
// Cleanup is idempotent: deleting an absent registration is a no-op.

import { AdHocMatch } from "./ephemeralSearch";

interface CSSHighlightRegistry {
  set(name: string, highlight: any): void;
  delete(name: string): void;
  clear(): void;
  get(name: string): any;
}
const cssHighlights = (): CSSHighlightRegistry | undefined =>
  (CSS as unknown as { highlights?: CSSHighlightRegistry }).highlights;

const HIGHLIGHT_NAME = "highlighty-adhoc";
const CURRENT_NAME = "highlighty-adhoc-current";
const STYLE_ID = "highlighty-adhoc-style";

let styleInjected = false;

const HIGHLIGHT_CSS = `
::highlight(${HIGHLIGHT_NAME}) {
  background-color: rgba(118, 244, 233, 0.55);
  color: inherit;
}
::highlight(${CURRENT_NAME}) {
  background-color: rgba(172, 137, 245, 0.85);
  color: #ffffff;
}
`;

export const isSupported = (): boolean =>
  typeof CSS !== "undefined" && Boolean(cssHighlights());

const injectStyleOnce = () => {
  if (styleInjected) return;
  // adoptedStyleSheets is constructable; works in Shadow DOM too. Fall back
  // to a <style> in <head> when the API or spec is missing.
  try {
    if (
      "adoptedStyleSheets" in document &&
      typeof CSSStyleSheet === "function" &&
      "replaceSync" in CSSStyleSheet.prototype
    ) {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(HIGHLIGHT_CSS);
      (document as any).adoptedStyleSheets = [
        ...(document as any).adoptedStyleSheets,
        sheet,
      ];
      styleInjected = true;
      return;
    }
  } catch {}
  if (document.getElementById(STYLE_ID)) {
    styleInjected = true;
    return;
  }
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = HIGHLIGHT_CSS;
  document.head.appendChild(style);
  styleInjected = true;
};

export const paint = (matches: AdHocMatch[], currentIndex: number) => {
  if (!isSupported()) return;
  injectStyleOnce();
  const HighlightCtor = (window as any).Highlight;
  if (!HighlightCtor) return;

  const reg = cssHighlights();
  if (!reg) return;

  const ranges = matches.map((m) => m.range);
  const allHighlight = new HighlightCtor(...ranges);
  reg.set(HIGHLIGHT_NAME, allHighlight);

  const current = matches[currentIndex];
  if (current) {
    const focus = new HighlightCtor(current.range);
    reg.set(CURRENT_NAME, focus);
  } else {
    reg.delete(CURRENT_NAME);
  }
};

export const clear = () => {
  const reg = cssHighlights();
  if (!reg) return;
  try {
    reg.delete(HIGHLIGHT_NAME);
    reg.delete(CURRENT_NAME);
  } catch {}
};

export const __testing = {
  HIGHLIGHT_NAME,
  CURRENT_NAME,
  STYLE_ID,
  resetStyleFlag: () => {
    styleInjected = false;
  },
};
