import React from "react";
import { CrossTabHit } from "../crossTab";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";

export interface CrossTabResultsProps {
  hits: CrossTabHit[];
  loading: boolean;
  onJump: (tabId: number) => void;
  onClose: () => void;
  // Controls the trial prefix on the title. "trial" adds "✨ TRIAL · "
  // and the .trial class on the panel root; anything else renders the
  // plain title.
  accessState?: PremiumFeatureAccessState;
}

const CrossTabResults: React.FC<CrossTabResultsProps> = ({
  hits,
  loading,
  onJump,
  onClose,
  accessState,
}) => {
  const isTrial = accessState === "trial";
  const baseTitle = loading
    ? "Searching all tabs…"
    : `${hits.length} other tab${hits.length === 1 ? "" : "s"}`;
  const title = isTrial ? `✨ TRIAL · ${baseTitle}` : baseTitle;
  return (
    <div
      className={"crosstab-panel" + (isTrial ? " trial" : "")}
      role="region"
      aria-label="Matches in other tabs"
    >
      <div className="crosstab-head">
        <span className="crosstab-title">{title}</span>
        <button
          type="button"
          className="iconbtn"
          aria-label="Close cross-tab results"
          onClick={onClose}
        >
          <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
            <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
          </svg>
        </button>
      </div>
      {loading && hits.length === 0 ? (
        <div className="crosstab-empty">Searching…</div>
      ) : !hits.length ? (
        <div className="crosstab-empty">No matches in other tabs</div>
      ) : (
        <div className="crosstab-list">
          {hits.map((hit) => {
            const host = (() => {
              try {
                return new URL(hit.url).hostname;
              } catch {
                return hit.url;
              }
            })();
            return (
              <button
                key={hit.tabId}
                type="button"
                className="crosstab-item"
                onClick={() => onJump(hit.tabId)}
                aria-label={`Open tab ${hit.title || host} (${hit.count} matches)`}
              >
                <div className="crosstab-item-head">
                  <span className="crosstab-item-title">{hit.title || host || "untitled"}</span>
                  <span className="crosstab-item-count">{hit.count}</span>
                </div>
                <div className="crosstab-item-host">{host}</div>
                {hit.snippet && <div className="crosstab-item-snippet">{hit.snippet}</div>}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default CrossTabResults;
