import { UserSubscription } from "../../../definitions/global.definition";
import { monotonicNow } from "./monotonicClock.utils";

export type PremiumFeatureAccessState = "free" | "trial" | "paid";

// End-of-day-tolerant validity check for a subscription's billing period,
// mirroring isSubscriptionStillValid (content.paygate.ts) so the entitlement
// predicate and the functional paywall gate agree on expiry. Returns false for
// a missing/invalid date. (SUB-01)
export function isWithinValidPeriod(
  currentPeriodEnd: string | null | undefined,
  nowMs: number
): boolean {
  if (!currentPeriodEnd) return false;
  const end = new Date(currentPeriodEnd);
  if (Number.isNaN(end.getTime())) return false;
  // "valid through" the whole end day, with timezone tolerance.
  end.setHours(23, 59, 59, 999);
  return end.getTime() >= nowMs;
}

// Single source of truth for paid/trial/free classification, shared with
// useEntitlement (the store-side gate). getPremiumFeatureAccessState used to
// treat ANY `isActive` subscription as "paid", which disagreed with
// useEntitlement (paid requires Paddle + active + not-canceled) — so a canceled
// or non-Paddle subscription leaked PRO surfaces (RegExp switch, Cmd+F bar,
// tooltips) that the rest of the app locked. Both now use this predicate. (SUB-02)
//
// Trials carry a LOCALLY-built `isActive: true` (see trial.utils.ts builders)
// that can go stale past expiry in a cached subscription object, so the trial
// branches additionally verify `currentPeriodEnd` — an expired trial is treated
// as free, consistent with isSubscriptionStillValid. (Paid `isActive` is
// backend-authoritative and already gated by isSubscriptionStillValid, so it is
// left to the backend here.) (SUB-01)
export function classifySubscription(
  subscription: UserSubscription | null | undefined,
  // SUB-09: default to the monotonic high-water clock so a rolled-back system
  // clock can't push `nowMs` back before an already-expired trial's
  // `currentPeriodEnd` and re-classify it as trial/paid. Callers that pass an
  // explicit `nowMs` (tests, deterministic gates) are unaffected.
  nowMs: number = monotonicNow()
): PremiumFeatureAccessState {
  // SUB-19 (owner decision: PRO-until-period-end): a Paddle subscriber who has
  // CANCELED keeps PRO until their paid period actually ends, rather than losing
  // it the instant they cancel. So a canceled subscription is still "paid" while
  // `currentPeriodEnd` is in the future; once it lapses it falls through to free.
  // A non-canceled active Paddle subscription stays backend-authoritative (no
  // period gate here — the content paygate routes through this same predicate).
  const isPaid =
    Boolean(subscription?.isPaddle) &&
    Boolean(subscription?.isActive) &&
    (!subscription?.isCanceled ||
      isWithinValidPeriod(subscription?.currentPeriodEnd, nowMs));
  if (isPaid) return "paid";

  const trialPeriodValid = isWithinValidPeriod(
    subscription?.currentPeriodEnd,
    nowMs
  );
  const isAppTrial =
    subscription?.accessSource === "app_trial" &&
    subscription?.subscriptionStatus === "trialing" &&
    trialPeriodValid;
  const isGuestTrial =
    subscription?.accessSource === "guest_trial" &&
    Boolean(subscription?.isActive) &&
    trialPeriodValid;
  if (isAppTrial || isGuestTrial) return "trial";

  return "free";
}

export function getPremiumFeatureAccessState(
  subscription: UserSubscription
): PremiumFeatureAccessState {
  return classifySubscription(subscription);
}

// True when the subscription grants PRO access — paid OR an in-period trial.
// Use this for entitlement gating instead of raw `subscription?.isActive`, which
// trusts a canceled, non-Paddle, or expired-trial subscription (SUB-05). Routes
// through the canonical classifier so every gate agrees with useEntitlement.
export function isProEntitled(
  subscription: UserSubscription | null | undefined,
  // SUB-09: monotonic high-water clock by default (see classifySubscription).
  nowMs: number = monotonicNow()
): boolean {
  return classifySubscription(subscription, nowMs) !== "free";
}

export function getPremiumFeatureTooltipLabel(
  subscription: UserSubscription,
  freeLabel?: string
) {
  const premiumFeatureAccessState = getPremiumFeatureAccessState(subscription);

  if (premiumFeatureAccessState === "trial") {
    return "Included in your trial. Upgrade to keep this PRO feature after your trial ends.";
  }

  return freeLabel ?? "This is a 🔐PRO feature.";
}
