import React, { useEffect, useMemo, useRef } from "react";
import { AdHocMatch } from "../ephemeralSearch";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";

export interface SnippetPanelProps {
  matches: AdHocMatch[];
  currentIndex: number;
  fullText: string;
  radius?: number;
  onJump: (index: number) => void;
  // When provided, renders a sticky header with the X close button.
  // BarRoot wires this to the same persistSettings path used by the
  // in-bar disable switch — clicking flips layout to "stripe".
  onClose?: () => void;
  // Controls the trial badge in the header. Falsy / "free" / "paid" =
  // no badge; "trial" adds "✨ TRIAL · " prefix and the .trial class.
  accessState?: PremiumFeatureAccessState;
  // Suppress the internal sticky header even when onClose is provided.
  // FloatingSnippetsShell sets this to false because it renders its own
  // header (drag handle + chevron + close). Default true preserves
  // back-compat. onClose is still wired through — the shell calls it from
  // its own header button.
  // When onClose is omitted the header never renders regardless of this prop,
  // because there would be no action to close.
  renderHeader?: boolean;
}

const SNIPPET_RADIUS_DEFAULT = 60;

// Tags we treat as the snippet's enclosing "row". Walk up from the
// match's text node and stop at the nearest one; slice its textContent
// instead of the page-wide flat text so context can't bleed across
// adjacent rows / cells / list items / paragraphs.
//
// BODY is deliberately excluded — if the walk reaches BODY without
// finding any block above, we fall back to flat-text slicing rather
// than slicing the whole page (which would just reintroduce the bleed
// we're trying to prevent).
const BLOCK_ISOLATION_TAGS = new Set([
  "P", "DIV", "LI", "TR", "TD", "TH", "BLOCKQUOTE", "PRE",
  "ARTICLE", "SECTION", "MAIN", "HEADER", "FOOTER", "NAV", "ASIDE",
  "FIGURE", "FIGCAPTION", "DETAILS", "SUMMARY", "DT", "DD",
  "H1", "H2", "H3", "H4", "H5", "H6",
]);

const findBlockAncestor = (node: Node | null): HTMLElement | null => {
  let cur: Node | null = node;
  while (cur && cur.nodeType !== Node.ELEMENT_NODE) cur = cur.parentNode;
  while (cur && cur.nodeType === Node.ELEMENT_NODE) {
    const el = cur as HTMLElement;
    if (BLOCK_ISOLATION_TAGS.has(el.tagName)) return el;
    cur = el.parentNode;
  }
  return null;
};

// SNP-21: the search corpus (ephemeralSearch) EXCLUDES <script>/<style>/
// <noscript>/<template> and display:none / visibility:hidden subtrees, but
// `Element.textContent` includes all of them. Slicing the card preview from raw
// textContent therefore leaked hidden CSS source / invisible text into the card
// (and desynced the offset from the match's own coordinate system). Walk only
// the same VISIBLE text the corpus indexed so the preview matches the page.
const SKIP_PREVIEW_TAGS = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE"]);

const isHiddenForPreview = (el: Element): boolean => {
  const he = el as HTMLElement;
  // Inline style — fast, and reliable in jsdom (which doesn't fully cascade CSS).
  if (
    he.style &&
    (he.style.display === "none" || he.style.visibility === "hidden")
  ) {
    return true;
  }
  const cs =
    typeof window !== "undefined" && typeof window.getComputedStyle === "function"
      ? window.getComputedStyle(el)
      : null;
  return !!cs && (cs.display === "none" || cs.visibility === "hidden");
};

// A TreeWalker over `block` that skips the corpus-excluded subtrees, yielding
// only the text nodes the search actually saw.
const visibleTextWalker = (block: Element): TreeWalker =>
  document.createTreeWalker(
    block,
    NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT,
    {
      acceptNode: (node: Node) => {
        if (node.nodeType === Node.ELEMENT_NODE) {
          const el = node as Element;
          return SKIP_PREVIEW_TAGS.has(el.tagName) || isHiddenForPreview(el)
            ? NodeFilter.FILTER_REJECT // skip this element's whole subtree
            : NodeFilter.FILTER_SKIP; // descend, but the element itself isn't text
        }
        return NodeFilter.FILTER_ACCEPT; // text node
      },
    }
  );

// The visible text of `block` (corpus-aligned), used as the preview slice source.
const visibleBlockText = (block: Element): string => {
  const walker = visibleTextWalker(block);
  let text = "";
  let node = walker.nextNode();
  while (node) {
    text += (node as Text).data;
    node = walker.nextNode();
  }
  return text;
};

// Returns the character offset of `range.start` within the block's VISIBLE text
// (see visibleBlockText), or null if the range's start isn't under `block`.
const offsetWithinBlock = (block: Element, range: Range): number | null => {
  const target = range.startContainer;
  if (!block.contains(target) && target !== block) return null;
  const walker = visibleTextWalker(block);
  let cursor = 0;
  let node = walker.nextNode();
  while (node) {
    if (node === target) return cursor + range.startOffset;
    cursor += (node as Text).data.length;
    node = walker.nextNode();
  }
  // Target is `block` itself (rare — when range is set on the element,
  // not a text node). Treat startOffset as a child-index walk.
  if (target === block) return cursor;
  return null;
};

interface SnippetSlice {
  before: string;
  after: string;
}

const sliceFromBlock = (
  match: AdHocMatch,
  radius: number
): SnippetSlice | null => {
  const startNode = match.range.startContainer;
  if (!startNode || !startNode.isConnected) return null;
  const block = findBlockAncestor(startNode);
  if (!block) return null;
  const offset = offsetWithinBlock(block, match.range);
  if (offset === null) return null;
  // SNP-21: slice from the VISIBLE text (corpus-aligned), not raw textContent,
  // so hidden <style>/<script>/display:none text can't bleed into the preview.
  const blockText = visibleBlockText(block);
  const matchLen = match.end - match.start;
  const sliceStart = Math.max(0, offset - radius);
  const sliceEnd = Math.min(blockText.length, offset + matchLen + radius);
  return {
    before: blockText.slice(sliceStart, offset),
    after: blockText.slice(offset + matchLen, sliceEnd),
  };
};

// SNP-11: for a form-field match the Range is synthetic (it wraps the field
// element, so its startContainer is the field's PARENT — not a text node whose
// content includes the match). `sliceFromBlock` therefore either returns null
// (→ flat-corpus fallback) or slices the wrong block text, so the card used to
// bleed the previous paragraph + the field's label into view. Slice the context
// from the field's OWN value around the matched substring instead, so a field
// card shows only that field's text.
const sliceFromField = (
  match: AdHocMatch,
  radius: number
): SnippetSlice | null => {
  const field = match.field;
  if (!field) return null;
  const value = field.element.value ?? "";
  const { fieldStart, fieldEnd } = field;
  return {
    before: value.slice(Math.max(0, fieldStart - radius), fieldStart),
    after: value.slice(fieldEnd, Math.min(value.length, fieldEnd + radius)),
  };
};

// Width of the native scrollbar gutter, used to offset the panel from
// the viewport edge so it doesn't sit on top of the scrollbar. On
// overlay-scrollbar systems (macOS default, mobile) this is 0 and the
// panel hugs the edge as before.
const measureScrollbarGutter = (): number => {
  if (typeof window === "undefined" || typeof document === "undefined") return 0;
  const root = document.documentElement;
  if (!root) return 0;
  const gutter = window.innerWidth - root.clientWidth;
  return gutter > 0 && gutter < 32 ? gutter : 0;
};

const CLOSE_LABEL =
  "Hide the snippets panel. Re-enable from Highlighty popup → Cmd+F takeover → Layout.";

const SnippetPanel: React.FC<SnippetPanelProps> = ({
  matches,
  currentIndex,
  fullText,
  radius = SNIPPET_RADIUS_DEFAULT,
  onJump,
  onClose,
  accessState,
  renderHeader = true,
}) => {
  const gutter = useMemo(measureScrollbarGutter, []);
  const currentSnippetRef = useRef<HTMLDivElement | null>(null);
  // When the user cycles matches via Enter / ArrowUp in the cmd+F bar
  // (or clicks a card directly) currentIndex moves. Bring the highlighted
  // card into view inside the panel's own scroll container. block:
  // "nearest" only scrolls if the card is actually out of view, so
  // already-visible cards don't jitter; and because position: fixed on
  // the floating shell makes the panel its own scroll-ancestor stop,
  // the page itself never re-scrolls here.
  //
  // No `behavior: "smooth"` on purpose — Enter is often pressed in rapid
  // succession to fly through matches, and queued smooth animations
  // either fight each other or get cancelled, leaving the panel pinned
  // to scrollTop=0. Instant scroll matches the bar's own keyboard-nav
  // tempo and is what users actually want here.
  //
  // typeof guard keeps JSDOM (test env) from crashing — jsdom doesn't
  // implement scrollIntoView on HTMLElement at all.
  useEffect(() => {
    const el = currentSnippetRef.current;
    if (el && typeof el.scrollIntoView === "function") {
      el.scrollIntoView({ block: "nearest" });
    }
  }, [currentIndex]);
  if (!matches.length) return null;
  const isTrial = accessState === "trial";
  const className = "snippet-panel" + (isTrial ? " trial" : "");
  return (
    <div
      className={className}
      role={renderHeader ? "region" : undefined}
      aria-label={renderHeader ? "Match snippets" : undefined}
      style={gutter > 0 ? { right: `${gutter}px` } : undefined}
    >
      {renderHeader && onClose && (
        <div className="snippet-panel-head">
          <span className="snippet-panel-title">
            {isTrial ? "✨ TRIAL · Snippets" : "Snippets"}
          </span>
          <button
            type="button"
            className="snippet-x iconbtn"
            aria-label={CLOSE_LABEL}
            title={CLOSE_LABEL}
            onClick={onClose}
          >
            <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
              <path
                d="M3 3l6 6M9 3l-6 6"
                stroke="currentColor"
                strokeWidth="1.4"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </div>
      )}
      {matches.map((m, i) => {
        // SNP-11: field matches slice from their own value (never null when
        // m.field is set, so they can't reach the bleeding flat-corpus
        // fallback); text matches slice from their block ancestor and fall back
        // to the flat corpus only when no live block ancestor is found.
        const blockSlice = m.field
          ? sliceFromField(m, radius)
          : sliceFromBlock(m, radius);
        const before =
          blockSlice?.before ??
          fullText.slice(Math.max(0, m.start - radius), m.start);
        const after =
          blockSlice?.after ??
          fullText.slice(m.end, Math.min(fullText.length, m.end + radius));
        const isCurrent = i === currentIndex;
        return (
          <div
            key={`${m.start}-${m.end}-${i}`}
            ref={isCurrent ? currentSnippetRef : null}
            className={"snippet" + (isCurrent ? " current" : "")}
            role="button"
            tabIndex={0}
            aria-current={isCurrent ? "true" : undefined}
            onClick={() => onJump(i)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onJump(i);
              }
            }}
          >
            …{before}
            <b>{m.text}</b>
            {after}…
          </div>
        );
      })}
    </div>
  );
};

export default SnippetPanel;
