import React, { useEffect } from "react";

export interface HintToastProps {
  message: string;
  onDone: () => void;
  durationMs?: number;
}

const HintToast: React.FC<HintToastProps> = ({ message, onDone, durationMs = 2000 }) => {
  useEffect(() => {
    const t = setTimeout(onDone, durationMs);
    return () => clearTimeout(t);
  }, [durationMs, onDone]);
  return (
    <div className="hint-toast" role="status" aria-live="polite">
      {message}
    </div>
  );
};

export default HintToast;
