// Re-installs the Cmd+F intercept after a bfcache restore. Without this,
// pages restored from the back/forward cache keep their content-script
// state but the keydown listener may have been torn down by feature
// re-init or never re-attached after suspended timers.
//
// Note: bfcache does not engage in Playwright headless=new, so this path
// is unit-tested only. Manual QA covers the live-browser case.

let attached: ((ev: PageTransitionEvent) => void) | null = null;

export const installBfcacheReinstall = (reinstall: () => void): void => {
  uninstallBfcacheReinstall();
  attached = (ev: PageTransitionEvent) => {
    if (ev.persisted) reinstall();
  };
  window.addEventListener("pageshow", attached as EventListener);
};

export const uninstallBfcacheReinstall = (): void => {
  if (attached) {
    window.removeEventListener("pageshow", attached as EventListener);
    attached = null;
  }
};
