import React, { forwardRef, useState } from "react";
import Tooltip from "./Tooltip";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";

export interface InputProps {
  value: string;
  count: number;
  currentIndex: number;
  onChange: (next: string) => void;
  onPrev: () => void;
  onNext: () => void;
  onClose: () => void;
  // Shift+Enter shortcut → opens the Save-highlight dialog with the
  // current term pre-filled. No-op if the term is empty.
  onSave?: () => void;
  history?: string[];
  // Controls the trial badge above the history dropdown. "trial" adds a
  // "✨ TRIAL · Search history" header row; everything else omits it.
  accessState?: PremiumFeatureAccessState;
  // Wipes the persisted search history. Called when the user clicks the
  // "Clear" pill in the dropdown header. If omitted, the pill is hidden.
  onClearHistory?: () => void;
}

// Cap on items rendered in the dropdown. Storage may hold up to
// searchHistory.max (default 20); the UI shows only the top slice so the
// dropdown doesn't grow tall enough to crowd the page.
const HISTORY_VISIBLE_MAX = 10;

const ChevronUp = () => (
  <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
    <path d="M2.5 7.5L6 4l3.5 3.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const ChevronDown = () => (
  <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
    <path d="M2.5 4.5L6 8l3.5-3.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const Close = () => (
  <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
    <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
  </svg>
);

const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    {
      value,
      count,
      currentIndex,
      onChange,
      onPrev,
      onNext,
      onClose,
      onSave,
      history,
      accessState,
      onClearHistory,
    },
    ref
  ) => {
    const display = count === 0 ? "0 of 0" : `${currentIndex + 1} of ${count}`;
    const [showHistory, setShowHistory] = useState(false);
    const visibleHistory = (history ?? [])
      .filter((h) => h && h !== value)
      .slice(0, HISTORY_VISIBLE_MAX);
    const canShowHistory = !value && visibleHistory.length > 0 && showHistory;
    const isTrial = accessState === "trial";
    const historyTitle = isTrial ? "✨ TRIAL · Search history" : "Recent searches";

    return (
      <>
        <div className="input-wrap" style={{ position: "relative" }}>
          <input
            ref={ref}
            type="text"
            placeholder="Find on page…"
            value={value}
            spellCheck={false}
            autoCorrect="off"
            autoCapitalize="off"
            autoComplete="off"
            onFocus={() => setShowHistory(true)}
            onBlur={() => setTimeout(() => setShowHistory(false), 120)}
            onChange={(e) => onChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                if (e.shiftKey) {
                  // Shift+Enter — quick save: open the promote dialog
                  // with the current term pre-filled. ArrowUp still
                  // navigates to the previous match for keyboard-only
                  // users who want plain prev.
                  if (onSave && value.trim()) onSave();
                } else {
                  onNext();
                }
              } else if (e.key === "Escape") {
                e.preventDefault();
                onClose();
              } else if (e.key === "ArrowDown") {
                e.preventDefault();
                onNext();
              } else if (e.key === "ArrowUp") {
                e.preventDefault();
                onPrev();
              }
            }}
            aria-label="Search this page"
          />
          <span className={"count" + (count === 0 && value ? " zero" : "")} aria-live="polite">
            {display}
          </span>
          {canShowHistory && (
            <div
              className={"history-pop" + (isTrial ? " trial" : "")}
              role="listbox"
              aria-label="Recent searches"
            >
              <div className="history-pop-head">
                <span className="history-pop-title">{historyTitle}</span>
                {onClearHistory && (
                  <button
                    type="button"
                    className="history-clear"
                    aria-label="Clear search history"
                    // mousedown before blur so the click lands before the
                    // dropdown disappears.
                    onMouseDown={(e) => {
                      e.preventDefault();
                      onClearHistory();
                    }}
                  >
                    Clear
                  </button>
                )}
              </div>
              {visibleHistory.map((h) => (
                <button
                  key={h}
                  type="button"
                  role="option"
                  aria-selected="false"
                  className="history-item"
                  // mousedown fires before blur, so the choice lands before
                  // the dropdown disappears
                  onMouseDown={(e) => {
                    e.preventDefault();
                    onChange(h);
                  }}
                >
                  <svg width="10" height="10" viewBox="0 0 12 12" fill="none" aria-hidden="true">
                    <path
                      d="M6 1.5a4.5 4.5 0 1 1-3.18 1.32"
                      stroke="currentColor"
                      strokeWidth="1.4"
                      strokeLinecap="round"
                      fill="none"
                    />
                    <path d="M2.6 1v2.5h2.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" fill="none" />
                  </svg>
                  <span>{h}</span>
                </button>
              ))}
            </div>
          )}
        </div>
        <div className="close-row">
          <Tooltip label="Previous match" shortcut="↑">
            <button type="button" className="iconbtn" aria-label="Previous match" onClick={onPrev} disabled={count === 0}>
              <ChevronUp />
            </button>
          </Tooltip>
          <Tooltip label="Next match" shortcut="Enter">
            <button type="button" className="iconbtn" aria-label="Next match" onClick={onNext} disabled={count === 0}>
              <ChevronDown />
            </button>
          </Tooltip>
          <Tooltip label="Close" shortcut="Esc">
            <button type="button" className="iconbtn" aria-label="Close search" onClick={onClose}>
              <Close />
            </button>
          </Tooltip>
        </div>
      </>
    );
  }
);

Input.displayName = "Input";
export default Input;
