import DOMIterator from "./domiterator";
// QRX-19: shared, unit-tested code-point step used after a zero-width regex
// match, so the four wrap loops below skip an empty match (e.g. `a*`/`\d*`)
// the same way the Cmd+F / PDF / form-field engines do, instead of aborting.
import { advanceRegexIndex } from "../../../search/regexExec";
// HLE-19: the ONE shared word-char class every whole-word surface uses
// (`[\p{L}\p{N}\p{M}_]`). Imported — not re-typed — from the same module the
// regex whole-word path (wrapRegexWholeWord) and the Cmd+F/PDF/form-field
// engines (isWordBoundary) consume, so the plain highlighter's whole-word
// boundary is byte-for-byte identical to theirs and the three surfaces can't
// drift. `\p{…}` requires the `u` flag; the "exactly" (whole-word) mark path
// below opts that flag in explicitly.
import { WORD_CHAR_CLASS } from "../../../search/normalization";

/**
 * Marks search terms in DOM elements
 * @example
 * new Mark(document.querySelector(".context")).mark("lorem ipsum");
 * @example
 * new Mark(document.querySelector(".context")).markRegExp(/lorem/gmi);
 */
export default class Mark {
  /**
   * Cache for diacritics RegExp creation to improve performance
   * @type {Map}
   * @static
   */
  static diacriticsCache = new Map();

  /**
   * HLE-21: reverse variant->base index for diacritic folding, built once from
   * the diacriticMap. Maps every accented/stroke/ligature VARIANT char that
   * appears inside a variant class (e.g. `ø`) back to that class's ASCII base
   * key (e.g. `o`), so a non-decomposing stroke letter used in a query folds to
   * the full base class instead of being emitted verbatim. Lazily populated on
   * the first createDiacriticsRegExp call (the map is a constant, so the index
   * is identical every time). `null` until built.
   * @type {Object<string,string>|null}
   * @static
   */
  static reverseDiacriticsIndex = null;

  /**
   * Build (once) and return the reverse variant->base diacritic index from the
   * canonical diacriticMap. A variant that is itself a map key (the base
   * letters a-z/A-Z) is skipped — those never reach the reverse lookup. First
   * occurrence wins (variants do not cross classes), so the result is
   * deterministic regardless of call order.
   * @param {Object<string,string>} diacriticMap - base -> "[variants]" class map
   * @return {Object<string,string>} variant char -> base key
   * @static
   */
  static getReverseDiacriticsIndex(diacriticMap) {
    // Memoized: after the first build the `diacriticMap` argument is ignored.
    // Safe because the sole caller (createDiacriticsRegExp) always passes the
    // same constant map. A future second caller passing a DIFFERENT map would
    // get this first map's index — switch to a keyed cache if that ever changes.
    if (Mark.reverseDiacriticsIndex) {
      return Mark.reverseDiacriticsIndex;
    }
    const index = Object.create(null);
    for (const baseKey in diacriticMap) {
      const cls = diacriticMap[baseKey];
      // Strip the surrounding [ ] and walk the class members by code point.
      const inner = cls.slice(1, -1);
      for (const variant of inner) {
        if (!diacriticMap[variant] && !(variant in index)) {
          index[variant] = baseKey;
        }
      }
    }
    Mark.reverseDiacriticsIndex = index;
    return index;
  }

  /**
   * @param {HTMLElement|HTMLElement[]|NodeList|string} ctx - The context DOM
   * element, an array of DOM elements, a NodeList or a selector
   */
  constructor(ctx) {
    this.ctx = ctx;
    this.ie = /MSIE|Trident/.test(window.navigator.userAgent);
  }

  /**
   * Options defined by the user.
   * @type {object}
   * @param {object} [val] - An object that will be merged with defaults
   */
  set opt(val) {
    this._opt = {
      element: "",
      className: "",
      exclude: [],
      iframes: false,
      iframesTimeout: 5000,
      separateWordSearch: true,
      diacritics: true,
      synonyms: {},
      accuracy: "partially",
      acrossElements: false,
      caseSensitive: false,
      ignoreJoiners: false,
      ignoreGroups: 0,
      ignorePunctuation: [],
      wildcards: "disabled",
      each: () => {},
      eachIframe: () => {},
      noMatch: () => {},
      filter: () => true,
      done: () => {},
      debug: false,
      log: window.console,
      ...val,
    };
  }

  get opt() {
    return this._opt;
  }

  /**
   * An instance of DOMIterator
   * @type {DOMIterator}
   */
  get iterator() {
    return new DOMIterator(
      this.ctx,
      this.opt.iframes,
      this.opt.exclude,
      this.opt.iframesTimeout,
      this.opt.eachIframe
    );
  }

  /**
   * Logs a message if log is enabled
   * @param {string} msg - The message to log
   * @param {string} [level="debug"] - The log level
   */
  log(msg, level = "debug") {
    if (this.opt.debug && this.opt.log[level]) {
      this.opt.log[level](`mark.js: ${msg}`);
    }
  }

  /**
   * Escapes a string for usage within a regular expression
   * @param {string} str - The string to escape
   * @return {string}
   */
  escapeStr(str) {
    return str.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&");
  }

  /**
   * Creates a regular expression string to match the specified search term
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createRegExp(str) {
    // HLE-16: sanitize the raw term BEFORE any regex machinery runs.
    //  1. NFC-normalize so a term pasted with NFD-decomposed accents (macOS
    //     `café` = `cafe`+U+0301) folds to the precomposed form the web mostly
    //     publishes, and so the diacritics step below sees a single accented
    //     letter rather than a base + a dangling required combining mark.
    //  2. Strip zero-width / format (Cf) characters a term picks up when
    //     copied from a PDF, justified column, or CMS: soft hyphen (U+00AD),
    //     zero-width space/joiners (U+200B–U+200D), word joiner (U+2060) and
    //     BOM/ZWNBSP (U+FEFF). Left in, each becomes a REQUIRED literal and the
    //     query silently matches nothing anywhere.
    // Guarded for engines without String.prototype.normalize (all modern
    // Chromium has it; this is belt-and-braces).
    str = str.normalize ? str.normalize("NFC") : str;
    str = str.replace(/[­​‌‍⁠﻿]/g, "");

    // HLE-15: plant sentinels for the term's OWN apostrophe/quote characters
    // (straight OR typographic) up front, so they ride through the whole regex
    // pipeline as opaque single chars and are expanded to family classes only
    // at the very end (expandQuoteSentinels). Planting here — not as a late
    // post-pass — keeps them OUT of the punctuation joiner class built from
    // ignorePunctuation (which itself contains quotes), where a late pass would
    // nest `[...]` inside `[...]` and corrupt the class.
    //    = apostrophe family    = double-quote family
    str = str.replace(/['‘’‚ʼ]/g, "").replace(/["“”„]/g, "");

    // Apply wildcards first if enabled
    if (this.opt.wildcards !== "disabled") {
      str = this.setupWildcardsRegExp(str);
    }

    // Always escape the string
    str = this.escapeStr(str);

    // HLE-19: the whole-word ("exactly") boundary compiles with the `u` flag
    // (its boundary uses `\p{…}`). Under `u`, escapeStr's `\-` — emitted for a
    // hyphen in the TERM (e.g. "state-of-art" → "state\-of\-art") — is an
    // "Invalid escape" OUTSIDE a character class, and the term body always sits
    // outside a class. `-` is not a metacharacter there, so drop the now-illegal
    // backslash HERE, while `str` is still just the escaped term: no
    // joiner/punctuation/diacritic class has been spliced in yet (the quote
    // sentinels are opaque PUA chars), so this touches ONLY the term's own
    // hyphens. Doing it later (e.g. in createAccuracyRegExp) would also strip the
    // `\-` from the ignorePunctuation joiner class `[…,\-–…]` inserted below and,
    // under `u`, turn the bare `-` between `,` and `–` into an ~8168-codepoint
    // RANGE — an over-match (`cat` → `c/a/t`). Scoped to "exactly" so every other
    // accuracy (never compiled with `u`) is byte-for-byte unchanged.
    const accForU =
      typeof this.opt.accuracy === "string"
        ? this.opt.accuracy
        : this.opt.accuracy && this.opt.accuracy.value;
    if (accForU === "exactly") {
      str = str.replace(/\\-/g, "-");
    }

    // Apply synonyms if any exist
    if (Object.keys(this.opt.synonyms).length) {
      str = this.createSynonymsRegExp(str);
    }

    // Handle joiners and punctuation in one pass if possible
    const needsJoinersHandling = this.opt.ignoreJoiners || this.opt.ignorePunctuation.length;
    if (needsJoinersHandling) {
      str = this.setupIgnoreJoinersRegExp(str);
    }

    // Apply diacritics handling
    if (this.opt.diacritics) {
      str = this.createDiacriticsRegExp(str);
    }

    // Handle merged blanks
    str = this.createMergedBlanksRegExp(str);

    // Apply joiners RegExp if needed
    if (needsJoinersHandling) {
      str = this.createJoinersRegExp(str);
    }

    // Apply wildcards RegExp if enabled
    if (this.opt.wildcards !== "disabled") {
      str = this.createWildcardsRegExp(str);
    }

    // HLE-15: swap the apostrophe/quote sentinels planted at the top back into
    // the character classes that match their whole typographic family. Done
    // LAST so the sentinels rode through escape/synonym/joiner/diacritics/blank
    // handling as opaque single chars (a sentinel is not in ignorePunctuation,
    // so it never lands INSIDE the joiner class and can't corrupt it), then
    // expand to `['‘’‚ʼ]` / `["“”„]` in the finished pattern.
    str = this.expandQuoteSentinels(str);

    // Finally, create the accuracy RegExp.
    // Note: sub-word suppression for separateWordSearch:false is handled
    // entirely by getSeparatedKeywords (it keeps only the whole term), so no
    // additional gate is needed here.
    return this.createAccuracyRegExp(str);
  }

  /**
   * Creates a regular expression string to match the defined synonyms
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createSynonymsRegExp(str) {
    const { synonyms, caseSensitive } = this.opt;
    const sens = caseSensitive ? "" : "i";
    const joinerPlaceholder =
      this.opt.ignoreJoiners || this.opt.ignorePunctuation.length
        ? "\u0000"
        : "";

    Object.entries(synonyms).forEach(([key, value]) => {
      const k1 =
        this.opt.wildcards !== "disabled"
          ? this.setupWildcardsRegExp(key)
          : this.escapeStr(key);
      const k2 =
        this.opt.wildcards !== "disabled"
          ? this.setupWildcardsRegExp(value)
          : this.escapeStr(value);
      if (k1 && k2) {
        str = str.replace(
          new RegExp(
            `(${this.escapeStr(k1)}|${this.escapeStr(k2)})`,
            `gm${sens}`
          ),
          `${joinerPlaceholder}(${this.processSynonyms(
            k1
          )}|${this.processSynonyms(k2)})${joinerPlaceholder}`
        );
      }
    });
    return str;
  }

  /**
   * Processes synonyms to work with ignoreJoiners and/or ignorePunctuation
   * @param {string} str - synonym key or value to process
   * @return {string} - processed synonym string
   */
  processSynonyms(str) {
    if (this.opt.ignoreJoiners || this.opt.ignorePunctuation.length) {
      str = this.setupIgnoreJoinersRegExp(str);
    }
    return str;
  }

  /**
   * Sets up the regular expression string to allow later insertion of wildcard matches
   * @param {string} str - The search term to be used
   * @return {string}
   */
  setupWildcardsRegExp(str) {
    return str
      .replace(/(?:\\)*\?/g, (val) => (val.charAt(0) === "\\" ? "?" : "\u0001"))
      .replace(/(?:\\)*\*/g, (val) =>
        val.charAt(0) === "\\" ? "*" : "\u0002"
      );
  }

  /**
   * Creates a regular expression string to allow ignoring of designated characters
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createWildcardsRegExp(str) {
    const spaces = this.opt.wildcards === "withSpaces";
    return str
      .replace(/\u0001/g, spaces ? "[\\S\\s]?" : "\\S?")
      .replace(/\u0002/g, spaces ? "[\\S\\s]*?" : "\\S*");
  }

  /**
   * Sets up the regular expression string to allow later insertion of designated characters
   * @param {string} str - The search term to be used
   * @return {string}
   */
  setupIgnoreJoinersRegExp(str) {
    return str.replace(/[^(|)\\]/g, (val, indx, original) => {
      const nextChar = original.charAt(indx + 1);
      return /[(|)\\]/.test(nextChar) || nextChar === "" ? val : val + "\u0000";
    });
  }

  /**
   * Creates a regular expression string to allow ignoring of designated characters
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createJoinersRegExp(str) {
    const joiner = [];
    if (
      Array.isArray(this.opt.ignorePunctuation) &&
      this.opt.ignorePunctuation.length
    ) {
      joiner.push(this.escapeStr(this.opt.ignorePunctuation.join("")));
    }
    if (this.opt.ignoreJoiners) {
      joiner.push("\\u00ad\\u200b\\u200c\\u200d");
    }
    return joiner.length
      ? str.split(/\u0000+/).join(`[${joiner.join("")}]*`)
      : str;
  }

  /**
   * Creates a regular expression string to match diacritics
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createDiacriticsRegExp(str) {
    const { caseSensitive } = this.opt;
    const cacheKey = `${str}_${caseSensitive}_${this.opt.diacritics}`;

    // Check if we have a cached result
    if (Mark.diacriticsCache.has(cacheKey)) {
      return Mark.diacriticsCache.get(cacheKey);
    }

    // In mark.js, diacritics: true means "ignore diacritics" (diacritic insensitive)
    // and diacritics: false means "consider diacritics" (diacritic sensitive)

    // If diacritics is false, we should return the string as is (diacritic sensitive)
    if (this.opt.diacritics === false) {
      // Cache the result
      Mark.diacriticsCache.set(cacheKey, str);
      return str;
    }

    // Define character mappings for diacritic insensitivity
    // Each base character maps to a character class of all its diacritic variants
    const diacriticMap = {
      'a': '[aáàâäãåāăąǎǟǡǻȁȃȧḁạảấầẩẫậắằẳẵặ]',
      'A': '[AÁÀÂÄÃÅĀĂĄǍǞǠǺȀȂȦḀẠẢẤẦẨẪẬẮẰẲẴẶ]',
      'b': '[bḃḅḇƀƃɓ]',
      'B': '[BḂḄḆɃƂƁ]',
      'c': '[cçćĉċčƈȼḉ]',
      'C': '[CÇĆĈĊČƇȻḈ]',
      'd': '[dďḋḍḏḑḓđƌɖɗ]',
      'D': '[DĎḊḌḎḐḒĐƋƉƊ]',
      'e': '[eéèêëēĕėęěȅȇȩḕḗḙḛḝẹẻẽếềểễệ]',
      'E': '[EÉÈÊËĒĔĖĘĚȄȆȨḔḖḘḚḜẸẺẼẾỀỂỄỆ]',
      'f': '[fḟƒ]',
      'F': '[FḞƑ]',
      'g': '[gĝğġģǥǧǵḡƣ]',
      'G': '[GĜĞĠĢǤǦǴḠƢ]',
      'h': '[hĥħḣḥḧḩḫẖ]',
      'H': '[HĤĦḢḤḦḨḪ]',
      'i': '[iíìîïĩīĭįǐȉȋḭḯỉịĳ]',
      'I': '[IÍÌÎÏĨĪĬĮǏȈȊḬḮỈỊĲ]',
      'j': '[jĵǰ]',
      'J': '[JĴ]',
      'k': '[kķǩḱḳḵƙ]',
      'K': '[KĶǨḰḲḴƘ]',
      'l': '[lĺļľḷḹḻḽƚł]',
      'L': '[LĹĻĽḶḸḺḼȽŁ]',
      'm': '[mḿṁṃ]',
      'M': '[MḾṀṂ]',
      'n': '[nñńņňǹṅṇṉṋ]',
      'N': '[NÑŃŅŇǸṄṆṈṊ]',
      'o': '[oóòôöõøōŏőơǒǫǭȍȏȫȭȯȱṍṏṑṓọỏốồổỗộớờởỡợǿ]',
      'O': '[OÓÒÔÖÕØŌŎŐƠǑǪǬȌȎȪȬȮȰṌṎṐṒỌỎỐỒỔỖỘỚỜỞỠỢǾ]',
      'p': '[pṕṗƥ]',
      'P': '[PṔṖƤ]',
      'q': '[q]',
      'Q': '[Q]',
      'r': '[rŕŗřȑȓṙṛṝṟ]',
      'R': '[RŔŖŘȐȒṘṚṜṞ]',
      's': '[sśŝşšșṡṣṥṧṩ]',
      'S': '[SŚŜŞŠȘṠṢṤṦṨ]',
      't': '[tţťțṫṭṯṱƭʈ]',
      'T': '[TŢŤȚṪṬṮṰƬƮ]',
      'u': '[uúùûüũūŭůűųưǔǖǘǚǜȕȗṳṵṷṹṻụủứừửữự]',
      'U': '[UÚÙÛÜŨŪŬŮŰŲƯǓǕǗǙǛȔȖṲṴṶṸṺỤỦỨỪỬỮỰ]',
      'v': '[vṽṿ]',
      'V': '[VṼṾ]',
      'w': '[wŵẁẃẅẇẉ]',
      'W': '[WŴẀẂẄẆẈ]',
      'x': '[xẋẍ]',
      'X': '[XẊẌ]',
      'y': '[yýỳŷÿỹȳẏỵỷỹ]',
      'Y': '[YÝỲŶŸỸȲẎỴỶỸ]',
      'z': '[zźżžẑẓẕ]',
      'Z': '[ZŹŻŽẐẒẔ]'
    };

    // Special handling for Hungarian characters
    const hungarianMap = {
      'a': 'aá',
      'e': 'eé',
      'i': 'ií',
      'o': 'oóöő',
      'u': 'uúüű',
      'A': 'AÁ',
      'E': 'EÉ',
      'I': 'IÍ',
      'O': 'OÓÖŐ',
      'U': 'UÚÜŰ'
    };

    // Replace each character with its diacritic-insensitive pattern
    let result = '';
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];

      // HLE-16 (NFD-page direction): a PRECOMPOSED accented letter reaching
      // here (the term was NFC-normalized in createRegExp) is not itself a map
      // key — its ASCII base is. Fold it to its base so the base's variant
      // class (which already lists both the precomposed form and, being a class
      // followed by no end-anchor under "partially", tolerates the decomposed
      // base+mark on the page) is emitted. This makes an NFC term `café` match
      // an NFD page `cafe`+U+0301 as well as a precomposed page `café`, without
      // affecting un-accented letters. Only single-mark Latin letters fold to a
      // 1-char base; anything else falls through unchanged.
      let base = ch;
      if (!diacriticMap[ch] && !hungarianMap[ch]) {
        // (a) HLE-16 (NFD-page direction): a precomposed accented letter folds
        // to its ASCII base via NFD decomposition (é -> e + U+0301 -> base e).
        if (ch.normalize) {
          const decomposed = ch.normalize("NFD");
          if (
            decomposed.length > 1 &&
            (diacriticMap[decomposed[0]] || hungarianMap[decomposed[0]])
          ) {
            base = decomposed[0];
          }
        }
        // (b) HLE-21 (stroke/ligature letters): `ø đ ł ħ` (+ uppercase) are
        // VALUES inside a variant class but are NOT map keys and have NO
        // combining-mark NFD decomposition, so (a) leaves them unchanged and
        // they used to fall to the verbatim else-branch below — matching only
        // the exact glyph, never the plain base. The reverse index folds such a
        // char to the base key of the class that already lists it, so it emits
        // the FULL class (bidirectional: an accented query now matches the plain
        // page, just as a plain query already matched the accented page). Only
        // consulted when (a) did not fold — a decomposable char keeps its NFD
        // base. ß (-> "ss", QRX transliteration), þ (independent letter), and ı
        // (dotless-i, absent from the map) are not class members and stay
        // unfolded here by design (a distinct, narrower root).
        if (base === ch) {
          const rev = Mark.getReverseDiacriticsIndex(diacriticMap)[ch];
          if (rev) {
            base = rev;
          }
        }
      }

      // Check if we have a mapping for this character
      if (diacriticMap[base]) {
        // HLE-22: after the base's variant class, absorb any dangling COMBINING
        // marks the page carries. HLE-16 NFC-normalizes the TERM, so an accented
        // term char reaches here PRECOMPOSED and folds to the bare-base class
        // `[eéèê…]` — which consumes only the base letter. But a page authored
        // in NFD (macOS content) stores that same accented letter as a base
        // letter FOLLOWED BY a separate combining mark (`e`+U+0301). Nothing in
        // the bare-base class consumed that trailing mark, so the accented query
        // matched nothing: under "partially" the pattern's next literal couldn't
        // line up with the page's combining mark, and under "exactly" HLE-19's
        // word boundary saw the mark (a `\p{M}` word char) and rejected the
        // match. `[̀-ͯ]*` (U+0300–U+036F, the combining diacritical marks block)
        // is zero-or-more, so it consumes the NFD page's mark when present and is
        // a no-op on NFC pages (no marks → matches zero, no over-match). Every
        // plain Latin base letter is a diacriticMap key too, so this covers both
        // the folded-accent path and a plain base letter meeting an NFD page.
        // A literal range (not `\p{M}`) is valid on BOTH the "exactly" (`u`) and
        // "partially" (no `u`) compile paths this string flows into.
        result += diacriticMap[base] + '[̀-ͯ]*';
      } else if (hungarianMap[base]) {
        // Special handling for Hungarian characters
        // HLE-22: same dangling-combining-mark consumption as the diacriticMap
        // branch above, for the Hungarian-vowel classes.
        result += `[${hungarianMap[base]}]` + '[̀-ͯ]*';
      } else {
        // No mapping, use the character as is. No combining-mark suffix here:
        // this branch also carries structural/escaped chars (escapes, group
        // parens, joiner/quote-sentinel class fragments), where a trailing
        // `[̀-ͯ]*` would corrupt the pattern — and every plain Latin base letter
        // is already a diacriticMap key, so it never reaches this branch.
        result += base;
      }
    }

    // Cache the result
    Mark.diacriticsCache.set(cacheKey, result);
    return result;
  }

  /**
   * Creates a regular expression string that merges whitespace characters
   * @param {string} str - The search term to be used
   * @return {string}
   */
  createMergedBlanksRegExp(str) {
    return str.replace(/\s+/g, "[\\s]+");
  }

  /**
   * HLE-15: swaps the apostrophe/quote sentinels (U+E000 / U+E001) planted at
   * the top of createRegExp back into character classes matching their whole
   * typographic family, so a term written with ANY straight-or-curly form
   * matches ANY form on the page and vice-versa.
   *   apostrophe family: ' U+2018 U+2019 U+201A U+02BC
   *   double-quote family: " U+201C U+201D U+201E
   * Sentinels are the only U+E000/U+E001 chars that can reach here, so this is
   * an unambiguous, idempotent final expansion.
   * @param {string} str - the finished pattern carrying sentinels
   * @return {string}
   */
  expandQuoteSentinels(str) {
    return str
      .replace(//g, "['‘’‚ʼ]")
      .replace(//g, '["“”„]');
  }

  /**
   * Creates a regular expression string to match the specified string with the defined accuracy
   * @param {string} str - The search term to be used
   * @return {string}
   */

  createAccuracyRegExp(str) {
    const { accuracy } = this.opt;
    const val = typeof accuracy === "string" ? accuracy : accuracy.value;
    const ls = typeof accuracy === "string" ? [] : accuracy.limiters;
    const lsJoin = ls.map((limiter) => this.escapeStr(limiter)).join("|");

    // Whole-word matching ships exclusively through accuracy:"exactly"
    // (content.highlight maps the UI toggle to that). The boundaries below
    // cover production; no separate completeWordSearch flag is consulted.
    switch (val) {
      case "complementary":
        return `()([^\\s${lsJoin}]*${str}[^\\s${lsJoin}]*)`;
      case "exactly": {
        // HLE-19: bound the term by a NON-word char / string edge using the
        // shared Unicode word-char class, instead of the old ~12-char ASCII
        // boundary set. The ASCII set under-matched ordinary typography — a
        // plain whole-word `world` missed `world—next` (em dash), `world’s`
        // (curly apostrophe), and `“world”` (curly quotes), while the REGEX
        // whole-word path (wrapRegexWholeWord) and Cmd+F (isWordBoundary) — both
        // built on THIS same class — matched them, so the same toggle gave three
        // different answers. Any char NOT in WORD_CHAR_CLASS is a boundary, so
        // the old explicit `<`/`>` alternatives are subsumed (both are non-word
        // chars). Group structure is unchanged: group 1 is the leading separator
        // (consumed by mark.js via matchIdx=2), group 2 is the term, and the
        // trailing boundary stays a zero-width lookahead so only the term is
        // wrapped. WORD_CHAR_CLASS is a `\p{…}` class → the "exactly" mark path
        // compiles with the `u` flag (see mark(), where `sens` gains `u` for
        // this accuracy).
        //
        // The term's own `\-` (from escapeStr on a hyphenated query like
        // "state-of-art") was already un-escaped to a literal `-` in
        // createRegExp, RIGHT AFTER escapeStr — before any joiner/punctuation
        // class was spliced in — so `str` here is `u`-valid without any further
        // rewriting. A blanket replace at THIS point would also strip the `\-`
        // out of the ignorePunctuation joiner class `[…,\-–…]` and, under `u`,
        // turn the bare `-` between `,` and `–` into an ~8168-codepoint RANGE
        // (whole-word `cat` would then match `c/a/t`, `c9a9t`, …). So we must
        // NOT touch `str` here.
        const wordInner = WORD_CHAR_CLASS.slice(1, -1); // \p{L}\p{N}\p{M}_
        return `(^|[^${wordInner}]+)(${str})(?=$|[^${wordInner}])`;
      }
      case "partially":
      default:
        return `()(${str})`;
    }
  }

  /**
   * Returns a list of keywords dependent on whether separate word search was defined
   * @param {array} sv - The array of keywords
   * @return {object}
   */
  getSeparatedKeywords(sv) {
    // Use a Set for faster lookups and automatic deduplication
    const keywordSet = new Set();

    sv.forEach((kw) => {
      if (!this.opt.separateWordSearch) {
        // When separateWordSearch is false, we only want to match the complete term
        if (kw.trim()) {
          keywordSet.add(kw);
        }
      } else {
        kw.split(" ").forEach((kwSplitted) => {
          if (kwSplitted.trim()) {
            keywordSet.add(kwSplitted);
          }
        });
      }
    });

    // Convert to array and sort
    const stack = Array.from(keywordSet).sort((a, b) => b.length - a.length);

    return {
      keywords: stack,
      length: stack.length,
    };
  }

  /**
   * Check if a value is a number
   * @param {number|string} value - the value to check
   * @return {boolean}
   */
  isNumeric(value) {
    return Number(parseFloat(value)) == value; // eslint-disable-line eqeqeq
  }

  /**
   * Returns a processed list of integer offset indexes that do not overlap each other
   * @param {array} array - unprocessed raw array
   * @return {array} - processed array with any invalid entries removed
   */
  checkRanges(array) {
    if (
      !Array.isArray(array) ||
      Object.prototype.toString.call(array[0]) !== "[object Object]"
    ) {
      this.log("markRanges() will only accept an array of objects");
      this.opt.noMatch(array);
      return [];
    }

    const stack = [];
    let last = 0;
    array
      .sort((a, b) => a.start - b.start)
      .forEach((item) => {
        const { start, end, valid } = this.callNoMatchOnInvalidRanges(
          item,
          last
        );
        if (valid) {
          item.start = start;
          item.length = end - start;
          stack.push(item);
          last = end;
        }
      });
    return stack;
  }

  /**
   * Initial validation of ranges for markRanges
   * @param {object} range - the current range object
   * @param {number} last - last index of range
   * @return {object}
   */
  callNoMatchOnInvalidRanges(range, last) {
    let start,
      end,
      valid = false;
    if (range && typeof range.start !== "undefined") {
      start = parseInt(range.start, 10);
      end = start + parseInt(range.length, 10);
      if (
        this.isNumeric(range.start) &&
        this.isNumeric(range.length) &&
        end - last > 0 &&
        end - start > 0
      ) {
        valid = true;
      } else {
        this.log(
          `Ignoring invalid or overlapping range: ${JSON.stringify(range)}`
        );
        this.opt.noMatch(range);
      }
    } else {
      this.log(`Ignoring invalid range: ${JSON.stringify(range)}`);
      this.opt.noMatch(range);
    }
    return { start, end, valid };
  }

  /**
   * Check valid range for markRanges
   * @param {object} range - the current range object
   * @param {number} originalLength - original length of the context string
   * @param {string} string - current content string
   * @return {object}
   */
  checkWhitespaceRanges(range, originalLength, string) {
    const max = string.length;
    const offset = originalLength - max;
    let start = parseInt(range.start, 10) - offset;
    start = start > max ? max : start;
    let end = start + parseInt(range.length, 10);
    if (end > max) {
      end = max;
      this.log(`End range automatically set to the max value of ${max}`);
    }
    const valid = !(
      start < 0 ||
      end - start < 0 ||
      start > max ||
      end > max ||
      string.substring(start, end).replace(/\s+/g, "") === ""
    );
    if (!valid) {
      this.log(
        `Skipping invalid or whitespace only range: ${JSON.stringify(range)}`
      );
      this.opt.noMatch(range);
    }
    return { start, end, valid };
  }

  /**
   * Calls the callback with an object containing all text nodes
   * @param {function} cb - Callback
   */
  getTextNodes(cb) {
    let val = "";
    const nodes = [];
    this.iterator.forEachNode(
      NodeFilter.SHOW_TEXT,
      (node) => {
        nodes.push({
          start: val.length,
          end: (val += node.textContent).length,
          node,
        });
      },
      (node) =>
        this.matchesExclude(node.parentNode)
          ? NodeFilter.FILTER_REJECT
          : NodeFilter.FILTER_ACCEPT,
      () => cb({ value: val, nodes })
    );
  }

  /**
   * Checks if an element matches any of the specified exclude selectors
   * @param {HTMLElement} el - The element to check
   * @return {boolean}
   */
  matchesExclude(el) {
    return DOMIterator.matches(
      el,
      this.opt.exclude.concat(["script", "style", "title", "head", "html"])
    );
  }

  /**
   * Wraps the instance element and class around matches
   * @param {HTMLElement} node - The DOM text node
   * @param {number} start - The position where to start wrapping
   * @param {number} end - The position where to end wrapping
   * @return {HTMLElement}
   */
  wrapRangeInTextNode(node, start, end) {
    const hEl = this.opt.element || "mark";
    const startNode = node.splitText(start);
    const ret = startNode.splitText(end - start);
    const repl = document.createElement(hEl);
    repl.setAttribute("is-highlighty", "true");
    if (this.opt.className) {
      repl.setAttribute("class", this.opt.className);
    }
    repl.textContent = startNode.textContent;
    startNode.parentNode.replaceChild(repl, startNode);
    return ret;
  }

  /**
   * Determines matches by start and end positions using the text node dictionary
   * @param {object} dict - The dictionary
   * @param {number} start - The start position of the match
   * @param {number} end - The end position of the match
   * @param {function} filterCb - Filter callback
   * @param {function} eachCb - Each callback
   */
  wrapRangeInMappedTextNode(dict, start, end, filterCb, eachCb) {
    dict.nodes.every((n, i) => {
      const sibl = dict.nodes[i + 1];
      if (!sibl || sibl.start > start) {
        if (!filterCb(n.node)) {
          return false;
        }
        const s = start - n.start;
        const e = (end > n.end ? n.end : end) - n.start;
        const startStr = dict.value.substr(0, n.start);
        const endStr = dict.value.substr(e + n.start);
        n.node = this.wrapRangeInTextNode(n.node, s, e);
        dict.value = startStr + endStr;
        dict.nodes.forEach((_, j) => {
          if (j >= i) {
            if (dict.nodes[j].start > 0 && j !== i) {
              dict.nodes[j].start -= e;
            }
            dict.nodes[j].end -= e;
          }
        });
        end -= e;
        eachCb(n.node.previousSibling, n.start);
        if (end > n.end) {
          start = n.end;
        } else {
          return false;
        }
      }
      return true;
    });
  }

  /**
   * Yields to the renderer one frame. Used by the chunked-variant
   * wrappers below when opt.chunkSize is set. Falls back to
   * setTimeout(0) in non-DOM contexts (Node tests).
   *
   * @return {Promise<void>}
   */
  _yieldFrame() {
    return new Promise((resolve) => {
      if (typeof requestAnimationFrame === "function") {
        requestAnimationFrame(() => resolve());
      } else {
        setTimeout(resolve, 0);
      }
    });
  }

  /**
   * HLE-02: lets the caller abort an in-flight chunked wrap BETWEEN chunks.
   * The chunked wrappers yield a frame every `chunkSize` marks; during that
   * yield a newer highlight pass can start and unmark the whole page. Without
   * this check the yielded loop resumes and keeps inserting wrappers into a
   * document the new pass already cleared (stale `<hility>` spans survive).
   * content.highlight passes `isCancelled: () => !isHighlightRunCurrent(gen)`.
   *
   * @return {boolean}
   */
  _isCancelled() {
    return !!(
      this.opt &&
      typeof this.opt.isCancelled === "function" &&
      this.opt.isCancelled()
    );
  }

  /**
   * Wraps the instance element and class around matches within single HTML elements
   * @param {RegExp} regex - The regular expression to be searched for
   * @param {number} ignoreGroups - A number indicating the amount of RegExp matching groups to ignore
   * @param {function} filterCb - Filter callback
   * @param {function} eachCb - Each callback
   * @param {function} endCb - End callback
   */
  wrapMatches(regex, ignoreGroups, filterCb, eachCb, endCb) {
    // Opt-in: when the caller passes opt.chunkSize > 0 we yield to
    // the renderer every N marks so the main thread stays responsive
    // on heavy passes (5k+ matches). Without it, behaviour is exactly
    // the legacy synchronous code path — keeps the existing mark.js
    // unit tests (which assert `done` fired before `mark()` returned)
    // working unchanged.
    const chunkSize =
      this.opt && this.opt.chunkSize > 0 ? this.opt.chunkSize : 0;
    if (chunkSize > 0) {
      return this._wrapMatchesChunked(
        regex,
        ignoreGroups,
        filterCb,
        eachCb,
        endCb,
        chunkSize
      );
    }
    const matchIdx = ignoreGroups === 0 ? 0 : ignoreGroups + 1;
    let logicalMatchIndex = 0;
    this.getTextNodes((dict) => {
      dict.nodes.forEach(({ node }) => {
        let match;
        while ((match = regex.exec(node.textContent)) !== null) {
          // QRX-19: a zero-width WHOLE match (a regex that can match empty, e.g.
          // `a*`/`\d*`) leaves regex.lastIndex unmoved. Skip past the full code
          // point (advanceRegexIndex — +2 for astral, mirrors the Cmd+F/PDF/
          // form-field engines) and continue, rather than aborting the pass (the
          // old `&& match[matchIdx] !== ""` guard ENDED the loop here, so a real
          // match later in the node was never reached). An empty IGNORED group
          // with a non-empty whole match keeps the legacy end-the-pass behavior.
          if (match[0] === "") {
            regex.lastIndex = advanceRegexIndex(
              node.textContent,
              regex.lastIndex
            );
            continue;
          }
          if (match[matchIdx] === "") {
            break;
          }
          if (!filterCb(match[matchIdx], node)) {
            continue;
          }
          let pos = match.index;
          if (matchIdx !== 0) {
            for (let i = 1; i < matchIdx; i++) {
              pos += match[i].length;
            }
          }
          logicalMatchIndex++;
          node = this.wrapRangeInTextNode(
            node,
            pos,
            pos + match[matchIdx].length
          );
          eachCb(node.previousSibling, logicalMatchIndex);
          regex.lastIndex = 0;
        }
      });
      endCb();
    });
  }

  /**
   * Async chunked variant of wrapMatches. Yields to the renderer
   * every `chunkSize` marks so the main thread doesn't stall on
   * heavy match volume. The completion contract is unchanged — `endCb`
   * fires once, after every match in the document has been wrapped —
   * callers that await on `opt.done` see no difference except the
   * promise resolves a few frames later.
   */
  async _wrapMatchesChunked(
    regex,
    ignoreGroups,
    filterCb,
    eachCb,
    endCb,
    chunkSize
  ) {
    const matchIdx = ignoreGroups === 0 ? 0 : ignoreGroups + 1;
    let logicalMatchIndex = 0;
    const dict = await new Promise((resolve) =>
      this.getTextNodes(resolve)
    );
    let inserted = 0;
    for (const original of dict.nodes) {
      let node = original.node;
      let match;
      while ((match = regex.exec(node.textContent)) !== null) {
        // QRX-19: skip a zero-width whole match (see wrapMatches) instead of
        // aborting the pass; advance a full code point so astral chars can't hang.
        if (match[0] === "") {
          regex.lastIndex = advanceRegexIndex(node.textContent, regex.lastIndex);
          continue;
        }
        if (match[matchIdx] === "") {
          break;
        }
        if (!filterCb(match[matchIdx], node)) {
          continue;
        }
        let pos = match.index;
        if (matchIdx !== 0) {
          for (let i = 1; i < matchIdx; i++) {
            pos += match[i].length;
          }
        }
        logicalMatchIndex++;
        node = this.wrapRangeInTextNode(
          node,
          pos,
          pos + match[matchIdx].length
        );
        eachCb(node.previousSibling, logicalMatchIndex);
        regex.lastIndex = 0;
        if (++inserted % chunkSize === 0) {
          await this._yieldFrame();
          // HLE-02: a newer pass may have superseded us during the yield.
          // Resolve the completion contract and stop inserting.
          if (this._isCancelled()) {
            endCb();
            return;
          }
        }
      }
    }
    endCb();
  }

  /**
   * Wraps the instance element and class around matches across all HTML elements
   * @param {RegExp} regex - The regular expression to be searched for
   * @param {number} ignoreGroups - A number indicating the amount of RegExp matching groups to ignore
   * @param {function} filterCb - Filter callback
   * @param {function} eachCb - Each callback
   * @param {function} endCb - End callback
   */
  wrapMatchesAcrossElements(regex, ignoreGroups, filterCb, eachCb, endCb) {
    const chunkSize =
      this.opt && this.opt.chunkSize > 0 ? this.opt.chunkSize : 0;
    if (chunkSize > 0) {
      return this._wrapMatchesAcrossElementsChunked(
        regex,
        ignoreGroups,
        filterCb,
        eachCb,
        endCb,
        chunkSize
      );
    }
    const matchIdx = ignoreGroups === 0 ? 0 : ignoreGroups + 1;
    let logicalMatchIndex = 0;
    this.getTextNodes((dict) => {
      let match;
      while ((match = regex.exec(dict.value)) !== null) {
        // QRX-19: skip a zero-width whole match (see wrapMatches) instead of
        // aborting the pass; advance a full code point so astral chars can't hang.
        if (match[0] === "") {
          regex.lastIndex = advanceRegexIndex(dict.value, regex.lastIndex);
          continue;
        }
        if (match[matchIdx] === "") {
          break;
        }
        let start = match.index;
        if (matchIdx !== 0) {
          for (let i = 1; i < matchIdx; i++) {
            start += match[i].length;
          }
        }
        const end = start + match[matchIdx].length;
        // Store the match value to avoid the unsafe reference in the callback
        const matchVal = match[matchIdx];
        logicalMatchIndex++;
        const currentLogicalMatchIndex = logicalMatchIndex;

        this.wrapRangeInMappedTextNode(
          dict,
          start,
          end,
          (node) => filterCb(matchVal, node),
          (node, lastIndex) => {
            regex.lastIndex = lastIndex;
            eachCb(node, currentLogicalMatchIndex);
          }
        );
      }
      endCb();
    });
  }

  /**
   * Async chunked variant of wrapMatchesAcrossElements. The trickier
   * of the two — `dict` is mutated in place by
   * wrapRangeInMappedTextNode, and `regex.lastIndex` is set into the
   * (mutated) dict.value. We must not touch either between yields;
   * the await only suspends inside this function, so as long as
   * external code doesn't race against the same `dict` object (it
   * doesn't — `dict` is local to this call), the contract holds.
   */
  async _wrapMatchesAcrossElementsChunked(
    regex,
    ignoreGroups,
    filterCb,
    eachCb,
    endCb,
    chunkSize
  ) {
    const matchIdx = ignoreGroups === 0 ? 0 : ignoreGroups + 1;
    let logicalMatchIndex = 0;
    const dict = await new Promise((resolve) =>
      this.getTextNodes(resolve)
    );
    let inserted = 0;
    let match;
    while ((match = regex.exec(dict.value)) !== null) {
      // QRX-19: skip a zero-width whole match (see wrapMatches) instead of
      // aborting the pass; advance a full code point so astral chars can't hang.
      if (match[0] === "") {
        regex.lastIndex = advanceRegexIndex(dict.value, regex.lastIndex);
        continue;
      }
      if (match[matchIdx] === "") {
        break;
      }
      let start = match.index;
      if (matchIdx !== 0) {
        for (let i = 1; i < matchIdx; i++) {
          start += match[i].length;
        }
      }
      const end = start + match[matchIdx].length;
      const matchVal = match[matchIdx];
      logicalMatchIndex++;
      const currentLogicalMatchIndex = logicalMatchIndex;

      this.wrapRangeInMappedTextNode(
        dict,
        start,
        end,
        (node) => filterCb(matchVal, node),
        (node, lastIndex) => {
          regex.lastIndex = lastIndex;
          eachCb(node, currentLogicalMatchIndex);
        }
      );
      if (++inserted % chunkSize === 0) {
        await this._yieldFrame();
        // HLE-02: a newer pass may have superseded us during the yield.
        // Resolve the completion contract and stop inserting.
        if (this._isCancelled()) {
          endCb();
          return;
        }
      }
    }
    endCb();
  }

  /**
   * Wraps the indicated ranges across all HTML elements
   * @param {array} ranges - The array of objects
   * @param {function} filterCb - Filter callback
   * @param {function} eachCb - Each callback
   * @param {function} endCb - End callback
   */
  wrapRangeFromIndex(ranges, filterCb, eachCb, endCb) {
    this.getTextNodes((dict) => {
      const originalLength = dict.value.length;
      ranges.forEach((range, counter) => {
        const { start, end, valid } = this.checkWhitespaceRanges(
          range,
          originalLength,
          dict.value
        );
        if (valid) {
          this.wrapRangeInMappedTextNode(
            dict,
            start,
            end,
            (node) =>
              filterCb(node, range, dict.value.substring(start, end), counter),
            (node) => eachCb(node, range)
          );
        }
      });
      endCb();
    });
  }

  /**
   * Unwraps the specified DOM node with its content
   * @param {HTMLElement} node - The DOM node to unwrap
   */
  unwrapMatches(node) {
    const parent = node.parentNode;
    const docFrag = document.createDocumentFragment();
    while (node.firstChild) {
      docFrag.appendChild(node.removeChild(node.firstChild));
    }
    parent.replaceChild(docFrag, node);
    if (!this.ie) {
      parent.normalize();
    } else {
      this.normalizeTextNode(parent);
    }
  }

  /**
   * Normalizes text nodes
   * @param {HTMLElement} node - The DOM node to normalize
   */
  normalizeTextNode(node) {
    if (!node) return;
    if (node.nodeType === 3) {
      while (node.nextSibling && node.nextSibling.nodeType === 3) {
        node.nodeValue += node.nextSibling.nodeValue;
        node.parentNode.removeChild(node.nextSibling);
      }
    } else {
      this.normalizeTextNode(node.firstChild);
    }
    this.normalizeTextNode(node.nextSibling);
  }

  /**
   * Marks a custom regular expression
   * @param {RegExp} regexp - The regular expression
   * @param {object} [opt] - Optional options object
   */
  markRegExp(regexp, opt) {
    this.opt = opt;
    this.log(`Searching with expression "${regexp}"`);

    // HLE-01: honor acrossElements directly (see mark() below). Regex already
    // got across-elements via the default separateWordSearch=true; decoupled
    // here too so the two gates can't silently drift.
    const useAcrossElements = this.opt.acrossElements;

    let totalMatches = 0;
    const fn = useAcrossElements
      ? "wrapMatchesAcrossElements"
      : "wrapMatches";
    const eachCb = (element, logicalMatchIndex) => {
      totalMatches++;
      this.opt.each(element, logicalMatchIndex);
    };
    this[fn](
      regexp,
      this.opt.ignoreGroups,
      (match, node) => this.opt.filter(node, match, totalMatches),
      eachCb,
      () => {
        if (totalMatches === 0) {
          this.opt.noMatch(regexp);
        }
        this.opt.done(totalMatches);
      }
    );
  }

  /**
   * Marks the specified search terms
   * @param {string|string[]} [sv] - Search value
   * @param {object} [opt] - Optional options object
   */
  mark(sv, opt) {
    this.opt = opt;

    let totalMatches = 0;
    let logicalMatches = 0;

    // HLE-01: honor the caller's acrossElements option directly. The previous
    // `separateWordSearch && acrossElements` coupling silently disabled
    // cross-element wrapping for whole-phrase (non-split) plain queries — the
    // default — so a match split across inline elements ("Pay with
    // <b>credit</b> card") was never highlighted, even though the regex path
    // (which leaves separateWordSearch at its default true) already wraps
    // across elements. Decoupled so plain and regex behave consistently.
    const useAcrossElements = this.opt.acrossElements;

    const fn = useAcrossElements
      ? "wrapMatchesAcrossElements"
      : "wrapMatches";

    // Convert search value to array if it's a string
    const searchTerms = typeof sv === "string" ? [sv] : sv;

    // Get the keywords based on separateWordSearch setting
    const { keywords: kwArr, length: kwArrLen } = this.getSeparatedKeywords(searchTerms);
    const sens = this.opt.caseSensitive ? "" : "i";
    // HLE-19: the whole-word ("exactly") boundary now uses the shared Unicode
    // word-char class `[\p{L}\p{N}\p{M}_]`, and `\p{…}` is ONLY valid when the
    // RegExp is compiled with the `u` flag — without it the class silently
    // degrades to matching the literal chars `p{LNM_}` (Annex-B identity
    // escapes), corrupting the boundary. So the "exactly" mark path must carry
    // `u`. Scoped to this accuracy only (accuracy may be a string or a
    // {value,limiters} object, mirroring createAccuracyRegExp) so no other mode
    // changes flags; the regex whole-word path already uses `gmu…`, so this
    // brings the plain path to the same footing. QRX-19's zero-width/surrogate
    // handling (advanceRegexIndex) already assumes code-point stepping, which is
    // exactly what `u` gives, so this is consistent with — not a regression of —
    // that path.
    const accVal =
      typeof this.opt.accuracy === "string"
        ? this.opt.accuracy
        : this.opt.accuracy && this.opt.accuracy.value;
    const uni = accVal === "exactly" ? "u" : "";

    const handler = (kw) => {
      // Store the original search term for reference
      this.opt._currentSearchTerm = kw;

      const regex = new RegExp(this.createRegExp(kw), `gm${sens}${uni}`);
      let matches = 0;
      let keywordLogicalMatches = 0;
      this.log(`Searching with expression "${regex}"`);
      this[fn](
        regex,
        1,
        (_, node) => this.opt.filter(node, kw, totalMatches, matches),
        (element, logicalMatchIndex) => {
          matches++;
          totalMatches++;
          keywordLogicalMatches = Math.max(
            keywordLogicalMatches,
            logicalMatchIndex
          );
          this.opt.each(element, logicalMatches + logicalMatchIndex);
        },
        () => {
          logicalMatches += keywordLogicalMatches;
          if (matches === 0) {
            this.opt.noMatch(kw);
          }
          // HLE-12: stop BETWEEN keywords too. If a newer pass cancelled this
          // one while the just-finished keyword was running, don't start the
          // next keyword — settle with done() instead. (Within-keyword chunk
          // cancellation is handled separately by the chunked wrappers; this
          // closes the gap between keywords in a multi-term mark().)
          if (kwArr[kwArrLen - 1] === kw || this._isCancelled()) {
            this.opt.done(totalMatches);
          } else {
            handler(kwArr[kwArr.indexOf(kw) + 1]);
          }
        }
      );
    };

    if (kwArrLen === 0) {
      this.opt.done(totalMatches);
    } else {
      handler(kwArr[0]);
    }
  }

  /**
   * Marks an array of objects containing a start with an end or length of the string to mark
   * @param {array} rawRanges - The original array of objects
   * @param {object} [opt] - Optional options object
   */
  markRanges(rawRanges, opt) {
    this.opt = opt;
    let totalMatches = 0;
    const ranges = this.checkRanges(rawRanges);
    if (ranges && ranges.length) {
      this.log(
        `Starting to mark with the following ranges: ${JSON.stringify(ranges)}`
      );
      this.wrapRangeFromIndex(
        ranges,
        (node, range, match, counter) =>
          this.opt.filter(node, range, match, counter),
        (element, range) => {
          totalMatches++;
          this.opt.each(element, range);
        },
        () => this.opt.done(totalMatches)
      );
    } else {
      this.opt.done(totalMatches);
    }
  }

  /**
   * Removes all marked elements inside the context with their HTML
   * @param {object} [opt] - Optional options object
   */
  unmark(opt) {
    this.opt = opt;
    let sel = this.opt.element ? this.opt.element : "*";
    sel += "[is-highlighty]";
    if (this.opt.className) {
      sel += `.${this.opt.className}`;
    }
    this.log(`Removal selector "${sel}"`);
    this.iterator.forEachNode(
      NodeFilter.SHOW_ELEMENT,
      (node) => this.unwrapMatches(node),
      (node) => {
        const matchesSel = DOMIterator.matches(node, sel);
        const matchesExclude = this.matchesExclude(node);
        return !matchesSel || matchesExclude
          ? NodeFilter.FILTER_REJECT
          : NodeFilter.FILTER_ACCEPT;
      },
      this.opt.done
    );
  }
}
