import { debounce } from "../shared";
import { GlobalSettings } from "../../definitions/global.definition";
import { currentGlobalSettings } from "./content.globalSettingsState";
import { doMarkSearch } from "./content.highlight";
import { showFoundCountOnIcon } from "./content.sumBadge";
import { toastLogic } from "./content.toast";
import { isEditableEventTarget } from "./utils/editable.utils";
let selectListener = null as unknown as AbortController;

export const initSearchOnHotkey = (
  settings: GlobalSettings,
  isObserver?: boolean
) => {
  const isSearchOnHotkey = settings.isSeachOnHotkey.isOn;

  const selectPress = async (e: KeyboardEvent) => {
    // TGL-06: read the LIVE settings at fire time, not the snapshot captured
    // when this listener was first armed. The arm-once guard below never
    // re-arms while the feature stays on, so a captured `settings` would stay
    // frozen to the first-arm query list — Shift+F would keep searching the old
    // queries and ignore ones the user added/edited since. Mirrors how
    // content.searchBySelect / content.switchOffHotkey read currentGlobalSettings.
    const live = currentGlobalSettings;
    if (e.key === "F" && e.shiftKey && live?.isSeachOnHotkey?.isOn) {
      // See editable.utils.ts: don't re-run search while the user is
      // typing in an editable surface.
      if (isEditableEventTarget(e)) return;
      // run search code
      runSearch(live, isObserver);
    }
  };

  if (isSearchOnHotkey && !selectListener) {
    selectListener = new AbortController();

    document.addEventListener("keyup", selectPress, selectListener);
  } else if (!isSearchOnHotkey && selectListener?.abort) {
    selectListener.abort();
    selectListener = null as unknown as AbortController;
  } else if (!isSearchOnHotkey) {
    runSearch(settings, isObserver);
  }
};

// switchOffCleanup uses this to drop the Shift+F listener when the
// extension is toggled off via popup; without it the listener stays alive
// and a Shift+F press could resurrect highlights on a "supposedly off"
// page.
export const cleanupSearchOnHotkey = () => {
  if (selectListener?.abort) {
    selectListener.abort();
    selectListener = null as unknown as AbortController;
  }
};

const runSearch = (
  settings: GlobalSettings,
  isObserver?: boolean
) => {
  doMarkSearch(settings, isObserver);

  const debouncedToastLogic = debounce(() => {
    toastLogic(settings);
    showFoundCountOnIcon(settings);
  }, 500);

  debouncedToastLogic();
};
