// Rich-editor highlighting via the CSS Custom Highlight API.
//
// Why this module exists: editors like Lexical, ProseMirror, Tiptap,
// Monaco, CodeMirror, Notion (and any custom contenteditable that
// reconciles against an internal model) react to foreign DOM mutations
// by reverting to their model state. mark.js wrapping their text with
// <hility> spans triggers exactly that revert path — Reddit's Lexical
// composer stripped the user's typed text alongside our wrapper
// (r/DataAnnotationTech, 2026-05-20). The mark.js shielding (see the
// EDITOR_FRAMEWORK_SELECTORS exclude and the ancestor-aware filter in
// content.highlight.ts) keeps mark.js OUT of those surfaces. This
// module is the second half: it paints highlights inside the same
// surfaces using the CSS Custom Highlight API, which renders via
// `::highlight()` between the DOM and the pixels. No DOM mutation, no
// reconciler war, copy-paste still returns clean text because nothing
// has been added to the tree.
//
// Browser support gate: CSS.highlights ships in Chrome 105 (Aug 2022),
// Safari 17.2 (Dec 2023), Firefox 140 (Jul 2025). On anything older we
// silently no-op — the page is no worse off than it was before this
// module existed, mark.js shielding still applies.
//
// Lifecycle:
//   boot(settings)  — feature-detect, snapshot settings, paint, install
//                     MutationObservers on every editor surface.
//   repaintAll()    — recompute matches against the current snapshot.
//                     Called when the saved-query list changes.
//   cleanup()       — drop highlights from CSS.highlights, disconnect
//                     observers, remove the injected ::highlight rules
//                     (both light DOM and per-shadow-root).

import { GlobalSettings, QueryItem } from "../../../definitions/global.definition";
import { QuerySearchOptions } from "../../../search/types";
import { getSearchOptions } from "../../../search/queryMatching";
import { hslFormatter } from "../../../components/shared/utils/color.utils";
import {
  EDITOR_FRAMEWORK_SELECTORS,
  EDITOR_CHROME_SELECTORS,
} from "../content.highlight";
import {
  computeFormFieldMatches,
  FormFieldMatch,
  MAX_FIELD_CHARS,
} from "../formFieldHighlights/computeMatches";

// Names registered with CSS.highlights are global per page. Prefix with a
// brand to avoid collisions with anything the page (or another extension)
// might be doing in the same Highlight registry.
const HIGHLIGHT_NAME_PREFIX = "hility-rich-";
const STYLE_ELEMENT_ID = "highlighty-rich-editor-highlights-styles";
const SHADOW_STYLE_MARKER = "data-highlighty-rich-editor-styles";

// Repaint coalescing window for MutationObserver bursts. Long enough that a
// 20-character paste fires one repaint, short enough that the user perceives
// the highlight as appearing "as they type".
const REPAINT_DEBOUNCE_MS = 100;

interface RichEditorState {
  // Editor element → MutationObserver. Per-editor because each editor's
  // mutations are independent and we want to scope observation to just
  // that subtree, not the whole document.
  observers: Map<Element, MutationObserver>;
  // Highlight names we currently own. Tracked so cleanup can remove only
  // ours (the API is a global Map; we mustn't blow away another
  // extension's or the page's registrations).
  registeredNames: Set<string>;
  // Shadow roots we've injected ::highlight CSS into, so cleanup can
  // walk them all even if the underlying editor surface has gone.
  shadowStyles: Set<ShadowRoot>;
  // Last-known settings snapshot. Re-read on each repaint so query list
  // / decoration / option changes take effect without a fresh boot.
  settings: GlobalSettings | null;
  repaintTimer: ReturnType<typeof setTimeout> | null;
}

let state: RichEditorState | null = null;

// Feature detection. The Custom Highlight API surfaces as both
// `CSS.highlights` (the registry) and the global `Highlight` constructor.
// Both must exist; old browsers / non-Chromium without the polyfill have
// neither. Wrapped in try because some sandbox harnesses freeze `CSS`.
const supportsCSSHighlights = (): boolean => {
  try {
    if (typeof CSS === "undefined") return false;
    const reg = (CSS as unknown as { highlights?: unknown }).highlights;
    if (!reg) return false;
    if (typeof (window as unknown as { Highlight?: unknown }).Highlight !== "function") {
      return false;
    }
    return true;
  } catch {
    return false;
  }
};

// Walk every open shadow root reachable from `root`. Closed roots return
// null for .shadowRoot and are unreachable by the platform. We do enter
// custom-element shadow roots here (unlike formFieldHighlights, which has
// to bail because it MUTATES the source) — this module only paints via
// the Custom Highlight API and never touches the DOM, so reactive Web
// Components have nothing to react to.
const walkOpenShadowRoots = (
  root: Document | Element | ShadowRoot,
  visit: (sr: ShadowRoot) => void
): void => {
  const queue: Element[] = [];
  if (root instanceof Document) {
    if (root.documentElement) queue.push(root.documentElement);
  } else if (root instanceof ShadowRoot) {
    for (const c of Array.from(root.children)) {
      if (c.nodeType === Node.ELEMENT_NODE) queue.push(c as Element);
    }
  } else {
    queue.push(root);
  }
  while (queue.length) {
    const el = queue.shift()!;
    // Don't dive into Highlighty's own UI subtrees.
    if (el.id === "highlighty-cmdf-host") continue;
    if (
      el.hasAttribute("data-highlighty-overlay") ||
      el.hasAttribute("data-highlighty-cmdf") ||
      el.hasAttribute("data-highlighty-adhoc")
    ) {
      continue;
    }
    const sr = (el as HTMLElement).shadowRoot;
    if (sr) {
      visit(sr);
      for (const c of Array.from(sr.children)) {
        if (c.nodeType === Node.ELEMENT_NODE) queue.push(c as Element);
      }
    }
    for (const c of Array.from(el.children)) {
      if (c.nodeType === Node.ELEMENT_NODE) queue.push(c as Element);
    }
  }
};

// REH-04 (owner decision: FIX — exclude read-only display widgets): a read-only
// display widget can advertise `role=textbox` + `contenteditable=true` purely for
// caret/selection behavior without being a user editor (e.g. a read-only chat
// transcript or a disabled rich field). Painting highlight bands onto its text
// surprises the user with marks on content they perceive as non-editable. Treat
// a surface as read-only — and exclude it — when it or an ancestor is marked
// `aria-readonly="true"` or `aria-disabled="true"`. Genuine editors don't carry
// those, so this only drops the over-matched display widgets.
const isReadOnlyEditorSurface = (el: Element): boolean =>
  el.closest('[aria-readonly="true"], [aria-disabled="true"]') !== null;

export const findEditorSurfaces = (): Element[] => {
  const out = new Set<Element>();
  const query = (root: ParentNode) => {
    for (const sel of EDITOR_FRAMEWORK_SELECTORS) {
      try {
        for (const el of Array.from(root.querySelectorAll(sel))) {
          out.add(el);
        }
      } catch {
        // Malformed selector — shouldn't happen because these are
        // hard-coded constants, but guard anyway so one bad entry can't
        // tank the whole pass.
      }
    }
  };
  query(document);
  walkOpenShadowRoots(document, query);
  const all = Array.from(out);
  // Keep only the innermost matched surfaces: drop any matched element that
  // CONTAINS another matched element. Two reasons:
  //   (a) Chrome avoidance — a framework root selector wraps editor chrome
  //       (CodeMirror 6's `.cm-editor` includes the line-number gutter,
  //       while `.cm-content` is just the editable text). Painting the inner
  //       content surface keeps highlights off the gutter.
  //   (b) De-duplication — when both an outer and inner selector match the
  //       same editor (`.tiptap` ⊃ `.ProseMirror`), walking the outer would
  //       re-collect the inner's text and register the same match twice.
  // Surfaces with no inner match (Monaco's `.monaco-editor`, CodeMirror 5's
  // `.CodeMirror`) survive this filter and rely on EDITOR_CHROME_SELECTORS
  // in collectTextNodes to skip their gutters.
  return all.filter(
    (el) =>
      // innermost-only (Chrome avoidance + de-dup, see above) …
      !all.some((other) => other !== el && el.contains(other)) &&
      // … and exclude read-only display widgets (REH-04).
      !isReadOnlyEditorSurface(el)
  );
};

interface TextNodeEntry {
  node: Text;
  // Cumulative offset in the concatenated editor text, [start, end).
  start: number;
  end: number;
}

// Concatenate all text nodes inside an editor surface into a single
// string, keeping a map from string offsets back to (node, localOffset)
// pairs. Skips Highlighty's own UI subtrees (in case an adhoc preview
// lands inside an editor — defensive).
export const collectTextNodes = (
  root: Element
): { text: string; nodes: TextNodeEntry[] } => {
  const nodes: TextNodeEntry[] = [];
  let text = "";
  let walker: TreeWalker;
  try {
    walker = (root.ownerDocument ?? document).createTreeWalker(
      root,
      NodeFilter.SHOW_TEXT,
      {
        acceptNode: (n) => {
          // Reject if any ancestor is one of Highlighty's own roots
          // (paranoia — the editor surfaces should never contain ours).
          const p = (n as Text).parentElement;
          if (!p) return NodeFilter.FILTER_REJECT;
          if (
            p.closest(
              "[data-highlighty-overlay],[data-highlighty-cmdf],[data-highlighty-adhoc],#highlighty-cmdf-host"
            )
          ) {
            return NodeFilter.FILTER_REJECT;
          }
          // Skip editor chrome (line-number gutters, glyph margins, minimap)
          // that lives inside the surface but isn't editable content. The
          // `closest` hit is only treated as chrome when it sits within the
          // editor root — a same-named class on an ancestor ABOVE the editor
          // (e.g. a page-level `.margin`) must not suppress real content.
          for (const sel of EDITOR_CHROME_SELECTORS) {
            let hit: Element | null = null;
            try {
              hit = p.closest(sel);
            } catch {
              hit = null;
            }
            if (hit && root.contains(hit)) return NodeFilter.FILTER_REJECT;
          }
          return NodeFilter.FILTER_ACCEPT;
        },
      }
    );
  } catch {
    return { text, nodes };
  }
  let n: Node | null;
  while ((n = walker.nextNode())) {
    const t = n as Text;
    const v = t.nodeValue ?? "";
    const start = text.length;
    text += v;
    nodes.push({ node: t, start, end: text.length });
  }
  return { text, nodes };
};

const findNodeAtOffset = (
  entries: TextNodeEntry[],
  offset: number,
  exclusiveEnd = false
): { node: Text; localOffset: number } | null => {
  // Binary search would be faster on huge editors; linear is fine up to
  // a few thousand text nodes which is far above any real editor surface.
  for (const e of entries) {
    if (exclusiveEnd) {
      // For Range.end (exclusive) — accept offset === e.end so the range
      // can terminate at the very last char of a text node.
      if (offset >= e.start && offset <= e.end) {
        return { node: e.node, localOffset: offset - e.start };
      }
    } else {
      if (offset >= e.start && offset < e.end) {
        return { node: e.node, localOffset: offset - e.start };
      }
      // Edge: the match begins exactly at the boundary between nodes
      // (offset === e.end of node[i] === e.start of node[i+1]). Iterating
      // forward we'll land on the next node naturally; no special case.
    }
  }
  return null;
};

export const matchToRange = (
  match: FormFieldMatch,
  entries: TextNodeEntry[]
): Range | null => {
  if (!entries.length) return null;
  if (match.end <= match.start) return null;
  const startInfo = findNodeAtOffset(entries, match.start, false);
  const endInfo = findNodeAtOffset(entries, match.end, true);
  if (!startInfo || !endInfo) return null;
  try {
    const r = (startInfo.node.ownerDocument ?? document).createRange();
    r.setStart(startInfo.node, startInfo.localOffset);
    r.setEnd(endInfo.node, endInfo.localOffset);
    return r;
  } catch {
    return null;
  }
};

// FNV-1a (32-bit) rendered as fixed-width unsigned hex — small, stable, and
// dependency-free. Not cryptographic; it only needs to spread distinct inputs
// to distinct digests. Hex output is itself a valid CSS ident fragment.
const stableHash = (s: string): string => {
  let h = 0x811c9dc5; // FNV offset basis
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    // FNV prime multiply via shifts (keeps it in 32-bit range under >>> 0).
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return (h >>> 0).toString(16).padStart(8, "0");
};

// REH-05: a lossy `s.replace(/[^a-zA-Z0-9_-]/g, "_")` collapses two distinct
// IDs that differ only in a stripped char (e.g. `a.b` vs `a/b`, or `x:1` vs
// `x_1`) into the SAME ident → both queries' ranges merge under one Highlight
// registration and render in the first query's color.
//
// IDs that are ALREADY valid CSS idents (the UUID-shaped common case) pass
// through unchanged — those can never collide (no substitution happens, so
// distinct inputs stay distinct), and keeping them verbatim preserves the
// readable, debuggable highlight names. Only IDs containing a char outside
// `[A-Za-z0-9_-]` are rewritten, and we rewrite them by appending a hash of
// the RAW string so two formerly-colliding IDs now diverge. The `h-` prefix
// keeps a hashed name from ever colliding with a verbatim one that happens to
// equal the (now-suffixed) escaped form.
const escapeCssIdent = (s: string): string => {
  if (!/[^a-zA-Z0-9_-]/.test(s)) return s;
  return `h-${s.replace(/[^a-zA-Z0-9_-]/g, "_")}-${stableHash(s)}`;
};

const buildHighlightName = (
  queryId: string,
  decorationType: string
): string =>
  `${HIGHLIGHT_NAME_PREFIX}${escapeCssIdent(queryId)}-${escapeCssIdent(decorationType)}`;

const cssRuleFor = (
  name: string,
  color: string,
  decorationType: QueryItem["decorationType"]
): string => {
  switch (decorationType) {
    case "underline":
      return `::highlight(${name}) { text-decoration: underline solid ${color}; text-decoration-thickness: 2px; }`;
    case "overline":
      return `::highlight(${name}) { text-decoration: overline solid ${color}; text-decoration-thickness: 2px; }`;
    case "line-through":
      return `::highlight(${name}) { text-decoration: line-through solid ${color}; text-decoration-thickness: 2px; }`;
    case "dotted-underline":
      return `::highlight(${name}) { text-decoration: underline dotted ${color}; text-decoration-thickness: 2px; }`;
    case "wavy-underline":
      return `::highlight(${name}) { text-decoration: underline wavy ${color}; text-decoration-thickness: 2px; }`;
    case "double-underline":
      return `::highlight(${name}) { text-decoration: underline double ${color}; text-decoration-thickness: 3px; }`;
    case "background":
    default:
      return `::highlight(${name}) { background-color: ${color}; }`;
  }
};

const ensureLightDomStylesheet = (cssText: string): void => {
  let style = document.getElementById(STYLE_ELEMENT_ID) as HTMLStyleElement | null;
  if (!cssText) {
    if (style) style.remove();
    return;
  }
  if (!style) {
    style = document.createElement("style");
    style.id = STYLE_ELEMENT_ID;
    document.head.appendChild(style);
  }
  if (style.textContent !== cssText) {
    style.textContent = cssText;
  }
};

const ensureShadowStylesheet = (sr: ShadowRoot, cssText: string): void => {
  if (!state) return;
  let injected = sr.querySelector(
    `style[${SHADOW_STYLE_MARKER}]`
  ) as HTMLStyleElement | null;
  if (!cssText) {
    if (injected) injected.remove();
    state.shadowStyles.delete(sr);
    return;
  }
  if (!injected) {
    injected = (sr.ownerDocument ?? document).createElement("style");
    injected.setAttribute(SHADOW_STYLE_MARKER, "");
    sr.appendChild(injected);
    state.shadowStyles.add(sr);
  }
  if (injected.textContent !== cssText) {
    injected.textContent = cssText;
  }
};

const clearAllHighlights = (): void => {
  if (!state) return;
  const reg = (CSS as unknown as { highlights?: { delete: (n: string) => void } })
    .highlights;
  if (!reg) return;
  for (const name of state.registeredNames) {
    try {
      reg.delete(name);
    } catch {
      // Ignore — registry might be locked / cleared mid-iteration.
    }
  }
  state.registeredNames.clear();
};

export const paintEditors = (settings: GlobalSettings): void => {
  if (!state) return;
  if (!supportsCSSHighlights()) return;

  const queries: QueryItem[] =
    settings.queryListState?.selectedList?.itemList ?? [];
  const activeQueries = queries.filter(
    (q) => !q.isInactive && q.name && q.name.trim().length > 0
  );
  const options: QuerySearchOptions = getSearchOptions(settings);

  // Drop everything before recomputing so we don't leave stale highlights
  // when a query is removed.
  clearAllHighlights();

  if (!activeQueries.length) {
    ensureLightDomStylesheet("");
    for (const sr of Array.from(state.shadowStyles)) {
      ensureShadowStylesheet(sr, "");
    }
    return;
  }

  // Group ranges by `${queryId}-${decorationType}` — each unique
  // (query, decoType) pair gets its own Highlight registration so the
  // ::highlight() rule applies the right paint.
  const rangesByName = new Map<string, Range[]>();
  // Map back from name to the (query, decoType) we used to build it so we
  // can render the corresponding CSS rule without re-deriving.
  const styleSpecByName = new Map<
    string,
    { color: string; decorationType: QueryItem["decorationType"] }
  >();

  const shadowsTouched = new Set<ShadowRoot>();
  const editors = findEditorSurfaces();
  // REH-03: a newly-mounted editor (e.g. a reply box that appears after the
  // first edit) is painted on this pass but has no observer of its own, so
  // edits to it alone wouldn't repaint until the next settings/query pass.
  // Install observers for any freshly-discovered surface now.
  installEditorObservers(editors);
  // REH-06: byId is loop-invariant (it never reads `editor`), so build it
  // once instead of rebuilding it per editor on every repaint burst.
  const byId = new Map(activeQueries.map((q) => [q.id, q]));
  for (const editor of editors) {
    const { text, nodes } = collectTextNodes(editor);
    if (!text.length || text.length > MAX_FIELD_CHARS) continue;

    const matches = computeFormFieldMatches(text, activeQueries, options);
    if (!matches.length) continue;

    const root = editor.getRootNode();
    if (root instanceof ShadowRoot) shadowsTouched.add(root);

    for (const m of matches) {
      const item = byId.get(m.queryId);
      if (!item) continue;
      const r = matchToRange(m, nodes);
      if (!r) continue;
      const decoType = item.decorationType ?? "background";
      const name = buildHighlightName(item.id, decoType);
      let arr = rangesByName.get(name);
      if (!arr) {
        arr = [];
        rangesByName.set(name, arr);
      }
      arr.push(r);
      if (!styleSpecByName.has(name)) {
        styleSpecByName.set(name, {
          color: hslFormatter(
            item.colors?.hsl ?? { h: 0, s: 0, l: 70, a: 1 }
          ),
          decorationType: decoType,
        });
      }
    }
  }

  // Register highlights in CSS.highlights
  const reg = (CSS as unknown as {
    highlights: { set: (name: string, h: object) => void };
  }).highlights;
  const HighlightCtor = (window as unknown as {
    Highlight: new (...args: Range[]) => object;
  }).Highlight;

  for (const [name, ranges] of rangesByName) {
    try {
      const hl = new HighlightCtor(...ranges);
      reg.set(name, hl);
      state.registeredNames.add(name);
    } catch {
      // Range may have been invalidated between collection and
      // registration (rare race during typing). Skip silently.
    }
  }

  // Build CSS rules text for the names we just registered.
  const rules: string[] = [];
  for (const name of state.registeredNames) {
    const spec = styleSpecByName.get(name);
    if (!spec) continue;
    rules.push(cssRuleFor(name, spec.color, spec.decorationType));
  }
  const cssText = rules.join("\n");

  ensureLightDomStylesheet(cssText);
  for (const sr of shadowsTouched) {
    ensureShadowStylesheet(sr, cssText);
  }
  // Tear stylesheets out of shadow roots we no longer touch (an editor
  // was removed from the DOM since the last pass).
  for (const sr of Array.from(state.shadowStyles)) {
    if (!shadowsTouched.has(sr)) {
      ensureShadowStylesheet(sr, "");
    }
  }
};

const scheduleRepaint = (): void => {
  if (!state) return;
  if (state.repaintTimer !== null) clearTimeout(state.repaintTimer);
  state.repaintTimer = setTimeout(() => {
    if (!state) return;
    state.repaintTimer = null;
    if (state.settings) paintEditors(state.settings);
  }, REPAINT_DEBOUNCE_MS);
};

// REH-03: accept an optional pre-computed surface list so paintEditors can
// (re)install observers for editors it just discovered without a second
// findEditorSurfaces() walk. Called with no args from boot/repaintAll.
const installEditorObservers = (known?: Element[]): void => {
  if (!state) return;
  const editors = new Set(known ?? findEditorSurfaces());
  // Disconnect observers for editors that have left the DOM.
  for (const [el, obs] of Array.from(state.observers)) {
    if (!editors.has(el)) {
      obs.disconnect();
      state.observers.delete(el);
    }
  }
  // Attach a fresh observer to any editor we don't already watch.
  for (const editor of editors) {
    if (state.observers.has(editor)) continue;
    const obs = new MutationObserver(() => scheduleRepaint());
    obs.observe(editor, {
      childList: true,
      subtree: true,
      characterData: true,
    });
    state.observers.set(editor, obs);
  }
};

const isFeatureEnabled = (settings: GlobalSettings): boolean => {
  // Tied to the umbrella isExtensionOn — no separate popup setting yet.
  // If we add one (likely with the v2.5 editor-decoration suite), gate
  // here.
  return Boolean(settings?.isExtensionOn);
};

export const boot = (settings: GlobalSettings): void => {
  if (!supportsCSSHighlights()) return;
  if (!isFeatureEnabled(settings)) {
    cleanup();
    return;
  }
  if (!state) {
    state = {
      observers: new Map(),
      registeredNames: new Set(),
      shadowStyles: new Set(),
      settings: null,
      repaintTimer: null,
    };
  }
  state.settings = settings;
  paintEditors(settings);
  installEditorObservers();
};

export const repaintAll = (): void => {
  if (!state || !state.settings) return;
  paintEditors(state.settings);
  installEditorObservers();
};

export const cleanup = (): void => {
  if (!state) return;
  clearAllHighlights();
  for (const obs of state.observers.values()) obs.disconnect();
  state.observers.clear();
  const ss = document.getElementById(STYLE_ELEMENT_ID);
  if (ss) ss.remove();
  for (const sr of state.shadowStyles) {
    const inj = sr.querySelector(`style[${SHADOW_STYLE_MARKER}]`);
    if (inj) inj.remove();
  }
  state.shadowStyles.clear();
  if (state.repaintTimer !== null) {
    clearTimeout(state.repaintTimer);
  }
  state = null;
};

export const __testing = {
  getRegisteredNames: (): string[] => Array.from(state?.registeredNames ?? []),
  hasState: (): boolean => state !== null,
  getObserverCount: (): number => state?.observers.size ?? 0,
  supportsCSSHighlights,
};
