// BarRoot is the React state owner for the Cmd+F takeover bar. It mounts
// inside a Shadow DOM (managed by mount.ts), runs the ad-hoc matcher on
// debounced input, paints results via the CSS Custom Highlight API, and
// dispatches promote / saved-query interactions back to the host content
// script through the BarHooks prop.
//
// The bar is intentionally controlled — all DOM-touching side effects
// (paint, scroll, focus restore, promote handoff) flow through hook
// callbacks the parent supplies. That keeps this component testable in
// jsdom: hooks can be mocked and assertions made on call shape.

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { FiClock } from "react-icons/fi";
import {
  CmdFTakeoverBarUiState,
  CmdFTakeoverSettings,
  QueryItem,
} from "../../../../definitions/global.definition";
import {
  AdHocMatch,
  AdHocSearchModifiers,
  AdHocSearchResult,
  createCachedFinder,
  find,
  filterMatchesToSavedHighlights,
} from "../ephemeralSearch";
import { CrossTabHit, requestCrossTabSearch } from "../crossTab";
import CrossTabResults from "./CrossTabResults";
import * as paintAdHoc from "../paintAdHoc";
import * as paintAdHocFallback from "../paintAdHocFallback";
import * as paintFieldOverlay from "../paintFieldOverlay";
import { cmdOrCtrlLabel } from "../../../../components/shared/utils/platform.utils";
import Input from "./Input";
import Modifiers, { ModifierKey } from "./Modifiers";
import Tooltip from "./Tooltip";
import Chips, { ChipModel } from "./Chips";
import FloatingSnippetsShell, { FloatingSnippetsState } from "./FloatingSnippetsShell";
import HintToast from "./HintToast";
import { useCmdFAccessState } from "./useCmdFAccessState";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";

export interface PromoteSubmission {
  name: string;
}

// Debounced input handler. Set high enough that a normal typing
// rhythm (~80-150ms/char) doesn't fire a search between every
// keystroke — on busy pages with the heavier settings on
// (visible-mode filter, scrollbar markers, snippet panel) each
// search blocks the main thread long enough to stall subsequent
// keystrokes when it fires that often.
export const DEBOUNCE_MS = 250;

export interface SavedQueryRef {
  query: QueryItem;
  count: number;
}

export interface BarHooks {
  onClose: () => void;
  onPromote: (submission: PromoteSubmission) => Promise<void> | void;
  onRemoveSavedQuery: (queryId: string) => void;
  onJumpToSavedMatch: (queryId: string, direction: 1 | -1) => void;
  onScrollToMatch: (match: AdHocMatch) => void;
  onModifiersChange: (modifiers: CmdFTakeoverSettings["modifiers"]) => void;
  // Called on every term change. Used to debounce-persist last query per
  // site, push to history, and update the bookmarkable URL hash.
  onTermChange?: (term: string) => void;
  // Called when the user clicks "Open" on a cross-tab result. Receives the
  // chrome.tabs id of the matched tab and the current search term, so the host
  // can ask that tab to open its finder pre-filled and continue the search.
  onJumpToTab?: (tabId: number, term: string) => void;
  // Called when the user flips the in-bar takeover switch off. The host
  // persists cmdFTakeover.isOn = false and tears the bar down — re-enable
  // happens from the popup.
  onDisableTakeover?: () => void;
  // Called when the user clicks the X on the in-page snippet panel. The
  // host persists cmdFTakeover.layout = "stripe" so the snippet panel
  // stays hidden across pages and reloads; re-enable from the popup.
  onCloseSnippets?: () => void;
  // Called whenever the search result set changes (including with an
  // empty array on cleared term). The host wires this to the scrollbar
  // overlay when settings.showInScrollbar is on.
  onAdHocResultsUpdate?: (matches: AdHocMatch[]) => void;
  // Called when the user clicks the "Clear" pill in the search-history
  // dropdown header. The host wipes cmdFTakeover.history and persists.
  // If omitted, the Clear pill is hidden.
  onClearHistory?: () => void;
  onReady?: () => void;
  /**
   * Called when the snippets panel's position or collapsed state changes.
   * Host persists via chrome.storage.local under cmdFTakeoverBarUiState
   * (debounced ~200ms). Optional so test stubs don't have to provide it.
   */
  onPersistBarUiState?: (state: CmdFTakeoverBarUiState) => void;
  /**
   * Called when the user clicks the new "search inside saved highlights"
   * modifier button on the bar. Host flips
   * cmdFTakeover.searchOnlyInSavedHighlights and re-renders.
   */
  onToggleSearchOnlySaved?: () => void;
  /**
   * Called when the user clicks the "Remember" modifier button on the bar.
   * Host flips cmdFTakeover.persistLastQueryPerSite and re-renders.
   */
  onToggleRememberLastQuery?: () => void;
}

export interface BarRootProps {
  settings: CmdFTakeoverSettings;
  savedQueries: SavedQueryRef[];
  initialTerm?: string;
  hint?: string;
  onHintDone?: () => void;
  history?: string[];
  hooks: BarHooks;
  /**
   * Where to walk text from. Defaults to document.body. Tests inject a
   * custom node so the matcher doesn't traverse the test runner's DOM.
   */
  searchRoot?: () => Node;
  /**
   * Test seam: lets the integration test override the matcher entirely
   * (and thus avoid having to construct CSS.highlights stubs). Production
   * callers leave this undefined.
   */
  finder?: typeof find;
  /**
   * Test seam for paint dispatch.
   */
  painter?: {
    paint: (matches: AdHocMatch[], currentIndex: number) => void;
    clear: () => void;
  };
  /**
   * Persisted snippets-panel state loaded from storage by the host.
   * Forwards the snippets panel's position and isCollapsed values to
   * FloatingSnippetsShell on mount.
   */
  initialBarUiState?: CmdFTakeoverBarUiState;
  /**
   * True when this open was SEEDED by an external action (the cross-tab "jump"
   * entry path) rather than by the user typing. Drives two behaviors, both
   * scoped to that entry path:
   *   1. One-shot auto-scroll to the first match once the seeded search settles,
   *      so the user lands on a result. Never fires on later user edits.
   *   2. The seeded term is NOT persisted as user intent — it doesn't clobber
   *      the destination's remembered last-query or write its bookmarkable URL
   *      hash (the user didn't choose to search this site).
   * Normal Cmd+F opens leave this undefined: no auto-scroll, normal persistence.
   */
  seededExternally?: boolean;
}

// CMF-03: the regex/fuzzy chips are PRO-gated — for a free user the chip
// renders locked and forced visually off (Modifiers.tsx `isLocked = isPro
// && isFree`). But `m.regex.isOn`/`m.fuzzy.isOn` can still be `true` in
// persisted settings (trial→free downgrade, or a storage bleed). Gate the
// modifiers actually handed to the in-page `search()` by `accessState` so
// the searched modifiers agree with the chip display: when `accessState`
// is "free", regex/fuzzy are forced off here, mirroring the cross-tab
// gate (`triggerCrossTabSearch` early-returns for free users). PRO/trial
// users are unaffected — their regex/fuzzy persist and apply as before.
const toModifiers = (
  m: CmdFTakeoverSettings["modifiers"],
  accessState: PremiumFeatureAccessState
): AdHocSearchModifiers => {
  const proAllowed = accessState !== "free";
  return {
    caseSensitive: m.caseSens.isOn,
    wholeWord: m.wholeWord.isOn,
    diacriticSensitive: m.diacriticSens.isOn,
    regex: proAllowed && m.regex.isOn,
    fuzzy: proAllowed && m.fuzzy.isOn,
  };
};

const BarRoot: React.FC<BarRootProps> = ({
  settings,
  savedQueries,
  initialTerm = "",
  hint,
  onHintDone,
  history,
  hooks,
  searchRoot,
  finder,
  painter,
  initialBarUiState,
  seededExternally,
}) => {
  const [term, setTerm] = useState(initialTerm);
  // The seeded term the cross-tab-jump one-shot scroll is armed for, or null
  // once disarmed. A single ref (not a boolean + term pair) so "armed for T" is
  // the only representable armed state. Captured at MOUNT only (useRef
  // initializer runs once) so a later update() re-render that drops the prop
  // can't disarm it before the debounced seeded search settles. The arm survives
  // a 0-match first settle (content not ready, or entitlement still clamping
  // regex/fuzzy) and fires when a later USER-DRIVEN settle for the SAME term
  // finds matches; it disarms the moment the term diverges from the seed (see
  // the search effect) so the user's own typed search is never auto-scrolled.
  const pendingScrollTermRef = useRef<string | null>(
    seededExternally === true ? initialTerm : null
  );
  const [modifiers, setModifiers] = useState(settings.modifiers);
  const accessState = useCmdFAccessState();
  const [matches, setMatches] = useState<AdHocMatch[]>([]);
  const [searchText, setSearchText] = useState("");
  const [currentIndex, setCurrentIndex] = useState(0);
  const [closing, setClosing] = useState(false);
  const [crossTabHits, setCrossTabHits] = useState<CrossTabHit[] | null>(null);
  const [crossTabLoading, setCrossTabLoading] = useState(false);
  const [localHint, setLocalHint] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const crossTabReqId = useRef(0);
  // CMF-12: the search effect re-runs on modifier/finder/painter changes too,
  // not just term changes. `onTermChange` (debounce-persist last query, history
  // push, URL-hash update) must only fire when the TERM actually changed, so we
  // remember the term we last notified the host about. Seeded to a sentinel
  // (never equal to any string term) so the FIRST effect run still reports the
  // initial term, exactly as the old unconditional call did.
  // Seeded to a sentinel so the FIRST effect run reports the initial term —
  // EXCEPT on the seeded (cross-tab jump) path, where we seed it to `initialTerm`
  // so the forwarded term is NOT persisted as if the user typed it here. A later
  // user edit changes `term`, so onTermChange fires normally then; and an empty
  // term never persists (guarded host-side), so a Save/clear can't wipe the
  // destination's remembered last-query either.
  const lastNotifiedTerm = useRef<string | symbol>(
    seededExternally === true ? initialTerm : Symbol("unset")
  );
  const defaultSnippetsState: FloatingSnippetsState = useMemo(
    () =>
      initialBarUiState?.snippetsPanel ?? {
        position: { top: null, left: null },
        isCollapsed: false,
      },
    [initialBarUiState]
  );

  // SNP-03: the snippets-panel state must live in React STATE, not a ref, so
  // that a hydration-time value change actually re-renders FloatingSnippetsShell
  // with the new `initialState` prop. (A ref carries the latest value but a ref
  // write triggers no re-render, so when the async initialBarUiState hydration
  // landed AFTER the shell had already mounted with matches present, the shell
  // kept its default position/collapse until some unrelated re-render happened.)
  //
  // This state is updated by BOTH paths:
  //   - storage hydration (the [defaultSnippetsState] effect below), and
  //   - persistSnippetsPanel (drags / chevron toggles)
  // so it always reflects the latest persisted value. Because BarRoot itself
  // does NOT unmount when the shell unmounts (matches → 0) and remounts
  // (matches → N), this state survives that cycle — which preserves the
  // remount-carries-latest-drag behavior the old ref was added for: the shell
  // remounts seeded from the latest dragged/collapsed value, not the stale
  // mount-time default.
  const [snippetsPanelState, setSnippetsPanelState] =
    useState<FloatingSnippetsState>(defaultSnippetsState);

  // True once the user has dragged/collapsed the panel in-session (i.e.
  // persistSnippetsPanel ran). After that, the in-session value is canonical
  // and a late storage hydration must NOT clobber it — mirroring the old
  // ref-based behavior, where persist wrote the ref and a subsequent hydration
  // overwrite was harmless because the shell's own guards never re-applied a
  // value the user had already moved past.
  const snippetsTouchedInSession = useRef(false);

  // Adopt the hydrated default when the initial storage load arrives async
  // (initialBarUiState changes from undefined → loaded value, re-memoizing
  // defaultSnippetsState). Skip if the user already interacted in-session so a
  // late hydration can't reset a drag/collapse the user made first.
  useEffect(() => {
    if (snippetsTouchedInSession.current) return;
    setSnippetsPanelState(defaultSnippetsState);
  }, [defaultSnippetsState]);

  // Per-bar-mount cached finder: walks the DOM once and reuses
  // (text, runs) across keystrokes; a MutationObserver invalidates
  // it when the page mutates (debounced). Tests override via the
  // `finder` prop; in production we always use the cached version so
  // typing on large pages (SEC filings, big tables) doesn't re-walk
  // the entire DOM with getComputedStyle on every search.
  // Corpus invalidation tick: bumped whenever the cached finder's
  // (text, runs) snapshot goes stale. The search effect depends on it,
  // so a page mutation OR a form-field value change re-runs find()
  // without requiring the user to touch the bar input again.
  const [corpusTick, setCorpusTick] = useState(0);
  const cachedFinderRef = useRef<ReturnType<typeof createCachedFinder> | null>(
    null
  );
  if (cachedFinderRef.current === null) {
    cachedFinderRef.current = createCachedFinder({
      onInvalidate: () => setCorpusTick((t) => t + 1),
    });
  }
  useEffect(() => {
    return () => {
      cachedFinderRef.current?.dispose();
      cachedFinderRef.current = null;
    };
  }, []);
  const activeFinder: typeof find = finder ?? cachedFinderRef.current.find;

  // The painter to use: explicit prop wins, otherwise pick at runtime.
  const activePainter = useMemo(() => {
    if (painter) return painter;
    if (paintAdHoc.isSupported()) return paintAdHoc;
    return paintAdHocFallback;
  }, [painter]);

  // Notify parent that we've rendered (cancels watchdog).
  useEffect(() => {
    hooks.onReady?.();
    inputRef.current?.focus();
    inputRef.current?.select();
    return () => {
      activePainter.clear();
      paintFieldOverlay.clear();
      hooks.onAdHocResultsUpdate?.([]);
    };
    // hooks.onReady is stable per mount; do not re-run.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-sync local modifier state when the popup pushes new settings.
  // Popup is canonical: an in-flight popup change overrides the bar's
  // local modifier toggles. Reference equality on settings.modifiers
  // means this only fires when the prop actually changes.
  useEffect(() => {
    setModifiers(settings.modifiers);
  }, [settings.modifiers]);

  // Re-publish current ad-hoc match set whenever showInScrollbar flips.
  // The host hook gates clear/set on the latest settings.showInScrollbar
  // value, so re-firing with the same payload yields the right behaviour
  // either way. Defense-in-depth — fix #1's modifier-resync loop already
  // re-runs the search effect on popup pushes, but tying this directly
  // to the toggle keeps the contract local and obvious.
  useEffect(() => {
    hooks.onAdHocResultsUpdate?.(matches);
    // hooks identity changes per update(); we only fire on the toggle.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settings.showInScrollbar]);

  // Re-run search whenever term or modifiers change (debounced). This is
  // the "user-initiated" path — currentIndex resets to 0 because the
  // user's previous match position is no longer meaningful.
  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    // CMF-12: only notify the host when the term itself changed. A modifier
    // toggle / finder-cache identity swap re-runs this effect with the same
    // term — re-firing onTermChange there caused redundant persist/history/URL
    // churn and violated the hook's "called on every term change" contract.
    if (lastNotifiedTerm.current !== term) {
      lastNotifiedTerm.current = term;
      hooks.onTermChange?.(term);
    }
    // Disarm the seeded one-shot the moment the term diverges from the seed —
    // SYNCHRONOUSLY, before the `!term` early return below, so even clearing the
    // input (term → "") disarms. Otherwise a clear-then-retype of the seeded
    // term would later auto-scroll the user's OWN search.
    if (
      pendingScrollTermRef.current !== null &&
      term !== pendingScrollTermRef.current
    ) {
      pendingScrollTermRef.current = null;
    }
    if (!term) {
      setMatches([]);
      setSearchText("");
      setCurrentIndex(0);
      activePainter.clear();
      paintFieldOverlay.clear();
      hooks.onAdHocResultsUpdate?.([]);
      return;
    }
    debounceTimer.current = setTimeout(() => {
      const root = searchRoot ? searchRoot() : document.body;
      // CMF-36: always run the (cached) activeFinder so its MutationObserver is
      // installed, then apply the saved-highlights filter as a post-step. The
      // old code called the module-level uncached findInsideSavedHighlights in H
      // mode, so no observer was installed and the count never refreshed after
      // the DOM settled. Filtering activeFinder's result keeps the corpus/observer
      // path live in both modes.
      const raw = activeFinder(term, toModifiers(modifiers, accessState), root);
      const result = settings.searchOnlyInSavedHighlights
        ? filterMatchesToSavedHighlights(raw)
        : raw;
      setMatches(result.matches);
      setSearchText(result.text);
      setCurrentIndex(0);
      activePainter.paint(result.matches, 0);
      paintFieldOverlay.paint(result.matches, 0);
      hooks.onAdHocResultsUpdate?.(result.matches);
      // Intentionally do NOT scroll on term change. Auto-scrolling while
      // the user is still typing is jarring — the page jumps under them
      // on every keystroke. Scrolling happens only on explicit
      // navigation (Enter / Shift+Enter / arrow buttons / snippet click).
      //
      // Exception: the seeded (cross-tab jump) entry path arms a ONE-SHOT scroll
      // so the user who clicked an All-tabs result lands on the first match here.
      // Fire for the SEEDED term once matches exist; a seeded term that finds 0
      // matches (content/entitlement not ready) stays armed for a later
      // USER-DRIVEN settle (this effect re-runs on the accessState-hydration or a
      // modifier change). Divergence is handled synchronously above, so here we
      // only need the still-armed-for-this-term case. Deliberately NOT honored on
      // the corpus-refresh (DOM-mutation) path — a page edit/late mutation must
      // never yank the viewport or stomp a field the user is typing in.
      if (pendingScrollTermRef.current === term && result.matches.length > 0) {
        pendingScrollTermRef.current = null;
        hooks.onScrollToMatch(result.matches[0]);
      }
    }, DEBOUNCE_MS);
    return () => {
      if (debounceTimer.current) clearTimeout(debounceTimer.current);
    };
    // hooks is identity-stable per mount in real use; finder/painter changes are intentional.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [term, modifiers, accessState, settings.searchOnlyInSavedHighlights, activeFinder, activePainter]);

  // CMF-06 + CMF-26: the cross-tab "All tabs" results belong to a specific term
  // AND a specific set of search modifiers (case-sensitivity, whole-word,
  // regex, fuzzy). When the in-page term changes (CMF-06) OR a modifier is
  // toggled (CMF-26), those results no longer correspond to the visible query
  // — so reset the panel (and bump the request id to drop any in-flight
  // cross-tab response) rather than leave stale hits on screen. This mirrors
  // the in-page search effect above, which already re-runs on a modifier
  // change; the cross-tab panel must not be left displaying a result set
  // computed under the previous modifiers.
  //
  // Keyed on `[term, modifiers]`: `modifiers` is `useState`-backed state, so
  // its reference is stable between renders (it only changes when
  // `setModifiers` runs — in `handleToggleModifier` or the popup-resync
  // effect). That's the SAME dependency the in-page search effect deps on
  // safely, so this can't loop every render. Re-running "All tabs" for the
  // same term + modifiers is a button click (neither dep changed), so this
  // never clobbers a fresh result set the user just requested.
  useEffect(() => {
    crossTabReqId.current += 1;
    setCrossTabHits(null);
    setCrossTabLoading(false);
    // CMF-44: since CMF-31 made cross-tab results depend on the "search only in
    // saved highlights" (H) mode, a change to it must reset the panel too —
    // otherwise toggling H after "All tabs" leaves hits computed under the old
    // mode on screen as if current (the CMF-26 staleness class, H dimension).
  }, [term, modifiers, settings.searchOnlyInSavedHighlights]);

  // Re-run search when the cached corpus invalidates (DOM mutation OR a
  // form-field value change). Distinct from the user-initiated effect so
  // the user's current navigation position is preserved — pressing Enter
  // to cycle through 7 matches must not reset to index 0 just because a
  // background re-render bumped the cache. We clamp the index against
  // the new match count so it stays in bounds.
  useEffect(() => {
    // Skip the initial mount tick (corpusTick === 0) — the user-driven
    // effect above is responsible for the first search.
    if (corpusTick === 0) return;
    if (!term) return;
    const root = searchRoot ? searchRoot() : document.body;
    // CMF-36: mirror the user-driven effect — cached finder + saved-highlights
    // post-filter, so the corpus-refresh path is identical in both modes.
    const raw = activeFinder(term, toModifiers(modifiers, accessState), root);
    const result = settings.searchOnlyInSavedHighlights
      ? filterMatchesToSavedHighlights(raw)
      : raw;
    setMatches(result.matches);
    setSearchText(result.text);
    setCurrentIndex((prev) =>
      result.matches.length === 0
        ? 0
        : Math.min(prev, result.matches.length - 1),
    );
    const nextIndex =
      result.matches.length === 0
        ? 0
        : Math.min(currentIndex, result.matches.length - 1);
    activePainter.paint(result.matches, nextIndex);
    paintFieldOverlay.paint(result.matches, nextIndex);
    hooks.onAdHocResultsUpdate?.(result.matches);
    // The seeded one-shot scroll is deliberately NOT honored here. A corpus
    // refresh fires on any DOM mutation — including the user typing the seeded
    // term into a page form field (the corpus indexes field values) or a late
    // async content load minutes after the jump. Auto-scrolling / selecting a
    // field match on those would yank the viewport or stomp the text the user is
    // actively editing. The one-shot only fires from the user-driven settle.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [corpusTick]);

  const navigate = useCallback(
    (direction: 1 | -1) => {
      if (!matches.length) return;
      const next = (currentIndex + direction + matches.length) % matches.length;
      setCurrentIndex(next);
      activePainter.paint(matches, next);
      paintFieldOverlay.paint(matches, next);
      hooks.onScrollToMatch(matches[next]);
    },
    [activePainter, currentIndex, hooks, matches]
  );

  const handleClose = useCallback(() => {
    setClosing(true);
    activePainter.clear();
    paintFieldOverlay.clear();
    // Slide-out animation duration matches the CSS keyframe.
    setTimeout(() => hooks.onClose(), 90);
  }, [activePainter, hooks]);

  const handleToggleModifier = useCallback(
    (key: ModifierKey) => {
      // CMF-13: compute `next` from the current modifiers state OUTSIDE the
      // setModifiers updater, fire the side-effecting persist exactly once,
      // then commit the state. Calling onModifiersChange (a chrome.storage
      // persist) inside the updater made the updater impure — React may invoke
      // an updater more than once (StrictMode / bail-out / concurrent), which
      // would double-fire the persist per click.
      const next = {
        ...modifiers,
        [key]: { ...modifiers[key], isOn: !modifiers[key].isOn },
      };
      hooks.onModifiersChange(next);
      setModifiers(next);
    },
    [hooks, modifiers]
  );

  // Shown when a free user clicks a locked PRO chip. The bar stays open
  // and the toast self-dismisses; the user can keep typing. Manage popup
  // navigation outside the bar — the bar shouldn't decide *how* upgrade
  // happens, only that the user pressed a paywalled control.
  const showLockedHint = useCallback((featureLabel: string) => {
    setLocalHint(
      `🔐 ${featureLabel} is a PRO feature. Open Highlighty to upgrade.`
    );
  }, []);

  const triggerCrossTabSearch = useCallback(async () => {
    if (!term.trim()) return;
    if (accessState === "free") {
      showLockedHint("All tabs search");
      return;
    }
    const reqId = ++crossTabReqId.current;
    setCrossTabLoading(true);
    setCrossTabHits([]);
    try {
      const { results } = await requestCrossTabSearch(
        term,
        toModifiers(modifiers, accessState),
        // CMF-31: apply the bar's saved-highlights-only mode to every tab.
        settings.searchOnlyInSavedHighlights
      );
      // Drop stale responses if the user changed the term meanwhile.
      if (reqId !== crossTabReqId.current) return;
      setCrossTabHits(results);
    } finally {
      if (reqId === crossTabReqId.current) setCrossTabLoading(false);
    }
  }, [accessState, modifiers, showLockedHint, term, settings.searchOnlyInSavedHighlights]);

  // One-shot save: term-as-name + a randomized color picked host-side.
  // No modal, no name-edit step — bar clears the term so the user can
  // keep searching. Editing/renaming happens in the popup.
  const handleSave = useCallback(async () => {
    const name = term.trim();
    if (!name) return;
    await hooks.onPromote({ name });
    setMatches([]);
    activePainter.clear();
    paintFieldOverlay.clear();
    setTerm("");
    inputRef.current?.focus();
  }, [activePainter, hooks, term]);

  const chipModels: ChipModel[] = useMemo(
    () => savedQueries.map((s) => ({ query: s.query, count: s.count })),
    [savedQueries]
  );

  const persistSnippetsPanel = useCallback(
    (next: FloatingSnippetsState, userInitiated: boolean = true) => {
      // SNP-23: only a GENUINE user drag/collapse marks the panel "touched this
      // session". An automatic clamp-correction (off-screen restore / window
      // resize) passes userInitiated:false, so it no longer poisons this flag —
      // otherwise every window-resizer (the exact SNP-01/04 audience) would then
      // be locked out of a later legitimate cross-tab / hydration adoption below.
      if (userInitiated) snippetsTouchedInSession.current = true;
      // Keep the lifted state authoritative so a later shell remount
      // (matches 0 → N) seeds from the latest dragged/collapsed value.
      setSnippetsPanelState(next);
      // SNP-05: read-modify-write. Spread the CURRENT persisted bar UI state
      // and override only `snippetsPanel` — do NOT hard-code the top-level bar
      // `position` to {null,null} on every snippet write. The top-level
      // `position` is the BAR's own position (distinct from
      // snippetsPanel.position); clobbering it to null on every drag/collapse
      // would wipe a persisted draggable-bar position the moment that feature
      // is wired up. `initialBarUiState` is the latest hydrated bar UI state;
      // fall back to a null top-level position only when nothing was persisted.
      hooks.onPersistBarUiState?.({
        ...(initialBarUiState ?? { position: { top: null, left: null } }),
        snippetsPanel: next,
      });
    },
    [hooks, initialBarUiState]
  );

  return (
    <div className="bar-root" data-highlighty-cmdf>
      <div className={"bar" + (closing ? " closing" : "")} role="toolbar" aria-label="Highlighty search">
        <Input
          ref={inputRef}
          value={term}
          count={matches.length}
          currentIndex={currentIndex}
          onChange={setTerm}
          onPrev={() => navigate(-1)}
          onNext={() => navigate(1)}
          onClose={handleClose}
          onSave={handleSave}
          history={settings.searchHistory.isOn ? history : undefined}
          accessState={accessState}
          onClearHistory={hooks.onClearHistory}
        />
        <div className="modifier-cluster">
          <Modifiers
            modifiers={modifiers}
            onToggle={handleToggleModifier}
            accessState={accessState}
            onLockedPro={(key) =>
              showLockedHint(key === "regex" ? "Regex" : "Fuzzy match")
            }
          />
          {hooks.onToggleSearchOnlySaved && (
            <Tooltip
              label="Search only inside saved highlights"
              hint="Restricts matches to text already inside your saved highlights."
            >
              <button
                type="button"
                className={
                  "mod saved-hl" +
                  (settings.searchOnlyInSavedHighlights ? " on" : "")
                }
                aria-pressed={settings.searchOnlyInSavedHighlights}
                aria-label="Search only inside saved highlights"
                onClick={hooks.onToggleSearchOnlySaved}
              >
                H
              </button>
            </Tooltip>
          )}
          {hooks.onToggleRememberLastQuery && (
            <Tooltip
              label="Remember last search per site"
              hint="When on, reopening the bar on this site pre-fills your last term."
            >
              <button
                type="button"
                className={
                  "mod remember" +
                  (settings.persistLastQueryPerSite ? " on" : "")
                }
                aria-pressed={settings.persistLastQueryPerSite}
                aria-label="Remember last search per site"
                onClick={hooks.onToggleRememberLastQuery}
              >
                <FiClock aria-hidden="true" />
              </button>
            </Tooltip>
          )}
        </div>
        <Tooltip label="Save as highlight" shortcut="Shift+Enter">
          <button
            type="button"
            className="promote"
            onClick={handleSave}
            disabled={!term.trim()}
            aria-keyshortcuts="Shift+Enter"
            aria-label="Save current search as highlight"
          >
            + Save highlight
          </button>
        </Tooltip>
        {settings.findInAllTabs && (
          <Tooltip
            label="Search all open tabs"
            shortcut={
              accessState === "trial"
                ? "✨TRIAL"
                : accessState === "free"
                ? "🔐PRO"
                : undefined
            }
            hint="Runs the current term across every open tab and lists tabs where it hit."
          >
            <button
              type="button"
              className={
                "crosstab-trigger" +
                (accessState === "trial" ? " trial" : "") +
                (accessState === "free" ? " locked" : "")
              }
              onClick={triggerCrossTabSearch}
              // Free users stay clickable so the click can route to the
              // upgrade hint. Loading/empty-term still disable the
              // button — those are state, not paywall.
              disabled={
                !term.trim() || (accessState !== "free" && crossTabLoading)
              }
              aria-disabled={accessState === "free" || undefined}
              aria-label={
                accessState === "trial"
                  ? "Search this term in all open tabs (PRO feature, included in trial)"
                  : accessState === "free"
                  ? "Search this term in all open tabs (PRO feature, locked — upgrade to use)"
                  : "Search this term in all open tabs"
              }
            >
              {crossTabLoading && accessState !== "free"
                ? "Searching tabs…"
                : "All tabs"}
            </button>
          </Tooltip>
        )}
        {settings.showSavedChips && (
          <Chips
            chips={chipModels}
            activeQueryId={null}
            onChipClick={(id) => hooks.onJumpToSavedMatch(id, 1)}
            onChipRemove={hooks.onRemoveSavedQuery}
          />
        )}
        {hooks.onDisableTakeover && (
          <Tooltip
            label="Disable Highlighty find"
            shortcut={`Restore native ${cmdOrCtrlLabel("F")}`}
          >
            <button
              type="button"
              className="takeover-switch on"
              role="switch"
              aria-checked={true}
              aria-label="Disable Highlighty find"
              onClick={hooks.onDisableTakeover}
            >
              <span className="takeover-switch-track" aria-hidden="true">
                <span className="takeover-switch-thumb" />
              </span>
            </button>
          </Tooltip>
        )}
      </div>
      {settings.layout === "stripe-with-snippets" && term && matches.length > 0 && (
        <FloatingSnippetsShell
          matches={matches}
          currentIndex={currentIndex}
          fullText={searchText}
          onJump={(i) => {
            setCurrentIndex(i);
            activePainter.paint(matches, i);
            // SNP-08: keep the on-page field-overlay's `--current` band in sync
            // with the jumped-to match, mirroring navigate() and the corpus-tick
            // effect. Without this a snippet-card jump left the previous field
            // marked current (two contradictory current indicators).
            paintFieldOverlay.paint(matches, i);
            hooks.onScrollToMatch(matches[i]);
          }}
          onClose={hooks.onCloseSnippets}
          accessState={accessState}
          initialState={snippetsPanelState}
          onPersistSnippetsPanel={persistSnippetsPanel}
        />
      )}
      {crossTabHits !== null && (
        <CrossTabResults
          hits={crossTabHits}
          loading={crossTabLoading}
          onJump={(tabId) => {
            hooks.onJumpToTab?.(tabId, term);
            setCrossTabHits(null);
          }}
          onClose={() => setCrossTabHits(null)}
          accessState={accessState}
        />
      )}
      {hint && onHintDone && <HintToast message={hint} onDone={onHintDone} />}
      {localHint && (
        <HintToast
          message={localHint}
          onDone={() => setLocalHint(null)}
          durationMs={2600}
        />
      )}
    </div>
  );
};

export default BarRoot;
