import { paidFeatures } from "../../components/shared/utils/constants.consts";
import {
  GlobalSettings,
  PaddleSubscription,
  QueryListState,
} from "../../definitions/global.definition";
import { isProEntitled } from "../../components/shared/utils/premiumFeature.utils";
import { getStorageDataLocal, setStorageDataLocal } from "../chrome.utils";

async function getSubsFromLocal() {
  const subscriptionStorageLocal = (await getStorageDataLocal(
    "subscription"
  )) as {
    subscription: PaddleSubscription;
  };

  const subscriptionStorage = subscriptionStorageLocal;

  // console.log(subscriptionStorage, 'subscriptionStorage');

  return subscriptionStorage?.subscription;
}

export async function isSubscriptionStillValid() {
  const subscription = await getSubsFromLocal();

  // SUB-19 (owner decision: PRO-until-period-end): route the content paygate
  // through the SAME canonical predicate the popup uses (classifySubscription /
  // isProEntitled) so the two layers can no longer disagree. Previously this
  // gated on `isActive` + a future `currentPeriodEnd` only, while the popup
  // required Paddle + active + not-canceled — so a canceled-but-in-period
  // subscriber got PRO on the page but a locked popup, and a non-Paddle
  // `isActive` record leaked PRO content-side. `isProEntitled` now grants a
  // canceled Paddle subscriber PRO until their period ends (and an in-period
  // trial), and locks the non-Paddle/non-trial anomalies the popup already
  // locked. The end-of-day period tolerance is preserved by `isWithinValidPeriod`.
  const isStillValid = isProEntitled(subscription);

  await setStorageDataLocal({ isSubscriptionStillValid: isStillValid });

  return isStillValid;
}

export async function globalSettingsFreemiumConverter(
  globalSettings: GlobalSettings
) {
  const isActive = await isSubscriptionStillValid();

  // TRANSIENT highlight copy: content.ts reads this to drive highlighting and
  // never writes it back to chrome.storage. Safe to cap EVERY list here so no
  // runtime path (now or future) can surface uncapped PRO data — see SUB-21.
  const result = isActive
    ? globalSettings
    : mapFreeGlobalSettings(globalSettings, { capAllLists: true });

  return result;
}

// SUB-06 / SUB-23: the dead `globalSettingsFreemiumConverterMessaging` was
// removed here. It gated the full PRO settings payload on raw
// `subscription?.isActive` alone (ignoring isCanceled/isPaddle/expiry — the
// SUB-05/SUB-19 fail-open shape) but had ZERO call sites (only its own test
// imported it). Rather than leave a latent fail-open trap that a future caller
// could wire to the popup→content path its name implied, it is deleted. The
// live converter (`globalSettingsFreemiumConverter`, above) correctly routes
// through `isSubscriptionStillValid()`.

// Tier 1 Cmd+F takeover paywalls. We *don't* hide the All-tabs / regex /
// fuzzy entry-point chips from free users anymore — they render in a
// locked state inside the bar (see Modifiers / BarRoot) so users can see
// what PRO unlocks. The paygate's job is therefore narrower: respect the
// user's stored preferences for *visibility*, but force the underlying
// PRO functionality OFF so a stored isOn from a prior PRO/trial session
// can't bleed power-user matchers into the free tier.
function clampCmdFTakeoverFree(
  cmdF: NonNullable<GlobalSettings["cmdFTakeover"]>
): NonNullable<GlobalSettings["cmdFTakeover"]> {
  return {
    ...cmdF,
    // Recent-terms dropdown — quality-of-life, only matters with repeat
    // use. No good "locked" surface to dangle, so stay clamped.
    searchHistory: { ...cmdF.searchHistory, isOn: false },
    // Snippets panel — clamp to the basic stripe layout. Same logic as
    // searchHistory: the value is the data, not the affordance.
    layout: cmdF.layout === "stripe-with-snippets" ? "stripe" : cmdF.layout,
    // Power-user modifiers — force isOn off so a lapsed-PRO profile can't
    // run the matcher in PRO mode on free. Visibility is *not* clamped:
    // whatever the user has stored is what the bar renders (which, for
    // visible chips, will be the locked treatment).
    modifiers: {
      ...cmdF.modifiers,
      regex: { ...cmdF.modifiers.regex, isOn: false },
      fuzzy: { ...cmdF.modifiers.fuzzy, isOn: false },
    },
  };
}

export function mapFreeGlobalSettings(
  globalSettings: GlobalSettings,
  options?: { capAllLists?: boolean }
) {
  // Guard against corrupted/partial storage shapes — older versions or
  // botched migrations can leave any of these fields undefined. Bailing
  // here would take down the content script's onStart path entirely.
  //
  // Free item-cap. selectedList.itemList is ALWAYS capped — that is the
  // reachable enforcement surface (every highlighter reads selectedList) and
  // the truncation is recoverable because queryList[] (the source of truth
  // setSelectQuertList re-hydrates selectedList from) is left intact here.
  //
  // queryList[] is capped ONLY when capAllLists is set (SUB-21). This flag is
  // true ONLY on the TRANSIENT runtime/broadcast converters in this file
  // (globalSettingsFreemiumConverter / ...Messaging), which feed the content
  // script's highlight projection and are NEVER written back to chrome.storage.
  // It defaults to false so the PERSISTED popup-save path
  // (globalSettingsPopupInterceptor → saveGlobalSettings → setStorageDataLocal)
  // passes queryList[] through UNTOUCHED — capping it there would permanently
  // truncate every saved list on each free-user save (a data-loss regression),
  // while protecting a leak no runtime reader of queryList[].itemList exists for.
  const capAllLists = options?.capAllLists ?? false;
  const FREE_ITEM_CAP = 5;
  const capItemList = (itemList: QueryListState["selectedList"]["itemList"]) => {
    const capped = (itemList ?? []).slice(0, FREE_ITEM_CAP);
    // SUB-20 (owner decision: regex is PRO-only). On the TRANSIENT highlight
    // projection ONLY (capAllLists), force every item's `isRegexp` off so a free
    // user's saved regex query highlights LITERALLY — closing the leak where
    // content.highlight (`item.isRegexp`) ran the PRO matcher regardless of tier.
    // The PERSISTED popup-save path (capAllLists:false) keeps `isRegexp` INTACT:
    // clamping it there would permanently strip the flag on every free save (the
    // SUB-21 data-loss trap), and the flag must survive for restore-on-upgrade.
    // The popup's RegExp control renders locked via the entitlement gate
    // independently of the stored flag.
    return capAllLists
      ? capped.map((item) => ({ ...item, isRegexp: false }))
      : capped;
  };

  const existingItemList =
    globalSettings.queryListState?.selectedList?.itemList ?? [];

  const queryListState: QueryListState = {
    ...(globalSettings.queryListState ?? {} as QueryListState),
    selectedList: {
      ...(globalSettings.queryListState?.selectedList ?? {} as QueryListState["selectedList"]),
      itemList: capItemList(existingItemList),
    },
    queryList: (globalSettings.queryListState?.queryList ?? []).map((list) =>
      capAllLists
        ? { ...list, itemList: capItemList(list?.itemList) }
        : list
    ),
  };

  const cmdFTakeover = globalSettings.cmdFTakeover
    ? clampCmdFTakeoverFree(globalSettings.cmdFTakeover)
    : globalSettings.cmdFTakeover;

  return {
    ...globalSettings,
    ...paidFeatures.globalSettings,
    queryListState: queryListState,
    cmdFTakeover,
  };
}
