import React from "react";
import { CmdFTakeoverSettings } from "../../../../definitions/global.definition";
import { PremiumFeatureAccessState } from "../../../../components/shared/utils/premiumFeature.utils";
import Tooltip from "./Tooltip";

export type ModifierKey = keyof CmdFTakeoverSettings["modifiers"];

const LABEL: Record<ModifierKey, string> = {
  caseSens: "Aa",
  wholeWord: "W",
  diacriticSens: "◌̇",
  regex: ".*",
  fuzzy: "~",
};

const TITLE: Record<ModifierKey, string> = {
  caseSens: "Match case",
  wholeWord: "Whole word",
  diacriticSens: "Match diacritics",
  regex: "Regular expression",
  fuzzy: "Fuzzy match",
};

const HINT: Record<ModifierKey, string> = {
  caseSens: "Apple ≠ apple. Off matches both.",
  wholeWord: "Skips matches inside other words — “cat” won’t match “category”.",
  diacriticSens: "café ≠ cafe. Off treats accents as the base letter.",
  regex: "Pattern syntax: .*  [a-z]+  ^foo$  (\\bword\\b).",
  fuzzy: "Typo-tolerant per word — “recieve” finds “receive”. Won’t match substrings.",
};

export interface ModifiersProps {
  modifiers: CmdFTakeoverSettings["modifiers"];
  onToggle: (key: ModifierKey) => void;
  accessState?: PremiumFeatureAccessState;
  // Fired when a free user clicks a locked PRO modifier. The bar uses this
  // to surface an "upgrade" hint toast — see BarRoot. If omitted, locked
  // clicks no-op silently (used in older tests that don't care).
  onLockedPro?: (key: ModifierKey) => void;
}

const ORDER: ModifierKey[] = ["caseSens", "wholeWord", "diacriticSens", "regex", "fuzzy"];

const Modifiers: React.FC<ModifiersProps> = ({
  modifiers,
  onToggle,
  accessState,
  onLockedPro,
}) => {
  const visible = ORDER.filter((k) => modifiers[k]?.visible);
  const isTrial = accessState === "trial";
  const isFree = accessState === "free";
  // Paid users have already upgraded — they don't need a "🔐PRO" reminder on
  // every PRO modifier. Free still gets the lock (upgrade nudge), trial still
  // gets ✨TRIAL (finite window reminder). Paid: silent.
  const isPaid = !isTrial && !isFree;
  return (
    <div className="modifiers" role="toolbar" aria-label="Search modifiers">
      {visible.map((k) => {
        const isPro = k === "fuzzy" || k === "regex";
        const isLocked = isPro && isFree;
        const proShortcut =
          isPro && !isPaid ? (isTrial ? "✨TRIAL" : "🔐PRO") : undefined;
        const proAriaSuffix =
          isPro && !isPaid
            ? isTrial
              ? " (PRO feature, included in trial)"
              : " (PRO feature, locked — upgrade to use)"
            : "";
        const className =
          "mod" +
          (modifiers[k].isOn && !isLocked ? " on" : "") +
          (isPro && isTrial ? " trial" : "") +
          (isLocked ? " locked" : "");
        return (
          <Tooltip key={k} label={TITLE[k]} shortcut={proShortcut} hint={HINT[k]}>
            <button
              type="button"
              className={className}
              aria-pressed={isLocked ? false : modifiers[k].isOn}
              aria-disabled={isLocked || undefined}
              aria-label={`${TITLE[k]}${proAriaSuffix}`}
              onClick={() => (isLocked ? onLockedPro?.(k) : onToggle(k))}
            >
              {LABEL[k]}
            </button>
          </Tooltip>
        );
      })}
    </div>
  );
};

export default Modifiers;
