// Detect whether the user is on a Mac so popup labels and Kbd glyphs can
// show ⌘ on macOS and Ctrl elsewhere. Prefer the modern userAgentData
// API; fall back to navigator.platform (deprecated but still populated).
// SSR-safe: returns false when navigator is undefined.

const isMac = (): boolean => {
  if (typeof navigator === "undefined") return false;
  const uaData: any = (navigator as any).userAgentData;
  if (uaData?.platform) {
    return String(uaData.platform).toLowerCase().includes("mac");
  }
  const platform = (navigator as any).platform || navigator.userAgent || "";
  return /mac|iphone|ipad|ipod/i.test(platform);
};

export const isMacPlatform = isMac;

export const cmdOrCtrl = (): "⌘" | "Ctrl" => (isMac() ? "⌘" : "Ctrl");

export const cmdOrCtrlLabel = (key: string): string =>
  isMac() ? `⌘${key}` : `Ctrl+${key}`;
