import { GlobalSettings } from "../definitions/global.definition";
import { cmdFTakeoverDefaults } from "../components/shared/utils/constants.consts";
import { getStorageDataLocal } from "./chrome.utils";
import { invokeBehaviour, receiveMessageFromPopup } from "./content.utils";
import {
  currentGlobalSettings,
  hasGlobalSettingsChanged,
  setGlobalSettings,
} from "./features/content.globalSettingsState";
import { globalSettingsFreemiumConverter } from "./features/content.paygate";
import { seedMonotonicClock } from "../components/shared/utils/monotonicClock.utils";
import { bootMinimal as cmdFBootMinimal } from "./features/cmdFTakeover";

// Unit tests import this module for its exported helpers (reconcileGlobalSettings,
// registerStorageReconcileListener, onStart) and must NOT trigger the full
// content-script boot, which reaches into feature modules that expect a live
// page. react-scripts/jest set NODE_ENV="test"; the real extension build uses
// "production", so this guard is a no-op in production.
const isTestEnv =
  typeof process !== "undefined" && process.env?.NODE_ENV === "test";

// Synchronous: install the Cmd+F intercept before awaiting chrome.storage.
// This lets a Cmd+F press during early page load reach Highlighty instead
// of falling through to native Find. Reads on/off + blacklist from a
// localStorage mirror written by every settings persist.
if (!isTestEnv) {
  cmdFBootMinimal();
}

const contentMessageRunner = () =>
  (chrome ?? browser).runtime.onMessage.addListener(receiveMessageFromPopup);

// Older versions and partial-storage upgrades can leave branches of the
// queryListState tree undefined. Several feature modules dereference
// `queryListState.selectedList.itemList` without local guards (paygate,
// toast, analytics, searchBySelect). Normalising once at the entry point
// is cheaper than 6 defensive guards.
const normalizeGlobalSettings = (raw: GlobalSettings): GlobalSettings => {
  const queryListState =
    raw.queryListState ?? ({} as GlobalSettings["queryListState"]);
  const selectedListRaw =
    queryListState.selectedList ??
    ({} as GlobalSettings["queryListState"]["selectedList"]);

  const normalizedSelectedList: GlobalSettings["queryListState"]["selectedList"] = {
    name: selectedListRaw.name ?? "",
    value: selectedListRaw.value ?? "",
    id: selectedListRaw.id ?? "",
    itemList: selectedListRaw.itemList ?? [],
  };

  return {
    ...raw,
    queryListState: {
      ...queryListState,
      selectedList: normalizedSelectedList,
      queryList: queryListState.queryList ?? [],
    },
    cmdFTakeover: raw.cmdFTakeover
      ? {
          ...cmdFTakeoverDefaults,
          ...raw.cmdFTakeover,
          modifiers: {
            ...cmdFTakeoverDefaults.modifiers,
            ...(raw.cmdFTakeover.modifiers ?? {}),
          },
          searchHistory: {
            ...cmdFTakeoverDefaults.searchHistory,
            ...(raw.cmdFTakeover.searchHistory ?? {}),
          },
          hintShown: raw.cmdFTakeover.hintShown ?? {},
          autoDisabledDomains: raw.cmdFTakeover.autoDisabledDomains ?? [],
          failureCounts: raw.cmdFTakeover.failureCounts ?? {},
          lastQueryPerSite: raw.cmdFTakeover.lastQueryPerSite ?? {},
          history: raw.cmdFTakeover.history ?? [],
        }
      : cmdFTakeoverDefaults,
    // Form-field highlighting: introduced in 2.4.6. Existing users
    // upgrading from <= 2.4.5 have no `formFieldHighlighting` key in
    // storage — backfill with the on-by-default shape so the feature
    // activates on first content-script boot after upgrade. Users who
    // explicitly disabled it (popup toggle off) keep their stored value
    // unchanged because the object exists.
    formFieldHighlighting: raw.formFieldHighlighting ?? {
      isOn: true,
      textareas: true,
      textInputs: true,
    },
  };
};

// MSG-11: the SINGLE apply pipeline for an incoming settings blob, shared by
// the boot path, the popup broadcast, and the storage.onChanged reconcile
// below. Given a RAW stored blob it runs the exact same transform the boot
// uses — normalizeGlobalSettings → globalSettingsFreemiumConverter (clamp for
// free/lapsed users) — then gates the (re-)apply on hasGlobalSettingsChanged.
//
// The gate does double duty:
//   1. It skips redundant re-highlights (no flash) when nothing user-visible
//      changed.
//   2. It prevents a SELF-WRITE LOOP. This tab's OWN persists write the RAW
//      blob (persistGlobalSettingsDelta, SUB-27). onChanged fires →
//      reconcileGlobalSettings(raw) → the SAME converter re-clamps to the
//      SAME projection currentGlobalSettings already holds → JSON-equal →
//      hasGlobalSettingsChanged returns false → no invokeBehaviour, no flash.
//      (Running the same converter the boot ran is what makes the outputs
//      match for the tab's own write.)
export async function reconcileGlobalSettings(rawBlob: GlobalSettings) {
  if (!rawBlob) return;

  const normalized = normalizeGlobalSettings(rawBlob);
  const globalSettings = await globalSettingsFreemiumConverter(normalized);

  // hasGlobalSettingsChanged compares the incoming (clamped) projection to the
  // cached one and, when they differ, adopts it as the new currentGlobalSettings
  // as a side effect. Equal → no-op (loop/flash guard above).
  if (!hasGlobalSettingsChanged(globalSettings)) return;

  invokeBehaviour(currentGlobalSettings);
}

// MSG-11: content-side chrome.storage.onChanged reconcile. Content registered
// onMessage only AFTER two boot awaits and had NO storage.onChanged listener
// anywhere, so a popup settings broadcast that landed during the boot window
// hit a tab with no listener ("Receiving end does not exist", swallowed by the
// sender) and the tab then stayed permanently stale — there was no route to
// catch up. This listener is the missing reconcile route: any future write to
// globalSettings.local re-runs the shared apply pipeline. It's a safety net for
// writes that happen AFTER boot; the boot-window race itself is closed by the
// post-boot re-read in onStart.
export function registerStorageReconcileListener() {
  const storageApi =
    typeof chrome !== "undefined" && chrome.storage
      ? chrome.storage
      : typeof browser !== "undefined" && (browser as any).storage
      ? (browser as any).storage
      : null;

  storageApi?.onChanged?.addListener(
    (changes: { [key: string]: chrome.storage.StorageChange }, areaName: string) => {
      if (areaName !== "local") return;
      const next = changes?.globalSettings?.newValue as
        | GlobalSettings
        | undefined;
      if (!next) return;
      reconcileGlobalSettings(next);
    }
  );
}

export async function onStart() {
  // SUB-09: load the persisted monotonic high-water clock before any
  // entitlement check (the freemium converter below routes through
  // isProEntitled), so a trial that lapsed in real time stays lapsed even if
  // the system clock was rolled back since the last visit.
  await seedMonotonicClock();

  const dataLocal = (await getStorageDataLocal("globalSettings")) as {
    globalSettings: GlobalSettings;
  };

  contentMessageRunner();

  // MSG-11: register the storage.onChanged reconcile so any settings write that
  // lands AFTER this point re-syncs the tab even if its broadcast was missed.
  registerStorageReconcileListener();

  if (dataLocal?.globalSettings) {
    const normalized = normalizeGlobalSettings(dataLocal.globalSettings);
    const globalSettings = await globalSettingsFreemiumConverter(normalized);

    setGlobalSettings(globalSettings);

    invokeBehaviour(currentGlobalSettings);
  }

  // MSG-11: close the boot-window gap. A settings write can commit DURING the
  // awaits above (seedMonotonicClock / getStorageDataLocal / converter) —
  // before the onChanged listener existed — so its onChanged fired into the
  // void and the initial read returned the OLD blob. Re-read once, now that the
  // listener is armed, and reconcile. This is a no-op via hasGlobalSettingsChanged
  // when nothing changed (the common case), and only re-applies when the
  // stored blob has moved on since the initial read.
  const fresh = (await getStorageDataLocal("globalSettings")) as
    | { globalSettings?: GlobalSettings }
    | undefined;
  if (fresh?.globalSettings) {
    await reconcileGlobalSettings(fresh.globalSettings);
  }
}

// Auto-run the content-script boot in the real extension. Skipped under jest
// (NODE_ENV="test") so unit tests can import the exported helpers in isolation.
if (!isTestEnv) {
  onStart();
}
