// Shared imperative drag helper. Mounts mousedown/mousemove/mouseup
// listeners that translate a host element via inline style. Designed to
// work across Shadow DOM boundaries — uses `matches`/`closest` guards
// for ignored targets and listens on `document` for move/up so the
// gesture survives the cursor leaving the host element.

export interface MakeDraggableOptions {
  /** Called on mouseup ONLY if the gesture exceeded the drag threshold. */
  onPersist?: (position: { top: number; left: number }) => void;
  /** If provided, clamps the new top/left into these bounds (inclusive). */
  getClampBounds?: () => {
    minTop: number;
    maxTop: number;
    minLeft: number;
    maxLeft: number;
  };
  /** Minimum pixel displacement (|dx|+|dy|) before treating as a drag. Default 4. */
  dragThresholdPx?: number;
  /**
   * Selectors whose mousedown is ignored so descendant interactive
   * elements (buttons, inputs, switches) aren't preempted by drag.
   * Default: ["button", "input", "textarea", "[role='switch']"].
   */
  ignoreSelectors?: string[];
}

const DEFAULT_IGNORE = ["button", "input", "textarea", "[role='switch']"];

// Module-level registry of pending click-swallow listeners. Any new drag
// gesture clears all stale swallows so one gesture can never accidentally
// suppress a click intended for a different draggable.
const pendingSwallows = new Set<EventListener>();

const clearPendingSwallows = () => {
  for (const fn of pendingSwallows) {
    document.removeEventListener("click", fn, true);
  }
  pendingSwallows.clear();
};

// SNP-09: while a drag is live, an <iframe> the cursor passes over consumes the
// document-level mousemove/mouseup (the events fire inside the iframe's own
// document), so onUp never runs and the panel freezes then ghost-drags. For the
// duration of a gesture we neutralize pointer-events on every iframe so the
// cursor passes through to the top document; the values are restored on mouseup
// (or on destroy() if the gesture is torn down first).
//
// This state is MODULE-LEVEL — like pendingSwallows above — because iframes are
// a document-global resource and makeDraggable has several live instances per
// page (the minimap mounts two handles; the snippets panel one). Per-instance
// state let a cross-instance re-arm after a lost mouseup bake "none" in as the
// saved "original", leaving every iframe permanently click-through until reload.
// The `if (suppressedEmbeds) return;` guard then covers same- AND cross-instance
// re-arms uniformly: a still-live suppression is never re-snapshotted.
// SNP-12: <object> and <embed> host nested browsing contexts / plugins that
// swallow the gesture's document-level mouseup exactly like <iframe>, so they
// must be neutralized too. And we preserve the exact value AND `!important`
// priority of any pre-existing inline pointer-events: (a) setting our "none"
// with `!important` makes it actually win over a page's `pointer-events: x
// !important` (a plain value would lose to it), and (b) saving/restoring the
// priority means a page's original `!important` is put back intact.
type SuppressedEmbed = { el: HTMLElement; value: string; priority: string };
let suppressedEmbeds: SuppressedEmbed[] | null = null;
const suppressIframePointerEvents = () => {
  if (suppressedEmbeds) return;
  const list: SuppressedEmbed[] = [];
  document.querySelectorAll("iframe, object, embed").forEach((node) => {
    const el = node as HTMLElement;
    list.push({
      el,
      value: el.style.getPropertyValue("pointer-events"),
      priority: el.style.getPropertyPriority("pointer-events"),
    });
    el.style.setProperty("pointer-events", "none", "important");
  });
  suppressedEmbeds = list;
};
const restoreIframePointerEvents = () => {
  if (!suppressedEmbeds) return;
  for (const { el, value, priority } of suppressedEmbeds) {
    if (value) {
      el.style.setProperty("pointer-events", value, priority);
    } else {
      // No pre-existing inline value → remove ours entirely (mirrors the old
      // `= ""` behaviour, which cleared the property).
      el.style.removeProperty("pointer-events");
    }
  }
  suppressedEmbeds = null;
};

export const makeDraggable = (
  host: HTMLElement,
  handle: HTMLElement,
  options: MakeDraggableOptions = {}
): { destroy: () => void } => {
  const threshold = options.dragThresholdPx ?? 4;
  const ignoreSelectors = options.ignoreSelectors ?? DEFAULT_IGNORE;
  handle.style.cursor = "grab";

  let activeOnMove: ((ev: MouseEvent) => void) | null = null;
  let activeOnUp: ((ev: MouseEvent) => void) | null = null;
  // Track this instance's swallow so destroy() can clean it up.
  let mySwallow: EventListener | null = null;

  const isIgnored = (target: EventTarget | null): boolean => {
    if (!(target instanceof Element)) return false;
    return ignoreSelectors.some((sel) => {
      try {
        return target.matches(sel) || !!target.closest(sel);
      } catch {
        return false;
      }
    });
  };

  const onMouseDown = (e: MouseEvent) => {
    // SNP-06: only the primary (left) button starts a drag. Without this gate a
    // right/middle-button press on the handle armed the full gesture
    // (preventDefault + document mousemove/mouseup + swallow), so a right-drag
    // moved the panel and — on macOS, where the context menu opens on mousedown
    // and the page never sees the matching mouseup — left the gesture armed to
    // ghost-drag the panel to the cursor and swallow the next page click.
    if (e.button !== 0) return;
    if (isIgnored(e.target)) return;
    // SNP-13: tear down any still-live gesture from THIS instance before arming
    // a new one. If gesture 1's mouseup was lost (released outside the window, or
    // over a swallowing embed), its onMove/onUp are still on `document`; arming a
    // second pair without removing them leaves TWO — and gesture 2's clean mouseup
    // would remove only its own, orphaning gesture 1 (a listener leak + a
    // ghost-drag the second gesture can't clear). Restoring iframe pointer-events
    // here too means the fresh suppression re-snapshots the true original, not the
    // already-"none" left by the lost gesture. `arming idempotent per instance`.
    if (activeOnMove) document.removeEventListener("mousemove", activeOnMove);
    if (activeOnUp) document.removeEventListener("mouseup", activeOnUp);
    activeOnMove = null;
    activeOnUp = null;
    restoreIframePointerEvents();
    // Any new drag gesture cancels all prior unconsumed swallow listeners.
    // This handles the case where a drag ended but no click event followed
    // (e.g. the user tabbed away, or a test completed without dispatching click).
    clearPendingSwallows();
    mySwallow = null;
    e.preventDefault();
    const startX = e.clientX;
    const startY = e.clientY;
    const rect = host.getBoundingClientRect();
    const origX = rect.left;
    const origY = rect.top;
    handle.style.cursor = "grabbing";
    let didMove = false;

    const onMove = (ev: MouseEvent) => {
      // SNP-13: if the primary button is no longer held, the mouseup was lost
      // (button released OUTSIDE the browser window, or over an embed that
      // swallowed it) — the browser reports `buttons === 0` on the next move.
      // Treat it as an implicit mouseup and end the gesture, so the panel can't
      // ghost-follow the button-less cursor until the next click. A real drag
      // always reports the primary button held (buttons & 1).
      if (ev.buttons === 0) {
        onUp();
        return;
      }
      const dx = ev.clientX - startX;
      const dy = ev.clientY - startY;
      if (!didMove && Math.abs(dx) + Math.abs(dy) < threshold) return;
      didMove = true;
      let nextLeft = origX + dx;
      let nextTop = origY + dy;
      const bounds = options.getClampBounds?.();
      if (bounds) {
        nextLeft = Math.min(Math.max(nextLeft, bounds.minLeft), bounds.maxLeft);
        nextTop = Math.min(Math.max(nextTop, bounds.minTop), bounds.maxTop);
      }
      host.style.left = nextLeft + "px";
      host.style.top = nextTop + "px";
      host.style.right = "auto";
    };

    const onUp = () => {
      handle.style.cursor = "grab";
      restoreIframePointerEvents();
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
      activeOnMove = null;
      activeOnUp = null;
      if (!didMove) return;
      const rect2 = host.getBoundingClientRect();
      options.onPersist?.({
        top: Math.round(rect2.top),
        left: Math.round(rect2.left),
      });
      // Swallow the trailing click that follows a real drag so the host
      // (or its descendants) don't fire onClick handlers as if the user
      // had just clicked.
      //
      // SNP-02: time-box the swallow. The trailing `click` only fires when
      // mousedown and mouseup share a common-ancestor target. When the panel
      // is clamped, the cursor can outrun the pinned handle and release over
      // a page element, so NO click follows the drag — leaving the swallow
      // armed to eat the user's next unrelated page click. The next drag's
      // mousedown (`clearPendingSwallows`) was the only other clearer. We now
      // auto-remove on the next macrotask so a missing trailing click can't
      // let the swallow linger; a real trailing click fires synchronously
      // before this timer and is still consumed.
      let swallowTimer: ReturnType<typeof setTimeout> | null = null;
      const removeSwallow = (swallow: EventListener) => {
        document.removeEventListener("click", swallow, true);
        pendingSwallows.delete(swallow);
        if (swallowTimer !== null) {
          clearTimeout(swallowTimer);
          swallowTimer = null;
        }
        if (mySwallow === swallow) mySwallow = null;
      };
      const swallow: EventListener = (clickEv: Event) => {
        clickEv.stopImmediatePropagation();
        clickEv.preventDefault();
        removeSwallow(swallow);
      };
      mySwallow = swallow;
      pendingSwallows.add(swallow);
      document.addEventListener("click", swallow, true);
      swallowTimer = setTimeout(() => {
        swallowTimer = null;
        removeSwallow(swallow);
      }, 0);
    };

    activeOnMove = onMove;
    activeOnUp = onUp;
    suppressIframePointerEvents();
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup", onUp);
  };

  handle.addEventListener("mousedown", onMouseDown);

  return {
    destroy: () => {
      handle.removeEventListener("mousedown", onMouseDown);
      // Restore any iframes neutralized by an in-flight gesture (SNP-09) so a
      // mid-drag unmount doesn't leave page iframes permanently click-through.
      restoreIframePointerEvents();
      if (activeOnMove) document.removeEventListener("mousemove", activeOnMove);
      if (activeOnUp) document.removeEventListener("mouseup", activeOnUp);
      if (mySwallow) {
        document.removeEventListener("click", mySwallow, true);
        pendingSwallows.delete(mySwallow);
        mySwallow = null;
      }
    },
  };
};
