import {
  GlobalSettings,
  NavigationBar,
  QueryItem
} from '../../definitions/global.definition';
import { dataHility, disableColorsState, hilityTag } from '../content.consts';
import { addPostHighlightListener } from './postHighlightHooks';
import { isEditableEventTarget } from './utils/editable.utils';

// let isAlreadyRunning = false;
let currentNavIndex = 0;
let elements = [] as HTMLElement[];
let currentWordId: string;

let navigationListener = null as unknown as AbortController;

const navigationItemClass = 'hility-navigation';
const navigationItemCssId = 'hility-navigation-style';

let navigationState: NavigationBar;

// Latest settings snapshot, captured every time navigation() is called from
// contentFileLogic. The post-highlight subscription below re-runs the arm
// logic with this snapshot once <hility> elements actually exist on the page.
// Without that hook the keyup listener would never arm for users who reload
// a page with navigationBar pre-enabled: contentFileLogic invokes
// navigation() *synchronously*, while mark.js inserts hility elements
// asynchronously — so the !elements.length bail wins on the initial call.
let latestSettingsForRearm: GlobalSettings | null = null;
let postHighlightSubscribed = false;

export function navigation(
  globalSettings: GlobalSettings,
  isObserver?: boolean,
  isMessagingTrigger?: boolean
) {
  latestSettingsForRearm = globalSettings;
  if (!postHighlightSubscribed) {
    postHighlightSubscribed = true;
    addPostHighlightListener(() => {
      // The bus fires *after* a highlight pass settles — elements
      // definitely exist now (or have been removed if all queries were
      // cleared). Re-run with isObserver=false so the arm path is reachable;
      // the function itself is idempotent on a settled listener.
      if (latestSettingsForRearm) {
        runNavigation(latestSettingsForRearm, false, false);
      }
    });
  }
  runNavigation(globalSettings, isObserver, isMessagingTrigger);
}

function runNavigation(
  globalSettings: GlobalSettings,
  isObserver?: boolean,
  isMessagingTrigger?: boolean
) {
  const item = globalSettings.navigationBar?.focusedWord;

  elements = filterHiddenElements(item);

  // NAV-03: filterHiddenElements only resets currentNavIndex on a focused-word
  // change. When the SAME query's match set SHRINKS (a re-highlight removes
  // matches, or the visibility filter drops collapsed ones), the module-level
  // currentNavIndex can be left pointing past the end of the new, shorter
  // `elements`. Left unclamped: the Shift+S/W press path increments/decrements
  // an out-of-range index and navigateElement no-ops on the undefined element
  // (navigation STUCK), and the popup-toggle deref sites throw on undefined.
  // Clamp back to the first match whenever the index falls out of range.
  if (currentNavIndex >= elements.length) currentNavIndex = 0;

  // console.log(elements, 'elements');
  // console.log(currentNavIndex, 'currentNavIndex');

  if (!elements?.length || isObserver) return;

  const isNavigation = globalSettings.navigationBar.isOn;

  if (!navigationState) setNavigationState(globalSettings.navigationBar);

  const down = globalSettings.navigationBar.assignedButtons.downButtonKey;
  const up = globalSettings.navigationBar.assignedButtons.upButtonKey;

  // console.log('navigation init');

  const navigationPress = (e: KeyboardEvent) => {
    // See editable.utils.ts: navigation defaults to S/W which both
    // appear in everyday typing, so unguarded the user would jump to
    // the next match every time they typed those letters in a search
    // box.
    if (isEditableEventTarget(e)) return;

    if (e.key === down && e.shiftKey && isNavigation) {
      // console.log(down, 'down');
      const isLastElement = elements.length - 1 === currentNavIndex;
      isLastElement ? (currentNavIndex = 0) : (currentNavIndex += 1);

      navigateElement(
        elements,
        true,
        isLastElement ? 'uncolorLast' : undefined
      );
    }

    if (e.key === up && e.shiftKey && isNavigation) {
      // console.log(up, 'up');

      const isFirstElement = currentNavIndex === 0;
      isFirstElement
        ? (currentNavIndex = elements.length - 1)
        : (currentNavIndex -= 1);

      navigateElement(
        elements,
        false,
        isFirstElement ? 'uncolorFirst' : undefined
      );
    }
  };

  /// DO NOT INITIATE TWICE THE EVENT LISTENER WHEN POPUP MODIFICATIONS HAPPEN
  if (isMessagingTrigger) {
    if (!isNavigation) {
      removeColor(elements[currentNavIndex]);
      currentNavIndex = 0;
    } else {
      colorCurrentElementOnMessage(elements, currentNavIndex);
    }
  }

  // IF THE BUTTONS ARE CHANGED IN THE POPUP, DESTROY PREVIOUS CONTROLLER, INITIALIZE NEW LISTENER
  if (
    navigationState?.assignedButtons?.downButtonKey !== down ||
    navigationState?.assignedButtons?.upButtonKey !== up
  ) {
    // console.log('re INIT navbuttons');

    onButtonsChanged(globalSettings, navigationPress);
    return;
  }

  if (isNavigation && !navigationListener) {
    generateNavigationCss();
    navigationListener = new AbortController();

    document.addEventListener('keyup', navigationPress, navigationListener);
    // console.log('adding nav listener');

    (elements[0] as HTMLElement).classList.add(navigationItemClass);
  } else if (!isNavigation && navigationListener?.abort) {
    navigationListener.abort();
    navigationListener = null as unknown as AbortController;

    // console.log('abort nav listener');
  }
}

function navigateElement(
  elements: HTMLElement[],
  isDown?: boolean,
  firstOrLast?: 'uncolorLast' | 'uncolorFirst'
) {
  const currentElement = elements[currentNavIndex] as HTMLElement;

  if (!currentElement) return;

  const previousElement = isDown
    ? (elements[currentNavIndex - 1] as HTMLElement)
    : (elements[currentNavIndex + 1] as HTMLElement);

  currentElement.classList.add(navigationItemClass);

  if (previousElement) {
    removeColor(previousElement);
  }

  if (firstOrLast === 'uncolorFirst') {
    removeColor(elements[0]);
  }
  if (firstOrLast === 'uncolorLast') removeColor(elements[elements.length - 1]);

  currentElement.scrollIntoView({
    behavior: 'smooth',
    block: 'center',
    inline: 'center',
  });
}

function filterHiddenElements(item: QueryItem) {
  // PAGE LIKE LINKEDIN HAVE HIDDEN ELEMENTS

  if (item?.id !== currentWordId) {
    currentNavIndex = 0;
    currentWordId = item?.id ?? '';
  }

  const foundElements = item?.id
    ? document.querySelectorAll(`[${dataHility}='${item?.id}']`)
    : document.getElementsByTagName(hilityTag);

  // console.log(foundElements, 'foundElements');

  const elements = Array.from(foundElements)?.filter(
    (element: any) =>
      element?.checkVisibility
        ? // VIS-03: mirror the chip/saved-match filter (isHilityCounted): reject
          // display:none / visibility:hidden / content-visibility:hidden, but
          // KEEP opacity:0 (Chrome-Find parity, and what the chip counts).
          // Passing checkOpacity:true here dropped opacity:0 matches the chip
          // still counted, so the chip said N while Shift+S/W stepped N-1.
          // CMF-37: contentVisibilityAuto is FALSE (matching isHilityCounted /
          // isElementInvisible) so a saved highlight inside off-screen
          // content-visibility:auto is navigable too — else the chip counts it
          // (N) but Shift+S/W steps N-1 (the same VIS-03 divergence). cv:HIDDEN
          // / closed <details> still return checkVisibility false regardless.
          element?.checkVisibility({
            contentVisibilityAuto: false,
            visibilityProperty: true, // honor CSS visibility:hidden/collapse
          })
        : true // if check visibility doesnt exist, dont filter the hidden elements
  ) as unknown as HTMLElement[];

  // elements.map((hilityItem, i) =>
  //   !hilityItem.id.includes('hility-nav')
  //     ? (hilityItem.id = `hility-nav-${i.toString()}`)
  //     : hilityItem
  // );

  return elements;
}

function colorCurrentElementOnMessage(
  elements: HTMLElement[],
  currentNavIndex: number
) {
  const currentElement = elements[currentNavIndex] as HTMLElement;

  // NAV-03: a stale out-of-range currentNavIndex (the match set shrank since
  // the last navigate) leaves currentElement undefined; guard the deref so the
  // popup-toggle message handler can't throw.
  if (!currentElement) return;

  currentElement.classList.add(navigationItemClass);
}
function removeColor(element: HTMLElement) {
  // NAV-03: same defensive guard for the toggle-off path
  // (removeColor(elements[currentNavIndex]) with a stale index).
  if (!element) return;
  element.classList.remove(navigationItemClass);
}

function setNavigationState(navigationBar: NavigationBar) {
  navigationState = navigationBar;
}

function onButtonsChanged(
  globalSettings: GlobalSettings,
  navigationPress: (e: KeyboardEvent) => void
) {
  navigationListener?.abort();
  navigationListener = null as unknown as AbortController;
  navigationListener = new AbortController();

  document.addEventListener('keyup', navigationPress, navigationListener);
  setNavigationState(globalSettings.navigationBar);

  // console.log('updated buttons');
}

function generateNavigationCss() {
  const doesExist = document.getElementById(navigationItemCssId);

  if (doesExist) return;

  // NAV-04: the focused-match "red" rule must OUT-SPECIFY the per-query
  // highlight rule so its !important actually wins the cascade. The per-query
  // sheet (content.highlight.ts) styles each mark with
  // `hility[data-hility="<id>"] { background: <color> !important; }`
  // (specificity 0,1,1). A bare `.hility-navigation` is only (0,1,0) — so with
  // both !important the higher-specificity per-query rule won and the current
  // match never turned red for background-decoration queries. Qualify the class
  // by the tag + attribute (`hility[data-hility].hility-navigation` = 0,2,1) so
  // it unambiguously beats 0,1,1. Use the `background` shorthand so it fully
  // overrides the per-query `background: <color>` shorthand (non-background
  // decoration types set `background: transparent` non-important, so this
  // !important still wins and paints them red too — no regression).
  const addedStyle = `
  ${hilityTag}[${dataHility}].${navigationItemClass} {
  background: red !important;
}`;

  const stylesheet = document.createElement('style');
  stylesheet.setAttribute('type', 'text/css');
  stylesheet.setAttribute('id', navigationItemCssId);
  stylesheet.textContent = addedStyle;

  // NAV-02: the on-page highlight sheets are re-queried live at Shift+D press
  // time, but this red-paint sheet is not. If the page is currently in a
  // deselected state (highlights suppressed via Shift+D, isStyleDisabled true)
  // and navigation injects its sheet afterward, the new sheet would be created
  // ENABLED — the focused-match red shows while every other highlight stays
  // hidden. Inherit the current deselect state so a sheet injected during a
  // deselect starts suppressed and re-syncs on the next toggle (mirrors the
  // DSC-01 fix for the [css-hility] sheets).
  (stylesheet as any).disabled = disableColorsState.isStyleDisabled;

  document.head.appendChild(stylesheet);
}

export function disableNavigationCss(isOff: boolean) {
  const navigationCss = document.getElementById(navigationItemCssId);
  // NAV-01: this is called from the Shift+D deselect handler
  // (content.disableColors.ts), which can fire when the navigation feature
  // never injected its stylesheet (feature off, or after cleanupNavigation
  // removed it). Without this guard the assignment dereferenced null and
  // threw inside the keydown handler.
  if (!navigationCss) return;
  (navigationCss as any).disabled = isOff;
}

// switchOffCleanup uses this to fully tear down navigation residue: the
// Shift+S/W listener AND the injected stylesheet that paints the focused
// match red. Resets currentNavIndex too so a re-on starts clean.
export function cleanupNavigation() {
  if (navigationListener?.abort) {
    navigationListener.abort();
    navigationListener = null as unknown as AbortController;
  }
  navigationState = null as unknown as NavigationBar;
  currentNavIndex = 0;
  // Stop the post-highlight rearm path from resurrecting the listener after
  // the extension has been toggled off. The bus subscription itself stays
  // installed (the bus tolerates idempotent listeners), but with no settings
  // to act on it becomes a no-op until navigation() is called again.
  latestSettingsForRearm = null;
  document.getElementById(navigationItemCssId)?.remove();
}
