import { contentFileLogic } from "../content.utils";
import { currentGlobalSettings } from "./content.globalSettingsState";
import { hilityTag, blacklistObserverSites } from "../content.consts";
import { hostMatchesAnyEntry } from "./content.blackWhitelist";

// Constants for better readability
const DEBOUNCE_DELAY = 500;
// HLE-17: cap the trailing debounce so a page that writes class/style
// (both in OBSERVED_ATTRIBUTES) faster than DEBOUNCE_DELAY — animation
// libraries, progress bars, skeleton shimmers — can't reset the trailing
// timer forever and starve the re-highlight pass. Mirrors CMF-49's cap in
// the Cmd+F cached finder: max(1500, debounce*3).
const MUTATION_MAX_WAIT_DELAY = Math.max(1500, DEBOUNCE_DELAY * 3);
const MINIMAP_HOST_ID = "highlighty-minimap-host";
const HIGHLIGHTY_SCROLLBAR_HOST_CLASS = "highlighty-scrollbar-highlighter";
const HIGHLIGHTY_SCROLLBAR_MARKER_CLASS = "highlighty-scrollbar-marker";
const HIGHLIGHTY_TOAST_TAGS = new Set(["hility-success", "hility-error"]);
const OBSERVED_ATTRIBUTES = [
  "class",
  "style",
  "hidden",
  "open",
  "aria-hidden",
  "aria-expanded",
] as const;
const HIGHLIGHTY_MANAGED_SELECTOR = [
  `#${MINIMAP_HOST_ID}`,
  `.${HIGHLIGHTY_SCROLLBAR_HOST_CLASS}`,
  `.${HIGHLIGHTY_SCROLLBAR_MARKER_CLASS}`,
  hilityTag,
  "hility-success",
  "hility-error",
].join(", ");

const OBSERVER_CONFIG: MutationObserverInit = {
  childList: true,
  attributes: true,
  attributeFilter: [...OBSERVED_ATTRIBUTES],
  subtree: true,
};

let observer: MutationObserver | null = null;
let mutationTimeoutId: ReturnType<typeof setTimeout> | null = null;
// HLE-17: armed ONCE per debounce window and never reset by a re-arm, so a
// sustained sub-DEBOUNCE_DELAY mutation storm can't push the pass off forever.
let mutationMaxWaitTimeoutId: ReturnType<typeof setTimeout> | null = null;
let isObserving = false;
let managedMutationSuppressionDepth = 0;
// IFR-01: same-origin iframes whose `load` we've hooked, so a frame that
// (re)loads or navigates later re-arms the observer over its new document.
// Pruned for disconnected frames on each arm and cleared on teardown.
const iframeLoadListened = new Set<HTMLIFrameElement>();

const disconnectObserver = () => {
  // A single MutationObserver instance observes the top body AND every
  // same-origin iframe body; disconnect() detaches all of them at once.
  observer?.disconnect();
  isObserving = false;
};

// Teardown clearer: drops BOTH the trailing debounce and the HLE-17 max-wait
// cap. Used by the real teardown paths (destroyObserverLogic,
// suppressObserverMutations). NOT used by scheduleRehighlight's re-arm — that
// would reset the cap and re-open the starvation window.
const clearTimers = () => {
  if (mutationTimeoutId) {
    clearTimeout(mutationTimeoutId);
    mutationTimeoutId = null;
  }
  // HLE-17: tear down the max-wait cap too, else a pending cap could fire a
  // pass after the observer is destroyed / suppressed.
  if (mutationMaxWaitTimeoutId) {
    clearTimeout(mutationMaxWaitTimeoutId);
    mutationMaxWaitTimeoutId = null;
  }
};

// HLE-17: fire the re-highlight pass, clearing BOTH timers first (whichever
// timer — trailing or max-wait — got here wins and starts a fresh window). A
// schedule that arrives DURING the pass therefore opens a clean window rather
// than extending the old one.
const fireRehighlight = async () => {
  if (mutationTimeoutId) {
    clearTimeout(mutationTimeoutId);
    mutationTimeoutId = null;
  }
  if (mutationMaxWaitTimeoutId) {
    clearTimeout(mutationMaxWaitTimeoutId);
    mutationMaxWaitTimeoutId = null;
  }

  if (
    !currentGlobalSettings?.isExtensionOn ||
    managedMutationSuppressionDepth > 0
  ) {
    return;
  }

  disconnectObserver();

  try {
    await contentFileLogic(currentGlobalSettings, true);
  } finally {
    observerLogic();
  }
};

// Debounced full re-highlight pass shared by the top-document observer, the
// same-origin iframe observers, and iframe `load` events. Disconnects the
// observer for the duration of the pass (so the <hility> marks it inserts —
// including inside iframes — don't re-trigger it) and re-arms afterward.
function scheduleRehighlight() {
  // Trailing debounce: coalesce a normal burst (reset on each event).
  if (mutationTimeoutId) clearTimeout(mutationTimeoutId);
  mutationTimeoutId = setTimeout(fireRehighlight, DEBOUNCE_DELAY);
  // HLE-17: max-wait — armed ONCE per window and never reset here, so a
  // sustained class/style storm that keeps re-arming the trailing timer can't
  // starve the pass forever. Whichever timer fires first runs fireRehighlight,
  // which clears both and starts a fresh window on the next event.
  if (!mutationMaxWaitTimeoutId) {
    mutationMaxWaitTimeoutId = setTimeout(fireRehighlight, MUTATION_MAX_WAIT_DELAY);
  }
}

export const suppressObserverMutations = () => {
  clearTimers();
  managedMutationSuppressionDepth += 1;

  return () => {
    managedMutationSuppressionDepth = Math.max(
      0,
      managedMutationSuppressionDepth - 1
    );
  };
};

const isHighlightyManagedElement = (element: Element | null): boolean => {
  if (!element) return false;

  const tagName = element.tagName.toLowerCase();

  return (
    tagName === hilityTag ||
    HIGHLIGHTY_TOAST_TAGS.has(tagName) ||
    element.id === MINIMAP_HOST_ID ||
    element.classList.contains(HIGHLIGHTY_SCROLLBAR_HOST_CLASS) ||
    element.classList.contains(HIGHLIGHTY_SCROLLBAR_MARKER_CLASS) ||
    Boolean(element.closest(HIGHLIGHTY_MANAGED_SELECTOR))
  );
};

const isHighlightyManagedNode = (node: Node | null): boolean => {
  if (!node) return false;

  if (node instanceof Element) {
    return isHighlightyManagedElement(node);
  }

  return isHighlightyManagedElement(node.parentElement);
};

const isRelevantMutation = (mutation: MutationRecord) => {
  if (mutation.type === "attributes") {
    return !isHighlightyManagedElement(mutation.target as Element | null);
  }

  const changedNodes = [...mutation.addedNodes, ...mutation.removedNodes];
  return changedNodes.some((node) => !isHighlightyManagedNode(node));
};

// Returns a same-origin iframe's body, or null when it's cross-origin
// (contentDocument access throws) or not yet loaded.
const getSameOriginIframeBody = (
  frame: HTMLIFrameElement
): HTMLElement | null => {
  try {
    return frame.contentDocument?.body ?? null;
  } catch {
    return null;
  }
};

// IFR-01: a same-origin iframe finished (re)loading. Cross-origin frames throw
// on access and are skipped. The standard debounced pass re-arms the observer
// over the frame's new document and re-highlights its content.
const onIframeLoad = (ev: Event) => {
  const frame = ev.currentTarget as HTMLIFrameElement | null;
  if (
    !frame ||
    !currentGlobalSettings?.isExtensionOn ||
    !currentGlobalSettings?.iframeSearch?.isOn ||
    !getSameOriginIframeBody(frame)
  ) {
    return;
  }
  scheduleRehighlight();
};

// IFR-01: a top-document subtree observer does NOT receive mutations that occur
// inside a nested document, so content added inside a same-origin iframe after
// the initial pass would never be re-highlighted. When iframe search is on,
// observe each same-origin iframe body with the same observer, and hook each
// frame's `load` so a frame that loads/navigates later is picked up too.
const armIframeObservers = () => {
  // Bound growth on SPA pages that churn iframes: drop listeners for frames no
  // longer in the document.
  iframeLoadListened.forEach((frame) => {
    if (!frame.isConnected) {
      try {
        frame.removeEventListener("load", onIframeLoad);
      } catch {}
      iframeLoadListened.delete(frame);
    }
  });

  document.querySelectorAll("iframe").forEach((node) => {
    const frame = node as HTMLIFrameElement;
    const iframeBody = getSameOriginIframeBody(frame);
    if (iframeBody && observer) {
      try {
        observer.observe(iframeBody, OBSERVER_CONFIG);
      } catch {
        // Detached document / engine edge — skip this frame.
      }
    }
    if (!iframeLoadListened.has(frame)) {
      iframeLoadListened.add(frame);
      frame.addEventListener("load", onIframeLoad);
    }
  });
};

const clearIframeLoadListeners = () => {
  iframeLoadListened.forEach((frame) => {
    try {
      frame.removeEventListener("load", onIframeLoad);
    } catch {}
  });
  iframeLoadListened.clear();
};

const armObserver = (body: HTMLElement) => {
  if (!observer || !currentGlobalSettings?.isExtensionOn) {
    return;
  }

  // IFR-03: in steady state (`isObserving === true`) flipping `iframeSearch` ON
  // mid-session re-runs this path, but the `isObserving` early-return below
  // would skip arming the iframe observers. Arm them BEFORE that return when
  // iframe search is on — `armIframeObservers` is idempotent (it prunes dead
  // frames, `observe()` on an already-observed body is a no-op, and the `load`
  // hook is guarded by `iframeLoadListened`), so this is safe to run on every
  // arm whether or not the top observer is already observing.
  if (currentGlobalSettings?.iframeSearch?.isOn) {
    armIframeObservers();
  }

  if (isObserving) {
    return;
  }

  observer.observe(body, OBSERVER_CONFIG);

  // OBS-01: also watch <html>'s DIRECT children (childList only, NOT subtree)
  // so a whole-body-ELEMENT replacement (document.body = newBody, or
  // documentElement.replaceChild(newBody, oldBody) — the Turbo/PJAX/legacy-AJAX
  // pattern) is delivered as a childList record on <html>. A body-subtree
  // observer alone never sees that swap (it observes WITHIN body), so it would
  // stay stranded on the now-detached old body and silently stop re-highlighting
  // the new body for the rest of the tab. childList-only keeps this cheap and
  // adds no <head>/subtree noise — only a body/head element add/remove fires it,
  // and managed nodes are filtered by isRelevantMutation. The delivered record
  // runs the normal debounced pass, which disconnects and re-arms
  // armObserver(document.body) over the NEW body — self-healing.
  const root = body.ownerDocument?.documentElement;
  if (root) {
    observer.observe(root, { childList: true });
  }

  isObserving = true;
};

export const destroyObserverLogic = () => {
  clearTimers();
  disconnectObserver();
  clearIframeLoadListeners();
  managedMutationSuppressionDepth = 0;
  observer = null;
};

// HLE-18: the observer kill-switch matches the live HOSTNAME against the
// registrable-host base list (blacklistObserverSites), NOT an href substring.
// Reuses the SCO-02/SCO-04 host matcher so `www./m./music.youtube.com` match
// `youtube.com` while `techblog.example.com`, `notyoutube.com`,
// `evilyoutube.com`, and `localhost` (or any URL merely MENTIONING "youtube" in
// its path/query) do NOT. Guarded so a hostile `window.location` access can't
// throw the observer arm path.
export const isObserverBlacklistedHost = (hostname: string): boolean =>
  hostMatchesAnyEntry(hostname, blacklistObserverSites);

export const observerLogic = () => {
  const body = document.body;
  let isBlacklistedHost = false;
  try {
    isBlacklistedHost = isObserverBlacklistedHost(window.location.hostname);
  } catch {
    isBlacklistedHost = false;
  }

  // Early return if conditions are not met
  if (!body || isBlacklistedHost || !currentGlobalSettings?.isExtensionOn) {
    destroyObserverLogic();
    return;
  }

  if (!observer) {
    observer = new MutationObserver((mutations: MutationRecord[]) => {
      if (managedMutationSuppressionDepth > 0) {
        return;
      }

      if (!mutations.some(isRelevantMutation)) {
        return;
      }

      scheduleRehighlight();
    });
  }

  armObserver(body);
};
