// Match-range computation for form-field highlighting.
//
// Pure function: given a field's current value and the active saved queries,
// return a flat list of non-overlapping match ranges suitable for direct DOM
// rendering by the mirror layer. No DOM access — testable in isolation.
//
// Semantics intentionally mirror the existing DOM and PDF search engines so
// users see the same matches everywhere:
//   - case-sensitivity, diacritic-sensitivity, whole-word, split-search,
//     and regex toggles all behave the same way as in queryMatching.ts
//   - catastrophic-backtrack patterns are rejected before compilation
//     (regexSafety.isLikelyCatastrophic) — JS can't interrupt a hung
//     RegExp.exec, so the only safe option is to skip dangerous patterns
//
// Overlap normalization (the form-field-specific bit):
//   1. Earlier query order wins. The popup's query list ordering is the
//      user's stated priority; when two queries match the same region, the
//      earlier-defined one renders.
//   2. Within the same query, the longer match wins (splitSearch can produce
//      both "the cat" and "cat" variants — keep "the cat").
//   3. Later overlapping ranges are dropped. Splitting them into surviving
//      slices is possible but not implemented here; a dropped match always
//      lives inside a kept one, so nothing visible is lost.

import { QueryItem } from "../../../definitions/global.definition";
import { QuerySearchOptions } from "../../../search/types";
import {
  normalizeSearchText,
  isWordBoundary,
  compileWholeWordRegex,
} from "../../../search/normalization";
import { advanceRegexIndex } from "../../../search/regexExec";
import { isLikelyCatastrophic } from "../utils/regexSafety";

// QRX-02/FFH-08: a decomposed grapheme (base + separate combining mark) at a
// match end leaves the trailing mark past the last *normalized* char's source
// index, so it would be excluded from the painted span. Extend past trailing
// combining marks, matching queryMatching.ts's QRX-02 fix.
const COMBINING_MARK_REGEX = /[\u0300-\u036f]/;

export interface FormFieldMatch {
  queryId: string;
  start: number;
  end: number;
}

// Hard cap to protect the page. Above this, we render no highlights rather
// than risk a long-task freeze on a pathological textarea. The mirror module
// honours the same cap when deciding whether to attach.
export const MAX_FIELD_CHARS = 100_000;

// Build all plain-text variants for a query. For splitSearch, multi-word
// queries also produce per-word variants. Inactive and empty queries return
// nothing so they're trivially skipped by the caller.
const plainVariants = (
  item: QueryItem,
  options: QuerySearchOptions
): string[] => {
  if (item.isRegexp) return [];
  const trimmed = item.name.trim();
  if (!trimmed.length) return [];
  const set = new Set<string>([trimmed]);
  if (options.splitSearch && /\s/.test(trimmed)) {
    trimmed
      .split(/\s+/)
      .map((p) => p.trim())
      .filter(Boolean)
      .forEach((p) => set.add(p));
  }
  return Array.from(set);
};

const findPlain = (
  text: string,
  variant: string,
  options: QuerySearchOptions
): Array<{ start: number; end: number }> => {
  // Per-call normalisation. The whole-string approach (vs. normalizeSearchTextWithMap)
  // works here because we never insert synthetic whitespace runs — the form
  // value is the source of truth, character-for-character. normalizeSearchText
  // returns same-length output when input has no combining marks; with marks,
  // NFD-then-strip can shorten the string, which would break offset mapping.
  // For correctness in the marked-text case we drop back to a per-character
  // walk that records original offsets.
  const opts = {
    caseSensitive: options.caseSensitive,
    diacriticSensitive: options.diacriticSensitive,
  };
  const normVariant = normalizeSearchText(variant, opts);
  if (!normVariant.length) return [];

  // Build a normalised view of `text` along with a parallel sourceMap that
  // points each normalised char back to its original-index. Mirrors the
  // map-building logic in normalization.normalizeSearchTextWithMap but
  // without the whitespace collapsing — form fields preserve all whitespace
  // as typed, and collapsing would shift offsets relative to the source.
  let normText = "";
  const sourceMap: number[] = [];
  for (let i = 0; i < text.length; i++) {
    const out = normalizeSearchText(text[i], opts);
    for (let j = 0; j < out.length; j++) {
      normText += out[j];
      sourceMap.push(i);
    }
  }

  const hits: Array<{ start: number; end: number }> = [];
  let cursor = 0;
  while (cursor <= normText.length) {
    const idx = normText.indexOf(normVariant, cursor);
    if (idx === -1) break;
    const endIdx = idx + normVariant.length;

    const passesBoundary =
      !options.completePhrase ||
      (isWordBoundary(normText, idx - 1) && isWordBoundary(normText, endIdx));

    if (passesBoundary) {
      const origStart = sourceMap[idx] ?? idx;
      let origEnd = (sourceMap[endIdx - 1] ?? origStart) + 1;
      // FFH-08: when the final matched grapheme is decomposed (base + a
      // separate combining mark stripped during normalization), the mark's
      // source index sits past `endIdx-1` and would be excluded. Extend past
      // trailing combining marks so the span end matches the engine contract
      // (queryMatching.ts QRX-02).
      while (origEnd < text.length && COMBINING_MARK_REGEX.test(text[origEnd])) {
        origEnd++;
      }
      if (origEnd > origStart) hits.push({ start: origStart, end: origEnd });
    }

    // Advance by variant length (in normalised units) so we don't re-emit
    // the same match. Math.max guards an empty-variant defensive case.
    cursor = idx + Math.max(normVariant.length, 1);
  }
  return hits;
};

const findRegex = (
  text: string,
  pattern: string,
  options: QuerySearchOptions
): Array<{ start: number; end: number }> => {
  // Catastrophic-backtrack guard runs on the RAW user pattern, BEFORE any
  // whole-word wrapping — the lookarounds wrapRegexWholeWord adds are zero-width
  // and must not mask a dangerous inner pattern from the detector.
  if (isLikelyCatastrophic(pattern)) return [];
  const flags = `gm${options.caseSensitive ? "" : "i"}u`;
  // FFH-09 (QRX-16 mirror): honor "Complete word search" (completePhrase) for
  // regex by WRAPPING the user pattern in zero-width word-boundary lookarounds
  // (shared `wrapRegexWholeWord`) instead of a post-match isWordBoundary filter.
  // The old post-filter under-matched ALTERNATION: for `cat|category` on
  // "category" with whole-word ON, the engine committed to the leftmost alt
  // "cat", the filter rejected it for the trailing boundary, and the longer
  // whole-word alt "category" was never retried → 0 matches. Baking the boundary
  // INTO the pattern lets the engine backtrack across alternation to the longer
  // whole-word alternative, so this surface agrees with the Cmd+F/PDF engines
  // (queryMatching.ts buildRegex, ephemeralSearch.ts findRegexMatches) and the
  // on-page mark.js highlighter (QRX-06). The wrap is zero-width + non-capturing,
  // so `m[0]`/`m.index` still cover ONLY the user's match, capture numbering is
  // preserved, and the maxIterations cap + advanceRegexIndex zero-width handling
  // below stay valid. The `u` flag (already in `flags`) is required for the
  // \p{…} classes inside wrapRegexWholeWord.
  let regex: RegExp;
  try {
    // QRX-20: validate the raw pattern before whole-word-wrapping (see
    // compileWholeWordRegex) so a malformed class can't become a valid-but-wrong
    // regex when completePhrase is on.
    regex = compileWholeWordRegex(pattern, flags, options.completePhrase);
  } catch {
    return [];
  }
  const hits: Array<{ start: number; end: number }> = [];
  let m: RegExpExecArray | null;
  // Defensive loop cap. A misbehaving pattern with frequent zero-width
  // matches could otherwise spin; in practice the lastIndex bump handles
  // it but the cap is a belt-and-braces guarantee that this function
  // always returns in bounded time.
  let iterations = 0;
  const maxIterations = text.length + 1;
  while ((m = regex.exec(text)) !== null) {
    iterations += 1;
    if (iterations > maxIterations) break;
    const start = m.index;
    const end = m.index + m[0].length;
    // Whole-word is now enforced INSIDE the compiled pattern (see the
    // wrapRegexWholeWord wrap above), so no post-match boundary filter is needed
    // — FFH-09 replaced the old isWordBoundary post-filter, which under-matched
    // alternation. Zero-width hits are still dropped (invisible spans).
    if (end > start) hits.push({ start, end });
    // QRX-15: advance past the WHOLE code point after a zero-width match. The
    // loop compiles with the `u` flag, so a flat `+= 1` before an astral char
    // (emoji, CJK-ext, …) lands inside the surrogate pair; the next exec snaps
    // lastIndex back, re-emits the empty match, and only the maxIterations cap
    // stops it — truncating real matches after the emoji. advanceRegexIndex
    // steps by the code-point width (mirrors the FIXED QRX-07 main path).
    if (m[0].length === 0) {
      regex.lastIndex = advanceRegexIndex(text, regex.lastIndex);
    }
  }
  return hits;
};

const normalizeOverlaps = (
  candidates: FormFieldMatch[],
  queryOrder: Map<string, number>
): FormFieldMatch[] => {
  // Sort by:
  //   1. queryOrder ascending — earlier-defined query wins
  //   2. length descending — within a query, longer match wins
  //   3. start ascending — stable tiebreak
  const sorted = [...candidates].sort((a, b) => {
    const orderA = queryOrder.get(a.queryId) ?? Number.MAX_SAFE_INTEGER;
    const orderB = queryOrder.get(b.queryId) ?? Number.MAX_SAFE_INTEGER;
    if (orderA !== orderB) return orderA - orderB;
    const lenA = a.end - a.start;
    const lenB = b.end - b.start;
    if (lenA !== lenB) return lenB - lenA;
    return a.start - b.start;
  });

  // Greedy accept: take each match unless it overlaps a previously-accepted
  // one. For the small N typical of form fields (a few queries × a few
  // matches), O(n²) is fine; if this ever shows up in profiles, switch to
  // an interval tree.
  const accepted: FormFieldMatch[] = [];
  for (const m of sorted) {
    const overlaps = accepted.some((a) => m.start < a.end && a.start < m.end);
    if (!overlaps) accepted.push(m);
  }
  return accepted.sort((a, b) => a.start - b.start);
};

export const computeFormFieldMatches = (
  text: string,
  items: QueryItem[],
  options: QuerySearchOptions
): FormFieldMatch[] => {
  if (!text || !text.length) return [];
  if (text.length > MAX_FIELD_CHARS) return [];
  if (!items.length) return [];

  const queryOrder = new Map<string, number>();
  items.forEach((item, index) => queryOrder.set(item.id, index));

  const candidates: FormFieldMatch[] = [];

  for (const item of items) {
    if (item.isInactive) continue;
    if (!item.name || !item.name.trim().length) continue;

    if (item.isRegexp) {
      for (const hit of findRegex(text, item.name, options)) {
        candidates.push({ queryId: item.id, start: hit.start, end: hit.end });
      }
      continue;
    }

    for (const variant of plainVariants(item, options)) {
      for (const hit of findPlain(text, variant, options)) {
        candidates.push({ queryId: item.id, start: hit.start, end: hit.end });
      }
    }
  }

  return normalizeOverlaps(candidates, queryOrder);
};
