import convert from "color-convert";
import { ColorResult, HSLColor, RGBColor } from "react-color";
import { best } from "wcag-color";

export function rgbRandomizer(): RGBColor {
  return {
    r: getRandomArbitrary(),
    g: getRandomArbitrary(),
    b: getRandomArbitrary(),
    a: 1,
  };
}
export function hslRandomizer(isBright?: boolean): HSLColor {
  return isBright
    ? {
        h: getRandomArbitrary(50, 350),
        s: getRandomArbitrary(85, 97),
        l: getRandomArbitrary(85, 95),
        a: 1,
      }
    : {
        h: getRandomArbitrary(0, 360),
        s: getRandomArbitrary(20, 80),
        l: getRandomArbitrary(30, 85),
        a: 1,
      };
}

export function convertRgbToAll(rgb: RGBColor): ColorResult {
  const hsl = convert.rgb.hsl(rgb.r, rgb.g, rgb.b);
  const hex = convert.rgb.hex(rgb.r, rgb.g, rgb.b);

  const result = {
    hex: hex,
    rgb: rgb,
    hsl: { h: hsl[0], s: hsl[1], l: hsl[2], a: rgb?.a },
  };

  return result;
}
export function convertHslToAll(hsl: HSLColor): ColorResult {
  const rgb = convert.hsl.rgb([hsl.h, hsl.s, hsl.l]);
  const hex = convert.hsl.hex([hsl.h, hsl.s, hsl.l]);

  const result = {
    hex: hex,
    rgb: { r: rgb[0], g: rgb[1], b: rgb[2], a: hsl?.a },
    hsl: hsl,
  };

  return result;
}

export function getRandomArbitrary(min = 0, max = 255) {
  const random = Math.random() * (max - min) + min;
  return parseInt(random.toString());
}

export function rgbFormatter({ rgb }: ColorResult) {
  // CDM-02: default a missing alpha to 1. An IMPORTED QueryItem whose color
  // object omits the alpha channel (e.g. a hand-edited / foreign upload routed
  // through convertRgbToAll, which propagates `a` verbatim) would otherwise
  // emit `rgba(r, g, b, undefined)` — an invalid CSS color browsers reject
  // entirely, so the highlight renders with NO color (invisible).
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${rgb?.a ?? 1})`;
}
export function hslFormatter(hsl: HSLColor) {
  // CDM-02: default a missing alpha to 1 (see rgbFormatter) so an alpha-less
  // imported color doesn't emit `hsla(..., undefined)` and render colorless.
  return `hsla(${hsl.h}, ${hsl.s}%, ${hsl.l}%, ${hsl?.a ?? 1})`;
}

export function getDefaultColors(isBright?: boolean): ColorResult {
  return convertHslToAll(hslRandomizer(isBright));
}

export function chooseColorPalette(hsl: HSLColor): ColorResult {
  return convertHslToAll(hsl);
}

export function generatePalette(): HSLColor[] {
  const hslNormal: HSLColor[] = Array.from(Array(10).keys()).map((_, i) => {
    return { h: i === 0 ? 10 : i * 35, s: 80, l: 85, a: 1 };
  });
  const hslOpacity: HSLColor[] = hslNormal.map((hslColors) => {
    return { ...hslColors, a: 0.5 };
  });

  return [...hslNormal, ...hslOpacity];
}

export function adaptiveFontColor(
  color: HSLColor,
  isContent?: boolean
): string {
  const alpha = color?.a ?? 1;

  // PUI-13: composite the (possibly translucent) highlight color over the
  // expected page background BEFORE measuring contrast. The opacity slider
  // spans 0.25–1; below 0.45 we already shortcut to the dark font (the cliff
  // below). For 0.45 ≤ alpha < 1 the highlight is partially transparent, so its
  // EFFECTIVE on-page color is the highlight blended over the page background —
  // lighter than the opaque swatch. Measuring contrast against the opaque color
  // (the old behaviour) could pick white where the real composited luminance is
  // actually too light for white text. We blend in RGB space over an assumed
  // white background (the common page case) so best() sees the real color.
  //
  // CDM-01: round h/s/l before building the string. `wcag-color`'s best()
  // parses the color with an integer-only regex (/\d+/g), so a FRACTIONAL hue
  // (the common color-picker output, e.g. 210.46) shatters into extra tokens
  // and the contrast is computed for the WRONG color — flipping the white/dark
  // font decision and producing unreadable (e.g. white-on-light) highlight
  // text. Rounding here also covers any fractional s/l reaching us from imports.
  const h = Math.round(color.h);
  const s = Math.round(color.s);
  const l = Math.round(color.l);

  let colorString: string;
  if (alpha >= 1) {
    colorString = `hsl(${h}, ${s}%, ${l}%)`;
  } else {
    // Convert to RGB and alpha-composite over white (255,255,255):
    //   out = fg * a + bg * (1 - a)
    const [r, g, b] = convert.hsl.rgb([h, s, l]);
    const blend = (channel: number) =>
      Math.round(channel * alpha + 255 * (1 - alpha));
    colorString = `rgb(${blend(r)}, ${blend(g)}, ${blend(b)})`;
  }

  const whiteFontColor = "#FFFFFF"; // white,
  const darkFontColor = isContent ? "#000000" : "#61707d"; // brand.textColor

  const bestFontColor = best(whiteFontColor, darkFontColor, colorString);

  // Below 0.45 the highlight is so faint that the page background dominates;
  // keep the original dark-font cliff (cheap guard, avoids over-trusting the
  // composite at extreme transparency).
  return alpha < 0.45 ? darkFontColor : bestFontColor;
}
