import { GlobalSettings } from "../../definitions/global.definition";
import { hilityTag, dataHility, dataHilityName } from "../content.consts";
import { debounce } from "../shared";
import {
  advanceCycleIndex,
  resetOtherCycleIndices,
  bucketize,
  bucketCountFor,
  decideFanOut,
  barHeightForCount,
  BAR_HEIGHT_MIN,
  DOC_HEIGHT_DRIFT_THRESHOLD,
  type BarEntry,
  type BucketInput,
  type MarkerTarget,
} from "./content.scrollbarHighlighter.utils";

// Track state
let highlighterEl: HTMLElement | null = null;
// Per-query saved entries. Maps queryId -> entries; one entry per
// rendered bar. Bucketing in renderSource may emit one entry with
// multiple members (a cluster bar) when a bucket exceeds FAN_OUT.
let savedEntries: Map<string, BarEntry[]> = new Map();
let adHocEntries: BarEntry[] = [];
let resizeObserver: ResizeObserver | null = null;
let scrollHandler: (() => void) | null = null;
// Two independent sources can keep the container alive: the saved-highlight
// scrollbar setting, and the Cmd+F bar's ad-hoc overlay. Container exists
// iff either source is active.
let savedActive = false;
let adHocActive = false;
let isEnabled = false;
// Tracks the docHeight at last full render; drift > DOC_HEIGHT_DRIFT_THRESHOLD
// triggers a re-bucket from updateMarkerVisibility (the scroll handler).
let lastDocHeight = 0;

// Remove every `.highlighty-scrollbar-highlighter` host in the document
// EXCEPT the one passed in `keep` (this session's live strip). Used on
// arm to purge unowned/baked-in strips, and on teardown (keep = null) to
// clear all of them.
//
// MAP-07: a "Save Page As" capture taken while Highlighty was running
// serialises the strip host into the saved HTML. Reopening that file, the
// live extension used to create its OWN strip alongside the baked-in one —
// two coexisted while ON (the stale one has 0 markers but is pinned
// full-height on the right with pointer-events:auto in the capture, so it
// ate clicks near the scrollbar), and toggling OFF removed only the live
// strip, leaving the baked-in one as residue. Claim (purge) unowned strips
// on arm and remove all on teardown.
const purgeStripHosts = (keep: HTMLElement | null): void => {
  document
    .querySelectorAll(".highlighty-scrollbar-highlighter")
    .forEach((el) => {
      if (el !== keep) el.remove();
    });
};

// Create the highlighter element
const createHighlighterElement = (): void => {
  // Remove existing highlighter if any
  if (highlighterEl) {
    highlighterEl.remove();
  }

  // MAP-07: before creating our fresh strip, purge any pre-existing
  // `.highlighty-scrollbar-highlighter` host that isn't this session's
  // element. On first arm `highlighterEl` is null, so all baked-in strips
  // from a Save-Page-As capture are removed here.
  purgeStripHosts(highlighterEl);

  // Create new highlighter element
  highlighterEl = document.createElement("div");
  highlighterEl.className = "highlighty-scrollbar-highlighter";

  // Style the highlighter
  Object.assign(highlighterEl.style, {
    position: "fixed",
    right: "0",
    top: "0",
    width: "8px",
    height: "100%",
    // MAP-05: the strip container is transparent and full-height; with
    // pointer-events:auto it was a click-eating band — a click anywhere in the
    // rightmost 8px (gaps between markers, empty regions, over right-edge page
    // UI) surprise-scrolled to the nearest match and swallowed the click. Make
    // the container transparent to pointer events; only the markers below opt
    // back in (pointer-events:auto), mirroring the minimap. Clicks not on a
    // marker now pass through to the page.
    pointerEvents: "none",
    zIndex: "9999",
    backgroundColor: "transparent",
  });

  // Append to body
  document.body.appendChild(highlighterEl);

  // Add CSS for markers if not already added. Scope to <head> + tag so
  // a page-owned element with id="highlighty-scrollbar-style" doesn't
  // trick us into skipping the actual style injection.
  if (!document.head.querySelector("style#highlighty-scrollbar-style")) {
    const style = document.createElement("style");
    style.id = "highlighty-scrollbar-style";
    style.textContent = `
      .highlighty-scrollbar-marker {
        position: absolute;
        width: 100%;
        height: 5px;
        background-color: rgba(255, 204, 0, 0.7);
        border-radius: 2px;
        cursor: pointer;
        transition: opacity 0.2s ease, width 0.2s ease, transform 0.2s ease;
        /* Add a subtle border to ensure visibility for light colors */
        box-shadow: 0 0 1px rgba(0, 0, 0, 0.5);
      }
      .highlighty-scrollbar-marker:hover {
        opacity: 1;
        width: 12px;
        transform: translateX(-2px);
      }
      /* Ad-hoc Cmd+F matches sit on the right half of the strip so they
         visually separate from the full-width saved-highlight markers. */
      .highlighty-scrollbar-marker.highlighty-scrollbar-marker-adhoc {
        width: 50%;
        left: 50%;
        height: 3px;
        opacity: 0.85;
        border-radius: 1px;
      }
      .highlighty-scrollbar-marker.highlighty-scrollbar-marker-adhoc:hover {
        width: 50%;
        transform: translateX(0);
      }
      /* The scrollbar strip is a screen affordance — hide on print so a
         page printout doesn't leak our UI as visual noise. */
      @media print {
        .highlighty-scrollbar-highlighter {
          display: none !important;
        }
      }
    `;
    document.head.appendChild(style);
  }
};

// Set up event listeners
const setupEventListeners = (): void => {
  // Idempotent: drop any prior scroll listener / ResizeObserver first, so a
  // re-arm (MAP-09: re-creating the host after a page body swap detaches it)
  // can't leak a second scroll listener or observer whose handler ref we'd no
  // longer be able to remove.
  if (scrollHandler) {
    window.removeEventListener("scroll", scrollHandler);
    scrollHandler = null;
  }
  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
  // Handle scrolling
  scrollHandler = debounce(() => updateMarkerVisibility(), 100);
  window.addEventListener("scroll", scrollHandler);

  // Handle resizing / reflow. MAP-02: observe BOTH <body> AND <html>
  // (documentElement). Many pages put the scroll — and the height that drives
  // marker positions (docHeight = max(body, documentElement).scrollHeight) — on
  // <html>, not <body>; a reflow that grows/shrinks the document without
  // changing body's own box wouldn't fire a body-only observer, leaving markers
  // stale on dynamic pages. One ResizeObserver, two targets → one debounced
  // re-render. (DOM-content additions are separately covered by the content
  // MutationObserver → highlight pass → updateScrollbarMarkers. Arbitrary inner
  // overflow:auto containers whose content moves matches without changing the
  // root height remain a documented limitation; such matches' document
  // positions are clipped to the container and generally stable.)
  resizeObserver = new ResizeObserver(
    debounce(() => updateMarkerPositions(), 100),
  );
  resizeObserver.observe(document.body);
  resizeObserver.observe(document.documentElement);

  // Handle clicks on the highlighter
  if (highlighterEl) {
    highlighterEl.addEventListener("click", handleHighlighterClick);
  }

  // MAP-11: document capture-phase pointerdown to catch marker clicks that the
  // native scrollbar thumb occludes (no `click` fires then — see
  // handleStripOccludedPointerDown). Idempotent: remove-then-add the stable ref
  // so a re-arm (MAP-09) can't leak a duplicate document-level listener.
  document.removeEventListener(
    "pointerdown",
    handleStripOccludedPointerDown,
    true,
  );
  document.addEventListener(
    "pointerdown",
    handleStripOccludedPointerDown,
    true,
  );
};

const stripHeight = (): number =>
  highlighterEl
    ? highlighterEl.getBoundingClientRect().height
    : window.innerHeight;

const allEntries = (): BarEntry[] => {
  const out: BarEntry[] = [];
  for (const entries of savedEntries.values()) {
    for (const e of entries) out.push(e);
  }
  for (const e of adHocEntries) out.push(e);
  return out;
};

// Full re-render of both active sources: re-reads every target's LIVE rect
// (phase-1) and re-buckets. Shared by the resize handler (reflow moves matches)
// and the scroll-handler drift check (doc grew/shrank). updateScrollbarMarkers /
// setAdHocMarkers reset lastDocHeight to the current height, so the nested
// updateMarkerVisibility they call sees ~0 drift and won't recurse.
function rerenderAllSources(): void {
  if (savedActive) updateScrollbarMarkers();
  if (adHocActive && adHocEntries.length > 0) {
    const ranges: Range[] = [];
    const color = adHocEntries[0].color;
    for (const entry of adHocEntries) {
      for (const m of entry.members) {
        if (m.kind === "range") ranges.push(m.range);
      }
    }
    setAdHocMarkers(ranges, color);
  }
}

// Resize handler. MAP-01: a reflow (responsive breakpoint, font/image load,
// sidebar expand, text rewrap) moves matches in the document. The old handler
// reused each entry's yTop (frozen at the last render) and only re-divided it
// by the new docHeight — so markers drifted off their real targets, and for
// cluster bars (yTop = a synthetic bucket-center in OLD coords) the result was
// doubly wrong. Re-read the live rects and re-bucket instead.
const updateMarkerPositions = (): void => {
  if (!isEnabled) return;
  if (allEntries().length === 0) return;
  // Re-read rects + re-bucket only when the document actually reflowed (its
  // height changed since the last render) — that's the reliable, cheap signal
  // that matches have moved. This also skips the ResizeObserver's initial
  // no-op callback (it fires once on observe) and benign resizes that don't
  // change layout, so a large page doesn't pay a full re-render for nothing.
  // (A reflow that moves matches without ANY height change isn't caught here.
  // It's rare, and is reconciled by the next highlight re-pass [content.highlight
  // calls updateScrollbarMarkers] or any height-changing reflow/resize — but NOT
  // by a bare scroll, whose drift check is also height-based.)
  const docHeight = Math.max(
    document.body.scrollHeight,
    document.documentElement.scrollHeight,
  );
  if (docHeight === lastDocHeight) return;
  rerenderAllSources();
};

// Update marker visibility based on scroll position
const updateMarkerVisibility = (): void => {
  if (!isEnabled) return;
  const all = allEntries();
  if (all.length === 0) return;

  // Cheap drift check — if the document has grown / shrunk by more than
  // DOC_HEIGHT_DRIFT_THRESHOLD since the last full render, re-bucket
  // everything. Cost is a single scrollHeight read (one layout flush),
  // bounded.
  const docHeight = Math.max(
    document.body.scrollHeight,
    document.documentElement.scrollHeight,
  );
  if (lastDocHeight > 0) {
    const drift = Math.abs(docHeight - lastDocHeight) / lastDocHeight;
    if (drift > DOC_HEIGHT_DRIFT_THRESHOLD) {
      // Re-render both sources — they re-read phase-1 rects from scratch.
      rerenderAllSources();
      return;
    }
  }
  lastDocHeight = docHeight;

  const windowTop = window.scrollY;
  const windowBottom = windowTop + window.innerHeight;
  for (const entry of all) {
    const isVisible =
      entry.bucketBottom > windowTop && entry.bucketTop < windowBottom;
    entry.markerEl.style.opacity = isVisible ? "1" : "0.7";
    // MAP-03: ad-hoc (Cmd+F) markers get their thin right-half geometry + shadow
    // from CSS (.highlighty-scrollbar-marker-adhoc: width:50%; left:50%). The
    // saved-marker inline width/boxShadow below would override that (inline >
    // class), collapsing them into ~8-10px midline nubs styled like saved bars.
    // Only saved markers get the inline visibility styling; ad-hoc keeps its CSS
    // look (just the opacity cue above).
    if (entry.source === "adhoc") continue;
    entry.markerEl.style.width = isVisible ? "10px" : "8px";
    entry.markerEl.style.boxShadow = isVisible
      ? "0 0 2px rgba(0, 0, 0, 0.7), 0 0 3px rgba(255, 255, 255, 0.5)"
      : "0 0 1px rgba(0, 0, 0, 0.5)";
  }
};

const createBarEl = (
  source: "saved" | "adhoc",
  queryId: string,
  bucketIdx: number,
  color: string,
  heightPx: number,
  memberCount: number,
  queryName: string,
): HTMLElement => {
  if (!highlighterEl) throw new Error("highlighterEl not initialised");
  const el = document.createElement("div");
  el.className =
    "highlighty-scrollbar-marker" +
    (source === "adhoc" ? " highlighty-scrollbar-marker-adhoc" : "");
  el.dataset.source = source;
  el.dataset.bucket = String(bucketIdx);
  el.dataset.query = queryId;
  el.dataset.clusterSize = String(memberCount);
  el.style.backgroundColor = color;
  el.style.opacity = "0.7";
  el.style.height = `${heightPx}px`;
  // MAP-05: the container strip is pointer-events:none; the markers opt back in
  // so they stay clickable (the click handler's direct-hit branch reads their
  // data-* attributes).
  el.style.pointerEvents = "auto";
  const label = memberCount > 1 ? `${queryName} × ${memberCount}` : queryName;
  el.title = label;
  el.setAttribute(
    "aria-label",
    memberCount > 1
      ? `${queryName}, ${memberCount} matches, click to scroll`
      : `${queryName}, click to scroll`,
  );
  highlighterEl.appendChild(el);
  return el;
};

const removeEntryDom = (entry: BarEntry): void => {
  if (entry.markerEl && entry.markerEl.parentNode) {
    entry.markerEl.remove();
  }
};

// Clear all entries (both saved and ad-hoc). Public for back-compat with
// the highlight-pass cleanup path.
export const clearScrollbarMarkers = (): void => {
  for (const entries of savedEntries.values()) {
    entries.forEach(removeEntryDom);
  }
  savedEntries = new Map();
  adHocEntries.forEach(removeEntryDom);
  adHocEntries = [];
};

const clearSavedEntries = (): void => {
  for (const entries of savedEntries.values()) {
    entries.forEach(removeEntryDom);
  }
  savedEntries = new Map();
};

const clearAdHocEntriesInternal = (): void => {
  adHocEntries.forEach(removeEntryDom);
  adHocEntries = [];
};

/**
 * Bucketize the provided per-query inputs and emit one DOM node per bar.
 * For buckets with > FAN_OUT members → one cluster bar at the bucket's
 * geometric center. Otherwise → one bar per member at its precise Y.
 *
 * Pure phase-2 (DOM writes); inputs must already carry absoluteTop /
 * absoluteBottom from the caller's phase-1 read pass.
 */
const renderSource = (
  source: "saved" | "adhoc",
  perQueryInputs: Map<string, BucketInput[]>,
  colorFor: (queryId: string) => string,
  nameFor: (queryId: string) => string,
  docHeight: number,
  stripHeightPx: number,
): Map<string, BarEntry[]> => {
  const out = new Map<string, BarEntry[]>();
  if (perQueryInputs.size === 0) return out;
  const bucketCount = bucketCountFor(stripHeightPx);

  for (const [queryId, inputs] of perQueryInputs.entries()) {
    const color = colorFor(queryId);
    const buckets = bucketize(inputs, docHeight, bucketCount);
    const entries: BarEntry[] = [];
    let entrySeq = 0;
    for (const [bucketIdx, members] of buckets.entries()) {
      const fan = decideFanOut(members.length);
      if (fan === "fan") {
        // One bar per member at its precise Y.
        for (const m of members) {
          const markerEl = createBarEl(source, queryId, entrySeq, color, BAR_HEIGHT_MIN, 1, nameFor(queryId));
          markerEl.style.top = `${(m.absoluteTop / docHeight) * 100}%`;
          entries.push({
            members: [m.target],
            markerEl,
            cycleIndex: 0,
            yTop: m.absoluteTop,
            bucketTop: m.absoluteTop,
            bucketBottom: m.absoluteBottom,
            color,
            source,
            queryId,
            bucketIdx: entrySeq,
          });
          entrySeq += 1;
        }
      } else {
        // Single cluster bar at bucket center; height encodes density.
        const yTop = ((bucketIdx + 0.5) / bucketCount) * docHeight;
        const heightPx = barHeightForCount(members.length);
        const markerEl = createBarEl(
          source,
          queryId,
          entrySeq,
          color,
          heightPx,
          members.length,
          nameFor(queryId),
        );
        markerEl.style.top = `${(yTop / docHeight) * 100}%`;
        let bucketTop = Infinity;
        let bucketBottom = -Infinity;
        const targets: MarkerTarget[] = [];
        for (const m of members) {
          targets.push(m.target);
          if (m.absoluteTop < bucketTop) bucketTop = m.absoluteTop;
          if (m.absoluteBottom > bucketBottom) bucketBottom = m.absoluteBottom;
        }
        entries.push({
          members: targets,
          markerEl,
          cycleIndex: 0,
          yTop,
          bucketTop,
          bucketBottom,
          color,
          source,
          queryId,
          bucketIdx: entrySeq,
        });
        entrySeq += 1;
      }
    }
    out.set(queryId, entries);
  }
  return out;
};

// MAP-04: is a marker's target still attached to the DOM? Element targets check
// the element; range targets check the start container's node.
const isMarkerTargetConnected = (target: MarkerTarget): boolean =>
  target.kind === "element"
    ? target.element.isConnected
    : (target.range.startContainer as Node | null)?.isConnected ?? false;

// Resolve the BarEntry a marker element points at, from its data attributes.
const resolveEntryFromMarker = (
  target: HTMLElement | null,
): BarEntry | undefined => {
  if (!target || !target.classList?.contains("highlighty-scrollbar-marker")) {
    return undefined;
  }
  const source = target.dataset.source as "saved" | "adhoc" | undefined;
  const bucketIdx = Number(target.dataset.bucket);
  const queryId = target.dataset.query ?? "";
  if (!source || !Number.isFinite(bucketIdx)) return undefined;
  const pool =
    source === "saved" ? savedEntries.get(queryId) ?? [] : adHocEntries;
  return pool.find((p) => p.bucketIdx === bucketIdx);
};

// Scroll to (and flash) an entry's next live member. Shared by the direct
// marker click and the MAP-11 occluded-click intercept.
const activateEntry = async (
  entry: BarEntry,
  all: BarEntry[],
): Promise<void> => {
  if (entry.members.length === 0) return;
  // Cycling: advance THIS entry, reset every other (cross-source).
  resetOtherCycleIndices(entry, all);
  // MAP-04: advance to the next member whose target is still in the DOM. A
  // match can be removed (e.g. SPA re-render) in the window before the next
  // highlight pass rebuilds the markers; without this, clicking the marker
  // cycles onto a detached node and scrolls nowhere. Skip detached members so
  // the click lands on a live occurrence (or no-ops cleanly if all are gone).
  let member: MarkerTarget | undefined;
  for (let i = 0; i < entry.members.length; i++) {
    const candidate = entry.members[advanceCycleIndex(entry)];
    if (isMarkerTargetConnected(candidate)) {
      member = candidate;
      break;
    }
  }
  if (!member) return;

  if (member.kind === "element") {
    member.element.scrollIntoView({ behavior: "smooth", block: "center" });
    try {
      await highlightElement(member.element);
    } catch (error) {
      console.error("Error highlighting element:", error);
    }
  } else {
    const r = member.range;
    const node: Node | null =
      r.startContainer.nodeType === Node.ELEMENT_NODE
        ? r.startContainer
        : r.startContainer.parentElement;
    (node as Element | null)?.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
  }
};

/**
 * Handle a DIRECT click on a marker.
 */
const handleHighlighterClick = async (e: MouseEvent): Promise<void> => {
  if (!isEnabled || !highlighterEl) return;
  const all = allEntries();
  if (all.length === 0) return;

  // MAP-05: the strip container is pointer-events:none, so a click that isn't
  // on a marker passes straight through to the page and never reaches this
  // handler. If we somehow get here without a marker hit, do nothing — the old
  // "nearest entry by Y midpoint" fallback turned the whole transparent 8px
  // right-edge column into a surprise scroll-to-match target that also
  // swallowed clicks meant for page content.
  const entry = resolveEntryFromMarker(e.target as HTMLElement | null);
  if (!entry) return;
  await activateEntry(entry, all);
};

// MAP-11: while the native overlay-scrollbar thumb occludes a marker (the
// ~0.5–1.5s after a scroll), a click at the marker's location hit-tests to
// <html>, not the marker — the marker's own `click` handler never runs and the
// native scrollbar consumes the gesture, so NO `click` event is dispatched at
// all. We therefore key on `pointerdown` (which DOES fire, targeting <html>)
// and, ONLY when the pointer is in the strip's x-band, is NOT already a direct
// marker hit, and is vertically aligned to a real marker, route the activation
// to that marker and preventDefault the native scrollbar paging. Tightly scoped
// so MAP-05 holds: clicks outside the band, in band gaps (no aligned marker),
// and direct marker hits are all left untouched (they scroll the page / run the
// marker's own click as before). No timer gate is needed — a non-occluded
// marker click has the marker as its target and is skipped by the direct-hit
// guard, so geometry alone is the safe, deterministic condition.
const MARKER_ALIGN_SLOP_PX = 8;
const handleStripOccludedPointerDown = (e: PointerEvent): void => {
  if (!isEnabled || !highlighterEl) return;
  // Primary button only — never hijack a right/middle press (SNP-06 spirit).
  if (e.button !== 0) return;
  const stripRect = highlighterEl.getBoundingClientRect();
  // Guard B — the strip's x-band only (never touches page-content clicks).
  if (e.clientX < stripRect.left || e.clientX > stripRect.right) return;
  // Guard C — a direct marker hit means the marker isn't occluded; its own
  // click handler runs, so don't double-act.
  const target = e.target as HTMLElement | null;
  if (target?.classList?.contains("highlighty-scrollbar-marker")) return;
  // Guard D — resolve the marker vertically aligned to the pointer (nearest
  // center, ± slop). An in-band press NOT aligned to any marker passes through,
  // so MAP-05's "gaps in the strip don't scroll" invariant is preserved.
  const markers = Array.from(
    highlighterEl.querySelectorAll<HTMLElement>(".highlighty-scrollbar-marker"),
  );
  let best: HTMLElement | null = null;
  let bestDist = Infinity;
  for (const marker of markers) {
    const r = marker.getBoundingClientRect();
    if (
      e.clientY < r.top - MARKER_ALIGN_SLOP_PX ||
      e.clientY > r.bottom + MARKER_ALIGN_SLOP_PX
    ) {
      continue;
    }
    const dist = Math.abs(e.clientY - (r.top + r.bottom) / 2);
    if (dist < bestDist) {
      bestDist = dist;
      best = marker;
    }
  }
  if (!best) return;
  const entry = resolveEntryFromMarker(best);
  if (!entry) return;
  // Suppress the native scrollbar track-paging that would otherwise consume
  // this gesture, then run the resolved marker's action directly.
  e.preventDefault();
  e.stopPropagation();
  void activateEntry(entry, allEntries());
};

/**
 * Helper function to create a promise that resolves after a specified delay
 */
const delay = (ms: number): Promise<void> => {
  return new Promise((resolve) => setTimeout(resolve, ms));
};

/**
 * Add a temporary highlight effect to an element
 * Using async/await for cleaner animation sequence
 */
const highlightElement = async (element: HTMLElement): Promise<void> => {
  // Store original styles
  const originalTransition = element.style.transition;
  const originalZIndex = element.style.zIndex;
  const originalBoxShadow = element.style.boxShadow;
  const originalTransform = element.style.transform;

  // Create a temporary overlay for text-decorated elements
  const decorationType = element.getAttribute("data-decoration-type");
  let overlay: HTMLDivElement | null = null;

  try {
    // Apply initial highlight effect
    element.style.transition =
      "all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)";
    element.style.zIndex = "9999";
    element.style.transform = "scale(1.15)";
    element.style.boxShadow =
      "0 0 15px 4px rgba(255, 255, 0, 0.8), 0 0 5px 2px rgba(255, 165, 0, 0.6)";

    // Create overlay for text-decorated elements
    if (decorationType && decorationType !== "background") {
      overlay = document.createElement("div");
      const rect = element.getBoundingClientRect();

      Object.assign(overlay.style, {
        position: "absolute",
        // MAP-10: getBoundingClientRect() is viewport-relative, but the overlay
        // is position:absolute on document.body (document-relative). Add the
        // scroll offsets so the flash lands on the match instead of off-document
        // when the page is scrolled. (rect.top + scrollY is scroll-invariant =
        // the element's document top, so this is correct even mid-scroll.)
        left: rect.left + window.scrollX + "px",
        top: rect.top + window.scrollY + "px",
        width: rect.width + "px",
        height: rect.height + "px",
        backgroundColor: "rgba(255, 255, 0, 0.25)",
        borderRadius: "3px",
        pointerEvents: "none",
        zIndex: "9998",
        transition: "all 0.4s ease",
        opacity: "1",
        boxShadow: "0 0 8px 2px rgba(255, 255, 0, 0.5)",
        border: "1px solid rgba(255, 215, 0, 0.6)",
      });

      document.body.appendChild(overlay);
    }

    // Phase 1: Keep the highlight at full scale for 1 second
    await delay(1000);

    // Phase 2: Scale back to normal size but keep the glow
    element.style.transform = "scale(1)";

    // Phase 3: Start fading out effects after another second
    await delay(1000);

    if (overlay) {
      overlay.style.opacity = "0";
    }

    // Gradually reduce the glow effect
    element.style.boxShadow = "0 0 5px 1px rgba(255, 255, 0, 0.5)";

    // Phase 4: Remove all effects after 500ms
    await delay(500);
  } finally {
    // Always restore original styles, even if there was an error
    element.style.transition = originalTransition;
    element.style.zIndex = originalZIndex;
    element.style.boxShadow = originalBoxShadow;

    // Only reset transform if it wasn't originally set
    if (!originalTransform) {
      element.style.transform = "";
    } else {
      element.style.transform = originalTransform;
    }

    // Remove overlay if it exists
    if (overlay && overlay.parentNode) {
      overlay.remove();
    }
  }
};

const ensureContainer = (): void => {
  // MAP-09: re-create when first arming OR when the host was detached by a page
  // body swap (SPA / Turbo / PJAX / `document.body.innerHTML = …`). The module
  // ref stays truthy while `isEnabled` stays true, so without the isConnected
  // check markers rebuild into a detached node and silently vanish for the tab
  // session. createHighlighterElement + the now-idempotent setupEventListeners
  // rebind onto the current document.body.
  if (isEnabled && highlighterEl?.isConnected) return;
  createHighlighterElement();
  setupEventListeners();
  isEnabled = true;
};

const tearDownIfIdle = (): void => {
  if (!isEnabled) return;
  if (savedActive || adHocActive) return;
  // Both sources released — tear everything down.
  if (scrollHandler) {
    window.removeEventListener("scroll", scrollHandler);
    scrollHandler = null;
  }
  if (resizeObserver) {
    resizeObserver.disconnect();
    resizeObserver = null;
  }
  // MAP-11: drop the document-level occluded-click intercept.
  document.removeEventListener(
    "pointerdown",
    handleStripOccludedPointerDown,
    true,
  );
  clearScrollbarMarkers();
  if (highlighterEl) {
    highlighterEl.remove();
    highlighterEl = null;
  }
  // MAP-07: remove ALL `.highlighty-scrollbar-highlighter` hosts, not just
  // our module ref, so a baked-in stale strip from a Save-Page-As capture
  // is also cleared on toggle-OFF (otherwise it survives as residue and
  // keeps eating clicks with pointer-events:auto). highlighterEl is null
  // here, so this removes any remaining hosts.
  purgeStripHosts(highlighterEl);
  // MAP-06: the injected <style id="highlighty-scrollbar-style"> carries no
  // css-hility attribute, so removeAllHilityStylesheets misses it — without
  // this removal it leaks in <head> across a full feature-OFF (HLE-05 residue
  // class). The inject path re-checks for the node, so re-enable stays safe.
  document.getElementById("highlighty-scrollbar-style")?.remove();
  isEnabled = false;
};

// Resolve the bar color for a hility element by reading the per-query
// <style> block that lives in <head>. Extracted from the old inline code
// so the same logic can be shared between fan-out and collapse paths.
const resolveColorForQuery = (
  sampleEl: HTMLElement,
  hilityId: string,
): string => {
  let color = "rgba(255, 204, 0, 0.7)";
  const decorationType = sampleEl.getAttribute("data-decoration-type");
  const styleElement = document.getElementById(hilityId);
  if (styleElement && styleElement.textContent) {
    if (decorationType && decorationType !== "background") {
      const decorColorMatch = styleElement.textContent.match(
        /text-decoration-color:\s*([^;!]+)/,
      );
      if (decorColorMatch && decorColorMatch[1]) {
        color = decorColorMatch[1].trim();
      } else {
        const computedStyle = window.getComputedStyle(sampleEl);
        const decorColor = computedStyle.getPropertyValue(
          "text-decoration-color",
        );
        if (decorColor && decorColor !== "currentcolor") color = decorColor;
      }
    } else {
      const bgMatch = styleElement.textContent.match(
        /background:\s*([^;!]+)/,
      );
      if (bgMatch && bgMatch[1]) color = bgMatch[1].trim();
    }
  }
  return color;
};

// Replace the ad-hoc marker set. Empty array clears them. Called by the
// Cmd+F bar on every search update and on close.
export const setAdHocMarkers = (
  ranges: ReadonlyArray<Range>,
  color: string,
): void => {
  if (!ranges.length) {
    clearAdHocMarkers();
    return;
  }
  adHocActive = true;
  ensureContainer();
  clearAdHocEntriesInternal();

  const documentHeight = Math.max(
    document.body.scrollHeight,
    document.documentElement.scrollHeight,
  );
  lastDocHeight = documentHeight;

  // Phase-1 read: collect every range's rect upfront, no DOM writes yet.
  const inputs: BucketInput[] = [];
  const fixedSubtreeCache = new Map<Element, boolean>(); // MAP-12, per-pass
  for (const range of ranges) {
    // MAP-12: skip ad-hoc matches inside a position:fixed subtree (same drift).
    const anchorEl =
      range.startContainer.nodeType === Node.ELEMENT_NODE
        ? (range.startContainer as Element)
        : range.startContainer.parentElement;
    if (isInFixedSubtree(anchorEl, fixedSubtreeCache)) continue;
    const rect = range.getBoundingClientRect();
    const top = rect.top + window.scrollY;
    inputs.push({
      target: { kind: "range", range },
      absoluteTop: top,
      absoluteBottom: top + rect.height,
    });
  }

  // Phase-2 write: single-query input map; renderSource emits one flat
  // list under queryId "adhoc".
  const perQueryInputs = new Map<string, BucketInput[]>();
  perQueryInputs.set("adhoc", inputs);
  const rendered = renderSource(
    "adhoc",
    perQueryInputs,
    () => color,
    () => "Find on page",
    documentHeight,
    stripHeight(),
  );
  adHocEntries = rendered.get("adhoc") ?? [];
  updateMarkerVisibility();
};

export const clearAdHocMarkers = (): void => {
  clearAdHocEntriesInternal();
  adHocActive = false;
  tearDownIfIdle();
};

// MAP-12: a match inside a position:fixed subtree has a VIEWPORT-anchored box —
// its rect.top does not move as the page scrolls — so the strip's document-space
// position `rect.top + window.scrollY` drifts the marker with every scroll,
// wandering away from the match it points at. Such a match stays visible +
// clickable at every scroll (not a dead target), so we DROP its marker rather
// than render a wandering one. Walk ancestors reading computed `position`,
// cached per element per pass to bound the getComputedStyle cost on match-dense
// pages. (Sticky is left as a documented residual — it is in document flow until
// it sticks, so its marker is correct most of the time.)
const isInFixedSubtree = (
  start: Element | null,
  cache: Map<Element, boolean>,
): boolean => {
  const chain: Element[] = [];
  let el: Element | null = start;
  let result = false;
  while (el && el !== document.body && el !== document.documentElement) {
    const cached = cache.get(el);
    if (cached !== undefined) {
      result = cached;
      break;
    }
    chain.push(el);
    let position = "";
    try {
      position = window.getComputedStyle(el).position;
    } catch {
      /* detached / cross-doc edge — treat as non-fixed */
    }
    if (position === "fixed") {
      result = true;
      break;
    }
    el = el.parentElement;
  }
  // Memoize the whole walked chain (all are in/out of the fixed subtree together).
  for (const node of chain) cache.set(node, result);
  return result;
};

// Update markers based on highlighted elements
export const updateScrollbarMarkers = (): void => {
  if (!isEnabled || !highlighterEl) return;
  // MAP-09: this is also called directly (post-highlight pass), not only via
  // initScrollbarHighlighter → ensureContainer. If a body swap detached the
  // host, rebuild it here too so markers don't append into a detached node.
  if (!highlighterEl.isConnected) ensureContainer();
  clearSavedEntries();

  const highlightedElements = document.getElementsByTagName(hilityTag);
  if (!highlightedElements || highlightedElements.length === 0) return;

  const documentHeight = Math.max(
    document.body.scrollHeight,
    document.documentElement.scrollHeight,
  );
  lastDocHeight = documentHeight;

  // Phase-1 read: collect every hility's rect, group by query.
  const colorCache: Record<string, string> = {};
  const nameCache: Record<string, string> = {};
  const fixedSubtreeCache = new Map<Element, boolean>(); // MAP-12, per-pass
  const perQueryInputs = new Map<string, BucketInput[]>();
  for (const raw of Array.from(highlightedElements)) {
    const el = raw as HTMLElement;
    const hilityId = el.getAttribute(dataHility) ?? "default";
    const rect = el.getBoundingClientRect();
    // MAP-08: skip matches with no layout box — display:none, a closed
    // <details>, an inactive tab panel, etc. Such an element's rect is all-zeros
    // (width === height === 0), so `rect.top + window.scrollY` collapses to the
    // current scroll position — a phantom marker that sits at the top on load
    // and then wanders to wherever the user has scrolled, and whose click lands
    // on an invisible element (a dead, no-op target). The X-Ray panel already
    // classifies these as "Hidden in page UI / not directly jumpable"; the strip
    // must match, not contradict it. (Off-screen but laid-out matches keep a
    // non-zero box and are unaffected.)
    if (rect.width === 0 && rect.height === 0) continue;
    // MAP-12: skip matches inside a position:fixed subtree (their marker drifts).
    if (isInFixedSubtree(el, fixedSubtreeCache)) continue;
    const absTop = rect.top + window.scrollY;
    const inputs = perQueryInputs.get(hilityId) ?? [];
    inputs.push({
      target: { kind: "element", element: el },
      absoluteTop: absTop,
      absoluteBottom: absTop + rect.height,
    });
    perQueryInputs.set(hilityId, inputs);

    if (!(hilityId in colorCache)) {
      colorCache[hilityId] = resolveColorForQuery(el, hilityId);
    }
    if (!(hilityId in nameCache)) {
      nameCache[hilityId] = el.getAttribute(dataHilityName) ?? hilityId;
    }
  }

  // Phase-2 write: bucket + fan-out + DOM creates.
  savedEntries = renderSource(
    "saved",
    perQueryInputs,
    (qid) => colorCache[qid] ?? "rgba(255, 204, 0, 0.7)",
    (qid) => nameCache[qid] ?? qid,
    documentHeight,
    stripHeight(),
  );

  updateMarkerVisibility();
};

// Initialize the scrollbar highlighter
export const initScrollbarHighlighter = (settings: GlobalSettings): void => {
  if (!settings.scrollbarHighlighter?.isOn) {
    destroyScrollbarHighlighter();
    return;
  }
  savedActive = true;
  ensureContainer();
  // Initial update of markers
  updateScrollbarMarkers();
};

// Destroy the saved-highlight scrollbar source. Container is torn down
// only if the ad-hoc source is also inactive.
export const destroyScrollbarHighlighter = (): void => {
  savedActive = false;
  clearSavedEntries();
  tearDownIfIdle();
};

// Toggle the saved-highlight scrollbar source.
export const toggleScrollbarHighlighter = (enabled: boolean): void => {
  if (enabled) {
    if (savedActive) return;
    savedActive = true;
    ensureContainer();
    updateScrollbarMarkers();
  } else {
    destroyScrollbarHighlighter();
  }
};
